window.READER_DATA={"title": "Sharh Fi Afaq", "slug": "sharh-fi-afaq", "pages": [{"n": 1, "paras": ["دراسات منهجية هادفة في البناء", "في آفاق التعليم", "دراسة في آفاق دعوة الأستاذ البنا ونظريات الحركة فيها من خلال رسالة التعليم", "سعيد حوى", "يطلب من: مكتبة وهبة", "١٤ شارع الجمهورية - عابدين تليفون ٩٣٧٤٧٠"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0001.png"}, {"n": 2, "paras": ["المقدمة", "ان اجيالا كثيرة في هذه الأمة قد حيل بينها وبين أن تعرف حسن البنا وفكرته ودعوته ، ومن حق هذه الأجيال أن تعرف ومن واجبنا أن نعرف ، خاصة وأن المسلمين ليس أمامهم الا فكر الأستاذ البنا اذا ما أرادوا الانطلاق الصحيح .. ثم ان هناك الكثيرين الذين يتعمدون تشويه صورة الأستاذ البنا في أذهان الناشئة ليحولوا بين هذه الأجيال وبين أن تسير في الطريق الصحيح الذي رسمه .. ثم انه قد نبتت هنا وهناك أفكار مريضة تريد أن تتخلص من دعوة حسن البنا ومن أفكاره فكان لابد أن يعرف هؤلاء، وغيرهم أن الانطلاقة على غير فكر الأستاذ البنا في عصرنا قاصرة أو مستحيلة أو عمياء، اذا ما أردنا عملا كاملا في خدمة الاسلام والمسلمين ..", "ثم ان هناك هجوما جاهلاً على كثير مما طرحه الأستاذ البنا ينزلق اليه ناس لم يرزقهم الله آفاق النظر التي أعطاها الله للأستاذ ؛ فاقتضى ذلك كله أن يكتب تلاميذه والمنتزهون بخصه مبينين ومقيمين الحجة ولعل هذا الكتاب يؤدى دوره في ذلك ..", "وسيدرك من يقرأ هذا الكتاب بامعان آفاق حركة الأستاذ البنا من خلال ادراكه لرسالة التعاليم التي هي من أنضج آثار الأستاذ البنا والتي تكاد تمثل آخر اجتهاداته الفكرية والعملية والتي هي حصيلة استشفاف عام لحركة التاريخ ولواقع المسلمين ولفهم دقيق للنصوص . وقد يأخذ الانسان العجب اذا عرف أن رسالة التعاليم هذه لا تخرج عن كونها صفحات قليلة جدا ولكنها رسمت معالم الطريق للأجيال الكثيرة ، بل اننا لا نبالغ اذا قلنا : انها رسمت معالم الطريق للأمة الاسلامية نحو النصر وفيما بعد النصر الى آماد بعيدة جدا ؛ وذلك مظهر من مظاهر عبقرية الأستاذ البنا رحمه الله ؛ أستغفر الله بل هو مظهر من مظاهر التوفيق الالهي لهذا الرجل .."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0002.png"}, {"n": 3, "paras": ["حدد الأستاذ البنا الأهداف التي يفترض على كل مسلم أن يعمل من أجلها وبين مضامينها وهي ليست أهدافاً مخترعة ولكنها أهداف مستقرأة . وحدد مراحل العمل من أجلها بما يسع احتياجات الأمة الإسلامية وبما يسع كل أقطارها .. وحدد معالم الشخصية الإسلامية من خلال أركان البيعة والواجبات التي تحتاجها الحركة لتحقيق الأهداف على ضوء المراحل .. وحدد الأصول التي تضبط الفهم وتضبط العلاقات وتضبط السير فلا غلو ولا تفريط ولا اندفاع وراء السراب ولا تعطيل للسنن .. وكل ذلك ضمن فقرتي رسالة التعاليم : أركان البيعة وواجبات الأخ المجاهد ..", "تتألف رسالة التعاليم من قسمين : القسم الأول منها في أركان البيعة .. والقسم الثاني في واجبات الأخ المجاهد .. ولقد استطاع الأستاذ البنا من خلال ذكر أركان البيعة وواجبات الأخ المجاهد أن يذكر كل ما تحتاجه الشخصية الإسلامية في عصرنا لينطلق المسلمون نحو تحقيق أهداف الإسلام انطلاقة سليمة ، ولذلك فان الرسالة وان أخذت طابع توجيه للفرد فانها ذكرت نظريات الحركة كلها سواء في السير نحو الدولة أو في السير بعد الدولة كما تحدثت عن سياسات الاخوان وغيرها وكل ذلك من خلال التوجيه المباشر للفرد ، لأن الفرد اذا لم تكن رؤيته واضحة في كل شيء فان قدرته على الانطلاق المستمر في صف منضبط مستقر تكون ضعيفة ..", "ان نقطة البداية لايجاد صف قادر على تحقيق الأهداف هي في وجود الفرد الذي وضحت لديه الأهداف ووضح لديه طريق تحقيقها وامتلك القدرة على التلاؤم مع الصف ولقد أعطت رسالة التعاليم هذا كله من خلال صفحاتها القليلة فكان هذا مظهرا من مظاهر التوفيق الالهي للأستاذ رحمه الله ..", "أحصت رسالة التعاليم في قسميها : قسم أركان البيعة وقسم الواجبات كل ما يلزم المسلم في عصرنا للانطلاق نحو تجاوز أخطاء"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0003.png"}, {"n": 4, "paras": ["الماضي وتبين معالم المستقبل فوضعت بذلك قدم المسلم على بداية الطريق للوصول الى أن تكون كلمة الله هي العليا في هذا المعالم بل وضعت رسالة التعاليم مفاتيح العالم بيد المسلمين أن أحسنوا السير فيها وأحسنوا العمل بها باذن الله ..", "ومن أهم ما حققته رسالة التعاليم في سطورها القليلة أنها نقلت كل ما يلزم الحركة من الاجمال الى التفصيل ومن الغموض الى الوضوح ، فمثلا آل الأمر في المجتمع الاسلامي في شأن البيعة الى أن تكون اما على ورد ذكر أو على التزام بشيخ فجاءت رسالة التعاليم لتحدد معالم البيعة التي يحتاجها عصرنا :", "انها بيعة على الفهم الصحيح للاسلام لأنه بدون فهم لا يكون عمل للاسلام أو بالاسلام ولا يكون سير مشترك من أجله واذا حمل سير مشترك فهو ضيق الدائرة ولا يسع الحاضر والمستقبل ..", "* انها بيعة على الاخلاص لأنه بدون اخلاص فلا قبول من الله ولا تحرك سليما ، يضاف الى ذلك أن الصف يمكن أن يغتال ..", "* وانها بيعة على عمل محدد البدايات واضح النهايات يبدأ بالنفس وينتهى بسيطرة الاسلام على العالم وهي واجبات لا يفطن المسلم المعاصر الى أنه مكلف بها ..", "* وأنها بيعة على الجهاد الذي غفل المسلم عن أنه ميزان الايمان ..", "* وانها بيعة على التضحية في كل شيء من أجل الوصول الى كل شيء .. الى جنة الله ..", "* وانها بيعة على الطاعة على حسب المرحلة وقدر الاستعداد ..", "* وانها بيعة على الثبات في كل ظرف وفي كل حين ..", "* وانها بيعة على أنتجرد لهذه الدعوة واخلاصها عما سواها ..", "* وانها بيعة على الاخوة كنقطة انطلاق ..", "* وانها بيعة على الثقة بالقيادة وبالصف ..", "بيعة ذات أركان عشرة لو اختل ركن منها فان الانطلاق لا يكون صحيحا والبناء لا يمكن أن يتكامل ، ويمكن أن يؤتى الأخ من قبل هذا الركن المختل وتؤتى الجماعة من قبل هذا الأخ ..", "ومن ثم فان أحكام هذه الأركان العشرة عند كل أخ هو وحده شرط الانطلاق والاستمرار .."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0004.png"}, {"n": 5, "paras": ["هذا هو القسم الأول من رسالة \"التعاليم فإذا وضحت هذه الأركان فقد وجدت شخصية المجاهد المستعد للالتزام بكل ما تقتضيه الحركة ، ومن ثم يأتي القسم الثاني وفيه \"التوجيهات الأربعون\" . ثم تأتي خاتمة الرسالة وفيها تلخيص وبعث على العمل ..", "وإذن يتحدد في هذه الرسالة للأخ كل ما يحتاجه باعتباره مسلما معاصرا مجاهدا ملتزما بصف منضبطا بقيادة . ومن خلال خطاب \"الفرد\" تتحدد بنية الجماعة وآلية الحركة ونظريات السير .. فمن لم يعرف هذه الرسالة لا يعرف دعوة الإخوان المسلمين ، ومن لم يلتزم بها فليس من \"الإخوان المسلمين\" وإن حمل الشارة وادعى الاسم ..", "تنقسم رسالة التعاليم إلى مقدمة وقسمين وخاتمة ، ومن المقدمة والخاتمة يفهم أن هذه الرسالة رسالة عمل وهي لنوع خاص من الإخوان ، هم \"الإخوان الحقيقيون\" . وليس فعل الأستاذ البنا غريبا إذ يخص بعض الإخوان بخطاب خاص فذلك من أسلوب القرآن ومن سنة رسول الله صلى الله عليه وسلم فقد خاطب الرسول صلى الله عليه وسلم وخاطب أهل الإيمان وخاطب غيرهم ؛ فأن يخص الأستاذ البنا نوعا من الإخوان بنوع من الخطاب فتلك فطنة منه رحمه الله ..", "لقد عرف الأستاذ البنا رحمه الله أنه ليس لدى كل مسلم في عصرنا استعداد للقيام بأرفع أنواع \"الالتزام الإسلامي\" ، وعرف أن الإسلام يحتاج إلى نوعية خاصة ولذلك جعل في ترتيب دعوته أن يكون الإخوان على درجات في \"العضوية\" فهذا منتسب وهذا مساعد وهذا عامل وهذا مجاهد وهذا نقيب وهذا نائب ؛ وكانت هذه الرسالة للأخوة المجاهدين ليستنهض همم المسلمين جميعا إلى ذلك وليعرف هذا النوع من \"الأخوة\" ما هي شروط الحركة الجهادية .. إنه لن ينهض الإسلام إلا بهذه النوعية ، ولن تستطيع هذه النوعية أن تحقق شروط النهضة إلا إذا التزمت بهذه الرسالة فالتزمت بأركان البيعة وأدت واجباتها .."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0005.png"}, {"n": 6, "paras": ["ولم يكن يخطر ببالى أن أكتب شرحا على رسالة التعاليم أو غيرها من رسائل الأستاذ البنا رحمه الله ، لان كلام الأستاذ البنا رحمه الله من باب السهل الممتنع الذى يفهمه كل انسان ولا يستطيعه الكثيرون ، ولأننى لا أريد أن أكون حجابا بين الأستاذ البنا وبين قارئه ، ونحن طب متى من لا يسعنى مخالفته فكتبت هذا الكتاب ..", "ولكون كلام الأستاذ البنا من باب السهل الممتنع الذى لا يحتاج الى تفسير حرفى الا لماما فاننى لم أسر فى هذا الكتاب على الطريقه التقليدية فى الشرح والتفسير وأنما حاولت أن أستشرف الآفاق التى يحتاجها درس رسالة التعاليم والآفاق التى أرادها الأستاذ البنا عندما وضع رسالة التعاليم ليكون الانطلاق على ضوئها ..", "ولأن هذا الكتاب ليس شرحا على الطريقة التقليدية فاننى أسميته : « فى آفاق التعاليم » ولم أحاول أن أضع العبارة ثم أذكر شرحها وقد يحدث ذلك أحيانا لكنه ليس هو الأسلوب الذى اعتمدته فى تقديم رسالة التعاليم ..", "خطتنا فى هذا البحث : تعرضت رسالة التعاليم لقضية رئيسية فى سياقها الرئيسى هى الشخصية الاسلامية المعاصرة : مقوماتها وواجباتها فعرضت المقومات من خلال ذكرها لأركان البيعة العشرة وذكرت الواجبات فيما بعد ذلك ، ومن خلال عرضها لمقومات الشخصية الاسلامية وواجباتها فى عصرنا ، تعرضت للأهداف التى يجب أن تحققها هذه الشخصية وتعرضت لمراحل الدعوة . ونحن سنسير فى هذا البحث متكلمين عن الأهداف وهذا بالضرورة يقتضى كلاما عن الوسائل ، ثم عن المراحل ، ثم عن المقومات والواجبات ، من خلال التعليق على كلام الأستاذ البنا فى رسالة التعاليم ، فهذه أبواب أربعة هى فى صلب الكلام عن رسالة التعاليم وسنعقد قبل ذلك أبوابا ثلاثة سوى تلك نتحدث فيها عن حسن البنا واضع نظريات العمل الاسلامى المعاصر وعن مفاتيح الفهم لدعوته وعن المهمات الكبرى فى هذه الدعوة فصارت الأبواب سبعة ولكى تأخذ"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0006.png"}, {"n": 7, "paras": ["رسالة التعاليم محلها في الهيكل العام لدعوة الإخوان المسلمين. ذكرنا بابا تاما تحت عنوان « فصول متممة » ثم ختمنا الكتاب بكلمة ختام هي الباب التاسع ..", "محل هذا الكتاب في سلسلة « في البناء » : لقد كان الكتاب الأول في سلسلة « في البناء » هو « جند الله ثقافة وأخلاقا » ليأخذ المسلم فيه الدروس الأولى فيما ينبغي أن يكون عليه ، ثم كان الكتاب الثاني هو « من أجل خطوة إلى الأمام على طريق الجهاد المبارك » وذلك من أجل أن يخطو المسلم على الطريق نحو الأهداف ، ثم الكتاب الثالث هو « المدخل إلى دعوة الإخوان المسلمين » ليعرف المسلم أن طريقه في هذا العصر محدد في الحركة على طريق الإخوان المسلمين . وإذ كانت الانحرافات الثقافية من أخطر ما يواجه المسلم فقد كان الكتاب الرابع هو « جولات في الفقهين الكبير والأكبر » من أجل أن يتجنب المسلم مزالق الطريق فكريا ، ولما كانت التعبئة الروحية هي الطريق لتجنب مزالق الطريق سلوكيا فقد كان الكتاب الخامس هو « تربيتنا الروحية » ولما كانت « رسالة التعاليم » تحدد المعالم الكبرى للأهداف والحركة نحوها وللشخصية التي تحققها فقد كان هذا الكتاب . ولكن رسالة التعاليم في الأصل كانت رسالة يراعى فيها التكوين الشامل للفرد ليكون كل شيء في حقه واضحا فينطلق على ضوء التكوين الشخصي في صف منظم بأسلوب مخطط له وهذا يقتضى أن يوجد الكتاب الذي يتحدث عن التخطيط والتنظيم ومن أجل ذلك فسيكون الكتاب السابع في هذه السلسلة هو كتاب « دروس في التخطيط والتنظيم » ان شاء الله تعالى .. وبعد .. فهذا أوان الشروع في المقصود .. ومن الله العون والتوفيق .."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0007.png"}, {"n": 8, "paras": ["الباب الأول", "حسن البنا واضع نظريات العمل الإسلامي المعاصر", "إذا كانت الفتوى تقدر مكانا وزمانا وشخصا ، فمن باب أولى نظريات العمل الإسلامي المعاصر . وإذا لم يكن كل إنسان مرشحا للفتوى فمن باب أولى قضية طرح نظريات العمل الإسلامي المعاصر . وإذ هو في حكم الثابت أنه لم تتوافر في إنسان معاصر مجموعة الصفات التي تحققت في حسن البنا رحمه الله يكاد يكون وحده هو المرشح لطرح نظريات العمل الإسلامي المعاصر . إن هذا ينبغي أن يأخذ عندنا طابع البديهية . على أن ذلك لا يعنى العصمة لحسن البنا رحمه الله ولا يعنى أيضا عدم ملاحظة الزمان والمكان ولا يعنى كذلك عدم مراعاة احتياجات المرحلة . ولكن هذا شيء وأن يأخذ كل أخ لنفسه حق النقض للبناء الذي أقامه البنا ، وأن تسير الجماعة بعيدة عن أضواء البنا شيء آخر . فالدراسة المستفيضة مع الثقة المطلقة مع القرار من الجماعة ومؤسساتها الرشيدة هو وحده الذي يمكن أن يتم به شيء من تعديل لنظرية ما طرحها الإمام الشهيد رحمه الله . وأخطر ما طرح في يوم ما فكرة التعارض بين خط سيد قطب رحمه الله وخط البنا رحمه الله . وكأن هناك خطين متعارضين . أو أن هناك خطا يلغى الآخر .", "إن خط سيد قطب مكمل لخط البنا وليس معارضا له . كل ما في الأمر أن « سيد » عمق هذا الخط وأعطاه مداه في بعض الأمور . والأستاذ البنا هو البناء . وهؤلاء الذين يزعمون التضاد بين الخطين يصل بعضهم أحيانا إلى أن يجعلوا من « سيد » رحمه الله إماما في الفقه والتوحيد ومفتيا في كل شيء وهو رحمه الله لم يرد ذلك كله ، ولم يضع نفسه هذا الموضع . نقول هذا ، ونحن نعلم مقدار الظلم الذي"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0008.png"}, {"n": 9, "paras": ["يوقعه كثيرون من الناس على تراث «سيد» . ولكن المهم دائما هو وضع الأمور في مواضعها والبعد عن غلو في غير محله ، سواء في الأفكار أو في الأشخاص .", "يبقى حسن البنا رحمه الله واضع نظريات العمل الإسلامي ، فهو الذي طرح فكرا قابلا للاعتماد وقابلا للتطبيق ، قابلا لأن يأخذ بيد المسلم من البداية إلى النهاية . وبيد المسلمين كذلك من البداية إلى النهاية بتوفيق الله عز وجل ، وهكذا يؤكد أن الأستاذ رحمه الله مجدد هذا العصر كما أجمع على ذلك كل من تحدث عنه عن معرفة وإنصاف . ولعله من خلال التجربة يظهر أن أي فكر معاصر لا يغنى عن فكر الأستاذ البنا رحمه الله . ففكر الأستاذ البنا فكر شامل يسع كل احتياجاتنا . ولئن أبرز بعض أخوانه بعض القضايا فذلك لا يغنى عن الأساس ولا عن الشمول في كل جوانب السير . ومن ذلك كله يتضح أن لحسن البنا رحمه الله فضلا على كل إنتاج أنتجه فرد من أفراد الجماعة في لحظة من اللحظات حيث يبقى الفضل الأول لبادر البذور ومتعهدها . وما من أحد من تلاميذ البنا كتب أو وجه أو أبرز إلا والأستاذ البنا صاحب الفضل في ذلك .. والفضل أولا وأخيرا لله .", "لقد جاء الأستاذ البنا والمسلمون في وضع قلق يندفعون في كل سبيل فيقدمون التضحيات الكثيرة ويقدمون الضحايا الكثيرة ولكنها اندفاعات أقل من احتياجات العصر ، ومن درس مجموع الثورات الإسلامية في هذا العصر من ثورة الشيخ شامل النقشبندي في تركستان إلى ثورة الشيخ سعيد الكردي في تركيا إلى ثورة الشيخ عز الدين القسام في فلسطين إلى سير المسلمين في الهند نحو باكستان فإنه يجد في هذا كله وغيره القصور عما يحتاجه العصر للوصول إلى انتصار إسلامي شامل وكامل بينما نرى في كلام الأستاذ البنا المكافأة لروح العصر للوصول إلى انتصار للإسلام مكافيء للعصر وشامل وكامل بأذن الله .", "وهؤلاء أخوانه وأبناؤه يستمرون على السير رغم كل الظروف الصعبة ويزدادون قوة وصلابة بفضل الله .", "ومن تأمل واقع المسلمين الحالي فإنه يجد أنه حيث وصل نفس الأستاذ البنا فثم حيوية للإسلام والمسلمين وحيث انعدم وصول هذا النفس نجد استسلاما رهيبا للقوى العالمية الكافرة ، وللقوى المحلية ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0009.png"}, {"n": 10, "paras": ["الظالمة . وسيأتي يوم يرى فيه ان شاء الله قارئو تاريخ هذه الأمة بوثوق أن بقية الحياة في هذه الأمة تمثلت في دعوة البنا وتلامذته وأن بداية السير المتصاعد لهذه الأمة بدأت بالأستاذ البنا . ولقد استطاع رحمه الله أن يوائم في السير الاسلامي المعاصر بين الحكم الشرعي واحتياجات العصر ، وبين التطلعات العليا للمسلم وبين النظرة الواقعية لمقتضيات السير ، وبين كمال التربية والتعليم وبين التنظيم والعمل السياسي والاقتصادي ، الى غير ذلك مما يغطى كل احتياجات المسلمين . فوضع لوازم ذلك وحرر الارث الاسلامي من الدخن الذي لحق به .", "فنا لا نرضى لأنفسنا أن ننطلق بعيدا عن سير الأستاذ البنا ، لأن التفريط في ذلك تفريط في السير الصحيح لنصرة الاسلام في هذا العصر .", "فلا ينبغي أن تستخفنا سطحية بعض الأمور ولا أن نستعجل في تحليل بعض الظواهر ولا أن تغيب عنا حقائق الأحداث فان السير بدون الأستاذ البنا يبقى قاصرا ، بل حاملا في طياته عوامل نهايته . ولقد كان الانفصام الحاد الذي وجد بين فكر الأستاذ البنا وبين وقع جماعة الاخوان في بعض الجهات السبب الذي أدى الى ظهور كثير من ظواهر القلقة والذي أدى الى مجموعة الانهيارات والانقسامات التي أصابت الجماعة في فترات ، لهذا كله فاننا نصر على احياء سير الأستاذ البنا واستكمال نواقصه والانطلاق على ضوئه وهو بفضل الله يحض في طياته عوامل الكمال والاستكمال ، ونترصع هذه الفقرة بكلمة من كلماته التي قالها في شأن التربية وهي أحد فروع سيره عليه الرحمة : « ان تكوين الأمم وتربية الشعوب ، وتحقيق الآمال ومناصرة المبادىء تحتاج من الأمة التي تحاول هذا ، أو من الفئة التي تدعو اليه على الأقل الى قوة نفسية عظيمة تتمثل في ارادة قوية لا يتطرق اليها ضعف ، ووفاء ثابت لا يعدو عليه تلون ولا غدر ، وتضحية عزيزة لا يحول دونها طمع ولا بخل ، ومعرفة بالمبدأ وايمان به وتقدير له يعصم من الخطأ فيه والانحراف عنه والمساومة عليه والخديعة بغيره » . أترى أن مثل هذا الكلام يصلح لتأسيس عمل اسلامي معاصر ؟ أو ترى أن مثل هذا الكلام يجوز أن يفرط فيه الا جاهل بالقيمة الحقيقية للأشياء ؟"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0010.png"}, {"n": 11, "paras": ["ان مجمل ما قلناه هنا يحتاج التدليل عليه الى استعراض شامل لنظريات الأستاذ البنا وهو متعذر في رسالة واحدة أو في كتاب واحد . ولكن الأيام ستكشف - والله أعلم - أنه لن تستطيع الحركة الاسلامية ولا في طور من أطوارها سواء قبل الدولة أو بعدها أو في السياسة الداخلية أو الخارجية للدولة الاسلامية أو في التربية أو التكوين أو في الاستراتيجية والحركة أن تستغنى عن فكر الأستاذ البنا رحمه الله . ولئن كان الأستاذ البنا بمجموع ما حباه الله عز وجل هو المرشح الوحيد لأن يطرح نظريات العمل الاسلامي فالدعوة التي أقامها تركيب ذو نسب معينة فمتى اختلفت هذه النسب حدث فساد . فالسلفية وللصوفية وللفقه وللفكر وللعلم وللجهاد وللتربية وللمال وللقوة ، ولغير ذلك فيها نسب اذا اختل واحد منها وقع في الدعوة نفسها خلل . ومن ثم فأخطر ما يواجه الدعوة والجماعة هو الارث الناقص والارث المدعى الجاهل للأستاذ . فاذا كانت مرحلة التكوين في دعوة البنا كذا وكذا ثم فرط في ذلك فلم تعط هذه المرحلة مداها في هذا أو ذاك فان تفريطا خطيرا يكون قد وقع . واذا لم تأخذ القيادات حظها من ارث شخصية الأستاذ البنا علما وعملا ومعرفة بالله وعبادة له وتقوى وورعا وزهدا ودأبا وجلدا ، ومن باب أولى أن تأخذ ارثها الكامل عن رسول الله صلى الله عليه وسلم .. اذا لم تأخذ القيادات ذلك فان تفريطا خطيرا يكون قد وقع . ومن ثم فان علينا أن نلحظ الارث الناقص فانه يكاد يكون خطرا مميتا في حق الجماعة .", "ان الجماعة في الاطار الذي أقامها به الأستاذ البنا رحمه الله قادرة على استيعاب المسلمين جميعا . فما من مسلم الا ويشعر أن في الجماعة ما يطمح اليه من كمال وزيادة ، وما من مجموعة الا وترى في الجماعة أن ما تحرص عليه من خير غير مغالية فيه موجود وزيادة . وبهذه الكمالات التي أقام بها الأستاذ البنا الجماعة كانت مستوعبة مستقطبة اذ استطاع الأستاذ رحمه الله أن يأخذ الخير حيث كان محررا اياه من دخنه فاجتمع في الجماعة الخير كله محررا من الدخن الذي علق فيه خلال العصور . فقد أخذ الأستاذ من التصوف وحرره من دخنه ووجه الى الفقه وحرره من دخنه . وفى العقائد كان الأمر كذلك . وهكذا قل في كل ما يحتاجه المسلمون في عصرنا الحاضر . وكل"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0011.png"}, {"n": 12, "paras": ["ذلك على أساس من الإسلام الصافي الخالص ، وبهذا كله اجتمع للجماعة وفي الجماعة ما به صلاح المسلمين . فإذا ما حدث أن تسلل إلى الجماعة نقص أو قصور بحيث أصبح أهل أي اتجاه في هذه الأمة يشعرون بتفوقهم عليها فعندئذ تكون الطامة . فالفقيه إذا لم ير فقها حقرنا . وإذا لم ير الصوف سيرا إلى الله حقرنا . وإن عالم التوحيد إذا رأى جهلنا في قضايا التوحيد حقرنا ولم يحترمنا . وقل مثل ذلك في السياسة والاقتصاد . وقل مثل ذلك في شئون الحرب والجهاد ؛ وقل مثل ذلك في تبنى قضايا الأمة كلها . وفي كل حالة من هذه الحالات يطمع المتفوق علينا في شأن ما أن يستوعبنا .. ولا خيار لنا في ذلك ، أما أن نستوعب وإما أن نستوعب(١) ولن نستطيع الاستيعاب إلا باستكمال الكمالات كلها . قال موسى عليه السلام لفرعون : « وتلك نعمة تمنها على أن عبدت بني إسرائيل » ( الشعراء : ٢٢ ) أى أتمن على أن جعلت بني إسرائيل عبيدا ؟ هل ترى موقفا مثل هذا الموقف في تبنى قضية شعب والوقوف في وجه مستبد به .", "مثل هذا الكمال في كل شيء نحن نحتاجه على أن يكون ذلك كله لله وحده ، وفي الله وحده ، وبالله وحده . أما هذا ، وإما أن يغرقنا غيرنا ويغرق كل جزء منا صنف من الناس وباستكمالنا كمالاتنا نكون حجة على خلق الله بدين الله ، وعلى المسلمين فيما ندعوهم إليه وبذلك وحده نستطيع أن نحمل عبء السير إلى أن تكون كلمة الله هي العليا في عالم يسيطر عليه الكفر .", "وطريقنا الوحيد في هذا كله هو السير على الأسس التي وضعها الأستاذ البنا وسترى الدليل على ذلك في هذا الكتاب .", "(١) نستوعب : الأولى بفتح النون وكسر العين ، والثانية بضم النون وفتح العين ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0012.png"}, {"n": 13, "paras": ["الباب الثاني", "في مفاتيح الفهم والدعوة لقضية الإخوان المسلمين", "قال عليه الصلاة والسلام في الحديث المتفق عليه لحذيفة : « أن تلزم جماعة المسلمين وإمامهم » . ان الأصل الذي لا يجوز أن يغيب عن المسلم هو أنه لابد للمسلمين من جماعة وإمام وأن الواجب الكبير على المسلم أن يكون ملتزماً بجماعة المسلمين وإمامهم ، وهذا هو المفتاح الأول لفهم قضية الإخوان المسلمين ، فقد ضاعت فكرة الجماعة الإسلامية أصلا ، وغاب عن المسلمين الطريق الصحيح للوصول إلى الجماعة والإمام ووفق الله عز وجل حسن البنا إلى رسم الطريق الكامل للوصول إلى الجماعة والامام باعتماد كل ما يلزم لذلك وبالسير العملي لما يحقق ذلك اذ أنه حتى تعتبر مجموعة ما جماعة للمسلمين فان ذلك يقتضى توافر شروط كثيرة في فهمها ووعيها وصفاء قيادتها ، ولا نعلم أن مجموعة ما في عصرنا توافرت فيها هذه الأمور كالجماعة التي أقامها الأستاذ البنا ، وذلك أن جماعة المسلمين هي التي لها قيادة راشدة منبثقة عن صف راشد على ضوء شورى اسلامية وأن جماعة المسلمين هي من اتصفت بالاسلامية الخالصة دون صفة زائدة على ذلك فهي دائما تعدل أو تطور أو تتبنى على ضوء ذلك وأن جماعة المسلمين هي التي تعمل لاقامة الاسلام كله في محيط الفرد والأسرة والشعب والعالم وأن جماعة المسلمين هي التي تفهم الاسلام وتلتزم به على نفس الطريقة التي كان عليها الرسول صلى الله عليه وسلم وأصحابه وهي صفة مستمرة في هذه الأمة الى قيام الساعة بشهادة النصوص ومن ثم فجماعة المسلمين هي الاستمرار لما اعتمدته"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0013.png"}, {"n": 14, "paras": ["الامة الاسلامية كان العصور في العقائد والسنن والجماعة الاخوان المسلمين هذا شأنها ، وفي رسالة المدخل بيان هذا وغيره من شروط اعتبار مجموعة ما جماعة المسلمين وكيف ان هذه الشروط كلها متوافرة في الاخوان المسلمين . وهذا هو المفتاح الأول لفهم قضية الاخوان المسلمين وفهم دعوتهم . ولما كان من الفرائض على المسلمين ألا يعطوا ولاءهم الا لجماعة المسلمين اقتضى هذا وجود اتجاه في كل قطر يتمثل به جماعة المسلمين حتى لا يضيع ولاء المسلم أو يعطى بسبب ضرورات العمل اليومي الى غير المسلمين الملتزمين ، ولما كان من الفرائض على المسلمين أن يقيموا أحكام الاسلام اقتضى هذا قيام جماعة تعمل لذلك اذ لا يتم ذلك بلا جماعة ، واذا كانت جماعة الاخوان المسلمين تعمل لذلك كله وتحاول أن تحقق هذا كله فذلك يدل على أن وجودها وقيامها فريضة اسلامية اقتضتها ضرورات اسلامية وهذا مفتاح ثان من مفاتيح فهم قضية الاخوان المسلمين ودعوتهم . وثمة عمليات لابد منها فلابد من نقل المسلم من السيوبة في الولاء الى الالتزام في الولاء ، ومن التفلت في الالتزام الاسلامي الى الالتزام الاسلامي ومن الجهل بالاسلام الى العلم به ومن الغفلة الى اليقظة والوعى وهذه العمليات كلها تقتضى قيام الجماعة الاسلامية ، وقد كان ذلك على يد الأستاذ البنا رحمه الله .. بتوفيق من الله .", "ان وجود الاخوان المسلمين عملية اقتضتها عملية احياء الاسلام علما وعملا وحالا ، واستمرارهم قضية تستلزمها ضرورة الرقابة والمعارضة في الاسلام ، ومن أجل الاسلام ووجودهم واستمرارهم تقتضيه عملية تحقيق أهداف الاسلام ، وكل ذلك فرائض فرضها الله عز وجل ، فالذين يتساءلون من المسلمين لماذا الاخوان ؟ عليهم أن يتساءلوا : لولا الاخوان كان ماذا ؟ وماذا سيكون ؟ .. فحتى علماء المسلمين المعاصرين المهتمين في احياء الاسلام انما يشتغلون في أحياء بعض منه ، وفي كثير من الأحيان يكون بينهم وبين روح العصر حجاب ، ثم انه في كثير من الأحيان تستجر الكثيرين الأحداث أنى بعد أو قرب من الاسلام . فاذا فهمنا هذه القضية بأبعادها كلها نكون قد عرفنا مفتاحا آخر من مفاتيح فهم قضية الاخوان المسلمين ودعوتهم .. ان دعوة الاخوان المسلمين هي رمز رفع شعار علم الاسلام السياسي في", "( ٢ - في آفاق التعاليم )"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0014.png"}, {"n": 15, "paras": ["كثير من الأقطار ان لم يكن في كل الأقطار وبدونها يبقى علم الاسلام السياسي ضائعا . ففي كل قطر اسلامي قامت حركات رفعت أعلاما سياسية غير اسلامية ، فهذا علم للوطنية ، وهذا علم للقومية ، وهذا علم للانسانية ، وهذا علم للشيوعية ، وهذا علم للاشتراكية ، واجتذب كل علم من هذه الأعلام مجموعة من المسلمين ، وبقى علم الاسلام السياسي لا رافع له . ومن العلوم بديهة في دين الله أن الاسلام نظام شامل ، ومنذ سقوط الدولة العثمانية - بل وقبل ذلك - منذ سقوط كثير من الأقطار الاسلامية تحت سيطرة الدول الكافرة زوى سلطان الاسلام السياسي وانحسر انحسارا كبيرا وكان لابد من رافع للواء العمل لاقامة نظام الاسلام السياسي ، وحمل الاخوان اللواء وذلك مفتاح آخر من مفاتيح فهم قضية الاخوان المسلمين ودعوتهم .. مما مر ندرك أن السير مع الاخوان شيء لابد منه للمسلم المعاصر لتحقيق كثير من الفروض حتى ولو كان للمسلم سيره الاسلامي الخاص فهناك تحقيق الأهداف الاسلامية التي تحتاج الى عمل جماعي وهناك فقه لدعوة بما يكافىء العصر وهناك فقه الاسلام في صراعه مع أنواع الكفر القديم والمعاصر وهناك المتابعة لما يجرى للمسلمين في العالم وهناك المواقف اليومية التي يقتضيها الصراع اليومى من أجل الاسلام وهناك العمل الاسلامي الموحد الذي يفترض على المسلمين أن يكونوا في ظله وهناك العمل الاسلامي وكل ذلك يقتضى سيرا مع الجماعة الاسلامية . هذا مع ملاحظة أن سير الاخوان سير شامل يسع كل التطلعات ويفجر كل الطاقات ، وبهذا لا يسع مسلما أن يتخلف عن هذه الدعوة .", "وانعد لعرض بعض مفاتيح دعوة الاخوان المسلمين .. رأينا أن تجديد الاسلام في هذا العصر هو سمة الاخوان الأولى وهاهنا قضيتان :", "الاسلام والعصر : هناك كثير من الأحكام التي تتغير بتغير الأزمان ، وكثير من الظروف تؤثر في طبيعة الفتوى ومن ثم قال فهاؤنا : « الفتوى تقدر زمانا ومكانا وشخصا » ، ولا شك أن عصرنا عصر له خصائصه وطبيعته ومواصفاته وتركيبه وبديهياته ومطالبه ومقبولاته ومرفوضاته وتعقيداته وللناس فيه مواقفهم من الاسلام ، والمسلمون أنفسهم"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0015.png"}, {"n": 16, "paras": ["تفرقوا واختلفوا وضعف الاسلام ووهت كثير من عراه في نفوس الكثيرين من المسلمين ومن ثم كانت قضية تجديد الاسلام في هذا العصر قضية معقدة تحتاج الى امكانيات معينة . وقد استطاع الاستاذ البنا بتوفيق الله عز وجل ان يضع كل الأسس المناسبة لتجديد الاسلام في عصرنا . فالتجديد ومعرفة العصر مفتاح من مفاتيح دعوة الاخوان المسلمين الرئيسية التي يدخل فيها أمور كثيرة منها :", "١ - لقد ورثنا رسول الله صلى الله عليه وسلم الكتاب والسنة والعمل بهما والحال الناتج عن العلم والعمل ، وعملية احياء الاسلام تقتضى احياء العلم والعمل والحال ، ونقصد بالحال الوضع القلبي والنفسي والروحي الذي كان لأصحاب رسول الله صلى الله عليه وسلم كالنفس مزكاة وأقلب خاشع لله والروح عارفة بالله مقرة بالعبودية .", "٢ - ويدخل في عطية احياء الاسلام : (أ) احياء ما يسمى حاليا بالفقه الدستورى وصياغة الحياة الاسلامية على ضوء ذلك . (ب) احياء ما يقابل وما يسمى بنقابات بحيث تنطلق كل نقابة من فقه الاسلام في عملها . (ج) احياء ما يقابل وما يسمى حاليا بالقوانين سواء أكانت قوانين مدنية أو جنائية أو شخصية أو دولية أو تجارية أو غير ذلك وصياغة الحياة الاسلامية على ضوء ذلك . (د) احياء نظام الأسرة . (ه) اعادة الحيوية الى الأمة الاسلامية لتستأنف مسيرتها العالمية في أداء رسالتها لتكون كلمة الله هي العليا في العالم كله .", "٣ - ويدخل في عملية احياء الاسلام احياء كليات الاسلام وجزئياته اذ بعض الناس يؤمنون بكليات الاسلام ويهملون جزئياته واذا عرضت عليهم أنكروها ، وبعض الناس يغرقون في فروع المسائل العطية وتغيب عنهم الكليات الكبرى في هذا الدين . فكان جزء مهم من عطية تجديد الاسلام التي قامت بها جماعة الاخوان - ولا زالت - أنها أحيت المفاهيم الكبرى وذكرت بالبديهيات العظمى وحدثت الناس عن الكليات وفى الوقت نفسه ربت على فهم الجزئيات والالتزام بها ، ودلت على طريق التعرف على المسائل الفرعية فدلت على ما هو أصل"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0016.png"}, {"n": 17, "paras": ["لا يسع الاختلاف فيه ودلت على ما هو فرع يمكن الاختلاف فيه وحدود الاختلاف ومتى يجوز ومتى لا. يجوز والأدب الجامع في كل مسألة وفي كل مقام . لقد كان المسلمون بحاجة إلى تحرير علوم الإسلام الرئيسية من دخنها الذي لحقها خلال العصور وكانوا بحاجة مع هذا إلى نظرة كلية جامعة في شأن الإسلام والمسلمين وقد فعل الأستاذ البنا ذلك كله بتوفيق الله عز وجل ، ولا زالت الجماعة تؤدي دورها في هذا السبيل ، وبادراكنا لهذه الجوانب كلها يكون قد تعمق لدينا فهم مفتاح من مفاتيح دعوة الإخوان المسلمين وقضيتهم .. وفي هذه العجالة السريعة نحب أن نذكر مجموعة أخرى من الأصول العامة في هذه الدعوة لندرك بها مجموعة أخرى من مفاتيح هذه الدعوة وقضيتها :", "( ١ ) لكل حزب في العالم أهدافه ووسائله واستراتيجيته ومناهجه العلمية والتربوية وقواعده التنظيمية ونظامه وخصته ولوائحه وغير ذلك ، والإخوان المسلمون وهم يحملون شرف رفع لواء حزب الله لهم ذلك كله ولكن الفارق بينهم وبين غيرهم أنهم في هذا كله مسلمون ، من الإسلام يستمدون وبه يلتزمون وعنه يصدرون وأذا فات كثير من المسلمين أن يعرفوا أن الإسلام فيه هذا كله فان الإخوان المسلمين فهموا من قوله تعالى : « ونزلنا عليك الكتاب تبيانا لكل شيء وهدى ورحمة وبشرى للمسلمين » ( النحل : ٨٩ ) ، لقد فهم الإخوان المسلمون من هذه الآية أن الإسلام فيه هذا كله فأهدافهم إسلامية ووسائلهم إسلامية وخصتهم ومناهجهم إسلامية وقواعدهم التنظيمية إسلامية ونظامهم ولوائحهم إسلامية .. وهكذا في شأنهم كله وبهذا ينفردون عن الناس أنهم يرجون أن يكونوا حزب الله وجنده الحقيقيين .", "( ٢ ) مجموع ما قاله الأئمة المجتهدون مما استنبطوه من الكتاب والسنة وما يمكن أن يستنبط على أصولهم من أحكام إلى قيام الساعة تعتبره جماعة الإخوان المسلمين من الشريعة الإسلامية فهو جزء منها ومجموع الأقوال في المسألة الواحدة يضع أمام الأمة الإسلامية والدولة الإسلامية وأمام المسلمين خيارات كثيرة . وقد قال علماء المسلمين : أن لإمام المسلمين أن يختار قولا من الأقوال الفقهية ويفرضه على مجموع الأمة ، وطبعا ينبغي أن يكون ذلك لمصلحة هي التي رجحته وفي ذلك من السعة ما فيه ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0017.png"}, {"n": 18, "paras": ["ان الأقوال المتعددة في المسألة الواحدة تجعل الدولة الاسلامية أمام خيارات عريضة تسع الزمان والمكان ، والاخوان المسلمون يعتمدون عد الأصل في القانون والدستور بما يحقق أكبر مردود لمصلحة هذه الأمة محليا وعالميا مع ابقائهم قضية الفتوى والالتزام الفقهي لقناعات الأفراد . ولتوضيح أهمية ما ذكرناه ، فلنضرب مثلا : في الموقف من أهل الذمة - أي المواطنين من غير المسلمين على الأرض الاسلامية - نجد أقوالا كثيرة للعلماء فمنهم المتشدد ومنهم الموسع ، وفي عصرنا قد يكون من المناسب أن نعامل هؤلاء على أوسع آراء الفقهاء كي لا يكون علينا حجة وكي لا يؤلب الرأي العام المحلي أو العالمي ضدنا ، والاخوان المسلمون وهم ينظرون إلى التطبيق بمثل هذه السعة يعطون الالتزام الاسلامي والمعاصر بأن واحد أكبر مدى عمى .", "( ٣ ) ان مراعاة الرأي العام المحلي والعالمي أصل من أصول الاسلام يعتمده الاخوان المسلمون ويعطونه مداه على أن يفهم ذلك فهما صحيحا . فنحن نراعي الرأي العام فيما لا يتعارض مع شريعتنا وفي حدود عدم تعطيلها أما اذا تعارض ذلك مع شريعتنا أو أدى إلى تعطيلها فعندئذ فلا مراعاة لأحد . قال تعالى : « يجاهدون في سبيل الله ولا يخافون لومة لائم » ( المائدة : ٥٤ ) أن الأصل الذي نعتمده في مراعاة الرأي العام ضمن الحدود التي ذكرناها هي ما فعله رسول الله صلى الله عليه وسلم يوم فتح مكة اذ قال لعائشة رضي الله عنها : « لولا أن قومك حديثو عهد بجاهلية لهدمت البيت وبنيته على قواعد ابراهيم » ؛ فهاهنا راعى رسول الله صلى الله عليه وسلم الرأي العام فيما لا يترتب عليه عمل .", "( ٤ ) كل ما يعتمده الاخوان يلاحظ فيه شيئان : أولا أن يكون سائغا شرعا وأن يكون مكافئا لأسلحة الخصوم ومحققا للأهداف فالدراسة تقابلها دراسة والتنظيم يقابله تنظيم والجريدة يقابلها جريدة والشعر يقابله شعر . والهدف المحلي يحتاج إلى وسائل مناسبة تقيمه والهدف العالمي يحتاج إلى وسائل مناسبة تقيمه ؛ وكل ذلك على ضوء الاسلام . وهذا الأصل الذي يعتمده الاخوان واضح من حياة الرسول صلى الله عليه وسلم اذ كان يقابل شعرا بشعر وخطابة بخطابة وجيشا بجيش .", "( ٥ ) الأصل الذي نعتمده في سياستنا الخارجية هو مصالح"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0018.png"}, {"n": 19, "paras": ["بمصالح فاذا اراد احد ان يعاملنا بأكثر من ذلك كان أراد أن يعاملنا مصالح بمبادىء فلا ، على أننا على استعداد من أجل أن ينتشر الاسلام أن نخسر الكثير ، وأصل آخر نعتمده في السياسة الخارجية وهو التعامل العادل مثلا بمثل على أننا من أجل أن ينتشر الاسلام يمكن أن نتساهل كثيرا . وفى أى تعامل خارجي أو أية مشاركة في مؤسسة عالمية فنحن ملتزمون بالاسلام واذا قبلنا نصوصا عامة فاننا نحتفظ لأنفسنا في أن نفسرها تفسيرا اسلاميا . فمثلا لو أننا شاركنا في منظمة هيئة الأمم المتحدة فاننا نكون محتفظين لأنفسنا بحق تفسير نصوصها ومواثيقها تفسيرا اسلاميا ولا نلتزم في التطبيق الا بما وافق اسلامنا ونرفض كل ما خالفه .", "( ٦ ) في سير الاخوان المسلمين نحو الولايات الاسلامية المتحدة لا يخضر ببالهم أن تكون هذه الولايات نسخا عن بعضها بل سيكون لكل ولاية قوانينها ومؤسساتها وقضاياها الخاصة بها يتحكم في ذلك المذهب الفقهي أو المذهب الاصولي الذي يعتمده سكان هذه الولاية كما يتحكم في ذلك لغة شعب الولاية وكثير من عاداته المشروعة ثم ارادته في اختيار نوع نظام الحكم المناسب له وهذا شيء لا تحكمه قاعدة واحدة . على أن جميع الولايات الاسلامية لابد أن تخضع بشكل ما لسلطة أمير المؤمنين وأجهزة الدولة المركزية على ضوء دستور يحكم الجميع ومؤسسات تخدم الجميع .", "( ٧ ) في الاسلام تتغير بعض الأحكام بتغير الأزمان ، ولكن هذا التغير محكوم بقواعد التغيير على ضوء الأصول الاسلامية نفسها ومن ثم فالاخوان المسلمون يحبون أن يكونوا واضحين في هذا وأن يوضحوا هذا كذلك للناس وفى سير المسلمين الحالي نحو الدولة الواحدة لا يسع المسلمين في كل أقطارهم نظام واحد ولا قاعدة واحدة ، ومن ثم فلكل قطر نظامه وستكون له خطته وله قياداته ، وسيكون لكل قيادة مبادراتها وخطتها داخل قطرها ولابد من التنسيق واشراف مكتب الارشاد ولابد أن يتم ذلك بما تكون به المركزية لصالح الجميع واللامركزية في بعض الشئون لصالح الجميع وكمبدأ عام فالقيادة الأعلى تقدم للقيادة الأدنى وتعطيها وترفدها وتقويها وتوجهها دون أن تشلها وتلغيها .."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0019.png"}, {"n": 20, "paras": ["من مجموعة هذه الأصول العامة في دعوة الإخوان المسلمين ندرك مفاتيح أخرى من مفاتيح الفهم لدعوة الإخوان المسلمين وقضيتهم وفيما يأتي زيادة توضيح لمفاتيح الفهم لهذه الدعوة ولكننا أحببنا أن نخص بعض الأمور بباب مستقل للتأكيد عليها وإذا كان لنا من شيء نختم به هذا الباب فهو أن نتذكر نحن الإخوان المسلمين مجموعة أمور : الأمر الأول : أن نفهم قضيتنا ودعوتنا ، هذا شيء .. وأن نحسن الدعوة إليها شيء آخر ؛ ثم أن نحسن صهر المستجيبين لهذا فهذا شيء أعلى وأرقى ومن ثم كان هناك قضايا ثلاث : فهم الدعوة ، واتقان الدعوة لها ، والقدرة على التربية والصهر فيها . وأي فشل في واحدة من هذه الثلاث يشكل كارثة في العمل الإسلامي عدا عن كونه قصورا هائلا ، ولذلك فعلينا أن نعمق في أنفسنا وأنفس إخواننا كل ما يخدم هذه الأمور الثلاثة .", "الأمر الثاني : قال موسى عليه السلام لفرعون : « هل لك إلى أن تزكى . وأهديك إلى ربك فتخشى » ( النازعات : ١٨ ، ١٩ ) . في عصرنا لابد أن نتحدث لبعض البيئات عما يحقق لها الإسلام من مكاسب دنيوية كجزء من طرائقنا في الدعوة ولكن الشيء الذي يجب أن نطرق به كل سمع هو الحديث عن الروح وعن النفس وعن القلب واحتياجات القلب إلى الاحياء ، واحتياجات النفس إلى التزكية واحتياجات الروح إلى العودة لمقام العبودية الخالصة لله عز وجل وكيف أن هذه المعاني يستحيل أن يصل إليها الانسان إلا بالاسلام ، والسير إلى الله عن طريقه من خلال اعتقاد صحيح وعمل صحيح وتوجه صحيح إلى الله بالعبادة والذكر ، وهذا يقتضي من الأخ أن يكون مدركا لموضوع السير إلى الله وأصول هذا السير وما يصادفه السائر ؛ وهذا نوع من النضج إذا لم يحصل للأخ فان فراغا كبيرا يفصل بينه وبين عصره . أن الغربي بشكل عام يستشعر الفراغ الروحي ومن ثم يفر بعض الغربيين إلى التصوف البوذي وأمثاله ، وما ذلك بمغن عنه شيئا . إن الذي يلبي احتياجات الروح وأشواق القلب وتطلعات النفس الفطرية هو الاسلام ، ولكن لهذه المعاني أصولها في السير الاسلامي فلابد من الاتقان لها ، كيف ننتقل بالقلب من حال إلى حال ؟ كيف نرجع إلى مقام العبودية الخالصة لله ؟ كيف تحفة ال..."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0020.png"}, {"n": 21, "paras": ["ذاك حتى تصبح مقامات لها ! كيف نطهر النفس من أمراضها كالحسد والعجب والكبر وأمثال ذلك ؟ هذا كله ينبغي أن يتضح في أنفسنا وأن نركز في دعوة الخلق إليه لأن ذلك جزء من هدى الأنبياء، وهو الجزء الذي يرتكز عليه كل شيء كما أنه الجزء الذي يحس كل إنسان بأنه بحاجة إليه سواء أكان غنيا أو فقيرا ! فالتركيز عليه مفتاح من مفاتيح الدعوة لقضيتنا ونحن في هذا الجانب صوفيون ولكنها صوفية سنية متحررة من أدخن مقيدة بعقائد أهل السنة والجماعة محررة على ضوء أقوال علماء المسلمين لتأخذ دعوتنا بعدها الصوفي الذي يبحث عنه صوفية عصرنا الذين اختلط عليهم ما هو حق بما هو خطأ وما هو بدعة بما هو سنة وما هو من الأصول بما هو من العوارض .", "الأمر الثالث : لابد أن نعرف عقلية الإنسان الذي نخاطبه وعلى ضوء ذلك يكون الخطاب وتكون الدعوة . فهناك المسلم في الأصل الذي ضلله الفكر الكافر ، وهناك الكافر الأصيل ، وهناك المسلم الغافل ، وهناك المسلم الصوفي ، وهناك المسلم السلفي ، وهناك رجل الدنيا ، وهناك المتطلع إلى الآخرة . وينبغي أن نتقن طريقة الخطاب مع كل هؤلاء ، وأن نتقن نقطة البداية مع كل واحد منهم . فالصوفي أعايد نلفت نظره إلى أن هناك واجبات مفروضة كمثل إقامة دولة الله وكمثل العمل لتكون كلمة الله هي العليا في العالمين ، وكمثل كون المسلمين جماعة واحدة وكل ذلك ينبغي أن يكون بأوضح دليل . والمسلم الذي لا يفهم قضيتنا ينبغي أن نعرفه من نحن وما هو الشيء الذي نعمل له ونتضع إليه وكيف أن هذا الشيء مفروض علينا وعليه ، وكيف أنه يجب عليه وعلينا أن نتعاون . والمسلم الذي يجهل الإسلام علينا أن نعلمه الإسلام ، وكل ذلك بصدر واسع وأناة لا تعرف شيئا اسمه نفاد صبر ، والمسلم السلفي نوضح له أن دعوتنا سلفية وأننا ملتزمون منهج السلف الصالح علما وعملا وحركة تؤدي إلى إقامة دولة الإسلام على نفس النهج ، وندعو المسلم السلفي ألا يسمح للشيطان أن يباعد بينه وبين العاملين لنصرة دين الله . وابن المسلم الذي ضلله أعداء الله عز وجل ينبغي أن نعيد له الثقة بإسلامه وقرآنه وأصول الإيمان من خلال عرض حجج الإيمان وظواهر إعجاز القرآن وأن ننظر إلى نقطة الخلل في إيمانه فنركز عليها وإلى نقطة الخطأ في تصوره فنصححها له"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0021.png"}, {"n": 22, "paras": ["من خلال نقاش هادئ، أو من خلال كتاب نضعه في يده وعينا أن نضع في حسابنا أننا في صراع مع الكفر والشيطان على المسلم، وأننا لن نسمح للكفر ولا للشيطان ان يغلبنا على أخينا ما استطعنا إلى ذلك سبيلا. وفي دعوتنا للكافرين علينا أن نركز على نقطة البداية التي منطلقها الايمان بالله وبرسوله صلى الله عليه وسلم وبالوحي المنزل فبقدر احكامنا هذا الأمر يكون انتقالنا الى ما بعده سهلا.", "ان الانطلاقة الأقوى بالانسان هي التي يجتمع فيها ذكر وعلم من لحظة البداية فكلما استطعنا أن نجعل الانسان يستغرق بالأذكار جزءا من وقته ويقضى بعضا منه بالمطالعة الهادفة والعلم فان ذلك يكون أقرب الى الكمال. أخرج رزين عن ابن عباس في تفسير قوله تعالى: « اعلموا أن الله يحيى الأرض بعد موتها » ( الحديد : ١٧ ) قال : يين القلوب بعد قسوتها فيجعلها مخبتة ويحيى القلوب الميتة بالعلم والحكمة، لاحظ قوله : يحيى القلوب الميتة بالعلم والحكمة، انه ما دمنا نسمع الانسان العلم والحكمة ويسمع لنا فان الطمع في حياة قلبه كبير وأهم ما ينبغى أن نلاحظه في هذا كله أن نضبط النفس عند الغضب وأن نعفو عند الاساءة فانه بدون هذين الخلقين لن نستطيع سياسة أمتنا. أخرج البخارى تعليقا عن ابن عباس في قوله تعالى : « أدفع بالتي هي أحسن » ( المؤمنون : ٩٦ ، فصلت : ٣٤ ) قال : الصبر عند الغضب والعفو عند الاساءة فاذا فعلوه عصمهم الله وخضع لهم عدوهم.", "وبعد .. فهذه عجالة سريعة هي بمثابة المفاتيح لفهم القضايا الكبرى في دعوة الاخوان المسلمين وفي طرائق دعوتهم لقضيتهم قدمنا بها لشرح رسالة التعاليم لكي نعرف محل رسالة التعاليم في دعوتنا وأهميتها بالنسبة للعمل الاسلامي المعاصر."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0022.png"}, {"n": 23, "paras": ["الباب الثالث في المهمات الكبرى", "ان أعظم مهماتنا على الاطلاق : التجديد والنقل ، تجديد الاسلام ، ونقل المسلم من طور الى طور ونقل الأمة الاسلامية من طور الى طور :", "١ - للاخوان المسلمين في كلام الأستاذ البنا مظهران : المظهر الأول : كجماعة من جماعات الخدمة العامة تشترك مع كل جماعة مسلمة تخدم خدمة عامة باعتماد بعض الوسائل .", "المظهر الثاني : كحركة تجديدية ، وقد ركز الأستاذ البنا رحمه الله على الجانب الثاني لأنه هو الأهم في هذه الحركة ، ومن مظاهر التجديد في هذه الحركة أن هذه الجماعة فطنت لما غفل عنه المسلمون من احتياجات العمل الاسلامي المعاصر : فالاسلام بحاجة الى عمل شامل يشعر به المسلم أنه مسلم ويشعر باتاه الجماعي ويشعر بارتباطه العام بالاسلام وأهله ويشعر بارتباطه الخاص بالاسلام وأهله . وبحاجة الى عمل شامل يبتدىء بالتعريف بالاسلام ويمر بالتكوين الدقيق وينتهى بالتنفيذ اليومى والتنفيذ الشامل لتحقيق الأهداف الكبرى التي فرض الله على المسلمين اقامتها على المستوى المحلى والمستوى العالمي . والاسلام بحاجة الى الجماعة التي تتولى هذا كله ، والجماعة حتى تقوم تحتاج الى مجموعة من المعانى يكمل بعضها بعضا .", "يقول الأستاذ البنا عن دعوتنا : « ثم يقف بنا كذلك أمامها كدعوة من الدعوات التجديدية لحياة الأمم والشعوب التي ترسم لها منهاجا جديدا تؤمن به وتسير عليه » ، وبمناسبة كلامه عن هذه الناحية يقول : « ولكن لب دعوتهم - أى الاخوان - فكرة وعقيدة يقذفون بها في نفوس الناس يتربى عليها الرأى العام وتؤمن بها القلوب وتجتمع من حولها"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0023.png"}, {"n": 24, "paras": ["الأرواح تلك هي مبادىء العمل للإسلام والعمل به في نواحي الحياة » . وفي مكان آخر يقول : « والوسائل العامة لدعوات لا تتغير ولا تتبدل ولا تعدو هذه الأمور الثلاثة :", "(١) الايمان العميق ، (٢) التكوين الدقيق ، (٣) العمل المتواصل » . وفي مكان آخر يتحدث عن أركان الوسيلة فيذكر منها ثلاثة :", "(١) المنهاج الصحيح ، (٢) المؤمنون العاملون ، (٣) القيادة الحازمة الموثوق بها .", "من استعراضنا لهذه النقاط السريعة ندرك المهمة الكبرى الأولى لنا وهي عملية التجديد في الأمة الاسلامية . كما ندرك واحدا من أهم ما تحتاجه هذه العملية وهي في تعبير الأستاذ البنا : « القيادة الحازمة الموثوق بها » . ان كل عمل ينطلق من غير هذه البداية هو عمل يفقد القابلية للبقاء والاستمرار فضلا عن كونه يستحيل عليه أن يؤدى دوره . ومن ثم كانت نقطة البداية هي هذه القيادة القادرة على التجديد والتحقيق والنقل والقيام بالواجبات كلها . بحيث تسع احتياجات الجماعة والأمة لذا فان البحث عن العناصر القيادية الاسلامية وتأهيلها واعطائها دورها شيء أساسي وهام في العمل الاسلامي ، ويجب أن يتقن الطريق اليه اتقانا كاملا . ولعل هذه الرسالة ستؤدى جزءا من هذه المهمة . هذه القيادة عليها أن تحقق الايمان العميق وأن تتولى عملية التكوين الدقيق وأن تعتاد العمل المتواصل على ضوء المنهاج الصحيح وبالتعاون مع المؤمنين العاملين . ما هي شروط هذه القيادة ؟ ما هي مواصفاتها ؟ كيف تعمل ؟ وكيف تتصرف ؟ ما هي أخلاقيتها وكفاءتها ؟ خطها وأساليبه تحركها وغير ذلك ؟ كل ذلك ينبغى أن يكون واضحا منذ البداية .", "٢ - نقل الأمة كمقدمة لنقل العالم . ان من أول مهمات الجماعة أو القيادة هي نقل المسلم ونقل المسلمين . فالمسلم الحالي ضعف شعوره باسلامه ومعنى انتسابه اليه ، كما ضعف شعوره بأنه واحد من أمة هي الأمة الاسلامية ؛ ومن ثم فأول أعمالنا هي اشعار المسلم باناه الاسلامي واناه الجماعي أو بتعبير آخر : ان كثيرين من المسلمين يشعرون بارتباطهم العام الى حد ما بالاسلام ومؤسساته العامة ولكن شعورهم بالاسلام وارتباطهم الخاص به وبأهله والذى يظهر في ربط المصير واعطاء الطاعة والولاء لجماعة"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0024.png"}, {"n": 25, "paras": ["المسلمين ، فهذا يكاد يكون معدوما ومن ثم فان أول مهمات الجماعة أن تنقل المسلم الى الشعور بذاته كمسلم والى الشعور باسلامه وارتباطه بالمسلمين ، ثم أن تنقله الى سقفه الأعلى في الاسلام وأن تضمه الى الصف ليتم من خلال ذلك نقل الأمة الاسلامية من طور الى طور ومن حال الى حال . حتى تتحقق الأهداف المحلية والعالمية على هذه الأرض . أن هاتين المهمتين الكبيرتين لا نعرف كيفية أدائهما على الوجه الأكمل الا اذا فهمنا رسالة التعاليم ولذلك فقد جعلنا الكلام عنهما احدى المقدمات لهذه الرسالة ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0025.png"}, {"n": 26, "paras": ["الباب الرابع", "في الأهداف", "ليس للاخوان المسلمين أهداف يبتدعونها ولكن فرض الاسلام على المسلمين أن يحققوا أهداف ويعملوا من أجلها ويبذلوا النفس والنفيس في سبيلها ، هذه الأهداف الاسلامية منها ما له علاقة بالانسان رجلا كان أو امرأة ومنها ما له علاقة بالأسرة ومنها ما له علاقة بالحرفة والعمل ومنها ما له علاقة بالشعوب ومنها ما له علاقة بالحكومات ، ومنها ما له علاقة في العالم كله ومنها ما له علاقة في الجانب السياسي ، ومنها ما له علاقة في الجانب الاقتصادي ومنها ما له علاقة في الجانب العسكري ، ومنها ما له علاقة في الجانب التعليمي والتربوي والاعلامي ، ومنها الأهداف المرحلية ، ومنها الأهداف الدائمة ، ومنها الأهداف الفرعية ، ومنها الأهداف الأصلية ، ومنها الهدف الدنيوي ، ومنها الهدف الأخروي ، ومنها الهدف المادي ، ومنها الهدف الغيبي . وكل ذلك متداخل متصل بعضه ببعض والأمر كبير لا يستوعبه الا من استوعب الأصول والفروع ، والا من استوعب نصوص الكتاب والسنة ، وعلم أصول الفقه وعلم الفقه في مدارسه الاسلامية كلها ، وهو باب واسع جدا ولذلك فان الاخوان المسلمين لم يبذلوا جهدا خاصا لاستقصاء الأهداف لاستحالة الاحاطة وتكون دراسة هذه الأمور كلها من مناهجهم . ومن ثم فلا يغيب عادة عن الأخ الذي سار في المناهج هدف رئيسي وكلما ازداد دراسة زاد معرفة بالأهداف ، والقيادات الرشيدة لا يفوتها ادراك أهدافها وطرق الوصول الى اقامتها .", "وقد أجمل الأستاذ البنا الأهداف الرئيسية للجماعة في أكثر من مكان من رسائله ، وكل ما ذكره الأستاذ البنا رحمه الله هو من الأهداف التي يفترض على كل مسلم أن يعمل لها بقدر وسعه ولذلك فقد لخصها"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0026.png"}, {"n": 27, "paras": ["في رسالة التعاليم وجعل العمل لها أحد أركان البيعة في دعوة الإخوان المسلمين فذكرها تحت ركن العمل . ولأن هذا الأمر يحتاج إلى تفصيل كثير فقد عقدنا له بابا هنا وسيمر معنا فيما بعد أثناء عرضنا لرسالة التعاليم ، نقول هذا ليعلم أن هذا الباب من صلب شرح رسالة التعاليم . ونحن سنسير في هذا الباب بأن نذكر بعض ما قاله الأستاذ البنا في غير رسالة التعاليم حول موضوع الأهداف ثم نذكر ما قاله الأستاذ البنا في رسالة التعاليم ثم نذكر ما يدخل في كل هدف ثم نذكر فصلا مكملا لتوضيح موضوع الأهداف .", "يقول الأستاذ البنا : « والخلاصة نحن نريد الفرد المسلم والبيت المسلم والشعب المسلم والحكومة المسلمة والدولة التي تقود الدول الإسلامية وتضم شتات المسلمين وتستعيد مجدهم وترد عليهم أرضهم المفقودة وأوطانهم المسلوبة وبلادهم المغصوبة ثم تحمل علم الجهاد ولواء الدعوة إلى الله حتى تسعد العالم بتعاليم الإسلام » . وقال الأستاذ : « اذكروا دائما أن لكم هدفين أساسيين :", "١ - أن يتحرر الوطن الإسلامي من كل سلطان أجنبي وذلك حق طبيعي لكل إنسان لا ينكره إلا ظالم جائر أو مستبد .", "٢ - أن يقوم في هذا الوطن الحر دولة إسلامية حرة تعمل بأحكام الإسلام وتطبق نظامه الاجتماعي وتعلن مبادئه القويمة وتبلغ دعوته الحكيمة إلى الناس وما لم تقم هذه الدولة فان المسلمين جميعا آثمون مسئولون بين يدى الله العلى الكبير عن تقصيرهم في إقامتها وقعودهم عن إيجادها » . هذا مجمل ما ذكره الأستاذ البنا عن الأهداف في غير رسالة التعاليم . وأما في رسالة التعاليم فقد قال : « ومراتب العمل المطلوبة من الأخ الصادق :", "١ - إصلاح نفسه حتى يكون : قوى الجسم ، متين الخلق ، مثقف الفكر ، قادرا على الكسب ، سليم العقيدة ، صحيح العبادة ، مجاهدا لنفسه ، حريصا على وقته »"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0027.png"}, {"n": 28, "paras": ["٢ - وتكوين بيت مسلم : بأن يحمل أهله على احترام فكرته والمحافظة على آداب الاسلام في كل مظاهر الحياة المنزلية ، وحسن اختيار الزوجة ، وتوقيفها على حقها وواجباتها ، وحسن تربية الأولاد ، والخدم ، وتنشئتهم على مبادىء الاسلام ، وذلك واجب كل أخ مسلم على حدة كذلك .", "٣ - وارشاد المجتمع : بنشر دعوة الخير فيه ومحاربة الرذائل والمنكرات وتشجيع الفضائل والأمر بالمعروف والمبادرة الى فعل الخير ، وكسب الرأى العام الى جانب الفكرة الاسلامية وصبغ مظاهر الحياة العامة بها دائماً . وذلك واجب كل أخ على حدة ، وواجب الجماعة كهيئة عاملة .", "٤ - وتحرير الوطن : بتخليصه من كل سلطان أجنبي - غير اسلامى - سياسى أو اقتصادى أو روحى .", "٥ - واصلاح الحكومة : حتى تكون اسلامية بحق ، وبذلك تؤدى مهمتها كخادم للأمة وأجير عندها ، وعامل على مصلحتها . والحكومة اسلامية ما كان أعضاؤها مسلمين مؤدين لفرائض الاسلام غير مجاهرين بعصيان ، وكانت منفذة لأحكام الاسلام وتعاليمه . ولا بأس بأن تستعين بغير المسلمين عند الضرورة في غير مناصب الولاية العامة . ولا عبرة بالشكل الذى تتخذه وبالنوع ما دام موافقا للقواعد العامة في نظام الحكم الاسلامى . ومن صفاتها : الشعور بالتبعة والشفقة على الرعية ، والعدالة بين الناس ، والعفة عن المال العام والاقتصاد فيه . ومن واجباتها : صيانة الأمن ، وانفاذ القانون ، ونشر التعليم ، واعداد القوة ، وحفظ الصحة ، ورعاية المنافع العامة ، وتنمية الثروة ، وحراسة المال ، وتقوية الأخلاق ، ونشر الدعوة . ومن حقها : متى أدت واجباتها : الولاء ، والطاعة ، والمساعدة بالنفس والمال . فاذا قصرت : فالنصح والارشاد ، ثم الخلع والابعاد ، ولا طاعة لمخلوق في معصية الخالق ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0028.png"}, {"n": 29, "paras": ["٦ - وإعادة الكيان الدولي للأمة الإسلامية : بتحرير أوطانها ، وإحياء مجدها ، وتقريب ثقافاتها ، وجمع كلمتها حتى يؤدي ذلك إلى إعادة الخلافة المفقودة والوحدة المنشودة .", "٧ - وأستاذية العالم : بنشر دعوة الإسلام في ربوعه حتى لا تكون فتنة ، ويكون الدين كله لله « ويأبى الله إلا أن يتم نوره » ( التوبة : ٣٢ ) . وهذه المراتب الأربعة الأخيرة تجب على الجماعة متحدة ، وعلى كل أخ باعتباره عضوا في الجماعة . ما أثقلها تبعات ، وما أعظمها مهمات يراها الناس خيالا ، ويراها الأخ المسلم حقيقة . ولن نيأس أبدا . ولنا في الله أعظم الأمل : « والله غالب على أمره ، ولكن أكثر الناس لا يعلمون » ( يوسف : ٢١ ) .", "هذه الفقرة من رسالة التعاليم ستمر معنا مرة ثانية أثناء عرضنا لرسالة التعاليم ، ولكن لأن هذه الفقرة تحدد أهداف حركة الإخوان المسلمين التي جاءت رسالة التعاليم لتكوين الشخص القادر على تحقيقها بإذن الله فقد أفردناها هنا وأحببنا من خلالها أن نفصل في موضوع أهداف الإخوان المسلمين كمقدمة من مقدمات الكلام عن رسالة التعاليم .", "فصل : فيما يدخل في كل هدف سنحاول في هذا الفصل أن نذكر ما يدخل في كل هدف من الأهداف من معان على ضوء كلام الأستاذ البنا نفسه وعلى ضوء النصوص . أقول وبالله المستعان :", "١ - الفرد المسلم الذي نريده هو القوي الجسم ، المتين الخلق ، المثقف الفكر ، القادر على الكسب ، السليم العقيدة ، الصحيح العبادة ، المجاهد لنفسه ، الحريص على وقته ، المنظم في شئونه ، النافع لغيره ، الذي يحمل أهله على احترام فكرته ، والمحافظ على آداب الإسلام في كل مظاهر الحياة المنزلية ، والذي يحسن اختيار الزوجة ، والذي يوقف زوجته على حقوقها وواجباتها ، والذي يحسن تربية أولاده ، ومن له نوع ولاية عليه فينشئهم على مبادىء الإسلام ، والذي يرشد المجتمع بنشر دعوة الخير فيه ، والذي يحارب الرذائل والمنكرات ويشجع"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0029.png"}, {"n": 30, "paras": ["الى جعل الرأى العام بجانب الاسلام ويسعى الى صبغ مظاهر الحياة العامة بالاسلام . ويسعى الى تحرير الوطن الاسلامي بتخليصه من كل سلطان أجنبي غير اسلامي ، سياسي أو اقتصادي أو روحي ويسعى الى أن تكون حكومته اسلامية بحق ، كما يسعى الى اعادة الكيان الدولى للأمة الاسلامية بتحرير أوطانها ، وأحياء مجدها ، وتقريب ثقافتها ، وجمع كلمتها . كما يسعى الى اعادة الخلافة المفقودة والوحدة المنشودة ، كما يسعى الى أستاذية العالم ، بنشر دعوة الاسلام في ربوعه حتى لا تكون فتنة ويكون الدين كله لله .", "٢ - البيت المسلم الذي نريده هو البيت الذي يعرف فيه الزوج والزوجة حقوقهما وواجباتهما ويلتزمان بهما ، ومن ذلك احسان تربية الأولاد والخدم وتنشئتهم على مبادىء الاسلام ، ومن ذلك المحافظة على آداب الاسلام في كل مظاهر الحياة المنزلية ، والزوجة المثالية هي التي ذكر الله مواصفاتها مختارا اياها لرسول الله صلى الله عليه وسلم بقوله : (( عسى ربه ان طلقكن ان يبدله أزواجا خيرا منكن مسلمات مؤمنات قانتات تائبات عابدات سائحات )) ( التحريم : ٥ ) . سواء أكانت ثيبة أو بكرا . قال تعالى في تتمة الآية : (( ثيبات وأبكارا )) ( التحريم : ٥ ) فالاسلام والايمان والطاعة والتوبة والعبادة والصوم هي سمات الزوجة المسلمة .", "ولن تتحقق مسلمة بالطاعة الا اذا كانت صالحة . قال تعالى : (( الرجال قوامون على النساء بما فضل الله بعضهم على بعض وبما أنفقوا من أموالهم ، فالصالحات قانتات حافظات للغيب بما حفظ الله )) ( النساء : ٣٤ ) . والبيت المسلم ينبغى أن يكون أفراده ملتزمين بالزى الاسلامي في حدوده الدنيا على الأقل ، ومن ذلك في حق المرأة ، أن تكون ثيابها سابغة لا تصف ولا تشف ، وينبغى أن تنشأ البنات على ذلك ، والأم هي القدوة فيه .", "والبيت المسلم لا يدخله شيء محرم ، ولا يعلق على جدرانه شيء محرم ، ولا يكون باطنه مكشوفا لمن هو خارجه . والبيت المسلم الكامل هو البيت الملتزم بمبادىء الاخوان المسلمين لأن ذلك هو الكمال الاسلامي المعاصر . ولذلك جعل الأستاذ البنا من واجبات الأخ العامل التزام المنزل مبادىء الاخوان المسلمين .", "٣١ - في آفاق التعاليم !"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0030.png"}, {"n": 31, "paras": ["والبيت المسلم بيت يؤهل الأبناء في مرحلة ما قبل البلوغ بكل ما يلزمهم للقيام بحق الله في مرحلة ما بعد البلوغ بحيث يأخذ بيدهم بعد البلوغ على طريق الرشاد . والبيت المسلم بعيد عن مظاهر المتع الفانية ، بعيد عن كل ما هو غير إسلامي .", "وقد جعل الأستاذ البنا من واجبات الأخ المجاهد ما يلي : قال : الزهادة والعزوف عن مظاهر المتع الفانية والبعد عن كل ما هو غير إسلامي في العبادات وفي المعاملات وفي شأنه كله وجزء رئيسي مما مر قضية تربية الأبناء وضبط الأخ لتصرفات من له ولاية عليه ، ونصح كل من له صلة قرابة به وتذكيره ودعوته . ان أبناء المسلمين اليوم في العالم هم أقل الأبناء رعاية . ومن ثم فعلى الآباء أن ينتبهوا وأن يعرفوا وأن يلاحظوا أن مرحلة ما قبل البلوغ مرحلة تأهيلية لما بعد البلوغ فكل ما يلزم المسلم بعد البلوغ ينبغي أن يدرب عليه قبل ذلك . فالمسلم مكلف بأمور كثيرة في العقائد والعبادات والآداب والأخلاق والمعاملات ، كما أنه مكلف بالجهاد والأعداد والاستعداد له ، وهذا يقتضي تدريبا جسميا ونفسيا . والمسلم لا ينبغي أن يكون عالة على الآخرين وهذا يقتضي أن يكون له حرفة ، وعلى الآباء أن يعرفوا ذلك وأن يؤهلوا أبناءهم في شأنه . وعلى الآباء أن يربوا أبناءهم على الاسلام ومحبة أهله ، كما وأن يربوهم على الايمان ويعودوهم على العبادات .", "فقد أمر الرسول صلى الله عليه وسلم أن يؤمر الأبناء بالصلاة وهم أبناء سبع وأن يضربوا عليها وهم أبناء عشر ، وقاس العلماء الصوم على الصلاة ، ويعودونهم على الانفاق والآداب والقتالية ويدربونهم ومنها معاشهم ويربونهم على الروح الجهادية والقتالية ويدربونهم . ومن ثم أمر الخليفة الراشد أن يعلم الأبناء الرماية والسباحة وركوب الخيل وأن يعودوا أن يثبوا على الخيل وثبا . ويدخل في هذا ركوب الدراجات والسيارات زيادة على ركوب الخيل . وإذا لم يكن للأبن أبوان فعلى وليه أو على أهل حيه أو قريته أن يقوموا بذلك ويلحظ في حق البنت أنها ستكون زوجة وأما وربة بيت وهذا يقتضي مزيد ملاحظة . وليعلم المسلم أن الذي لا ينجح في تربية أبنائه وأهله فانه في الغالب يدلل عن عجزه عن تربية الناس وقيادتهم . ان تعويد الأبناء على الخير كله وعلى أدب الحياة كله واجب اسلامي لا يسع مسلما أن يتخلف عنه ، ومن"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0031.png"}, {"n": 32, "paras": ["أهم ما ينبغى أن يركز عليه الآباء في تربيتهم للأبناء قضايا العفة والستر وضبط الشهوة الجنسية والنأى بأنفسهم عن مواطن الفساد وصحبه أهل الريب ، وعليهم أن يعودوا الأبناء على محبة الزى الاسلامى والهيئة الاسلامية .", "٣ - والشعب المسلم الذي نريده هو الذي أسلم لله وجهه ، واستجاب لدعوة الخير ، وحارب الرذيلة والمنكر ، وتمت فيه الفضائل وخصائص الانسان وأخلاق الربانيين ، وصبغ حياته كلها بصبغة الاسلام ظاهرا وباطنا ، وأصبحت مفاهيمه اسلامية ، وتصوراته اسلامية ، ومواقفه اسلامية ، وتخلص من كل تناقض فيما بين ذاته وبين هذا الاسلام ، وتعامل مع أناس كلهم على ضوء ذلك فهو في علاقاته مع المواطنين من غير المسلمين يطبق أحكام الاسلام ، وهو في علاقاته مع كل مسلمى العالم ملتزم بالاسلام ، وهو في علاقاته مع العالم كله ملتزم بالاسلام ، وهو لا يخرج في تصرفاته كلها عن قواعد العدل والرحمة ومبادىء الحق والاحسان ، وهى أمور ليس غير الاسلام يعطيها مضمونها الصحيح السليم ؛ عقله مسلم وقلبه مسلم وعواطفه اسلامية ، مؤمن عامل للصالحات ، متواص بالحق والصبر ، متناصح ، مؤمن بالشورى ويلتزم بها ويخضع لها ، متطلع نحو الآخرة ، لا يعطى الدنيا أكثر من وزنها ومما تستحقه ، فهى مرحلة الى الآخرة . متوكل على الله ، معتمد عليه . يكره الفواحش كلها ويجتنبها ، ويكره الذنب كله ، شعب متعاطف بعضه مع بعض يحب بعضه بعضا ، تراحم ، لا يحمل أفراده الغضب على الخطأ ، بل المسامحة هي الأصل الذي يحكمهم ، مستجيب لأمر الله تعالى ، مقيم للصلاة منفق في سبيل الله ، يرفض الظلم ولا يقبله . قال تعالى : « والذين إذا أصابهم البغى هم ينتصرون » ( الشورى : ٣٩ )", "٤ - ونريد الحكومة الاسلامية في كل قطر اسلامى ، ان هدفا من أهدافنا أن تقوم الحكومة الاسلامية في كل قطر اسلامى وذلك فريضة اسلامية على أهل كل قطر في عصرنا ؛ اذ أصبح التدخل الخارجي مرفوضا دوليا ، ويمكن أن يترتب عليه مضاعفات ومشاكل للدولة المتدخلة قد لا تحمد عقباها . ومن ثم أصبح جهاد كل قطر اسلامى من أجل اقامة حكومته الاسلامية هو الطريق الوحيد تقريبا للوصول الى الحكم الاسلامى في القطر ، وذلك فريضة والعمل من أجل ذلك بطريقه فريضة شرعية ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0032.png"}, {"n": 33, "paras": ["على كل مسلم ومسلمة . لقد فرض الله على المسلمين اقامة شريعته فقال : « يا أيها الذين آمنوا كتب عليكم القصاص » ( البقرة : ١٧٨ ) وقال : « سورة أنزلناها وفرضناها » ( النور : ١ ) وقال : « فلا جناح عليكم فيما فعلن في أنفسهن بالمعروف » ( البقرة : ٢٣٤ ) وكل ذلك يدل على مفروض على المسلمين أن يقيموا شريعة الله ولن يتم ذلك بدون حكومة اسلامية في كل قطر ، تحكم بشريعة الله . وكل ما لا يتم الواجب الا به فهو واجب . وما دام هذا الواجب لم يقم فان على كل مسلم ومسلمة العمل من أجله بالقدر المستطاع حتى يقوم . وكل ما يحتاجه هذا هو من باب الفرائض وأول ما تتوجّه الفريضة في شأنه على القادرين عليه وقد حدد الأستاذ البنا مواصفات الحكومة الاسلامية فقال : « والحكومة اسلامية ما كان أعضاؤها مسلمين ، مؤدين لفرائض الاسلام ، غير مجاهرين بعصيان ، وكانت منفذة لأحكام الاسلام وتعاليمه ، ولا بأس بأن تستعين بغير المسلمين عند الضرورة في غير مناصب الولاية العامة . ولا عبرة بالشكل الذي تتخذه ولا بالنوع ما دام موافقا للقواعد العامة في نظام الحكم الاسلامي . ومن صفاتها الشعور بالتبعة ، والشفقة على الرعية ، والعدالة بين الناس ، والعفة عن المال العام والاقتصاد فيه . ومن واجباتها : صيانة الأمن ، وانفاذ القانون ، ونشر التعليم ، واعداد القوة ، وحفظ الصحة ، ورعاية المنافع العامة ، وتنمية الثروة ، وحراسة المال ، وتقوية الأخلاق ، ونشر الدعوة ، ومن حقها متى أدت واجباتها : الولاء والطاعة والمساعدة بالنفس والمال ، فاذا قصرت فالنصح والارشاد ، ثم الخلع والابعاد ، ولا طاعة لمخلوق في معصية الخالق » . ومن كلام الأستاذ البنا في نفس الفقرة : « واصلاح الحكومة حتى تكون اسلامية بحق وبذلك تؤدى مهمتها كخادم للأمة وأجير عندها وعامل على مصلحتها » .", "ان هذا الهدف من أهدافنا وهو اقامة الحكومة الاسلامية في كل قطر فيه لبس كثير وهذا يقتضى وقفات كثيرة هي بمثابة شروح وتوضيحات حتى لا يبقى لبس ولا غموض ولا اعتراض ولا تساؤل ولا تشكيك . أولا : قال الأستاذ البنا : « والحكومة اسلامية ما كان أعضاؤها مسلمين ، مؤدين لفرائض الاسلام ، غير مجاهرين بعصيان ، وكانت منفذة لأحكام الاسلام وتعاليمه » . بهذه الفقرة أعطانا الأستاذ ميزانا تزن به كل حكومة ، فالحكومة لا تكون اسلامية الا اذا كان رجالها"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0033.png"}, {"n": 34, "paras": ["مسلمين ملتزمين ، وكانت أنظمتها ولوائحها وقوانينها ودستورها وارتباطاتها اسلامية . ولا انفصال بين هذا وهذا . حتى ان رسولنا عليه السلام أجاز لنا القتال اذا ترك الحكام الصلاة أو وجد الكفر البواح ، وأفتى فقهاء الحنفية وغيرهم بأن الامام اذا فسق يستحق العزل . وفى واقعنا نجد أن الأمر في أكثر الجهات متفلت فلا التزام في الاسلام لا في سلوك الحكام ولا فيما يطبق من أحكام . ثانياً: وقال الأستاذ البنا : « ولا بأس بأن تستعين بغير المسلمين عند الضرورة في غير مناصب الولاية العامة » هذه القضية من أهم القضايا التي تواجهها الحركة الاسلامية اذ في كل قطر توجد أقلية أو أكثرية من غير المسلمين وبحجة هذه الأقليات يطرح بعضهم فكرة أنه لا يجوز تطبيق الاسلام دوليا وعالميا ولأسباب محلية . والذى نقوله : ان فقهاء المسلمين بين متشدد في هذا الموضوع أو متساهل . فقد تشدد بعضهم حتى لم يبيحوا أن يتسلم غير المسلم وظيفة كاتب . وتوسع بعضهم حتى أجاز أن يتسلم غير المسلم بعض الوظائف التنفيذية . والذى نراه أن هذه المعانى تحكمها عهودنا ومواثيقنا والتزاماتنا . أنه بالامكان أن نعقد ميثاقا تعاقديا مع غير المسلمين في كل قطر وعلى ضوئه يكون التعامل بعد السلطة ، ونبقى ملتزمين به كما فعل رسول الله صلى الله عليه وسلم في مواثيقه مع يهود المدينة ، ويبدو أننا نستطيع أن نعطيهم الكثير في مقابل أن يسلموا ببعض المسلمات ، وبشكل عام : « لهم ما لنا وعليهم ما علينا » .", "بل ذكر فقهاء المسلمين أن المسلم لو أراق خمر ذمى فإنه يضمن ثمنه ، ولو قتل خنزير ذمى فإنه يضمنه ولا يضمن مثل ذاك للمسلم ، وفى قضايا الأحوال الشخصية فإنه يمكن أن يحكم قانونهم ومحاكمهم المرتبطة بوزارة العدل ، بل يستطيعون في كل قضية خاصة بهم أن يحتكموا الى محاكمهم ودوائرهم الخاصة ، أما اذا رغبوا أن يحتكموا الينا أو كانت القضية فيما بينهم وبين المسلمين فالشريعة الاسلامية هي الحكم . وعنى كل فان هذه المعانى وغيرها يضبطها كما قلنا الميثاق المشترك بيننا وبينهم وعلى ضوئها ينبثق القانون والدستور ، والمسألة في كل الأحوال منوطة برأى الجماعة الاسلامية واجتهاداتها . ثالثا : قال الأستاذ البنا : « ولا عبرة بالشكل الذي تتخذه ولا بالنوع ما دام موافقا للقواعد العامة في نظام الحكم الاسلامي » ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0034.png"}, {"n": 35, "paras": ["هذه النقطة مهمة جداً في كلام الأستاذ البنا . ففي واقعنا الحالي نجد أقطاراً تعتمد النظام الملكي ، وأخرى تعتمد شبيها به ، وأخرى تعتمد النظام الجمهوري ، وأخرى تعتمد أنظمة مختلفة . وفي سيرنا نحو الدولة الإسلامية الواحدة ، وفي سيرنا في كل قطر تحكمنا هذه القاعدة التي قالها الأستاذ البنا ولابد من التفريق بين الرئاسة العليا للدولة الإسلامية الواحدة وبين ما سوى ذلك . فالرئاسة العليا للدولة الإسلامية الواحدة نحن محكومون بنصوص محددة وبسنة الخلافة الراشدة ، ومن ثم فعندنا صيغة واحدة هي صيغة الخلافة والامامة وأمرة المؤمنين ، فالكلام اذن فيما سوى ذلك . فقد حدث في التاريخ أن قامت ولايات إسلامية على رأسها سلطان أو أمير للمسلمين وكلها تعترف للخلافة بسلطان عليها ولو كان اسميا . وقد كان في سنة رسول الله صلى الله عليه وسلم أنه اذا دخل أحد في الاسلام فانه يزيده ولا ينقصه فمن كان أميراً أبقاه على امرته وهكذا .. ونحن اذا اعتمدنا هذا المبدأ بتوسع فان مسيرتنا ستأخذ طابعا أقل عنفا ، ونستطيع بذلك أن نتجاوز أوضاعاً تصبح مؤيدة لنا بدلا من أن تصبح حربا علينا . ولنرجع الى عبارة الأستاذ : « ولا عبرة بالشكل الذي تتخذه ولا بالنوع ما دام موافقا للقواعد العامة في نظام الحكم الاسلامي » وقد نجد أن هناك أنظمة لسنا بحاجة الى أن ندخل في صراع معها فعلينا أن نسعى لتطويرها نحو اسلامية أكثر وأجود .", "ومن ثم فان أهلها يستطيعون أن يطمئنوا على أنفسهم وتكن الشرط هو موافقة هذه الأنظمة للقواعد العامة في نظام الحكم الاسلامي من وجود المؤسسات الشورية ومن وجود الالتزام بحاكمية الله المتمثلة بالخضوع للكتاب والسنة ، فدستورها اسلامي ، وقوانينها اسلامية ، وهناك التزام عملي بالاسلام عند رجالات الحكم ، وسياستها الخارجية منسجمة مع مبادىء الاسلام ، وهي قائمة بخدمة الأمة وتصرفاتها كلها منسجمة مع مصلحتها وقد رأينا تحديد الأستاذ البنا لبعض مواصفاتها بقوله : « ومن صفاتها الشعور بالتبعة والشفقة على الرعية ، والعدالة بين الناس ، والعفة عن المال العام والاقتصاد فيه . ومن واجباتها صيانة الأمن ، وانفاذ القانون ، ونشر التعليم ، واعداد القوة ، وحفظ الصحة ، ورعاية المنافع ، وتنمية الثروة ، وحراسة المال ، وتقوية الأخلاق ، ونشر الدعوة . ومن حقها"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0035.png"}, {"n": 36, "paras": ["متى أدت واجبها : الولاء والطاعة والمساعدة بالنفس والمال ، فاذا قصرت فالنصح والارشاد ، ثم الخلع والابعاد ؛ ولا طاعة لمخلوق في معصية الخالق » ، ان هناك أنظمة لا يمكن أن يكون بيننا وبينها الا الصراع ، وهناك أنظمة يمكن أن نقدم لها كل الدعم اذا قبلت أمورا أربعة : (أ) أن يكون دستورها وقوانينها اسلامية . (ب) أن تسير في طريق تسليم أجهزة الحكم للملتزمين بالاسلام . (ج) أن تكون سياستها الخارجية منسجمة مع المبادىء الاسلامية . (د) أن لا تتنكر لسيرنا العام نحو اقامة الاسلام محليا وعالميا ، وهذا الشرط الأخير يصوغه الأستاذ البنا بقوله : « يجب على الاخوان المسلمين اذا أيدوا هيئة ما من الهيئات أن يستوثقوا أنها لا تتنكر لغايتهم في وقت من الأوقات » .", "يحاول الكثيرون أن يقولوا بأنكم أيها الاخوان المسلمون لستم واقعيين فيما تريدون من أهداف ، فأنتم تحملون شعار الدولة الاسلامية دون أن تعرفوا ماهيتها ، وأنتم تحاربون أوضاعا ليس من الواضح ما هو الجزء الذي تحاربونها بسببه . والجواب أن هذا ليس صحيحا . هو أوضح أننا نريد الدستور الاسلامي والقوانين الاسلامية والفوارق بين الموجود وبين ذلك قائمة . وواضح أننا نريد التزاما بالاسلام من الصلاة الى الاعتراف لله بالحاكمية .", "وواضح أن هذا ليس موجودا . وواضح أننا نريد دولة تقام بها الصلاة ، وتؤدى بها الزكاة ، ويؤمر فيها بالمعروف بحرية ، وينهى فيها عن المنكر بحرية ، وواضح أن هذا ليس موجودا ؛ وواضح أننا نريد تحقيق أهداف الاسلام في السياسة والاقتصاد والسلم والحرب والاجتماع والتعليم والاعلام ، وواضح أن هذا ليس موجودا . وواضح أننا نريد سياسة خارجية وداخلية اسلاميتين ، وواضح أن هذا ليس موجودا . وفي سلسلة « الأصول الثلاثة » بيان واضح لكثير مما نريد على ضوء الاسلام . وفي سلسلة « في البناء » بيان كذلك لكثير مما نريد فان يتهمنا الآخرون بالغموض فذلك كثير .. على أنه قد يكون من المناسب أن نقدم للناس صورة واضحة عما نريد ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0036.png"}, {"n": 37, "paras": ["ان كثيرين من اخواننا تجرهم شعارات الآخرين الى تبنى مواقف دخيلة علينا فنجد بعض اخواننا يفرق ما بين الفكر الاصلاحي ويرفضه وبين الفكر الثورى ويتبناه وهو أمر عن شعارات شيوعية لا دخل لنا بها . ان أهدافنا اسلامية ووسائلنا اسلامية ولا تقيد أنفسنا بغير ذلك .. والتعبير الذي استعمله الأستاذ البنا كما رأينا هو : « اصلاح الحكومة حتى تكون اسلامية بحق » وقد قال عز وجل : « والذين يمسكون بالكتاب وأقاموا الصلاة انا لا نضيع أجر المصلحين » ( الأعراف : ١٧٠ ) .", "ه - ونريد الدولة الاسلامية النواة ؛ يقول الأستاذ البنا كما مر معنا تحت عنوان « والخلاصة نحن نريد » بعد أن ذكر أننا نريد الحكومة الاسلامية : « والدولة التي تقود الدول الاسلامية وتضم شتات المسلمين وتستعيد مجدهم وترد عليهم أرضهم المفقودة وأوطانهم المسلوبة وبلادهم المغصوبة » فهذا هدف كبير من أهدافنا ، انه قد نستطيع أن نقيم حكما اسلاميا في قطر من الأقطار ، ولكن قد لا يكون هذا القطر وحده مرشحا لقيادة العمل الاسلامي في العالم ، كما أنه ليس مرشحا لقيادة الدول الاسلامية في الطريق الصحيح ، اما لخفة وزنه أو لعزلته أو لضعف مركزه الجغرافي أو السياسي أو الاقتصادي أو لامكانية الاستغناء عنه . وهكذا تظهر ضرورة وجود الدولة النواة التي هي في تعبير الأستاذ البنا : « تقود الدول الاسلامية وتضم شتات المسلمين وتستعيد مجدهم وترد عليهم أرضهم المفقودة وأوطانهم المسلوبة وبلادهم المغصوبة » فهذه مجموعة أمور أو مجموعة واجبات يجب أن تتحملها وتعمل لها الدولة النواة .", "( ١ ) أن تقود الدول الاسلامية ؛ فمركزها في العالم الاسلامي مركز القائد ، والقيادة ليست دعوى ولا مطلبا بل هي عمل راشد ، تسلم بسببه الدول الاسلامية لدولة منها بحق القيادة . وقد يكون العرب من بين شعوب العالم الاسلامي هم المرشحين لهذا الدور أكثر من غيرهم فأذا ما قامت وحدة على الأرض العربية كلها بشكل من الأشكال ذات مضمون اسلامى ، فان العالم الاسلامي سيسلم لهذه الدولة فيأخذ منها ويعطيها ، وتصبح وحدة العالم الاسلامي أو أنواع من الوحدة فيه قريبة جدا ، لأن مجموع الفوائد السياسية والاقتصادية والعسكرية"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0037.png"}, {"n": 38, "paras": ["التي ستأمن للمسلمين نتيجة لذلك لا تعد ، ومن ثم فان دول العالم الاسلامي نفسها سترغب في الاندماج أو الانخراط في هذه الدولة . وان تطوير الجامعة العربية مع نجاح الاسلاميين في كل قطر يمكن أن يكون نقطة انطلاق نحو هذا . (ب) « وتضم شتات المسلمين » ان مهمة الدولة النواة أن تصل الى كل مسلم في العالم فتأخذ منه وتعطيه وتطالبه وتحميه . (ج) « وتستعيد مجدهم » بأن تعيد للمسلمين عز السلطان السياسي للاسلام وترد عليهم أرضهم المفقودة وبلادهم المغصوبة . ان هذه كلها واجبات الدولة الاسلامية النواة ولن تستطيع أن تتحمل هذا العبء الا دولة ذات مواصفات سياسية واقتصادية وعسكرية فهذه وحدها تستطيع أن تعمل ذلك كله أما اذا تصدت دولة لا تملك مؤهلات خاصة فانه لن يترتب على ذلك شيء بل قد يترتب على ذلك خلاف المقصود .", "٦ - ونريد أن تقوم في العالم الاسلامي الدولة الاسلامية الواحدة أو الولايات الاسلامية المتحدة التي يكون عليها خليفة واحد للمسلمين ، ولها حكومة مركزية واحدة . يقول الأستاذ البنا : « وأن يتحرر الوطن الاسلامي من كل سلطان أجنبي » . وأن تقوم في هذا الوطن الحر دولة اسلامية حرة . وقال : « واعادة الكيان الدولي للأمة الاسلامية ، بتحرير أوطانها ، واحياء مجدها ، وتقريب ثقافاتها ، وجمع كلمتها حتى يؤدى ذلك كله الى اعادة الخلافة المفقودة والوحدة المنشودة » . وهذا كله من الفرائض الاسلامية التي أهملها المسلمون ، لذلك يقول الأستاذ : « وما لم تقم هذه الدولة فان المسلمين جميعا آثمون مسئولون بين يدى الله العلى الحكيم عن تقصيرهم في اقامتها وقعودهم عن ايجادها . ومن العقوق للانسانية في هذه الظروف الحائرة أن تقوم فيها دول تهتف بالمبادىء الظالمة ، وتنادى بالدعوات الغاشمة ولا يكون في الناس من يعمل لتقوم دولة الحق والعدالة والسلام . ومن واجبات الدولة كما ذكرها الأستاذ :", "(١) ان تعمل بأحكام الاسلام وذلك فريضة . (ب) تطبيق نظامه الاجتماعي . والمراد بالاجتماعي هنا نظامه كله ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0038.png"}, {"n": 39, "paras": ["(ج) وتعلن مبادئه القويمة فلا تبقى هذه المبادىء مجهولة . ( د ) وتبلغ دعوته الحكيمة للناس فلا يبقى انسان في هذا العالم الا وبلغته دعوة الله وقامت بها الحجة عليه . والملاحظ أن الأستاذ يعتبر اعلان الخلافة الرسمية يأتي في مرحلة متأخرة وفي ذلك مصالح كثيرة . الا أن اعلان الخلافة ولو تأخر فانه لابد أن يعطى أحكام الخلافة ، وقد ذكرنا أكثر من مره قول فقهاء الشافعية : ان الخلافة اذا فقدت تعطى أحكام الخليفة لأعلم أهل زمانه . وأذن فتأخر الاعلان الرسمى للخلافة لا يعنى عدم وجود من يعطى أحكامها . وبالتالى فلا تعطيل ولا ابتداء من غير امام . وان تأخر الاعلان الرسمى للخلافة قد يكون ضروريا ليتم ذلك باتفاق المسلمين جميعا ، وباختيارهم الحر ، وباتفاق أقطارهم ، حتى لا تكون فتنة وفرقة أو تعدد .", "٧ - ونريد اخضاع العالم كله لكلمة الله . قال تعالى : « وقاتلوهم حتى لا تكون فتنة ويكون الدين كله لله » ( الأنفال : ٣٩ ) . وقال : « هو الذى أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون » ( الصف : ٩ ) ويقول الأستاذ البنا : « ثم تحمل - أى الدولة الاسلامية - علم الجهاد ولواء الدعوة إلى الله حتى تسعد العالم بتعاليم الاسلام » ويقول مفسرا : « وأستاذية العالم بنشر دعوة الاسلام في ربوعه « حتى لا تكون فتنة ويكون الدين كله لله » ( الأنفال : ٣٩ ) « ويأبى الله الا أن يتم نوره » ( التوبة :", "٣٢ ) ورسولنا صلى الله عليه وسلم بشرنا بما يفيد قيام دولة اسلامية عالمية . وبشرنا بفتح روما بعد القسطنطينية .", "والخير في آخر هذه الأمة مرتجى كما هو في أولها ، لقوله صلى الله عليه وسلم : « أمتى كالمطر لا يدرى آخره خير أم أوله » أو كما قال صلى الله عليه وسلم . وذلك كله كائن قبل نزول المسيح عليه السلام وظهور المهدى لا كما يتوهمه كثير من العامة ، وفيما بيننا وبين ذلك لابد من اتقان العمل واحسانه فهناك الواجب الدائم والواجب المرحلى ، وهذه الأهداف السبعة التي تعرضنا لها في هذه الفقرات السبع الأخيرة يتوقف بعضها على بعض فاقامة الدولة المسلمة في كل قطر مرحلة لوجود الحكومة الاسلامية في الدولة النواة وهذه مرحلة"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0039.png"}, {"n": 40, "paras": ["القوة الاسلامية العالمية وهذه مرحلة لما بعدها . يقول الأستاذ البنا في خاتمة الكلام عن مراتب العمل : « وما أثقلها من تبعات ، وما أعظمها مهمات ، يراها الناس خيالا ، ويراها الأخ المسلم حقيقة ولن نيأس أبدا . ولنا في الله أعظم الأمل « والله غالب على أمره ، ولكن أكثر الناس لا يعلمون » ( يوسف : ٢١ ) .", "في كل ما مر معنا من أهداف ذكرها الأستاذ لاحظنا أن الهدف الأصيل هو اقامة الاسلام ، ويدخل في ذلك اقامة أركان الاسلام ، واقامة أنظمة الاسلام السياسية والاجتماعية والاقتصادية والعسكرية والأخلاقية والتعليمية والاعلامية . ويدخل في ذلك اقامة مؤيدات الاسلام البشرية ويدخل في ذلك كل ما يستلزمه من لوازم ، فالواجب هدف وما يستلزمه الهدف فهو واجب وتفصيل ذلك واسع .", "فصل مكمل", "لعله من المناسب هنا أن نتحدث عن أمور متعددة تحتاج الى وضوح مما له علاقة في الأهداف تتكامل فيها الصورة وتنهار بها بعض الاعتراضات ولذلك نقول : كثيرون من الناس لا يعرفون النظام الذي يريده دعاة الاسلام ، ولربما رغب دعاة الاسلام ألا يفصلوا ، حرصا على أن يبقى الهدف العام هو الاسلام الخالص ، وذلك أن التفصيلات يتفرع عنها دخول في متاهات من النقاش والجدال والأخذ والرد ، ربما أبعدت عن القضية الأساسية ، وكثيرون من الناس يتصورون أن الدولة الاسلامية تعنى تخلفا وقصورا عن روح العصر . وكثيرون من الناس يتصورون أن الاسلام يعنى سلب الناس كثيرا مما يحبونه ويرتاحون اليه . ويحاول الكثيرون أن يوهموا طبقات من الناس أن تطبيق الاسلام يعنى سلب هذه الطبقات كثيرا من مكاسبها التي أعطتهم اياها أنظمة أخرى ، أو قطع الطريق على مكاسب يمكن أن يعطيهم اياها الآخرون . وكثيرون من الناس يعتبرون أن كلمة كل متدين ولو كان أميا تعنى الاسلام ولو كان كلامه خاطئا . وكثير من الناس لا يفرقون بين طروح بعض"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0040.png"}, {"n": 41, "paras": ["والانسان ، وبين طروح العلماء الحقيقيين . وكثيرون من الناس. يتصورون بأن العالم سينقض علينا انقضاضا رهيبا بمجرد تبنينا اسم الاسلام ، ويتصورون أننا سنلاقى أفضع أنواع الضغوط نتيجة لذلك ، وهذا كله يقتضى منا حدا أدنى من الكلام .", "١ - ان النظام الذي نريده هو النظام المريح لكل أفراد الشعب الا الذين يظلمون فهؤلاء يجب ان يحمنوا على الجادة . والنظام المريح هو الذي تتوافر فيه برأينا مجموعة خصائص :", "( أ ) النظام التي تتأمن فيه سيادة القانون العادل ، ونحب هنا أن نؤكد على كلمة العادل فلا تكفى سيادة القانون وحدها ، بل لابد أن يكون القانون عادلا . ولا قانون أكثر عدلا من شريعة الله عز وجل . وقد رأينا من قبل أن شريعة الله تحكم الجميع مسلمين وغير مسلمين . ولكن إذا شاء غير المسلمين أن يحتكموا الى شرائعهم فيما ليس من حق الدولة ، وفيما ليس من مشكلة مشتركة بينهم وبين مسلم فلهم ذلك على أن يتم كذلك ضمن سيادة القانون المحدد والمجاز .", "(ب) النظام الذي يلاحظ فيه مجموع التركيب العام للشعب فيكون الغنم والغرم عاما للجميع ، ويكون التمثيل في المؤسسات العامة بنسبة ما يستشعر به الجميع العدل بحيث يستشعر كل مواطن أن هذا النظام نظامه .", "(ج) النظام الذي تتلقى فيه كفاءة الرجل مع سلامة المنهج ، ومرونة اللوائح مع الخدمة السريعة والجيدة لكل مواطن .", "(د) النظام الذي يجعل كل مواطن مجاهدا ، وكل مواطن مختصا ، بحيث لا يبقى اختصاص الا وقد وجد وسهل لأصحابه أن ينجحوا ويبدعوا .", "(ه) النظام الذي يحقق لكل انسان حدا أدنى من الخدمات والرفاه فيتحقق به استغناؤه وكرامته .", "(و) النظام الذي يربى الشعب على منتهى الوعى السياسي ، ويحميه من التدجيل السياسي ، ويتعامل معه بصراحة كاملة ويتخذ قراراته على أساس من النضج والشورى .", "(ز) النظام الذي تتوافر بعناصره أعلى درجات الثقة من الشعب ،"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0041.png"}, {"n": 42, "paras": ["والذي يملك قدر من الكفاءة ، وأعلى درجات العزم ، وأشد طاقات التعامل المكافئ مع ما يواجهه من خلال مؤسسات شورية رفيعة ، ووزارة راشدة ، وجيش ذي كفاءة عالية ، وتدريب راق ، وأخلاقية فذة ، وسلاح جيد وعناصر قيادية وفنية ممتازة . (ح) النظام الذي يعبئ طاقات الشعب كلها رجالا ونساء وأطفالا ، سياسيا واقتصاديا وعسكريا ، في خدمة الأمة . (ط) النظام الذي يقضع الطريق على أية عملية تخريبية داخلية وخارجية من خلال المواقف الصريحة والواعية ومن خلال التوعية الصحيحة للأمة . (ي) النظام الذي لا يصرف فيه قرش الا في محله ولا يجبى فيه قرش الا بعدل وحق .", "ان النظام الذي نريده هو هذا .. نظام مريح لكل مواطن ، أما التفصيلات والطرق التي تحقق هذه المعاني فانها ستأتي من خلال الشورى داخل الجماعة المسلمة ، ومن خلال الشورى العامة لمجموع طوائف الشعب . وسيقول كثيرون : ان هذه الطروح مشتركة لدى الكثيرين . ونقول : صحيح هذا ولكن الفارق بين طروحنا وطروح غيرنا أننا نطرحها صادقين ، وغيرنا يطرحها كاذبا ، وأننا مؤتمنون عليها ، وغيرنا ليس بمؤتمن عليها ، والتاريخ شاهد والواقع شاهد . وأن أمتنا ستتعب كثيرا اذا لم تسلم بهذه البديهيات وأننا نتصور أنه بمجرد أن يقوم النظام المريح الذي تريده في مكان ما في الأرض الاسلامية فان عدواه ستصل الى بقية الأقطار . ان النظام الذي نريده نظام يرتاح فيه الانسان ولا يمكن أن يرتاح الانسان الا في ظل نظام الاسلام ، وظل عدالة الاسلام ؛ أما المسلم فلأنه لا يستشعر اطمئنانا الا بذاك . أما غير المسلم فهذا التاريخ شاهد على أنه كان مرتاحا في ظل شريعتنا وعدالتنا ، بدليل أنه بقي على هذه الأرض واستمر على دينه ، ولو لم يكن مرتاحا فانه اما أن يغير دينه واما أن يفر ، فاذا لم يكن هذا أو ذاك ، فذلك دليل على أن غير المسلم كان مرتاحا على الأرض الاسلامية . فنظام تحكمه المسلمات الاسلامية لا يمكن الا أن يكون مريحا للانسان ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0042.png"}, {"n": 43, "paras": ["مجموع الآراء الاجتهادية فيه ما هو الأصلح والأجود لمصلحة الشعب شأنه ، ونوع اختلف فيه أئمة الاسلام فهذا النوع تتبنى الدولة من وطبيعة العصر ، وفى ذلك ما يضمن وحدة التشريع ومرونة التطبيق الذي يسع الزمان والمكان .", "٢ - والذين يتصورون أن التطبيق الاسلامي يعنى تخلفا أو قصورا عن روح العصر واهمون ومغرور بهم . هذه اسرائيل قامت على أساس ديني بحت فهل اعتبر العالم شرقه وغربه نظام اسرائيل متخلفا مدنيا ؟ ان الغرب الرأسمالي ينظر الى اسرائيل كنموذج على التطبيق الديمقراطي وأن الشرق الشيوعي ينظر الى اسرائيل كنموذج على التطبيق الاشتراكي . الجميع يعترفون بها والهيئات الدولية تتعاون معها ، وهذه دولة الاتحاد السوفييتي ، وهذه دولة الصين ، تقومان على أساس نظرية شاملة خاطئة في شأن الكون والانسان ، ومع ذلك لا ينظر اليهما الآخرون على أنهما بلدان متخلفان مدنيا . ان التقدم والتخلف موازين محددة والاسلام متى وجد حملته الحقيقيون لا يمكن الا أن يكون الصيغة العليا لتقدم الانسان في كل مكان .", "٣ - والذين يتصورون أن التطبيق الاسلامي يسلب الناس كثيرا مما يحبون ومما يرتاحون اليه هم أحد اثنين : أما انسان مخطىء في تصوره للمحبوب والمريح ، وأما انسان لا يعرف الاسلام حق المعرفة . فاذا كان المحبوب والمريح هو الخمر والزنا والحشيش والأفيون وأمثال هذه المعاني فلا شك أن الاسلام قطع الطريق على الضار والسيىء والشرير ، فالذين يحاربون الاسلام من أجل هذا مرضى يحتاجون الى شفاء . وأما الذين يتصورون أن الاسلام يسلب الانسان ما ترتاح اليه النفس السليمة والعقل المستقيم وما يحبه العقل السليم والذوق السليم ؛ فهؤلاء يحتاجون الى دراسة الاسلام من جديد .", "٤ - وأما الذين يتصورون أن التطبيق الاسلامي سيسلبهم مكاسب فهم أكثر الناس وهما ؛ فالاسلام يزيد ولا ينقص . ونحب أن يعرف الناس بصراحة أن الاسلام عندما يحكم لن ينظر أهله الى الوراء بل سينظرون الى الأمام . وما فعلته الأنظمة السابقة لن يعتبروا"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0043.png"}, {"n": 44, "paras": ["انفسهم مسئولين عنه ، بل سيفعلون كل ما ينبغى فعله فيما هو مطروح امامهم . والآن اصبحت اكثر البلاد الاسلاميه - في حكم الكثير من فقهاء المسلمين - دار حرب وأنظمة التي سيطرت عليها أنظمة كافرة ، ولن يدخل الاسلاميون في سلسة لا نهاية لها من رد مظالم النظام التالى ثم الأول ثم السابق ثم اللاحق لا في موضوع الأرض ولا في غيرها وانما سيحلون القضايا المعلقة كلها بمنتهى الحكمة ويتعاملون مع الواقع من خلال تطويره ويتركون الفتوى والتقوى أن تعملا عملهما في أي دائرة من دوائر الماضي . فهم لم يتورطوا ، ولن يتورطوا في سلسلة من التقصى لا نهاية لها ، ومن ثم فليطمئن الجميع على أن التطبيق الاسلامي سيعطيهم ولا يحرمهم ولكن هذا لا يلغى حقا عند الله ولا يزيل باطلا عنده ، وعلى المسلم الحريص على آخرته أن يطمئن إلى ما يلقى به الله عز وجل . وهذا كله شيء، وعملية اعادة النظر في القوانين لتكون اسلامية شيء آخر . وتكن القوانين الجديدة ستحكم القضايا المعلقة والمقبلة ومن أجل أن يطمئن أهل التقوى ستنشأ مؤسسات للفتوى على كل المذاهب يستطيع الفرد أن يستفتيها في كل قضية من القضايا وأن يستقصى ، وتستطيع الدولة أن تتعرف في كل شأن على آراء المدارس الفقهية لتختار منها .", "ه - وانى الذين يخافون من الاسلام نتيجة لرؤيتهم عبوس متدين ، أو انكاره الشديد على قضية محتملة ، أو سماعهم لفتوى شيخ ينظر الى الأمور نظرة ضيقة ، نقول : ان الأمر عند الاسلاميين على غير ما تخافون وتحذرون فالاسلام الذي من هديه أن يعطى كل وقت حكمه ، وكل حالة أوجها ، والاسلام الذي تبلغ مدارسه الاجتهادية العشرات والتي اعتمدت من الأصول والقواعد ما يسع كل مصالح الانسان هو أبعد عن أن يكون مصدر خوف . والاسلاميون الذي فهموا الاسلام حق الفهم وعرفوا مدارسه الاجتهادية وأصول اجتهادها ، هم أبعد الناس عن أن يكونوا مظنة قصور على أنه ينبغى أن يكون واضحا كذلك أن الاسلاميين لا يمكن أن يداهنوا أو يساوموا أو يلينوا في تطبيق الاسلام .", "٦ - وأما الذين يخافون من تكالب العالم علينا اذا طبقنا"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0044.png"}, {"n": 45, "paras": ["مع الواقع حيثما كان هذا الواقع وان العالم على استعداد لأن يبادلنا مصالح بمصالح ونحن على استعداد لذلك كذلك ، أما الذين يريدون أن يتعاملوا معنا على أساس مبادىء بمصالح فعليهم أن يفتشوا عن غيرنا ، لقد جربت بعض البلدان أن تتخلى عن اسلامها من أجل الآخرين فلم ينفعها ذلك عند الآخرين .", "هذه تركيا تخلت فترة طويلة عن اسلامها لكسب ود الغرب ، ومع ذلك يقف الغرب ضدها دائما عندما يكون الأمر صراعا بينها وبين أجزاء منه ، ولو كان موقفها عادلا . ان خرافة الخوف هذه خرافة قديمة ذكرها القرآن وفندها : « وقالوا ان نتبع الهدى معك نتخطف من ارضنا ، أو لم نمكن لهم حرما آمنا يجبى اليه ثمرات كل شيء رزقا من لدنا ولكن أكثرهم لا يعلمون » ( القصص : ٥٧ ) . وفى اللحظة التي نحمل الاسلام فيها حق الحمل فان الرعب سيقطع قلوب كل من يدخل أو يفكر أن يدخل في صراع مع المجاهد المسلم الذي يعشق الموت في سبيل الله عز وجل ، ثم ان الله عز وجل وعدنا النصر ووعدنا الرفاه اذا طبقنا شرعه ، والله لا يخلف الميعاد « ان تنصروا الله ينصركم » ( محمد : ٧ ) « ولو أنهم اقاموا التوراة والانجيل وما أنزل اليهم من ربهم لأكلوا من فوقهم ومن تحت أرجلهم » ( المائدة : ٦٦ ) « ولو أن أهل القرى آمنوا وأتقوا لفتحنا عليهم بركات من السماء والأرض ، ولكن كذبوا فأخذناهم بما كانوا يكسبون » ( الأعراف : ٩٦ ) ووعد الله لا يخلف . « الشيطان يعدكم الفقر ويأمركم بالفحشاء ، والله يعدكم مغفرة منه وفضلا ، والله واسع عليم » ( البقرة : ٢٦٨ ) . وقد جرت عادة الكثيرين أنهم اذا ناقشتهم في الكليات الاسلامية يسلمون ثم يثيرون بعض الأسئلة الجزئية ، ونحن لا نبخل في الجواب لكن مثل هذه الأسئلة لا تتناهى ، فلا نقف عندها هنا .. ونحب هنا أن نشير الى موضوع ينبغي أن يعطى كامل الأهمية وهو تبسيط طروحنا أمام العامة والتركيز على بعضها وبشكل مبسط اذ أن الكثيرين من العامة يعجز عن ادراك الكثير من أبعاد الدعوة الاسلامية ، كما أن الكثيرين من الناس لا يدركون الا الشيء القليل الذي يمس مصالحهم . ونحن حركة مهمتها الأولى التربية على أداء الواجب .", "ولكن السنة جرت على ابراز الايجابيات في مستقبل الدعوة الاسلامية وتبيان بركاتها ونتائجها على"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0045.png"}, {"n": 46, "paras": ["الأفراد والأمة ومن ثم فلا يجوز أن نغفل هذا الجانب على أن لا يكون ذلك على حساب الحق وعلى ألا يكون ذلك مسايرة للأهواء ؛ فان عقاب ذلك عند الله كبير ، قال تعالى : (( وان كادوا ليفتنونك عن الذي أوحينا اليك لتفتري علينا غيره ، واذن لاتخذوك خليلا . ولولا أن ثبتناك لقد كدت تركن اليهم شيئا قليلا . اذن لأذقناك ضعف الحياة وضعف الممات )) ( الاسراء : ٧٣ - ٧٥ ) أى لأذقناك عذابا مضاعفا في الحياة وعذابا مضاعفا في الممات : (( ثم لا تجد لك علينا نصيرا )) ( الاسراء : ٧٥ ) وإذا اتضح هذا وهو موضوع تحدثنا عنه من قبل فان علينا أن نركز مع التبسيط على ما يلى :", "( أ ) أننا أمة لا عز لها ولا مجد الا بهذا الاسلام . ( ب ) أن الاسلام وحده الحل لكل مشاكلنا السياسية والاقتصادية والاجتماعية الداخلية والخارجية .", "( ج ) وأنه بالاسلام سيكون لكل عامل عمل ، ولكل طالب محتاج راتب ، ولكل فلاح أرض ، ولكل مواطن سكن وزوجة وحد أدنى من الغنى .", "( د ) وأن مشكلات احتلال الأرض لن تنتهى الا من خلال رفع علم الاسلام واعلان الجهاد .", "( ه ) وأن الوحدة العربية لن تتم الا بالاسلام ، وأن توحيد العالم الاسلامى لن يتم الا بالاسلام وأن تغيير ميزان العالم لصالحنا لا يتم الا بالاسلام ؛ وأن شيئا جديدا سيطرأ على العالم كله بهذا الاسلام . ( و ) وأن العمل لاقامة الحكومة الاسلامية فريضة ، وأن التجمع على أساس الاسلام فريضة ، وأن كل تجمع لا يرضاه الاسلام لا يجوز وهو اما كفر أو نفاق أو فسوق .", "( ز ) وأن اقامة الدولة الاسلامية شيء ممكن ، بل هو أكثر امكانا من غيره ؛ فاذا كان الشيوعى الذى يريد تغيير كل شيء وهو على باطل لا يستبعد امكانية اقامة الشيوعية ، فكيف يستبعد مسلم ذلك على أرض الاسلام .", "( ح ) وأن الاسلام يعطى العدل لكل مواطن له صفة المواطنة على", "( ٤ - في آفاق التعاليم )"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0046.png"}, {"n": 47, "paras": ["الأرض الإسلامية ويحرم ظلمه ولو لم يكن مسلما . حتى إن الرسول صلى الله عليه وسلم يقول : « إذا ظلم أهل الذمة كانت الدولة لهم » .", "(ط) التطبيق الإسلامي لا يعنى الحرمان من المتع المفيدة . وإنما يحد من اتباع الأهواء الضارة .", "(ي) وأن التطبيق الإسلامي وحده هو الذي يجمع للأمة أعلى درجات القوة ماديا ومعنويا ، وأعلى درجات التوزيع العادل للثروة وأعلى درجات الشعور بالمسئولية . إن تركيز مثل هذه المعاني وتبسيطها مهم جدا . كما أن تعميقها شيء مهم كذلك . وينبغي أن نلاحظ طرق عرض هذه المعاني فنعرضها لكل إنسان بالطريقة المناسبة . فأحيانا تعرض من خلال المعاني القرآنية والحديثية . وأحيانا تبرز من خلال التعليق على وضع ما . والداعية الحكيم لا يعجزه أن يركز المعنى الذي يريده بأساليب متعددة .", "ونحب هنا أن نوضح خطأين كبيرين يقع فيهما الكثير من أدعاة : الخطأ الأول : تعميق النظرة التشاؤمية في شأن الإسلام ، والخطأ الثاني : جل ما هو كمال في حق بعض الناس هو الأصل في قضايا المعاش . أما الخطأ الأول فتجد مظاهره في أنك تلقى مسلما يرى أن الدنيا فسدت ، وأن الإسلام انتهى وأنه لا أمل ، وأنه لا نصر ، والعجب كل العجب أن يعرض كل ذلك مؤيدا بالشواهد من الكتاب والسنة . وشتان بين ما يقولون وبين هدى القرآن والسنة . إن هدى القرآن أن يفتح للمسلم باب الثقة بالله ، وهؤلاء يخافونه ، وكان الرسول صلى الله عليه وسلم يبشر دائما بانتصار الإسلام ، وهؤلاء يبشرون بانكساره .. صحيح أن الرسول صلى الله عليه وسلم حدثنا بظروف قاتمة تمر على هذه الأمة ولكن لنحذرها ونتجاوزها ونعالجها لا لنستسلم لها ، وقد رأينا في كتاب « جند الله ثقافة وأخلاقا » كيف أن الرسول صلى الله عليه وسلم بشر بدولة الإسلام العالمية ، وبشر بفتح روما ، وبشر بأن الجماعة الإسلامية منصورة حيث وجدت ما قاتلت ، فقد قال رسول الله صلى الله عليه وسلم لقريش في ابتداء الإسلام : « كلمة واحدة تدين لكم بها العرب وتخضع لكم بها العجم » وذكر"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0047.png"}, {"n": 48, "paras": ["لعدى كيف أنه ستفتح على المسلمين كنوز كسرى . ذلك كان هديه عليه السلام في تربية الجماعة المسلمة .. وهؤلاء يعلقون على الأمة الاسلامية باب الأمل فليذكر هؤلاء الحديث الشريف : « من قال هلك المسلمون فهو أهلكهم » .", "أما الخطأ الثاني : فمظهره مثلا التركيز على أن أبا بكر رضى الله عنه كان يأخذ كفايته من بيت المال وعمر كذلك ، ثم يبدأ الواعظ بالتعليق .. والتعليق على هذا وذاك طيب لابراز ميزة التربية الاسلامية ، وابراز ميزات هؤلاء الطيبين الأطهار من الرعيل الأول لهذه الأمة ، ولكن على أن لا يتجاوز ذلك الى ما يشعر الرجل المعاصر أن الدولة الاسلامية دولة فقر وافقار ، ودولة تقتير على المواطنين ، أخرج أبو داوود بسند حسن عن رسول الله صلى الله عليه وسلم قال : « من كان لنا عاملا فليكتسب زوجة ، وان لم يكن له خادم فليكتسب خادما ، وان لم يكن له مسكن فليكتسب مسكنا ، ومن اتخذ غير ذلك - اى بغير اذن من الدولة أو اتفاق معها - فهو غال أو سارق » .", "فلابد أن تؤمن الدولة لكل موظف من موظفيها مسكنا وزوجة وخدمة عامة وينبغي أن يعطى الموظف ما تؤمن به حاجاته وزيادة ، وعلى الواعظ والمربى والعالم والمعلم أن يكون دقيقا جدا في عصرنا وهو يتحدث ، فلا يوجد حجبا بين الناس وبين امكانية التطبيق الاسلامي المعاصر .", "وفى نهاية هذا الفصل نريد أن نبين لأعداء الاسلام توهماتهم الضعيفة اذ يتصورون أنهم بجرة قلم أو بكلمة فاجرة يستطيعون أن يمحوا من قانون العالم كله الاسلام ..", "الى هؤلاء نقول : هل الاسلام أقل عمقا في أنفس أهله من اليهودية في أنفس اليهود ، أو من النصرانية في أنفس النصارى ؟", "لقد عاشت النصرانية على أرضنا مئات السنين ، والحاكمون مسلمون والاسلام هو الحاكم ، وعاشت اليهودية على أرضنا مئات السنين ، والحاكمون مسلمون ، والاسلام هو الحاكم ، أى عاشت في ظل نظام مخالف كل الفترات ، وعاشت اليهودية في روسيا في ظل"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0048.png"}, {"n": 49, "paras": ["القيامرة رغم الاضطهادات المتكررة ثم جاءت الثورة الشيوعية وهي ثورة ملحدة مضطهدة في نظامها للأديان ، ومربية على العداء للأديان ، ومع ذلك فأنت ترى أن يهود الاتحاد السوفييتي هم أكثر يهود العالم حماسا للدولة اليهودية وحماسا للهجرة إليها ، بل إن الذين أقاموا دولة إسرائيل وأوجدوها ، ولا يزالون يسيطرون عليها أكثرهم من المعسكر الشرقي . فاذا كان هذا هو الشأن في مثل اليهودية والنصرانية في أنفس أصحابها فهل يتصور ألا مجنون أن بإمكانه بجرة قلم أو بكلمة مهما كان شأنها أن يلغي الإسلام من أنفس المسلمين . والإسلام هو ما هو في كونه حقا وفي ملاءمته للفطرة وفي رعاية الله عز وجل له ولأهله . قال تعالى : « يريدون ليطفئوا نور الله بأفواههم والله متم نوره ولو كره الكافرون . هو الذي أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون » ( الصف : ٨ ، ٩ ) . فهؤلاء الذين يتوهمون أن باستطاعتهم أن يلغوا الإسلام من حياة المسلمين أو يقضوا على الإسلام أصلا واهمون .. واهمون .. وسيحطمهم الإسلام كما حطم غيرهم وسيفيء المسلمون إلى إسلامهم كلما أوغل الآخرون في محاولة إبعادهم عنه . وانما مثلهم في حربهم للإسلام كما قال الشاعر : كناطح صخرة يوما ليوهنها فلم يهنها وأوهى قرنه الوعل", "وهذا الإسلام أعمق في نفوس المسلمين مما يتوهمون ، وكلما ازدادوا ايغالا في حربه سيتحرك الإسلام في نفوس المسلمين بشكل أكبر ، ثم لتكون المعركة الفاصلة ولن يكون الإسلام مغلوبا ولن يكون أهله مغلوبين بإذن الله عز وجل .", "وبعد ... انه لابد أن نلاحظ ونحن نتكلم عن الأهداف الوضوح والبعد عن التعقيد الذي يليق بكتب الفلسفة أو بالمحاولات الفلسفية لتعقيد المبادىء لأن هذا ليس هو طريق الدعوات العملي واليومي . وعلى ضوء ذلك ينبغي أن ينظر إلى هذا الموضوع : اننا ببساطة نرغب أن نقيم دولة الله في كل قطر ، وأن ننصر شريعة الله ، وأن نحيى سنة رسول الله ، وأن نوحد أمة الله ، وأن نجاهد في سبيل الله حتى يخضع العالم كله ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0049.png"}, {"n": 50, "paras": ["نكلمه الله . اننا ببساطة نريد أن نعرف الناس على الله وأن نرجعهم الى مبدأ الحاكمية به الذي طريقه الايمان برسالة محمد صلى الله عليه وسلم والالتزام بشريعته وذلك بواسطة الجهاد بأنواعه كلها ؛ قال عليه الصلاة والسلام : « من قاتل لتكون كلمة الله هي العليا فهو في سبيل الله » ، أن العمل من أجل أن تكون كلمة الله هي العليا هو التلخيص الدقيق لسيرنا . وأن جعل كلمة الله هي العليا محور كل هدف وكلمة الله تتمثل في القرآن وأن سنة رسول الله صلى الله عليه وسلم هي الشرح التفصيلي والعملي لكلمة الله .. اننا جماعة شعارها : الحق ، والقوة ، والحرية .", "الحق : ويتمثل بما أنزله الله عز وجل على محمد صلى الله عليه وسلم قال تعالى : « والذي أنزل إليك من ربك الحق » ( الرعد : ١ ) .", "والقوة : وقد أمر الله عز وجل أهل الايمان أن يعدوها : « وأعدوا لهم ما استطعتم من قوة ومن رباط الخيل » ( الأنفال : ٦٠ ) .", "والحرية : والمراد بها ما عبر عنه الصحابة رضوان الله عليهم عندما كانوا يقولون : جئنا لنخرج الناس من عبادة العباد الى عبادة الله ، ومن جور الأديان الى عدل الاسلام .. هذه شعاراتنا وهي أهدافنا وبعضها مع كونه هدفا فهو وسيلة ، وهذه الأهداف محكوم بعضها ببعض ، فالقوة عندنا يحكمها الحق ، والحرية عندنا للحق الذي لا يأتيه الباطل من بين يديه ولا من خلفه .. يمثل هذه البساطة يمكن أن نتكلم عن أهدافنا ، ولكنها ببساطة ترتكز على ما يغطي العالم كله بيانا وعدلا وحكمة . نحن نريد وسنعمل باذن الله بكل ما أوتينا من قوة من أجل أن يصبح الكتاب والسنة بمثابة المسلمات عند البشر جميعا ، وأن يقوم في المجتمع الانساني نظام شورى يعتمد كمسلمات له الكتاب والسنة ، فمن أدرك هاتين القضيتين أدرك أهدافنا كلها . وهذا يقتضي منا ونحن نعمل لذلك أن لا نتناقض مع هذين الهدفين لا في أشخاصنا ، ولا في مناهجنا ؟"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0050.png"}, {"n": 51, "paras": ["ولا في طبيعة تنظيمنا ، نظريا أو عمليا ، إذ بقدر نجاحنا في أنفسنا بتوفيق الله في أن نقيم الكتاب والسنة في أنفسنا في المقام الأول فهما والتزاما ، وبقدر ما ننجح في الوصول إلى الإطار العملي في تحقيق الشورى داخل الجماعة وعتاد الخضوع لها يكون سيرنا مستقيما وإمكانية الوصول إلى تحقيق الأهداف موجودا بإذن الله تعالى ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0051.png"}, {"n": 52, "paras": ["الباب الخامس في الوسائل", "ان الكلام عن الأهداف يستدعى بالضرورة أن نتكلم عن الوسائل المكافئة لتحقيق الأهداف .", "وها نحن نتكلم عن الأهداف هدفا هدفا ونتحدث عن بعض الوسائل المكافئة لتحقيق هذه الأهداف . فنقول والله المستعان :", "الهدف الأول كما ذكر الأستاذ البنا رحمه الله هو « الفرد المسلم » قال : « نحن نريد الفرد المسلم » والفرد المسلم رجل وامرأة ، طفل وطفلة ، شاب وفتاة ، كبير وصغير ، وبشكل عام فالوسائل لتكوين الفرد المسلم ثلاثة يجب أن تجتمع حتى تؤتى ثمارها كاملة .", "(١) المربى ، (٢) المنهج المناسب ، (٣) البيئة الصالحة .", "وأى خلل في واحد من هذه الثلاث لابد أن يترتب عليه خلل في تخريج الشخصية المسلمة الا اذا تداركت الفرد نفحة ربانية وشاء الله ان يعوض . والبيئة الصالحة هي الجو الذي يأخذ المسلم فيه الأخلاق والعلم والعمل وينأى بواسطتها عن اللهو والعبث فضلا عن «الحرام» ، والتي مظهرها العلم والذكر فهي دائما اما في علم أو في ذكر وأنا يكون ذلك في جو المسجد فذلك أفضل والا ففي كل بيت مسلم يمكن أن يقوم سوق للخير ، وعلينا أن نحذر من البيئات المرضية التي يمكن أن تنشأ على هامش الجماعة أو في داخلها ، وعلينا أن نضغط كثيرا على الاخوة الذين يشكلون دوائر تبتعد قليلا أو كثيرا عن الأخلاقية الجادة الرصينة لجماعة مسلمة متعبدة متهجدة . والمربى الحكيم هو الوارث الكامل أو في اصطلاح القرآن : « الولى المرشد » وهي في"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0052.png"}, {"n": 53, "paras": ["اصطلاحنا المتواضع « النائب » ومن ثم فيجب أن يعطى الاخوة النواب دائما من أنفسهم أفضلية للتربية والتكوين فاذا لم يكن الأخ النائب هو الذي يتولى التربية فالأخ النقيب ثم الأخ المجاهد ، على أن يبقى للأخ النائب صلة ما في التربية أو في العطاء العلمي لتبقى الملاحظة دقيقة والاشراف محكما . وأما المنهج فسيأتي الكلام عليه وهو ذكر وعلم ، وبقدر ما يستنير عقل الأخ وقلبه بالعلم والذكر والعمل يكون النضج صحيحا ، ومن أجل نضج الفرد ينبغي أن يكون للأخ أوراده اليومية وينبغي أن يكون له اعتكافه السنوي الذي تهيء برامجه الجماعة وينبغي أن يعتاد على الخلوات وعلى أنواع الأذكار وعلى قيام الليل وعلى الأخلاق العليا في كل دائرة وينبغي أن يمر على دورات متعددة روحية وعلمية ليكمل نضجه سواء أكان رجلا أو امرأة . طفلا أو شابا أو شيخا . وههنا نكتفي أن نسجل بأنه على كل شعبة من شعبنا أن يكون عندها فرعان : فرع للعمل النسائي وفرع للعمل في صفوف الصغار ، فالحلقات لكل ، والرعاية المناسبة لكل ، والكتب المناسبة لكل ، والاحتياجات اللازمة لابعاد الفتنة بسبب العمل في مثل هذه الأجواء ينبغي أن تؤخذ . ومن المناسب أن يلاحظ في تربية الأطفال قضية تأهيلهم لمرحلة ما بعد البلوغ ، جسما ، وعقلا ، وقلبا ، وروحا ، وحرفة ، وعملا ، وأن يدربوا على أعمال الفروسية ، وأخلاقها ، وبعض ألعاب القوة ، وعلينا أن نلاحظ أن قوة الحافظة عند الطفل كبيرة ، ومن ثم فعلينا أن نحفظهم كثيرا من كتاب الله ، وسنة رسوله صلى الله عليه وسلم والآداب الخاصة والعامة وأن نعلقهم بالذكر والعلم ، ومن المناسب أن نلاحظ في الدراسات النسائية القضايا الخاصة بالنساء زيادة على القضايا المشتركة .", "وعلينا أن نركز كثيرا في تربية النساء على قضية الترغيب والترهيب ، وكتب السيرة ، والوعظ ، وقصص الصالحات . ولسنا في هذا الباب بسبيل الاحاطة ، وأنما المهم الاشارة ههنا ، وباختصار أن الحلقة العامة والخاصة سواء أكانت حلقة علم أو ذكر ، والأسرة ، والكتيبة ، والفرقة والمذاكرة والمدارسة الشخصية كل ذلك وسائل ينبغي التوسع فيها لتربية الفرد أيا كان فلننتقل إلى الكلام عن الوسائل المناسبة لتحقيق الهدف الثاني ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0053.png"}, {"n": 54, "paras": ["والهدف الثاني من أهدافنا كما ذكره الأستاذ آنفاً هو « البيت المسلم » ، فما هي الوسائل المكافئة لذلك ؟", "١ - لابد لكل أخ من أن يعطى اهتماماً خاصاً لبيته سواء أكان زوجاً أو أخاً أو أبناً .", "٢ - لابد للجماعة من أن تعطى العمل النسائي حقه من خلال نشر الكتاب ، ومن خلال إقامة الحلقات النسائية العامة والخاصة ، ومن خلال التكوين العالي للأخوات المسلمات .", "٣ - لابد لكل أخ من أن يتخذ الزوجة الصالحة ، وينبغي أن تعطى الأخوات أفضلية فلا يتطوع الأخ لغيرهن إلا في حالات ، وينبغي أن يتم التزاوج بين الإخوان ، وأن توجد التسهيلات المناسبة لذلك .", "٤ - ينبغي أن يربط كل أخ أبناءه ، وبناته وإخوته ، وأخواته بأجهزة الجماعة .", "٥ - ومن أجل ذلك كله ينبغي أن تنشىء الجماعة الأجهزة اللازمة لتغطية كل الشئون من جهاز لرعاية شئون الأبناء في كل شعبة إلى جهاز لتغطية العمل النسائي في كل شعبة إلى جهاز خاص لتكوين الأخوات المسلمات في كل مركز إلى جهاز خاص في المركز يتلقى الأبناء إذا تجاوزوا مرحلة معينة .", "٦ - وينبغي على الجماعة ، وعلى الأفراد أن يسهروا على تحرير بيوتهم من كل مخالفة ، وعلى القيادة أن تسهر على منع التنافس الدنيوي بين نساء الإخوان ، وتشجيع مظاهر الزهد .", "٧ - كما أن على الجماعة أن تنشىء الحلقات المسجدية النسائية ، وتؤمن لها مدرسات نشيطات صالحات أو مدرسين مؤتمنين .", "٨ - كما أن على القيادة أن تخص الكتب النسائية بعناية معينة ، فتختار وتكلف بالتأليف وتطبع ، وتشجع على انطباعة ، وتضع أنواعاً من الكتب النسائية تحت تصرف المرأة ، والبنت المسلمة ، وحبذا لو اتجهت جهود البعض لإيجاد المكتبة النسائية ، وفي المكتبة الحالية كتب كثيرة تخص النساء في التأليف فحبذا لو نشرت وعممت . والبيت المسلم لن يوجد فقط من خلال توجيه الزوج أو الأب أو الابن ، بل يوجد من خلال هذا ومن خلال إيجاد البيئات المناسبة ، والرعاية المتكاملة ، وإلا فإن التوجيه أحياناً يكون في فراغ ، إذ ما نقوله يكون في واد ، وكل شيء"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0054.png"}, {"n": 55, "paras": ["يعطيهم عكسه ويهدم ما تصنع فلابد من أجل وجود البيت المسلم أن يرتبط البيت المسلم بمجموعة من الروابط الاسلامية ان أمكن ، وفي حالة التعذر لابد من تركيز الجهود .", "٩ - وعلى الجماعة بقدر المستطاع أن تشجع الزواج المبكر ، والزواج من الأرامل ، فنحن حركة جهادية تحتاج الى ايجاد قيم خاصة ، وعادات متعارف عليها تبعد المسلم والمسلمة عن الترف ، وتحقق له حاجاته الضرورية .", "١٠ - هذا كله ينبغى أن يتم قبل السلطة وبعدها ، غير أنه بعد السلطة لابد أن تتعاون الأوقاف ، وصندوق الزكاة وخزينة الدولة العامة من أجل تأمين البيت المسلم المؤمن له حاجاته كلها من خلال تسهيل الزواج وتأمين المهر ، وتأمين بيت السكن ، وتدبير العمل ، وغير ذلك مما يلزم لاقامة البيت المسلم المطمئن .", "والهدف الثالث من أهدافنا هو « الشعب المسلم » ، اذ أن الأستاذ البنا يرى صعوبة التطبيق الاسلامى دون الارتكاز على شعب مسلم . فالحكومة الاسلامية لا يصح أن تقوم على فراغ . يقول الأستاذ رحمه الله : « ولكن الاخوان أعقل وأحزم من أن يتقدموا لمهمة الحكم ، ونفوس الأمة على هذا الحال ، فلابد من فترة تنتشر فيها مبادىء الاخوان ويتعلم فيها الشعب كيف يؤثر المصلحة العامة على المصلحة الخاصة » .", "ويقول في مكان آخر : « وليست الوسيلة القوة كذلك ، فالدعوة الحق ، انما تخاطب الأرواح أولا ، وتناجى القلوب ، وتطرق مغاليق النفوس ، ومحال أن تثبت بالعصا أو أن تصل اليها على شفا الأسنة والسهام ، ولكن الوسيلة في تركيز كل دعوة ، وثباتها معروفة مقروءة لكل من له المام بتاريخ الجماعات ، وخلاصة ذلك جملتان : « ايمان وعمل » و « محبة واخاء » من مثل هذا ندرك أن الأستاذ رحمه الله يعلق أهمية كبيرة على وجود الشعب المسلم كمقدمة لابد منها لما وراءه . ومن ثم وضعه الثالث في ترتيب الأهداف ، وجعل الحكومة ، وغيرها من الأهداف يأتى فيما بعد ذلك ، ومن أجل ذلك جعل الأستاذ"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0055.png"}, {"n": 56, "paras": ["البنا مراحل دعوتنا ثلاثا : التعريف ، والتكوين ، والتنفيذ . ومن ثم فان طريقنا الى وجود الشعب المسلم هو التعريف والتكوين . يقول الأستاذ : « ماذا فعل رسول الله صلى الله عليه وسلم في تركيز دعوته في نفوس الرعيل الأول من أصحابه أكثر من أن دعاهم الى الايمان والعمل ، ثم جمع قلوبهم على الحب والاخاء ، فاجتمعت قوة العقيدة الى قوة الوحدة ، وصارت جماعتهم هي الجماعة النموذجية التي لابد أن تظهر كلمتها ، وتنتصر دعوتها ، وان ناوأها أهل الأرض جميعا . وماذا فعل الدعاة من قبل ، ومن بعد أكثر من هذا ينادون بالفكرة ، ويوضحونها ، ويدعون أناس اليها فيؤمنون بها ويعملون لتحقيقها ، ويجتمعون عليها ، ويزدادون عددا فتزداد الفكرة بهم ظهورا حتى تبلغ مداها وتبتلع ما سواها ، وتلك سنة الله « ولن تجد لسنة الله تبديلا » ( الأحزاب : ٦٢ ، الفتح : ٢٣ ) . « وليست دعوة الاخوان بدعا في الدعوات فهي صدى من الدعوة الأولى . يدوى في قلوب هؤلاء المؤمنين ، وتتردد على ألسنتهم ، ويحاولون أن يقذفوا به ايمانا في قلوب الأمة المسلمة ليظهر عملا في تصرفاتهم ، ولتجتمع قلوبها عليه فاذا فعلوا ذلك أيدهم الله ، ونصرهم وهداهم سواء السبيل .", "فانى الايمان والعمل ، والى الحب والاخاء أيها الاخوان والله معكم ؛ وتلك وسيلتكم : « والله غالب على أمره » ( يوسف : ٢١ ) . وفي مكان آخر من رسائله يقول الأستاذ : « وسيقف جهل الشعب بحقيقة الاسلام عقبة في طريقكم » . من كل ما مر معنا ندرك أن طريقنا الى ايجاد الشعب المسلم هو التعريف بالاسلام والجماعة والتكوين على أخلاقية الاسلام ، وأدب الصف المسلم . وطريقنا الى ذلك هو الحلقات العامة والخاصة والأسر والكتائب ، والحوار الدائم والأمر بالمعروف والنهي عن المنكر ، ولابد ههنا أن ننبه الى قضيتين مرتبطتين بموضوع الشعب المسلم وهي أن نجمع في خطابنا للشعب بين التعريف بالاسلام ، وتربية الثقة فيه وبأن الجماعة ستؤمن له كل حاجاته الضرورية ، وفي الوقت نفسه ينبغي أن نربى الصف على أعلى درجات التضحية ، ونكران الذات ، وهذا"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0056.png"}, {"n": 57, "paras": ["موضوع يقتضي توضيحا : في قصة آدم نجد قوله تعالى : « وقلنا يا آدم اسكن أنت وزوجك الجنة ، وكلا منها رغدا حيث شئتما ، ولا تقربا هذه الشجرة فتكونا من الظالمين » ( البقرة : ٣٥ ) « فقلنا يا آدم إن هذا عدو لك ولزوجك فلا يخرجنكما من الجنة فتشقى . إن لك ألا تجوع فيها ولا تعرى . وأنك لا تظمأ فيها - أي لا تعطش - ولا تضحى » ( طه : ١١٧ - ١١٩ ) أي لا يصيبك الحر . نلاحظ في هذا الجانب من قصة آدم عليه السلام أنه طمئن على حاجاته الضرورية مع التكليف ، ونلاحظ أن الشيطان أتاه من خلال تطلع النفس البشرية إلى الخلود قال : « هل أدلك على شجرة الخلد وملك لا يبلى » ( طه : ١٢٠ ) وهذه قضايا رئيسية يجب أن نفطن لها في عملنا الدعوي والسياسي فمذ خالطت هذه الروح الجسد ، أصبح لها حاجاتها ولها تطلعاتها . هذه الحاجات والتطلعات منها المرضي ومنها الصحيح ، والملاحظ أن النفس البشرية إذا لم تطمئن إلى حصولها على حاجاتها الضرورية وشيء من تطلعاتها ، فإن استعدادها للتكليف في الغالب يكون ضعيفا ، ومن ثم والله عز وجل هو الأعلم بالطبيعة البشرية طمأن آدم على حاجاته الضرورية في وقت التكليف ، والملاحظ أن الشيطان أتى آدم عليه السلام من خلال تطلع عميق في النفس البشرية . هذه قضايا يجب أن نضعها في حسابنا ، ونحن نتعامل مع النفس البشرية ، إذ أن كل حركة دينية أو سياسية فضلا عن حركة تجمع بينهما إذا لم تعرف كيف تتعامل مع النفس البشرية في صحتها ومرضها لا تنجح ، ونحن مهمتها أن تظهر النفس البشرية ، وكيفية التعامل معها ، فإننا نكون مفرطين .", "ثم أن للشعوب نفسياتها التي هي أثر بيئتها ، وتاريخها ، وثقافتها ، وأنواع الحكومات التي تعاقبت عليها ، فإذا لم يكن هذا كله على ذكر منا ، ونحن نتعامل مع شعوبنا ، فإننا سنفشل فشلا ذريعا في سياسة هذه الشعوب ، ومن ثم تجد أن أعرف خلق الله بطبيعة النفس البشرية وطريقة التعامل معها هو رسول الله صلى الله عليه وسلم ، وإخوانه من الرسل عليهم الصلاة والسلام ثم أصحابه رضوان الله عنهم ، وكان ذلك من جملة توفيقات الله لهم حتى قادوا أو ساسوا ، وقد كان في حياة رسول الله صلى الله عليه وسلم شيئان على غاية من الأهمية فيما نحن فيه : الأول : خطاب الناس من خلال إشعارهم بأن الحاجات الضرورية ، والتطلعات الكبيرة متحققة من خلال الإسلام ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0057.png"}, {"n": 58, "paras": ["الثاني : تربية الصف على أعلى درجات الايثار ونكران الذات ، وترك المصلحة الخاصة لحساب المصلحة العامة ، فبينما تخاطب العامة من خلال مصالحها وتطلعاتها الدنيوية نتقنها الى ما هو أعلى ، يربى الصف على ترك الكل في الله . وعندما تغلب الصف تطلعاته الدنيوية في لحظة من اللحظات ، فان أدنى تذكير يرجع الصف الى أخلاقيته الرفيعة ، وبينما تكون العامة هي أكثر الناس انتفاع بالدنيا يكون الصف في بعض الحالات أكثر الناس حرمانا منها ، وهو الذي كسب المعارك وهو الذي قدم كما حدث يوم حنين . وهذا فارق رئيسي بين دعوات الأنبياء ، ودعوات أهل الدنيا . الأنبياء يدعون الأمة الى الواجب ويسبقون الأمة اليه ، ويعطون الأمة كل الحقوق ، ولا يأخذون لأنفسهم شيئا الا القليل الذي لابد منه ، والدعوات السياسية الدنيوية يدعى أصحابها نكران الذات ، وأنهم حريصون على مصلحة الأمة ، وهم أكثر الناس جشعا ، وأقلهم تذكرا لمصالح الأمة الا في حدود ما يحتاجون اليه من تأييد الأمة .", "اذا اتضح هذا كله نقول : انه لابد أن نسير الأمة كلها بفئاتها ، وطبقاتها ، وطوائفها ، وأسرها ، وقبائلها ، وعشائرها ، وقطاعاتها ، وأن ندرس ما يمكن أن نعطيه لكل منها من منافع ومصالح على أساس الاسلام وهو شيء كثير ، وأن نشعرها جميعا بذلك ، بحيث تطمئن الأمة كلها الى عطائنا ، ونثق مع هذا بقدرتنا على معالجة أمورها كلها الداخلية والخارجية بمنتهى العدل والحزم ، هذا في جانب ، وفي الجانب الآخر يجب أن يربى الصف على الاخلاص لله وحده ، وعلى الايثار الرفيع في كل شيء ، ولنلاحظ هذا النص في تهذيب سيرة ابن هشام ( الجزء الأول ص ١٠٣ ) ما يلى : لما اشتكى أبو طالب ، وبلغ قريشا قتله قريش بعضها لبعض : ان حمزة وعمر قد أسلما ، وقد فشا أمر محمد - صلى الله عليه وسلم - في قبائل قريش كلها ، فانطلقوا بنا الى أبى طالب فيأخذ لنا على ابن أخيه ، ويعطيه منا ، والله ما نأمن أن ييزونا أموالنا . قال ابن عباس : فمشوا الى أبى طالب فكلموه وهم أشراف قومه : عتبة بن ربيعة ، وشيبة بن ربيعة ، وأبو جهل ابن هشام ، وأمية بن خلف وأبو سفيان بن حرب في رجال من أشرافهم فقالوا : يا أبا طالب انك منا حيث قد علمت وقد حضرك ما ترى ، وتخوفنا عليك وقد علمت الذي بيننا وبين ابن أخيك فادعه فخذ له منا"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0058.png"}, {"n": 59, "paras": ["وخذ لنا منه ، ليكف عنا ، ونكف عنه ، وليدعنا وديننا ، وندعه ودينه . فبعث إليه أبو طالب فجاءه فقال : يا ابن أخي .. هؤلاء أشراف قومك قد اجتمعوا ليعطوك ، وليأخذوا منك ؛ فقال رسول الله صلى الله عليه وسلم : « نعم .. كلمة واحدة تعطونيها تملكون بها العرب وتدين لكم بها العجم » . فقال أبو جهل : نعم وأبيك وعشر كلمات ، قال : « تقولون : لا إله إلا الله ، وتخلعون ما تعبدون من دونه » ، فصفقوا بأيديهم ثم قالوا : أتريد يا محمد أن تجعل الآلهة إلها واحدا ، إن أمرك لعجيب ، ثم قال بعضهم لبعض : إنه والله ما هذا الرجل بمعطيكم شيئا مما تريدون ، فانطلقوا وامضوا على دين آبائكم حتى يحكم الله بينكم وبينه » . لاحظ قوله عليه السلام : « تملكون بها العرب وتدين لكم بها العجم » انه خطاب لمن هو خارج الصف باللغة التي يفهمها هؤلاء ، لغة قريبة من الطبيعة البشرية ، ولكنها صادقة وحق بأن واحد .", "في جمع الفوائد نقلا عن الترمذي والشيخين أثناء الكلام عن غزوة حنين هذه الرواية الآتية تحت الرقم ( ٦٦٥٢ ) : « لما كان يوم حنين أقبلت هوازن وغطفان وغيرهم بذراريهم ونعمهم ، ومع النبي صلى الله عليه وسلم يومئذ عشرة آلاف ، ومعه الطلقاء ، فأدبروا عنه حتى بقى وحده ، فنادى يومئذ نداءين لم يخلط بينهما بشيء التفت عن يمينه فقال : « يا معشر الأنصار » ؛ قالوا : لبيك يا رسول الله أبشر نحن معك ، ثم التفت عن يساره فقال : « يا معشر الأنصار » ، قالوا : لبيك يا رسول الله أبشر نحن معك ، وهو على بغلة بيضاء ، فنزل فقال : « أنا عبد الله ورسوله » ، فانهزم المشركون ووزع رسول الله صلى الله عليه وسلم الغنائم على غير الأنصار فوجد الأنصار في أنفسهم وأينغ سعد رسول الله صلى الله عليه وسلم الخبر ، قال : « فأين أنت من ذلك يا سعد » ؟ قال : يا رسول الله ما أنا إلا من قومى . قال : « فأجمع لي قومك في هذه الحظيرة » ، فخرج سعد فجمع الأنصار في تلك الحظيرة ، فجاء رجال من المهاجرين فتركهم فدخلوا وجاء آخرون فردهم ، فلما اجتمعوا له أتاه سعد فقال : قد اجتمع لك هذا الحي من الأنصار ، وأتاهم رسول الله صلى الله عليه وسلم فحمد الله ، وأثنى عليه بما هو أهله ، ثم قال : « يا معشر الأنصار .. مقالة بلغتني عنكم ، وجدة وجدتموها على في أنفسكم ؟ .. ألم آتكم ضلالا فهداكم الله » ،"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0059.png"}, {"n": 60, "paras": ["وعانة فأغناكم الله ، وأعداء فألف الله بين قلوبكم » ؟ قالوا : بلى والله ورسوله أمن وأفضل ، ثم قال : « ألا تجيبونني يا معشر الأنصار » ؟ قالوا : بماذا نجيبك يا رسول الله ؟ .. لله ولرسوله المن والفضل ؛ قال صلى الله عليه وسلم : « أما والله لو شئتم لقلتم ، فلصدقتم ، ولصدقتم : أتيناك مكذبا فصدقناك ، ومخذولا فنصرناك ، وطريدا فآويناك ، وعائلا فآسيناك ، أوجدتم يا معشر الأنصار في أنفسكم في لعاعة من الدنيا تألفت بها قوما ليسلموا ، ووكلتكم إلى إسلامكم ، ألا ترضون يا معشر الأنصار أن يذهب الناس بالشاة والبعير وترجعوا برسول الله إلى رحالكم ؟ .. فوالذي نفس محمد بيده لولا الهجرة لكنت امرأ من الأنصار ، ولو سلك الناس شعبا ، وسلكت الأنصار شعبا لسلكت شعب الأنصار .. اللهم ارحم الأنصار وأبناء الأنصار ، وأبناء أبناء الأنصار » . قال : فبكى القوم حتى أخضلوا لحاهم ، وقالوا : رضينا برسول الله قسما وحظا ، ثم انصرف رسول الله صلى الله عليه وسلم وتفرقوا » . لاحظ كيف خاطب الصف ، وكيف أعطى الحديث عهد بالصف ، الصف يقدم التضحيات كلها ، وليس له إلا الله ورسوله صلى الله عليه وسلم وعندما تنازع الطبيعة البشرية قلوب الصف يعود الصف إلى أخلاقيته بأدنى تذكير .", "في كتاب حياة الصحابة ص ( ٤٩٨ ) الجزء الثاني ما يلي : « أخرج ابن ماجه بإسناد صحيح عن ابن عباس رضي الله عنهما قال : حدثني عمر بن الخطاب رضي الله عنه قال : دخلت على رسول الله صلى الله عليه وسلم وهو على حصير قال : فجلست فإذا عليه إزاره وليس عليه غيره ، وإذا الحصير قد أثر في جنبه ، وإذا أنا بقبضة من شعير نحو الصاع ، وقرظ في ناحية من الغرفة ، وإذا اهاب معلق فابتدرت عيناي فقال : « ما يبكيك يا ابن الخطاب » ؟ فقلت : يا نبي الله .. ومالي لا أبكى وهذا الحصير قد أثر في جنبك وهذه خزانتك لا أرى فيها إلا ما أرى ، وذلك كسرى وقيصر في الثمار والأنهار ، وأنت نبي الله وصفوته ، وهذه خزانتك ! قال : « يا ابن الخطاب .. أما ترضى أن تكون لنا الآخرة ولهم الدنيا » ؟ لاحظ كيف يكون الخطاب للصف ؟ من كل ما مر ندرك أنه لابد"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0060.png"}, {"n": 61, "paras": ["من خطاب للأمة تلاحظ به حاجاتها الضرورية ، وتطلعاتها المشروعة ، ولابد من تربية راقية للصف على ذلك ، والتقصير في هذا أو هذا خطأ ينبغي أن نتجاوزه ؛ انه ينبغي أن يعلم الطلاب أنه في دولتنا سيكون لكل طالب محتاج راتب ، وفي دولتنا سيكون لكل إنسان حاجاته الضرورية من مسكن وزوجة وملبس ، وسيكون لكل موظف ما يكفيه ويغنيه ، وأن عدالة في التوزيع لابد أن تشمل الأمة كلها فيغتني الجميع ، وأما الصف فلابد له من تربية على التضحية في الله والايثار في الله وغير ذلك ، وهذا لن يتم بسهولة ، فهناك الصراع بيننا وبين الطبيعة البشرية ، كي تستقر هذه الأمور في النفس لتصبح أخلاقا . ان بعض المربين يفرقون بين الحال والمقام ؛ فالحال يتحول ، والمقام مستقر . ولا يصل الإنسان إلى المقام إلا بعد الحال ، فالحلم لا يصبح مقاما للإنسان إلا بعد مجاهدة للنفس وحمل لها عليه ؛ وكذلك الذلة للمؤمنين والعزة على الكافرين . والجهاد والكرم وغير ذلك من مكارم الأخلاق ولن يتخلق الصف بهذا كله دفعة واحدة ، وريثما تصبح هذه الأمور بدهيات في الصف فان جهدا كبيرا ينبغي أن يبذل ومراقبة دائمة ينبغي أن توجد ، وتذكيرا متواصلا لابد أن يكون ، ودراسات كثيرة ينبغي أن تتم ، ومع هذا وذاك فان الصف قد يمر بمحن كأثر عن ظهور النزعات البشرية ، غير أن القيادة الراشدة بما أعطاها الله عز وجل من حكمة ، قادرة باذن الله أن تأخذ بيد الصف من طور إلى طور ضمن ما يحتمله الصف في كل مرحلة لتصل إلى القمة ، ومن ثم نلاحظ أن رسول الله صلى الله عليه وسلم تدرج في الصف من حال إلى حال فكان في بداية الأمر يسكت عن كثير من الأمور وفي آخر الأمر كان لا يتركها ، لاحظ عقابه للثلاثة الذين خلفوا في آخر حياته عليه السلام وموقفه يوم أحد من الذين انفصلوا عن الصف .", "بهذا كله : من تغطية للشعب كله بالحلقات العامة والحلقات الخاصة ومن تركيز من خلال الكتاب والمحاضرة ومن خلال حوار دائم مع كل فئة لتذكيرها بما يقدم لها الاسلام ومن تفهم لغير المسلمين في ألا يخافوا من الاسلام ، ومن خلال تعميق الثقة بأشخاصنا وجماعتنا باستيعابنا لكل مشاكل الأمة داخليا وخارجيا وقدرتنا باذن الله على حلها ، ومن خلال تربية راقية لكل من استجاب لنا من هذه الأمة ليوجد الصف القادر على الارتقاء بالأمة وقيادة الشعب وتسييره في الطريق الذي نريد من"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0061.png"}, {"n": 62, "paras": ["خلال تفنن في أساليب العمل والاستقطاب ، ومن خلال الابداع في ايجاد انواع التنظيمات المتعددة التي لا تبقى أحدا الا استقطبته والاحسان في جعل كل الاتجاهات السياسية تعطى الاسلام من نفسها الكثير ، ثم الضغط الداخلى على قيادتها نحو مزيد من الاسلام ، من خلال ذلك كله نرجو أن يوجد الشعب المسلم .", "والهدف الرابع من أهدافنا في ترتيب الأستاذ البنا هو « الحكومة الاسلامية في كل قطر » ، فلنتكلم عن قضية الوصول الى الحكم والسلطة : ذكر الأستاذ البنا في رسائله ما يشير الى أن الحكم ليس هدفا للاخوان لأشخاصهم ، بل الهدف هو أن يوجد الحكم الاسلامي ، ومتى وجد فالاخوان جند وأنصار للحاكم المسلم وللحكومة المسلمة كائنة ما كانت .", "يقول الأستاذ : « .. وعلى هذا فالاخوان المسلمون لا يطلبون الحكم لأنفسهم فان وجد من الأمة من يستعد لحمل هذا العبء وأداء هذه الأمانة والحكم بمنهاج اسلامي فهم جنوده وأنصاره وأعوانه » . وفى تأكيد هذا المعنى من الأستاذ قطع لدابر كل تهمة توجه للاخوان أنهم طلاب دنيا . ان الهدف هو تحقيق فريضة فرضها الله عز وجل على هذه الأمة فاذا قام بها أحد من الأمة فهم أعوانه . والا فان الاخوان ليسوا أمام خيار ؛ ولذلك قال الأستاذ بعد ذلك : « وان لم يجدوا فالحكم من منهاجهم وسيعملون لاستخلاصه من أيدى كل حكومة لا تنفذ أوامر الله » وقد أثبت الواقع العملى أن فردا واحدا ليس قادرا على تطبيق الاسلام وأنه لا يؤتمن على اقامة الاسلام الا الاسلاميون الذين ربطوا مصيرهم بهذا الدين دنيا وآخرة . ثم ان السير الاسلامي العالمي يفرض على الاخوان أن يستمروا في خطهم لكيلا تقف حدود التطبيق الاسلامي عند قطر بعينه . ان تطبيق الاسلام محليا بحاجة الى الاخوان وتطبيقه عالميا بحاجة الى الاخوان - والله أعلم - وهذا يحمل الاخوان مسئوليات خاصة مع احتفاظ الاخوان بأنفسهم طاهرة نقية باذن الله من مطامع الدنيا لأنفسهم ، كيف وهم يقرأون قوله تعالى : « تلك الدار الآخرة نجعلها للذين لا يريدون علوا في الأرض ولا فسادا ، والعاقبة للمتقين » ( القصص : ٨٣ ) . يقول", "٥١ - في آفاق التعاليم >"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0062.png"}, {"n": 63, "paras": ["الأستاذ البنا : « وكلمة لابد أن نقولها في هذا الموقف : هي أن الإخوان المسلمين لم يروا في حكومة من الحكومات التي عاصروها ، لا الحكومة القائمة ، ولا الحكومة السابقة ، ولا غيرها من الحكومات الحزبية من ينهض بهذا العبء أو من يبدى الاستعداد الصحيح لمناصرة الفكرة الاسلامية . فتتعلم الأمة ذلك ولتطالب حكامها بحقوقها الاسلامية وليعمل الاخوان .. » فاذا اتضح هذا الواقع عرف أنه ليس أمامنا خيار في أن نعمل ليقوم الاسلام في أقطارنا وليكون قيامه انطلاقة نحو مسيرة عالمية بداياتها صحيحة ونهاياتها سليمة باذن الله . ومن الملاحظ أن الأستاذ البنا يرى أنه لا يمكن أن يقوم الحكم الاسلامي على فراغ فكرى أو تربوى في الأمة . يقول الأستاذ : « ولكن الاخوان أعقل وأحزم من أن يتقدموا لمهمة الحكم ونفوس الأمة على هذا الحال فلا بد من فترة تنتشر فيها مبادىء الاخوان ويتعلم فيها الشعب كيف يؤثر المصلحة العامة على المصلحة الخاصة » . وفى هذا درس كبير لاخواننا الذين يهملون هذه الناحية ويتصورون أنه من خلال وثبة أفراد يمكن أن تتحول الأمة من حال الى حال ، ويقوم الاسلام قياما كاملا بينما الأرضية التي يستندون عليها هي الفراغ . ومن ثم فان الأستاذ عندما يتحدث عن الوسائل يقول : « وليست الوسيلة القوة كذلك فالدعوة الحق انما تخاطب الأرواح وتناجى القلوب وتطرق مغاليق النفوس ، ومحال أن تثبت بالعصا ، أو أن تصل اليها على شفا الأسنة والسهام » . ولكن الوسيلة في تركيز كل دعوة وثباتها معروفة لكل من له المام بتاريخ الجماعات ، وخلاصة ذلك جملتان : ايمان وعمل ، ومحبة واخاء .. » فالدعوة الاسلامية لا تقوم كما سنرى الا على أرضية التعريف والتكوين .", "فعندما نربط الأمة كلها بالحلقات العامة والخاصة والكتاب والمجلة وعندما يوجد الجيل القادر على اقامة دولة الاسلام عندئذ نصل الى أن تكون كلمة الله هي العليا .", "قد يتصور بعضنا أنه من خلال مجموعة رجال أو مجموعات يمكن أن تقام دولة الاسلام وفى هذا ما فيه . ان الرغبة في العمل يجب أن تقوم على ضوء معان متعددة ولأمر ما قدم الأستاذ البنا للاجابة عن هذا السؤال : متى تكون خطوتنا تنفيذية ؟ بقوله : « ان ميدان القول غير ميدان الخيال وميدان العمل غير ميدان القول وميدان الجهاد غير"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0063.png"}, {"n": 64, "paras": ["ميدان العمل وميدان الجهاد الحق غير ميدان الجهاد الخاضي .. يسهل على كثير أن يتخيلوا ! ولكن ليس كل خيال يدور بالبال يستطاع تصويره أقوالا باللسان . وان كثيرين يستطيعون أن يقولوا ، ولكن قليلين من هذا الكثير يثبتون عند العمل . وكثير من هذا القليل يستطيعون أن يعملوا ، ولكن قليلا منهم يقدرون على حمل أعباء الجهاد الشاق والعمل العنيف ، وهؤلاء المجاهدون هم الصفوة القلائل من الأنصار قد يخطئون الطريق ولا يصيبون الهدف أن لم تتداركهم عناية الله . وفى قصة طالوت بيان لما أقول . والأستاذ البنا رحمه الله من بين من تكلموا في فقه الدعوة الاسلامية في العصر الحديث هو الذي رسم الطريق الصحيح للحكم ودل على الطريق الموصلة اليه وحذر المستعجلين كما حمس المتقاعسين ومن كلامه : « أن طريقكم هذا مرسومة خطواته موضوعة حدوده ، ولست مخالفا هذه الحدود التي اقتنعت كل الاقتناع بأنها أسلم طريق للوصول . أجل قد تكون طريقا طويلة ولكن ليس هناك غيرها . انما تظهر الرجولة بالصبر والمثابرة والجد والعمل الدائب ، فمن أراد منكم أن يستعجل ثمرة قبل نضجها أو يقطف زهرة قبل أوانها فليست معه في ذلك بحال ، وخير له أن ينصرف عن هذه الدعوة الى غيرها من الدعوات . ومن صبر معى حتى تنمو البذرة وتنبت الشجرة وتصلح الثمرة ويحين القطاف فأجره في ذلك على الله ولن يفوتنا واياه أجر المحسنين اما النصر والسيادة واما الشهادة والسعادة » . هذا الطريق المرسومة خطواته الموضوعة حدوده تجده في رسائل الأستاذ البنا ومذكراته . وفى البناء العملى الذي أقامه والذي تتعرف عليه من خلال التتبع . هذا الطريق تجده مفقودا في كثير من الجهات ، ومع ذلك فان بعض القيادات تستشهد على جمودها وخمودها بكلام الأستاذ البنا الذي نقلناه .", "واذن لابد من سيرنا في الطريق كنه كما رسمه الأستاذ . ونقول عندئذ للمستعجلين : تأتوا .. أما أن نعطل التعريف والتكوين والتنفيذ ونعطل كل شيء ثم نقول للاخوان قفوا ؛ فان ذلك هو الموت . اننا نحن المسلمين تحكمنا نواميس الكون كما تحكم غيرنا ؛ غير أن الله عنايته الخاصة بنا ورحمته الخاصة بنا ، وامداده الخاص لنا ان التقيناه فالأخ الذي ينسى نواميس الكون نذكره بأنه لا يستطيع ألا يتنفس وألا يأكل وهذا يدل على أنه مقهور بنواميس ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0064.png"}, {"n": 65, "paras": ["الكون وقوانينه ومن ثم فان علينا أن نعرف نواميس الكون وأن نسير في طريق تسخيرها . يقول الأستاذ رحمه الله : « ألجموا نزوات العواطف بنظرات العقول ، وأنيروا أشعة العقول بلهب العواطف ، وألزموا الخيال صدق الحقيقة والواقع . واكتشفوا الحقائق في أضواء الخيال الزاهية البراقة . ولا تميلوا كل الميل فتذروها كالمعلقة . ولا تصادموا نواميس الكون فانها غلابة ، ولكن غالبوها واستخدموها وحولوا تيارها واستعينوا ببعضها على بعض . وترقبوا ساعة النصر وما هي منكم ببعيد » . أن طريق البنا علينا أن نحييها كلها فذلك وحده يملأ فراغ النفس الاسلامية وفراغ العمل الاسلامي وهو وحده الطريق الموصل الى الغاية . يقول الأستاذ : « على أن التجارب في الماضي والحاضر قد أثبتت أنه لا خير الا في طريقكم ولا انتاج الا مع خطتكم ولا صواب الا فيما تعملون فلا تغامروا بجهودكم ولا تقامروا بشعار نجاحكم واعملوا » .", "انطبع في أذهان الكثيرين أن الاخوان المسلمين يعتبرون استعمال السلاح هو الطريق المفضل عندهم للحكم وهذا من أكبر الأخطاء فالأستاذ البنا بصريح العبارة يقول : « ان الاخوان المسلمين سيستخدمون القوة حيث لا يجدى غيرها » فالطريق المفضل عند الاخوان المسلمين للوصول الى الحكم الاسلامي هو غير استعمال القوة لقد طالب الأستاذ الهضيبي بالحياة النيابية أمام محاكم ١٩٥٤ ورشح الأستاذ البنا نفسه للمجلس النيابي في أوائل الأربعينات ، فالطريق المفضل عندنا لاقامة الحكم الاسلامي هو ذاك أن تعطى حرية الدعوة والعمل والتربية وأن تعطى للأمة فرصة التعبير عن رأيها في انتخاب ممثليها .", "ولكن أن يحارب الحاكمون الاسلام وأن يحولوا بين المسلم واسلامه وأن يحولوا بين الاسلام وبين الانتصار في الوقت الذي يفتحون فيه الطريق لكل دعوة ضالة فما العمل في هذه الحالة ؟", "ان موقف الاخوان المسلمين في هذا الموضوع على غاية من العدالة والوضوح ، فقد كلفنا الله بالاسلام وكلف العالم به ونحن مسئولون عن هذا التكليف فكل من طبق الاسلام فنحن جنده وأعوانه ومن لم يفعل فليعط الاسلام وأهله حرية العمل وحرية الوصول عن طريق التمثيل النيابي الذي اعترف العالم كله بأنه طريق مشروع ، فاذا لم"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0065.png"}, {"n": 66, "paras": ["يكن هذا ولا هذا فمن حق المسلمين أن يفكروا في الوسائل الأخرى ، على ضوء ذلك كله ينبغى أن يفهم فكر الاخوان المسلمين وفكر الأستاذ البنا وعلى ضوء أننا مسلمون مكلفون بأن تكون أجسادنا قوية وتدريبنا عاليا على ضوء ذلك نقول : يرفض الأستاذ البنا مبدأ الثورة كطريقة للوصول الى الحكم ، ويرفع بدلا منه شعار استخدام القوة . والفارق بين الشيئين - والله أعلم - أن الثورة عمياء هوجاء ، واستخدام القوة اسلاميا لا يكون الا بصيرة وتعقل . وأن الثورة يرافقها ظلم ، واستخدام القوة اسلاميا يحكمه العدل . وأن الثورة قد لا يبالى بنتائجها وأما استخدام القوة اسلاميا فالنظر الى العواقب مقدم فيه . والثورة تشكل اندفاعات حاقدة ، واستخدام القوة اسلاميا هو عين الرحمة . يقول الأستاذ : « ان الاخوان المسلمين سيستخدمون القوة العماية حيث لا يجدى غيرها ، وحيث يثقون أنهم قد استكملوا عدة الايمان والوحدة وهم حين يستخدمون هذه القوة سيكونون شرفاء ، صرحاء ، وسينذرون أولا وينتظرون بعد ذلك ثم يقومون في كرامة وعزة ويحتملون كل نتائج موقفهم هذا بكل رضاء وارتياح . وأما الثورة فلا يفكر الاخوان المسلمون فيها ولا يعتمدون عليها ولا يؤمنون بنفعها ونتائجها وان كانوا يصارحون بأن الحال اذا دامت على هذا المنوال ولم يفكر أولوا الأمر في اصلاح عاجل وعلاج سريع لهذه المشاكل فسيؤدى ذلك حتما الى ثورة ليست من عمل الاخوان المسلمين ولا من دعوتهم » . وقد حدثت الثورة في مصر وعانى الاخوان منها أكثر مما عانى غيرهم ولنقف عند قول الأستاذ البنا : « سيستخدمون القوة العملية حيث لا يجدى غيرها » وهذا النص يفهم منه أنه اذا كان بالامكان أن نصل الى اقامة الحكم الاسلامى عن غير طريق استعمال القوة ، فان ذاك سيكون طريقا مفضلا .", "ومن كلام الأستاذ البنا يفهم : أن الاخوان يستخدمون القوة بعد أن يفكروا وبعد أن يزنوا النتائج ويغوصوا الى أعماق الأمور . يقول الأستاذ : « ولكن الاخوان المسلمين أعمق فكرا وأبعد نظرا من أن تستويهم سطحية الأعمال والفكر ، فلا يغوصوا الى أعماقها ولا يزنوا نتائجها وما يقصد منها وما يراد بها ، فهم يعلمون أن أول درجة من درجات القوة : قوة العقيدة والايمان ، ويلى ذلك قوة الوحدة والارتباط ،"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0066.png"}, {"n": 67, "paras": ["ثم بعدهما قوة الساعد والسلاح - ولا يصح أن توصف جماعة بالقوة حتى تتوفر لها هذه المعاني جميعا ، وأنها إذا استخدمت قوة الساعد والسلاح وهي مفككة الأوصال مضطربة النظام أو ضعيفة العقيدة خامدة الايمان ، فسيكون مصيرها الفناء والهلاك - هذه نظرة . ونظرة أخرى ، هل أوصى الاسلام - وأخوة شعاره - باستخدام القوة في كل الظروف والأحوال ؟ أم حدد لذلك حدودا ، واشترط شروطا ، ووجه القوة توجيها محدودا ؟ ونظرة ثالثة ، هل تكون القوة أول علاج ؟ أم أن آخر الدواء الكي ؟ وهل من الواجب أن يوازن الانسان بين نتائج استخدام القوة النافعة ، ونتائجها الضارة وما يحيط بهذا الاستخدام من ظروف ؟ .. أم من واجبه أن يستخدم القوة وليكن بعد ذلك ما يكون ؟ هذه نظرات يلقيها الاخوان المسلمون على أسلوب استخدام القوة قيل أن يقدموا عليه - والثورة أعنف مظاهر القوة ؛ فنظر الاخوان المسلمين اليها أدق وأعمق ؛ وبخاصة في وطن كمصر جرب حظه في الثورات فلم يجن من ورائها الا ما تعلمون . وبعد كل هذه النظرات والتقديرات أقول لهؤلاء المتسائلين : ان الاخوان المسلمين سيستخدمون القوة العمنية حيث لا يجدى غيرها ، وحيث يثقون أنهم قد استكملوا عدة الايمان والوحدة ، وهم حين يستخدمون هذه القوة سيكونون شرفاء صرحاء .. سينذرون أولا ، وينتظرون بعد ذلك ثم يقدمون في كرامة وعزة ، ويحتملون كل نتائج موقفهم هذا بكل رضاء وارتياح . أما الثورة فلا يفكر الاخوان المسلمون فيها ، ولا يعتمدون عليها ، ولا يؤمنون بنفعها ونتائجها ؛", "وان كانوا يصارحون كل حكومة في مصر بأن الحال اذا دامت على هذا المنوال ولم يفكر أولوا الأمر في اصلاح عاجل وعلاج سريع لهذه المشاكل فسيؤدى ذلك حتما الى ثورة ليست من عمل الاخوان المسلمين ولا من دعوتهم ، ولكن من ضغط الظروف ومقتضيات الأحوال ، واهمال مرافق الاصلاح ، وليست هذه المشاكل التي تتعقد بمرور الزمن ويستفحل أمرها بمضى الأيام الا نذيرا من هذه النذر ؛ فليسرع المنقذون بالأعمال » ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0067.png"}, {"n": 68, "paras": ["والأستاذ البنا يقدم قوة العقيدة والايمان وقوة الوحدة والارتباط على معانى القوة الأخرى :", "يقول الأستاذ رحمه الله : « فهم - أى الاخوان - يعلمون أن أول درجة من درجات القوة ، قوة العقيدة والايمان ويلى ذلك قوة الوحدة والارتباط ثم بعدها .. » .", "ولنتحدث عن هاتين القضيتين :", "القضية الأولى - قوة العقيدة والايمان : ان ميزان قوة العقيدة والايمان هو حال رسول الله صلى الله عليه وسلم وأصحابه . كما أن ميزان صحة العقيدة هو ما كان عليه رسول الله صلى الله عليه وسلم وأصحابه ونحن علينا أن نبحث عن هذين الكمالين في باب صحة العقيدة ، وفى باب قوتها وفى باب سلامة الايمان ، وفى باب كماله . ونحاول أن نتحقق بذلك تحقيقا عاليا . ويجب أن يكون أمرنا في هذين البابين على كماله كى تكون نقطة البداية قد تحققت في أنفسنا . وفى صفنا . والعقيدة وقضايا الايمان في حياة أصحاب رسول الله صلى الله عليه وسلم كانت قضايا هي ملء القلوب والعقول والأسماع والأبصار . بينما هي في قلوب الكثيرين الآن قضايا هامشية ، فبدلا من أن تكون هي الأصل وعنها تتفرع الأشياء أصبح غيرها أصلا وهي بالنسبة له فرع . ولاشك أن الجهد الذي ينبغى أن يبذل للارتقاء بمعانى العقيدة والايمان في عصرنا لابد أن يكون كبيرا ؛ فلابد فيه من القدوة ولابد فيه من المنهج السليم ولابد فيه من البيئة الصالحة ولابد فيه من الأجواء المتعددة التي يكمل كل منها الآخر حتى تبقى العقيدة يقظة حية توترها التأثيرى في النفس عال ويدفعها نحو الآخرة كبير : حلقات القرآن والسنة والفقه ؛ حلقات الذكر المأثور ، أجواء العبادة ، أجواء العمل الصالح المشترك ؛ الدراسات المتكاملة ، المربون الحكماء الصالحون ، الصحبة الطيبة ، الصلة الدائمة بالقرآن والسيرة ، الأوراد الخاصة المتعددة للأخ ، ورد المحاسبة والاستغفار ، ورد الصلاة على رسول الله صلى الله عليه وسلم ، ورد التوحيد ، الورد القرآني ، ورد قيام الليل وصلاة الضحى ، أوراد الصلوات مع اقامة الصلوات ؛"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0068.png"}, {"n": 69, "paras": ["الورد العلمي ، ورد الأمر بالمعروف والنهي عن المنكر ، والنصيحة ، والدعوة إلى الله ؛ هذا كله لابد منه لأذكاء نور العقيدة والايمان في القلب ليبقى القلب حيا . وهذا كله بعد أن يصل الأخ إلى حياة قلبه بمعرفة الله بالسير في طريق ذلك من خلال العلاج القلبي والقرآني الذي يأخذ به .", "أننا نحن الاخوان المسلمين اذا لم نكن أحياء القلوب بمعرفة الله وقادرين على نقل الحياة إلى الأمة بواسطة القرآن والتعريف المحي على الله ، إذا لم نكن كذلك فاننا لا نكون على طريق الأستاذ البنا .. يقول الأستاذ : « ولكنكم روح جديد يسرى في قلب هذه الأمة فيحييه بالقرآن ، ونور جديد يشرق فيبدد ظلام المادة بمعرفة الله . وصوت داو يعلو مرددا دعوة الرسول صلى الله عليه وسلم » . فلنلاحظ هذه الكلمات ، ولنغط الحلقات القرآنية مداها ولنعرف الناس على الله تعريفا عقليا وشعوريا ذوقيا ، ولنبلغ الناس دعوة رسول الله صلى الله عليه وسلم وهي الاسلام ، وفى ذلك حياة لأنفسنا وللأمة . ولنلاحظ أن الايمان الشعوري الذوقي يبقى الهدف الأوفى للتربية الاسلامية ، وإن نقل المسلم من ايمان العامة إلى الايمان العقلى ، ثم نقله من الايمان العقلى إلى الايمان القلبي الذوقي يبقى علامة على اتقاننا طرائق التربية الاسلامية العالية ، ولقد رأينا في غير هذه الرسالة الأحاديث التي تذكر أن أول علم يرفع من الأرض الخشوع . ونحن كحركة تجديدية اذا لم نحي كل العلوم الاسلامية والتي منها علم الخشوع ، الخشوع الذي هو جزء من علم اصلاح القلوب ، اذا لم نفعل ذلك نكون قد أخفقنا في تحقيق دورنا كمجددين لعري الاسلام التي وهت كثيرا وذلك كله مرتبط بقضية قوة العقيدة والايمان . فاذا أتضح هذا كله فعلينا أن نتذكر أنه يدخل في قوة العقيدة والايمان في كلام الأستاذ البنا قوة الثقة بفكر الجماعة وفهمها ومؤسسها وقياداتها الراشدة وسيرها وطريقها ونظرياتها في العمل الاسلامي المعاصر . فما لم تكن حماسة الأخ لدعوته ولجماعته هي نفس حماسة أصحاب رسول الله صلى الله عليه وسلم أو تقارب ذلك فان الأمر لا يؤتى ثماره .", "ان علينا أن ننطلق بنفس الروح التي انطلق بها أصحاب رسول الله صلى الله عليه وسلم نحو اعلاء كلمة الله دون التفات لرضا أحد من الناس أو سخطه ؟"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0069.png"}, {"n": 70, "paras": ["وهذا أول ما يدخل في قوله تعالى : « يُجَاهِدُونَ فِي سَبِيلِ اللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَائِمٍ » ( المائدة : ٥٤ ) أما اذا تخلفنا عن هذه الروح فلن يكون منا الا العقم ، ولن تكون حركتنا الا عقيمة ، وهذا كله ادا لم يفض من الأعلى الى الأدنى كمال فلن يتم شيء على الاطلاق . ان كثيرين من اخواننا يطالبون اخوانهم بأدب طالب العلم مع شيخه العالم ، ولكن دون أن يكون هناك علم ، وبأدب المريد مع شيخه المربي ولكن دون وجود صلاح المربي وأهليته ، وبأدب الجندي مع قائده دون أن توجد أهلية القائد وجدارته ، وفي كل هذه الأحوال لا يحصد الأعلى من الأدنى الا الاستهزاء وسلب الثقة ، ولا يقدم الأعلى للأدنى الا المطالبة بالحقوق . ولا تفلح جماعة هذا شأن كبارها وصغارها . وهكذا فموضوع بناء قوة العقيدة والايمان موضوع متشابك المعالم ، متعدد المطالب ولابد للجماعة من اعطائه حقه . ولعل حقه هو اقامة كل ما ورد في مناهجنا ودراساتنا كاخوان مسلمين . فلنتتبع هذه الأمور ولنبذل جهدا كاملا لاقامتها . وعلينا ألا نفرط بفكرة صالحة ، وألا نحقر أنفسنا وأخواتنا ، كما أن علينا أن لا نبلى لغيرنا حق الحلم بمقام الصديقين والشهداء والصالحين . بل علينا أن نرتقى نيكون في صفنا الصالح والشهيد والصديق . فعندئذ يكون صفنا قد أخذ حظه من قوة العقيدة والايمان أو على الأقل قد أصبح مرشحا ليأخذ هذا الحظ .", "القضية الثانية - قوة الوحدة والارتباط : ان وحدة المسلمين في العالم كله فريضة من فرائض الله عليهم ، فضلا عن وحدتهم في كل قطر من أقطارهم . فشيء بديهي أن يكون المسلمون في قطر الواحد يدا واحدة وجبهة واحدة لها قيادة واحدة . وهذا لن يتم الا بمجموعة أمور ، ولقد رأينا في هذه السلسلة أن فكر الأستاذ البنا وحده هو الذي يمكن أن يلتقى عليه كل المسلمين المنصفين ، وهو الوحيد الذي يمكن أن يجتمع عليه المسلمون المخلصون ؛ فاذا ما حدث خلل في تبنى هذا الفكر أو في التفريط في أحد أجزائه ؛ فعندئذ يصبح تلاميذ البنا عاجزين عن توحيد المسلمين . ورأينا في هذه السلسلة أن الجماعة التي أقامها الأستاذ البنا هي وحدها المرشحة لتحرير المسلمين من أمراضهم . فاذا عجزت هذه الجماعة عن ايجاد النموذج الصحى في"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0070.png"}, {"n": 71, "paras": ["من أن تفعل للمسلمين شيئا ولن تستطيع الجماعة أن توحد المسلمين الا اذا كانت محل ثقة المسلمين بفكرها ورجالها ومؤسساتها ومواقفها العملية والنظرية ولن تستطيع أن توحد المسلمين أيضا الا اذا استطاعت أن تشكل في المسلمين القوة الأكبر بحيث يحس كل المشتغلين في الحقل الاسلامي على الأقل بوجودها حيث التفتوا . ولن تستطيع أن توحد المسلمين الا اذا وجد فيها أعلى درجات الوحدة والارتباط بأن استطاعت أن تتجاوز كل العوامل التي تؤدى الى الفرقة والخلاف ومن ثم كان بناء الجماعة بناء صحيحا هو نقطة البداية في توحيد المسلمين في كل قطر ثم توحيد المسلمين في العالم .", "ولا تتم وحدة الجماعة الا بانتقاف الصف الأدنى حول الصف الأعلى وثقته المطلقة به فما لم يكن صف المجاهدين والأنصار والعامة يثق بصف النقباء ، وما لم يكن صف النقباء يثق بصف النواب ويلتف حوله ، وما لم يكن صف النواب يثق بمجلس شوراه وقيادته التنفيذية ، وما لم يكن هؤلاء على منتهى الثقة في من فوقهم فان وحدة الجماعة لا تتم . وما لم يكن الربط بين هؤلاء جميعا وبقية أجهزة الجماعة على أشده لا تكون وحدة الجماعة على أشدها وبالتالى فان قوة الوحدة والارتباط لا تكون موجودة ، وبالتالى لا تكون الجماعة مرشحة لتحقيق الأهداف ، وهذا كله لن يتم الا بقواعد صحيحة سليمة في التنظيم والتربية واعطاء الصفة على ضوء المناهج والخصائص .", "هذه الجماعة التي اجتمع لها قوة العقيدة والايمان وقوة الوحدة والارتباط ان وجدت من يقيم الاسلام فهي جنده وعونه واذا لم تجد فانها تفتش عن الوسيلة الأفضل لاقامة الحكم الاسلامي ومن تلك الوسائل عندها : اقامته عن طريق \"الحكم النيابي\" ما دام يؤدى الى اختيار \"أهل الحل والعقد\" . فاذا حيل بين الاسلام وبين الحكم فان شريعة الله أوجبت على المسلمين أن يفكروا بالوسائل الأخرى لاقامة حكم الله ومن ذلك استخدام القوة . ورسول الله صلى الله عليه وسلم يقول : « الا أن تروا كفرا بواحا » فاذا وجد الكفر البواح فقد أذن الله لنا بالقتال ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0071.png"}, {"n": 72, "paras": ["والهدف الخامس من أهدافنا في ترتيب الأستاذ البنا هو « الدولة الإسلامية النواة » أو في تعبير الأستاذ البنا نفسه : « والدولة التي تقود الدول الإسلامية ، وتضم شتات المسلمين ، وتستعيد مجدهم ، وترد عليهم أرضهم المفقودة وأوطانهم المسلوبة وبلادهم المغصوبة » . والوسائل المكافئة لذلك أن تقوم الدولة الإسلامية الكبيرة ذات الفعائيات السياسية والاقتصادية والفنية في قطاع كبير من الأرض ، اما في دولة واسعة الأرجاء أو مكانها ولكننا نسعى أن تقوم وحدة بكل الوسائل بين مجموعة الدول التي تنتصر بها الحركة الإسلامية لتأخذ هذه الدولة النواة على عاتقها ما ذكره الأستاذ البنا من واجبات ، والتي من جملتها ضم شتات المسلمين في العالم في ظل دولة اسلامية واحدة يشعر كل مسلم في العالم أنها دولته لها ولاؤه وانتماؤه ، وعليها واجب حمايته ورعايته حيث كان .", "ووسائلنا لاقامة دولة النواة هو العمل المنسق الموحد منذ البداية ، في ظل قيادة واحدة نحو هذه الدولة . ومن ثم كانت الدعوة الواحدة والتنظيم الواحد والتخطيط المشترك والتربية الواحدة وغير ذلك من خطوات حالية هي البدايات الصحيحة والوسائل المعتمدة للوصول إلى هذه الدولة النواة .", "والهدف السادس من أهدافنا هو « قيام الدولة الإسلامية الواحدة » أو قيام دولة الولايات المتحدة التي تضم أقطار الأمة الإسلامية كلها في دولة واحدة تخضع لقيادة مركزية واحدة على رأسها امام واحد للمسلمين هو خليفة رسول الله صلى الله عليه وسلم في قيادة هذه الأمة وارشادها . ووسائلنا لذلك هي السير في المقدمات الصحيحة والتي بدايتها وجود القواعد السليمة الصالحة التي منها يكون الانطلاق الاسلامي في كل الأقطار الاسلامية لتصب في النهاية في هذا الهدف الكبير .", "والهدف السابع من أهدافنا هو « اقامة دولة الاسلام العالمية » التي تصل بركاتها ورحمتها الى كل شعوب الأرض ؛ وطريقنا الى ذلك بعد اقامة دولة الاسلام العالمية هو العمل المستمر المتوافرة كل أدواته ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0072.png"}, {"n": 73, "paras": ["المكافئة لأحكام قبول هذا العالم دعوة الله . وهذا كائن باذن الله عز وجل ، فليس هو حلما من الأحلام بل هو حقيقة واقعة بشرنا بها رسولنا صلى الله عليه وسلم .", "ولنكتف بهذا القدر ، فالأمر أوسع من أن يحيط به فرد أو يحصر في موضع ، بل هو موضوع متجدد يحتاج كل يوم الى دراسات ومناقشات ، وعلى الجماعة أن تبلور ذلك كله بقرارات يومية مكافئة لكل وضع تصادفه في هذا العالم ككل ، وفي كل جزء من أجزائه . وعلى الجماعة أن تضع تجارب كل قطر وكل مؤسسة وكل عقل اسلامي في خدمة الجميع كما أن عليها أن لا تجمد بعضها بتعميمات جامدة ؛ كما لا تحرج بعضها بالانطلاق في طريق لا تراعى فيه احتياجات المسلمين جميعا ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0073.png"}, {"n": 74, "paras": ["الباب السادس في مراحل الدعوة", "وهذا الباب كذلك في صلب شرح رسالة التعاليم لأن الأستاذ البنا تحدث عن مراحل الدعوة في رسالة التعاليم أثناء حديثه عن ركن الطاعة في أركان البيعة ؛ ولأن هذا الموضوع يشكل نظرية رئيسية من نظريات الأستاذ البنا فقد أفردنا له بابا ولنا كلام بعد ذلك على هذا الركن أثناء عرضنا لرسالة التعاليم .", "يقول الأستاذ البنا في رسالة التعاليم : « وذلك أن مراحل هذه الدعوة ثلاث :", "* التعريف - بنشر الفكرة العامة بين الناس ، ونظام الدعوة في هذا الطور نظام الجمعيات الادارية ، ومهمتها العمل للخير العام ، ووسيلتها الوعظ والارشاد تارة ، واقامة المنشآت النافعة تارة أخرى الى غير ذلك من الوسائل العلمية ، وكل شعب الاخوان القائمة الآن تمثل هذا الطور من حياة الدعوة ، وينظمها « القانون الأساسي » وتشرحها رسائل الاخوان وجريدتهم ، والدعوة في هذا الطور « عامة » . ويتصل بالجماعة فيه كل من أراد من الناس ، متى رغب في المساهمة في أعمالها ، ووعد بالمحافظة على مبادئها ، وليست الطاعة التامة لازمة في هذا الطور بقدر ما يلزم فيه احترام النظم والمبادىء العامة للجماعة .", "* التكوين - باستخلاص العناصر الصالحة لحمل أعباء الجهاد ، وضم بعضها الى بعض . ونظام الدعوة - في هذا الطور - صوفى بحت من الناحية الروحية وعسكرى بحت من الناحية العملية ، وشعار هاتين الناحيتين دائما « أمر وطاعة » من غير تردد ولا مراجعة ولا شك »"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0074.png"}, {"n": 75, "paras": ["ولا حرج ، وتمثل الكتائب الاخوانية هذا الطور من حياة الدعوة ، وتنظمها رسالة « المنهج » سابقا ، وهذه الرسالة الآن « رسالة التعاليم » . والدعوة فيه خاصة لا يتصل بها الا من استعد استعدادا حقيقيا لتحمل أعباء جهاد طويل المدى ، كثير التبعات ، وأول بوادر هذا الاستعداد « كمال الطاعة » .", "* التنفيذ - والدعوة في هذا الطور جهاد لا هوادة معه ، وعمل متواصل في سبيل الوصول الى الغاية وامتحان وابتلاء لا يصبر عليهما الا الصادقون . ولا يكفل النجاح في هذا الطور الا كمال الطاعة كذلك ، وعلى هذا بايع الصف الأول من الاخوان المسلمين في يوم ٥ ربيع الأول سنة ١٣٥٩ ه . وأنت بانضمامك الى هذه الكتيبة وتقبلك لهذه الرسالة وتعهدك بهذه البيعة تكون في الدور الثاني وبالقرب من الدور الثالث . فقدر التبعة التي التزمتها وأعد نفسك للوفاء بها » .", "ذكر الأستاذ البنا رحمه الله مراحل هذه الدعوة فحددها بأنها : التعريف والتكوين والتنفيذ . وعلى هذا فطريقنا لنقل المسلم من طور الى طور ومن حال الى حال حتى تتحقق الأهداف هي : التعريف والتكوين والتنفيذ . وبناء على ذلك فالقيادة الحق والجماعة الحق هي التي تستطيع أن تقود هذه العمليات الثلاث وتديرها وتنجح في ذلك كله . أما القيادة العاجزة عن هذه الثلاث مجتمعة أو عن واحدة منها منفردة أو القاصرة عن واحدة منها فضلا عن القيام بها كاملة مجتمعة فأنها لا ينبغي لها أن تسير . والجماعة بمجموعها اذا عجزت عن القيام بهذه الشئون فانها في هذه الحالة تكاد تفقد مبرر وجودها وعليها أن تتدارك أمرها ، ومن أجل النجاح بهذه الأمور الثلاثة لابد أن يوجد عندنا ثلاثة أجهزة : جهاز التعريف ، وجهاز التكوين ، وجهاز التنفيذ . ولابد أن يكون لكل جهاز مناهجه وخططه ووسائله وأساليبه وآلية العمل فيه ، وأن يكون ذلك كله ضمن هيكل تنظيمي ، وخطة عمل شاملة ، ونظرية واضحة في التربية والتعليم . وهذا يقتضي وضوحا في درجات العضوية ونوعيتها وآلية تكامل الأجهزة بعضها مع بعض ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0075.png"}, {"n": 76, "paras": ["صور العمل : لم يقيدنا الأستاذ البنا رحمه الله بصورة واحدة من صور العمل في قضية التعريف والتكوين والتنفيذ . فذكر مرة بما يشعر أن التعريف يمكن أن يتم كمرحلة مستقلة ، ثم يأتي التكوين كمرحلة مستقلة ، ثم يأتي التنفيذ كمرحلة مستقلة . وفى مكان آخر جمع بين صورتين فقال : « وأما التدرج ، والاعتماد على التربية ، ووضوح الخطوات في طريق الاخوان ، فذلك أنهم اعتقدوا أن كل دعوة لابد لها من مراحل ثلاث : مرحلة الدعاية والتعريف والتبشير بالفكرة وإيصالها إلى الجماهير من طبقات الشعب . ثم مرحلة التكوين وتحضير الأنصار وإعداد الجنود وتعبئة الصف بين هؤلاء المدعوين . ثم بعد ذلك كله مرحلة التنفيذ والعمل والإنتاج . وكثيرا ما تسير هذه المراحل الثلاث جنبا إلى جنب نظرا لوحدة الدعوة وقوة الارتباط بينهما جميعا ، فالداعى يدعو ، وهو في نفس الوقت يتخير ويربى ، وهو في الوقت نفسه يعمل وينفذ كذلك . ولكن لا شك في أن الغاية الأخيرة أو النتيجة الكاملة لا تظهر إلا بعد عموم الدعاية وكثرة الأنصار ومتانة التكوين » . ان كلام الأستاذ البنا هذا يعطينا فرصا كبيرة للتفكير في تنفيذ مراحل الدعوة على مقتضيات الظروف وحاجة مرحلة ما وغير ذلك . وهكذا نجد أنفسنا أمام صور متعددة للحركة تجعل القيادات أمام خيارات واسعة في كل مرحلة وكلما تغير ظرف أو طرأ طارئ .", "« الصورة الأولى » : أن تشتغل الجماعة كلها بالتعريف من خلال المحاضرات والحلقات العامة والحلقات الخاصة والكتاب والبيان . حتى إذا اطمأنت لاستقطاب الأمة كلها من خلال الحلقات العامة والخاصة وأشخاص الجماعة ، سارعت إلى إجراء عمليات انتقاء دقيقة لعناصر تقيم لها دورات تؤهلها للتنفيذ ثم سارت بعملية تنفيذ مدروسة ومخطط لها ، وهذا يقتضى صفا مهيأ للتعريف ، ومقتنعا به ، وثقة بالقيادة إذا اقتصرت عليه . كما يقتضى وجود قيادة قادرة ومؤهلة لإدارة التعريف بشكل كامل ، ولتهيئة ما يلزم من اعداد كامل لمراحل لاحقة . فلا تضيع بالتعريف فتقتصر عليه ، ولا تعجز عن التكوين فتفشل فيه ، ولا تقصر عن التنفيذ فتتدمر الجماعة ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0076.png"}, {"n": 77, "paras": ["« الصورة الثانية » : أن تشتغل الجماعة بآن واحد بالتعريف من خلال جهازه وبالتكوين من خلال جهازه وبالتنفيذ اليومي من خلال جهازه وهذا يقتضى وجود أجهزة تعمل بشكل دائم ومتكامل ، تحت اشراف قيادة تحسن وضع الأمور في مواضعها .", "« الصورة الثالثة » : أن تتحرك الجماعة بجملتها في التعريف ، ثم تنتقل بجملتها لتكوين العناصر التي كسبتها في المرحلة الأولى ، ثم تنتقل بجملتها للتنفيذ اليومي ، لتعطى جميع العناصر مرانا على التنفيذ . ثم تعود مرة ثانية الى التعريف ، ثم الى التكوين ، ثم الى التنفيذ وهكذا دواليك .", "« الصورة الرابعة » : أن تقتصر الجماعة على التعريف والتكوين فتجمع بينهما فقط بآن واحد ، والقيادة وحدها تعد خطط التنفيذ وتدرس امكانياته ، ويستمر العمل على ذلك حتى تطمئن القيادة على قدرتها على التنفيذ الشامل فتسير فيه .", "« الصورة الخامسة » : أن يجرى التنفيذ والتعريف والتكوين بآن واحد ، ويتولاه جهاز واحد . فمن عرف كون ثم دفع إلى التنفيذ . فلا فصل بين هذا وهذا وهذا لا في الجهاز ولا في الأشخاص ولا في المراحل . وهكذا يكون نمو التعريف والتنفيذ والتكوين واحدا ، ولكن هذا يقتضى أن يكون كل فرد قادرا على التعريف والتكوين والتنفيذ بآن واحد . وهكذا نجد أن مجموعة من الصور تتعدد معنا بحسب تعدد الأوضاع التي تمر على القطر الواحد ، أو بحسب تعدد أحوال الأقطار الاسلامية . فهناك قطر يناسبه تعريف وتكوين وتنفيذ يومي . وهناك قطر يناسبه تعريف فتكوين فاعداد للتنفيذ . والقيادات الموثوقة الأمينة المؤهلة لاتخاذ القرار السليم هي التي تعتمد الصورة المناسبة .", "آراء في التعريف والتكوين والتنفيذ : انه بمقدار نضجنا في قضية التعريف والتكوين والتنفيذ ، تكون أمورنا سائرة في الطريق الصحيح ، وبمقدار ما يكون التعريف صحيحا يكون التكوين أسهل ، وبقدر ما يكون التكوين صحيحا يكون التنفيذ أحكم وأقوى . ومن ثم فان النضج في هذه القضايا بشكل عام هو مظهر النضج العملي والنظرى في الجماعة . وبقدر ما توجد عندنا أجهزة"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0077.png"}, {"n": 78, "paras": ["مختصة ناضجة في كل قضية من هذه القضايا يكون سيرنا قد أخذ مسراه الكامل . فهذه قضايا ثلاث :", "١ - نضج نظرياتنا في هذه المسائل الثلاث .", "٢ - وجود الناضجين في هذه المسائل بشكل عام .", "٣ - وجود الأجهزة المختصة في هذه المسائل الثلاث . ولا شك أن الكلام في هذه القضايا متشعب إذ هو مرتبط بقضية الخصائص وقضية المناهج العضوية وقضية خطة العمل وقضايا أمن الجماعة ونوعية الأنظمة التي تعيش الحركة في سلطانها وغير ذلك .", "ماهية التعريف والتكوين والتنفيذ : قال الأستاذ البنا رحمه الله في التعريف : « التعريف : بنشر الدعوة بين الناس ويتصل بالجماعة كل من أراد من الناس ممن رغب بالمساهمة في أعمالها ووعد بالمحافظة على مبادئها وليست الطاعة التامة لازمة في هذا الطور بقدر ما يلزم فيه احترام النظم والمبادىء العامة للجماعة . وقال متحدثا عن هذه المرحلة : مرحلة الدعاية والتعريف والتبشير بالفكرة وإيصالها إلى الجماهير من طبقات الشعب » . وقال الأستاذ البنا عن التكوين : « التكوين باستخلاص العناصر الصالحة لحمل أعباء الجهاد وضم بعضها إلى بعض . ونظام الدعوة في هذا الطور صوفي بحت من الناحية الروحية وعسكري بحت من الناحية العملية . وشعار هاتين الناحيتين دائما « أمر وطاعة » من غير تردد ولا مراجعة ولا شك ولا حرج . والدعوة فيه خاصة لا يتصل بها إلا من استعد استعدادا حقيقيا لتحمل أعباء جهاد طويل المدى كثير التبعات . وأول بوادر هذا الاستعداد كمال الطاعة » . وقال الأستاذ : « ثم مرحلة التكوين وتخير الأنصار وإعداد الجنود وتعبئة الصفوف من بين هؤلاء المدعوين » . وقال الأستاذ البنا عن التنفيذ : « التنفيذ والدعوة في هذا الطور جهاد لا هوادة معه وعمل متواصل في سبيل الوصول إلى الغاية وامتحان وابتلاء لا يصبر عليهما إلا الصادقون . ولا يكفل النجاح في هذا الطور إلا كمال الطاعة كذلك » . وقال الأستاذ البنا : « ثم بعد ذلك كله مرحلة التنفيذ والعمل والإنتاج . وكثيرا ما تسير هذه المراحل الثلاث : أي التعريف والتكوين والتنفيذ جنبا إلى جنب نظرا لوحدة الدعوة وقوة الارتباط بينها جميعا .", "٦١ - في آفاق التعاليم"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0078.png"}, {"n": 79, "paras": ["فالداعي يدعو ، وهو في نفس الوقت يتخير ويربى ، وهو في الوقت عينه يعمل وينفذ كذلك . ولكن لاشك في أن الغاية الأخيرة أو النتيجة الكامنة لا تظهر الا بعد عموم الدعاية ، وكثرة الأنصار ، ومتانة التكوين « وفي هذه مقتطفات من كلام الأستاذ البنا رحمه الله ، ومنها نفهم أن التنفيذ عنده نوعان : تنفيذ يومي ، وتنفيذ شامل ، وأن التنفيذ اليومي مرتبط بموضوع العمل المتواصل المكافئ . وأما التنفيذ الشامل فيرتبط بموضوع تحقيق الأهداف الجماعية الكبرى . ومن كلامه أيضا أنه يدخل في التكوين التدريب الروحي والتدريب الرياضي بأن واحد . وأن المرشح له هو المستعد لكمال الطاعة . ومن كلام الأستاذ البنا نفهم أنه يدخل في التعريف : التعريف بالاسلام والتعريف بالجماعة ومبادئها وأن كمال الطاعة في هذه المرحلة ليس شرطا ، وانما يطالب الانسان في هذه المرحلة بمجرد احترام النظم والمبادىء العامة للجماعة .", "التكامل بين التعريف والتكوين والتنفيذ :", "في التعريف يبقى الهدف الأول أن يعرف الانسان الاسلام وأن يلم بالثقافة الاسلامية القديمة والمعاصرة ، وأن يعرف الجماعة وفكرها ، وأن يعطيها ولاءه ، مع الايمان والصلاة والزكاة . أى أن يعرف الاسلام وأن يلتزم به ويأهله بشكل عام ، وبقدر استعداده يعطى ويأخذ ، وبقدر سنه يعطى ويأخذ . والمهم هو ما ذكرناه فيأخذ حظه من فهم الأصول الثلاثة ، ومن القرآن وعلومه وخاصة التلاوة والحفظ ، ومن السنة وعلومها ، ومن الفقه والتوحيد والتصوف المصفي ومن أصول الفقه ، ومن العربية ومن التاريخ الاسلامي والسيرة ، ومن معرفة لحاضر العالم الاسلامي ، ومن معرفة بانتأمر على الاسلام وأساليب خصومه ، ومن الدراسات الاسلامية المعاصرة ومن فقه الدعوة من خلال الحلقات العامة والخاصة وأسرة التعريف ، وهذه قضايا كثيرة وكبيرة فأن يبقى الانسان فيها مدة طويلة فذلك ممكن ، والعبرة ألا ينتقل من مرحلة التعريف الى مرحلة التكوين حتى يتأكد من التزامه الكامل واستعداده للطاعة الكامنة ، أى أن يجتمع عنده ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0079.png"}, {"n": 80, "paras": ["كمال الاستعداد للتقوى والطاعة « فاتقوا الله وأطيعون »(١) . ومتى وجد الاستعداد والالتزام المبدئي ولم يكن هناك مانع فإنه يمكن أن ينتقل الإنسان إلى أسرة تكوين ، والهدف من أسرة التكوين أن يكون الإنسان إسلاميا وإخوانيا بشكل كامل . والأصل في أسرة التكوين العمل والتدريب . وقد رأينا كلام الأستاذ البنا رحمه الله عن التكوين إذ عبر عنه بقوله : « ونظام الدعوة في هذا الطور صوفي بحت من الناحية الروحية وعسكري بحت من الناحية العملية ، وشعار هاتين الناحيتين دائما أمر وطاعة من غير تردد ولا مراجعة ولا شك ولا حرج » .", "ومن ثم فإن المشرف على التكوين ينظر في أمر الأخ عن دراسته واستيعابه ، وعن التزامه وتضحيته ، وعن عبادته وتقواه ، ثم على ضوء المناهج وخريطة التكوين يطلب منه تكميل نواقصه ، من خلال الجهد الشخصي ، ومن خلال الإحاطة على المتصدرين للعلم والتعليم الإسلاميين ، ومن خلال الدراسة المشتركة والدورات ، مع ملاحظة ما قاله الأستاذ عن مرحلة التكوين من أنها صوفية وجندية . ففي الجانب الصوفي يركز على الأوراد : ورد الاستغفار والمحاسبة ، ورد الصلاة وقيام الليل ، ورد الذكر والدعاء . وفي الجانب الآخر يركز على الأمر بالمعروف والنهي عن المنكر وضرورة الطاعة بالمعروف . وهكذا حتى يستكمل موازين النضج في التكوين كما سنراها . وخلال ذلك يدرس استعداده . فهناك ناس قابليتهم للتعليم أكثر . وهناك ناس قابليتهم للتكوين أكثر . وهناك ناس قابليتهم للتنفيذ أكثر . وعلى ضوء الدراسة يفرز الأخ إما إلى جهاز تعريف أو تكوين أو تنفيذ . وإذا فرز إلى جهاز أقيمت له دورة أو دورات ليستكمل دوره في مهمته في الجهاز المفروز إليه . وأيا كان جهازه فيجب أن يوجه إلى استكمال ثقافته الإسلامية . وأيا كان جهازه الخاص فإنه يعتبر جزءا من جهاز التنفيذ ، وكل مرحلة تكمل نواقص المرحلة السابقة ويجب أن تكون موازين الكمال معروفة ، وعلى ضوء الأخذ الكامل للعلم والخصائص يعطى الإنسان صفة النقيب أو النائب . وقد نجد إنسانا أخذ حظه", "(١) آل عمران : ٥٠ ، الشعراء : ١٠٨ ، ١١٠ ، ١٢٦ ، ١٣١ ، ١٤٤ ، ١٥٠ ، ١٦٣ ، ١٧٩ ، الزخرف : ٦٣"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0080.png"}, {"n": 81, "paras": ["الأدنى من الثقافة الاسلامية مما أهله الى مرحلة التكوين ، وأخذ حظه الأدنى من التكوين مما أهله الى مرحلة التنفيذ ، لكنه ما لم يحصل كمالات هذا كله لا يصح أن يعطى صفة النقيب أو النائب ، وهكذا نجد أن كل مرحلة بحاجة الى ما قبلها وأن كل مرحلة تخدم ما بعدها .", "(( فصل ))", "المراد بالتعريف : تعريف الانسان على الاسلام بشكل عام ، تعريفا علميا وعمليا ، وهذا يقتضى تعليما ، وحدا أدنى من الخصائص وحدا أدنى من الالتزام . ووسيلتنا الى ذلك الحلقات العامة ، والحلقات خاصة ، والدعوة الفردية ، والمذكرة الفردية . وميزان النجاح في هذه المرحلة دراسة مجموعة من الكتب الهادفة المتكاملة ، والتزامه ببعض الأمور الرئيسية . فاذا تحقق بهذا كله فانه يمكن أن ينقل الى مرحلة التكوين . واذا فاته كل شيء من الخصائص أو الالتزام فانه يستمر في الحلقات العلمية لأخذ برامج أرقى علميا ولكنه لا يكون مرشحا للتكوين . والمراد بالتكوين : تربية الانسان على ضوء درجات العضوية في الجماعة ليؤدى دوره الكامل في خدمة الاسلام من خلال الصف ، وذلك يكون من خلال الأسر والحلقات والدورات . الحلقات لأخذ البرامج العلمية الضرورية لدرجات العضوية . والأسر لأخذ البرامج الخاصة . والدورات لاعطائه الزاد المركز الضرورى لمرحلة ما . ومراتب العضوية الرئيسية عندنا يمكن أن تكون أربعة : رتبة النصير ، فالمجاهد ، فالنقيب ، فالنائب . ولكل رتبة ثقافتها وخصائصها والتزاماتها . وبناء على التكوين يفرز الانسان اما الى جهاز التعريف أو التكوين أو التنفيذ .", "ان كثيرين من اخوتنا يتمنون أن يقفزوا الى قضايا التنفيذ دون أن يعطوا موضوع التعريف والتكوين الأهمية اللازمة لهما وهذا خطأ لأن التنفيذ الذى لا يستند الى أرضية التعريف والتكوين محكوم عليه بالفشل لأسباب متعددة :"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0081.png"}, {"n": 82, "paras": ["( أ ) لأن أجهزة التنفيذ في هذه الحالة يمكن أن يتسلل لها أو يدخلها أو يدخس فيها من ليس جديرا بالثقة وواحد في هذه الحالة يمكن أن يسبب كارثة . ( ب ) لأن التنفيذ المعاصر يحتاج إلى ذكاء وقاد وتدريب عال وهذا كله يحتاج إلى انتقاء من خلال أجهزة التعريف والتكوين . ( ج ) لأن أجهزة التعريف والتكوين هي التي يمكن أن تقدم لنا المدد الدائم الذي يرفد أجهزة التنفيذ وبدون ذلك فان أجهزة التنفيذ قد تتوقف عن النمو . ( د ) لأن أجهزة التنفيذ إذا لم تستطع أن تحرك مجموع الأمة من خلال أجهزة التعريف والتكوين فانها ستفشل . ( ه ) لأن أجهزة التعريف والتكوين هي التي تقدم المسح الشامل لكل شيء في الأمة بشكل تلقائي وعفوي وذلك ضروري للتنفيذ . ( و ) لأن أجهزة التعريف والتكوين هي التي تستطيع أن تتصل بكل فرد في الأمة ومن خلال ذلك يتم نقل الأمة والناس .", "(( فصل ))", "في درجات العضوية ومراحلها ولوازم كل مرحلة وخريطة ذلك بشكل عام : ان علة المسلمين تكمن في الخلل بواحدة من دوائر ثلاث : اما دائرة العلم والثقة ، واما دائرة النقص في الخصائص ، واما في دائرة الالتزام . فاما أنك تجد مسلما لا ثقافة ولا علم اسلاميين عنده ، ثم لا خصائص ولا التزام ، واما أن تجد بعض علم دون خصائص أو التزام ، أو التزاما دون خصائص وعلم ، أو شيئا من الخصائص والعلم دون الالتزام . وهكذا تبقى قضايا المسلمين سائبة أو ضائعة بسبب ذلك ، وبشكل عادي تبقى قضية الاسلام نفسه ضعيفة بسبب من ذلك ، ولا شك أن علاج هذا الوضع كله انما يكون بالانتساب الى جماعة المسلمين ، فذلك الذي يحقق الالتزام ، وأن تحاول الجماعة على ضوء نظرية متكاملة أن تعطى كل ما يلزم في باب الثقافة والعلم ، وأن تنمى"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0082.png"}, {"n": 83, "paras": ["ما استطاعت قضية الخصائص ، وشيء عادى أنه في هذه الدوائر الثلاث لابد من تدرج ، ولابد من الانتقال بالعضو من حد أدنى إلى حد أرقى منه ، إلى ما فوق ذلك . والأستاذ البنا ذكر تفصيلا : ست درجات في مراتب العضوية يمكن أن تختصر إلى أربعة : هي درجة الأنصار ثم درجة المجاهدين ثم درجة النقباء ثم درجة النواب . والمفروض أن يكون لكل درجة منها منهاجها العلمي والثقافي وأن يكون لها خصائصها وأن يكون لها التزاماتها ، وعلى ضوء التحصيل العلمي والتحقق بالخصائص ومقدار الالتزام يكون التقدم في درجات العضوية أو البقاء في درجات دنيا أو حتى البقاء على هامش الصف . وبشكل عام فاننا نعتبر مجموعة الأبواب التي ذكرت في كتاب « جند الله ثقافة » هي مجموعة الأبواب التي يعتبر أخذها دليل الكمال في الثقافة الاسلامية وعلومها أصولا وفروعا ، ولكن الثقافة الكاملة المرادة من الأخ شيء يزيد على ذلك . إذ الثقافة المعاصرة ينبغي أن تكون جزءا من تكوين الأخ الثقافي ، وكذلك الثقافة التأهيلية التي تؤهله للنبوغ في اختصاص حياتي أو تؤهله للنجاح في جانب من العمل الاسلامي ، ان ذلك كله هو مظهر للكمال في الدائرة الأولى ؛ أما الخصائص فلا شك أن مجموع خصائص الأخ النصير أقل من خصائص الأخ النقيب ، فضلا عن النائب . فما هي الخصائص التي تناسب كلا من درجات العضوية . ثم أن مقدار ما يطالب به العضو بالتزامات يختلف حتما باختلاف درجات عضويته . فما هي التزامات كل عضوية من العضويات . انه لابد أن تكون نظرياتنا في هذا الموضوع واضحة ولابد أن نعطيها وجودها العملي وينبغي أن تكون النظريات من القوة والوضوح بحيث يشعر كل مسلم ضرورتها وبداهتها .", "لا شك أنه ما من مسلم يمارى أن عليه كحد أدنى من الثقافة أن يعرف أهم ما يلزمه في حياته اليومية ، وما يلزمه لواقعه اليومي لتأدية الواجبات والسنن اليومية أو الأسبوعية أو الشهرية في حدها العادى ولحياة العادية ؛ وبالتالى فأن نطالب المسلم مثلا بأن يدرس كتابا"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0083.png"}, {"n": 84, "paras": ["مختصرا في العقائد ، وكتابا مختصرا في فقه العبادات ، ورسالة صغيرة في الأخلاقيات ، وأن يعرف كيف يقرأ كتاب الله من خلال تلاوة يومية ، ويعرف علم التجويد ، وأن يحفظ بعض ما ورد فيه ندب خاص من سور قرآنية ، وأن يعرف شبهات أعداء الله عن الاسلام من خلال دراسته لكتاب في ذلك ، وأن يعرف معركة الاسلام مع خصومه ، وأن يكون عنده شيء من فقه الدعوة . أن هذه المعاني كلها يمكن أن يدرك المسلم ضرورتها ، وأن يعرف بالبداهة أنها تلزمه كحد أدنى في دائرة الثقافة ، وأن يطالب المسلم بأن يقيم الصلاة ويؤتى الزكاة وأن يحرر ولاءه لجماعة المسلمين وأن يكون له ورده اليومي من قراءة قرآن واستغفار وصلاة على رسول الله صلى الله عليه وسلم وتكرار لا اله الا الله وقيام الليل . كل ذلك يقبله المسلم بداهة كحد أدنى من الخصائص ، وأن يطالب المسلم بأن يلتزم بحضور الاجتماعات العلمية اذا دعى اليها وأن يدفع زكاته لأهل الاسلام وبالتحديد لجماعة المسلمين ، اذا لم يكن هناك من هو أحق شرعا فذلك أيضا يقبله المسلم بداهة كحد أدنى من الالتزام .", "وهذا الذي نتصور أنه لابد منه لاعطاء صفة العضوية الأولى عضوية النصير . فاذا ما أريد نقل الأخ الى درجة المجاهد ؛ فانه يحتاج الى دراسة صفات حزب الله كما وردت في القرآن ، ويحتاج الى التحقق بخصائص الجندية الربانية ، ولابد أن يقتنع بضرورة الجندية الربانية التي تستلزم الطاعة للقيادة الربانية ، وعليه أن يقنع بضرورة الدراسات القرآنية الخاصة في قضايا الجهاد ، وبضرورة الدورة الروحية للتحقق بخصائص المقاتل الروحية ، وبضرورة الدورة الأمنية لينمو حسه الأمني ، وبضرورة ممارسة الأمر بالمعروف والنهي عن المنكر كصفتين أساسيتين للجماعة التي تستأهل نصر الله ، وبضرورة أنواع من التدريب الرياضي . وذلك كله ينبغي أن يكون الأساس المعتمد لاعطاء صفة العضوية من الدرجة الثانية . عضوية المجاهد . وأن يطالب الأخ أن يأخذ حظا لا بأس به من كل أبواب الثقافة الاسلامية ، وحظا مما يلزمه كثقافة معاصرة ، وأن يطالب الأخ ويمرن على الكرم ، وتحمل المسئوليات وتنفيذها بشجاعة ، وأن يطالب بالحلم والأناة والرحمة باخوانه وخدمتهم ورعايتهم كخصائص وردت في شأنها نصوص مرتبطة بقضية الآمرة ، وأن يطالب الأخ ببيعة على الالتزام بقواعد الجماعة المنبثقة عن شوراها ،"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0084.png"}, {"n": 85, "paras": ["وأن يطالب بالالتزام بطاعة القيادة المنبثقة عن القواعد التنظيمية للجماعة ، كل ذلك واضح المعنى ويسهل فهمه بالبداهة ، وكل ذلك لابد منه ليعطى الأخ درجة النقيب .", "وأن نطالب الأخ بالتوسع في كل أبواب الثقافة الاسلامية المعاصرة ، وأن نطالبه بأخذ الخصائص التي تقتضيها الوراثة النبوية ، وأن نطالبه بالنزول على رأى الأكثرية صاحبة الحق في الشورى على ضوء نظريات الجماعة ، كل ذلك معقول المعنى بالنسبة لاعطاء الأخ درجة النائب .", "ولا يصح أن نعطى أخا رتبة درجة ، ما دام متخلفا في دائرة من دوائرها الثلاث . لأن أى تساهل في اعطاء الصفة سيكون على حساب سلامة الثقة ، التي بدونها لا يتم عمل وسيكون على حساب سلامة الصف التي بدونها لا يستطيع الصف أن يحتفظ بقدرته على الحركة السليمة المستمرة ، ولا بقدرته على تحقيق الأهداف . وان أى تفريط في سلامة الصف يجعله غير مرشح للنمو الذي يؤهله للتوسع المستمر لتحقيق كلمة الأستاذ البنا رحمه الله : « وخلاصة ذلك جملتان : ايمان وعمل ، ومحبة واخاء » وماذا فعل رسول الله صلى الله عليه وسلم في تركيز دعوته في نفوس الرعيل الأول من أصحابه أكثر من أن دعاهم الى الايمان والعمل ثم جمع قلوبهم على الحب والاخاء فاجتمعت قوة العقيدة الى قوة الوحدة . وصارت جماعتهم هي الجماعة النموذجية التي لابد أن تظهر كلمتها وتنتصر دعوتها وان ناوأها أهل الأرض جميعا ، وماذا فعل الدعاة جميعا من قبل ومن بعد أكثر من هذا ينادون بالفكرة ويوضحونها ويدعون الناس اليها ، فيؤمنون بها ويعملون لتحقيقها ويجتمعون عليها ، ويزدادون عددا فتزداد الفكرة بهم ظهورا ، حتى تبلغ مداها وتبتلع ما سواها ، وتلك سنة الله « ولن تجد لسنة الله تبديلا » ( الأحزاب : ٦٢ ، الفتح : ٢٣ ) وليعلم أن قدرة الصف على النمو المطرد مع احتفاظه بسلامته بحيث لا يتعرض للانقسام ، هي وحدها السبيل لذلك ، وأى اهمال في قضية العضوية أو تساهل في اعطاء أحد صفة لا يستحقها ، تفريط بحق الصف وبالتالى حق العمل الاسلامى أصلا ، لأن التنفيذ يستحيل اذا لم يوجد الصف السليم الذي تملؤه الثقة والقادر على اتخاذ كل قرار سليم .", "ووسائلنا للوصول الى التربية على مراحل العضوية كلها هي"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0085.png"}, {"n": 86, "paras": ["الحلقات العلمية العامة والخاصة ، ونظام الدورات . وعلى الجماعة أن تؤمن هذه الأمور كلها ولوازمها والترتيبات والتنظيمات والأجهزة اللازمة لذلك .", "وهذه خريطة نحاول فيها أن نرسم خريطة التكوين بشكل تقريبي وهي خريطة نلحظ فيها ما يلزم لكل درجة من درجات العضوية الأربع في الدوائر الثلاث : الثقافة والعلم - الخصائص - الالتزام ، ونذكر فيها كذلك الدورات اللازمة لبعض أنواع العضوية . وسنذكر بعد الجدول مجموعة الملاحظات الضرورية لاستيعاب هذه الخريطة . وما ورد في هذه الخريطة من أسماء كتب لا يراد به الكتاب بعينه ، بل المراد المضمون . فأي كتاب حقق المضمون فانه يمكن أن يعتمد ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0086.png"}, {"n": 87, "paras": ["الدائرة الأولى : دائرة الثقافة والعلم والحفظ", "المادة | المرحلة الأولى | المرحلة الثانية --- | --- | ---", "١ - القرآن | إتقان التلاوة ، حفظ سور : الكهف ، الواقعة ، يس ، تبارك وجزء عم | دراسة سورتي الأنفال وبراءة وحفظهما إن أمكن", "٢ - السنة | الأربعون النووية المأثورات |", "٣ - الأصول الثلاثة | خلاصة |", "٤ - الفقه | فقه الصلاة والزكاة ، قراءة متن فقه كمتن نور الإيضاح أو ما يقابله |", "٥ - أصول الفقه | |", "٦ - التوحيد | ما يجب معرفته على كل مسلم أو أصول العقائد |", "٧ - التصوف | رسالة المسترشدين |", "٨ - اللغة العربية | |", "٩ - التاريخ الإسلامي السيرة ، حياة الصحابة | نور اليقين ، تهذيب السيرة أو صور من حياة الرسول |", "١٠ - حاضر العالم الإسلامي | |", "١١ - الثقافة المعاصرة | شبهات حول الإسلام |", "١٢ - الدراسات الإسلامية | |", "١٣ - التآمر على الإسلام والمسلمين | من أجل خطوة إلى الأمام | جند الله ثقافة وأخلاقا رسالة التعاليم ، المعالم", "١٤ - فقه الدعوة | الصراع بين الفكرة الإسلامية والفكرة الغربية |"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0087.png"}, {"n": 88, "paras": ["(تابع) الدائرة الأولى : دائرة الثقافة والعلم والحفظ", "المرحلة الثالثة المادة", "١ - القرآن: حفظ سورة البقرة ودراستها ، ودراسة كتاب مختصر في علوم القرآن", "٢ - السنة: كتاب الأذكار - رياض الصالحين - دراسة كتاب في علوم الحديث كشرح البيقونية", "٣ - الأصول الثلاثة: سلسلة الأصول الثلاثة", "٤ - الفقه: اللباب في شرح الكتاب - مراقي الفلاح أو كفاية الأخيار ، والفقه المبسط", "٥ - أصول الفقه: أصول الفقه لخلاف - جولات في الفقهين", "٦ - التوحيد: شرح الجوهرة - أو كبرى اليقينيات", "٧ - التصوف: تربيتنا الروحية", "٨ - اللغة العربية: قطر الندى - البلاغة الواضحة - قراءة كتاب لتصحيح اللفظ والمران على الخطابة", "٩ - التاريخ الإسلامي السيرة ، حياة الصحابة: حياة الصحابة - مذكرات الدعوة والداعية", "١٠ - حاضر العالم الإسلامي: تتبع ما كتب ويكتب في هذا الشأن", "١١ - الثقافة المعاصرة: حوار - فلسفتنا - كتب المودودي", "١٢ - الدراسات الإسلامية: تتبع ما كتب ويكتبه كتاب الحركة الإسلامية المعاصرة بما يخدم استيعاب فكر العصر", "١٣ - التآمر على الإسلام والمسلمين: التبشير والاستعمار - الغارة - البروتوكولات", "١٤ - فقه الدعوة: المدخل - تفهيم التعاليم - جند الله تخطيطا وتنظيما وتنفيذا"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0088.png"}, {"n": 89, "paras": ["( تابع ) الدائرة الأولى : دائرة الثقافة والعلم والحفظ", "المادة | المرحلة الرابعة ---|---", "١ - القرآن | الأساس في التفسير - مطالعات في الظلال", "٢ - السنة | الأساس في السنة وفقهها", "٣ - الأصول الثلاثة |", "٤ - الفقه | التوسع في دراسة الفقه", "٥ - أصول الفقه | أصول الفقه للدكتور أديب الصالح", "٦ - التوحيد |", "٧ - التصوف | المطالعة في كتاب إحياء علوم الدين", "٨ - اللغة العربية | شذور الذهب ، المران على الكتابة وخاصة كتابة الدراسات في شأن محلي ومعالجته", "٩ - التاريخ الإسلامي السيرة ، حياة الصحابة | كتاب ريني وحلان عن الفتوحات الإسلامية", "١٠ - حاضر العالم الإسلامي | تتبع ما كتب ويكتب في هذا الشأن", "١١ - الثقافة المعاصرة | المتابعة لدراسة كتب فقهاء الدعوة", "١٢ - الدراسات الإسلامية | اقتصادنا - مدخل الدكتور النجار إلى الاقتصاد الإسلامي", "١٣ - التآمر على الإسلام والمسلمين | التتبع", "١٤ - فقه الدعوة | دراسة الأنظمة واللوائح المعتمدة"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0089.png"}, {"n": 90, "paras": ["( تابع ) خريطة التكوين", "| المراحل | الدائرة الثانية : دائرة الخصائص | المراحل | الدائرة الثالثة : دائرة الالتزام | | :--- | :--- | :--- | :--- | | المرحلة الأولى | إقامة الصلاة <br> إيتاء الزكاة <br> سلامة الولاء | المرحلة الأولى | - حضور الاجتماعات العامة والخاصة <br> - دفع الزكاة للجماعة <br> - ورد الدعاء - وقراءة جزء من القرآن <br> - المحافظة على السنن الرواتب وسنة الضحى وقيام الليل | | المرحلة الثانية | محبة الله <br> الرحمة بالمؤمنين - العزة على الكافرين <br> الجهاد بالنفس والمال <br> إعطاء الولاء الكامل بفروعه كلها لجماعة المسلمين | المرحلة الثانية | ١ - الالتزام بمقتضيات الخصائص بالسير فيما يؤدي إلى ذاك <br> ٢ - الطاعة الكاملة في المعروف | | المرحلة الثالثة | الحلم والأناة { خصائص دلت عليها <br> الخدمة <br> الكرم <br> الشجاعة { نصوص لنصب الأمرة | المرحلة الثالثة | البيعة على الطاعة للقيادة المنبثقة عن القواعد المعتمدة بالشورى والالتزام بالدعوة إلى الصف دون ملاحظة شخص | | المرحلة الرابعة | الصدق <br> الأمانة والالتزام بالاسلام ظاهرا وباطنا <br> الوعي - التبليغ <br> التعليم - التربية | المرحلة الرابعة | الالتزام بالنزول على رأي الأكثرية صاحبة الحق في القرار على ضوء قواعد الجماعة |"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0090.png"}, {"n": 91, "paras": ["(تابع) خريطة التكوين", "المراحل | وعده خريطة الدورات التأهيلية المقترحة لكل مرحلة من المراحل ---|--- المرحلة الأولى | يمكن أن تقدم رسالة من أجل خطوة إلى الأمام في دورة يتم خلالها التعويد على الخصائص والمطالعة بالالتزام والتعويد عليه ويفضل أن يتم ذلك بعد كل الدراسات المقررة أن تقرر اعطاؤها بشكل دورة . المرحلة الثانية | ١ - دورة روحية .", "٢ - دورة أمنية .", "٣ - دورة على ممارسة الأمر بالمعروف والنهي عن المنكر .", "٤ - دورة رياضية وكشفية . المرحلة الثالثة | دورة في إدارة الحلقات والرحلات والحفلات والأسر والمجموعات الحركية والخروج في الدعوة إلى الله ، ويمكن أن يعتمد كأساس لهذه الدورة « المدخل » . المرحلة الرابعة | دورة تأهيلية للعمل الذي سيفرز له الأخ النائب يقدمها له الجهاز الذي سيفرز له ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0091.png"}, {"n": 92, "paras": ["(( ملاحظات ))", "١ - نذكر أحيانا سلسلة الأصول الثلاثة في منهاج النقيب ونذكرها أحيانا في منهاج النصير ولا تناقض فالنصير ينبغي أن يأخذ خلاصة عنها والنقيب ينبغي أن يستوعبها .", "٢ - ان المراحل الرئيسية في العضوية داخل الصف الاسلامي أربع : مرحلة الأنصار ، ثم مرحلة العاملين « المجاهدين » ، ثم مرحلة النقباء ، ثم مرحلة النواب وهم الذين يقابلون خلفاء المرشد في اصطلاح الصوفية ، وهذه قضية اصطلاحية والعبرة للمضمون فقد تختصر هذه المراحل أو توسع .", "٣ - يمكن أن يتقدم انسان في العلم دون الخصائص والالتزام ، أو في العلم والخصائص دون الالتزام ، أو في الالتزام دون الخصائص والعلم ؛ وكل ذلك وضع غير عادى ويجعله صاحبه مرشحا لعضوية ما دون اعطائه صفتها .", "٤ - اعتمدت الخريطة مبدأ الدورات كأساس للانضاج في بعض المراحل اما من أجل علم ، أو من أجل تربية خصائص أو من أجل تنمية التزام .", "٥ - ذكر في الجدول المراحل الأربع في درجات العضوية ، والمنهج المناسب لكل منها ، وما هي خصائص كل منها ، وما هي التزامات كل منها ، وما هي الدورات التي تلزم بعضها .", "٦ - ينبغي أن يلاحظ القائمون على التعليم والتربية أنه في منهاج المرحلة الأولى لابد أن نلاحظ قضية الايمان ، فاذا وجدت شبه أو تعقيدات فكرية لدى انسان فينبغي أن يعمق الايمان في قلبه ، من خلال عرض بعض المعاني ، أو وضع بعض الكتب في يده ، أو تدريسه اياها ، ككتاب « الله » وكتاب « الرسول » صلى الله عليه وسلم . كما ينبغي أن يدفع نحو الذكر للوصول الى الطمأنينة القلبية .", "٧ - يلاحظ أن المرحلة الثانية مرحلة عملية تكوينية وقد جعل الأستاذ البنا عن سماتها أنها صوفية بحتة من الناحية الروحية وجندية بحتة من ناحية الانضباط ويراعى فيها تعدد الدورات : الدورة الروحية ليصبح الأخ ذاكرا عابدا ، ودورة الأمر بالمعروف والنهي عن المنكر"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0092.png"}, {"n": 93, "paras": ["ليصبح ذلك من أخلاقه ، والدورة الرياضية ليمتلك الأخ اللياقة في الجسم . والأخ الموجه يستطيع أن يعتمد كتاب « تربيتنا الروحية » في موضوع الدورة الروحية .", "٨ - يلاحظ أن المرحلة الثالثة هي التي تخرج الواسطة بين الصف الأول وبين القاعدة كلها ، كما أنها تخرج الأخوة أصحاب العلاقة المباشرة في المتابعة .", "٩ - يلاحظ أن المرحلة الرابعة هي مرحلة الوراثة الكاملة فليس لها حدود تقف عندها وحدها الأدنى أن يأخذ الأخ من الثقافة الاسلامية أصولا وفروعا ما يعتبر به مستوعبا لكل علم ، ومن الخصائص ما يعتبر به غير مفرط بخلق ، ومن الالتزام ما يضمن به عدم انقسام الصف الاسلامي . اننا لا نتصور أن تنفيذا صحيحا يمكن أن يتم الا اذا كان العلم والخصائص والالتزام هو الأساس لذلك فعلينا أن ننتبه جيدا وألا نتسرع في عملية البناء قبل وجود عناصرها اللازمة لها ، فلان نتأنى في عملية البناء ليكون البناء متينا خير من أن نستعجل عملية البناء فيسقط أو يتصدع ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0093.png"}, {"n": 94, "paras": ["الباب السابع في مقومات الشخصية الإسلامية وواجباتها من خلال رسالة التعاليم", "تلخيص وتقديم : ذكرنا في الباب الأول أن واضع نظريات العمل الإسلامي المعاصر هو حسن البنا رحمه الله ، وذكرنا في الباب الثاني بعض مفاتيح الفهم لدعوة الاخوان المسلمين ، وذكرنا في الباب الثالث بعض المهمات الكبرى لحركة الاخوان المسلمين . وقادنا ذلك إلى الأهداف الكبرى لحركة الاخوان المسلمين ، كما حددها الأستاذ البنا في رسالة التعاليم وغيرها ، فأوصلنا ذلك إلى مراحل السير لتحقيق هذه الأهداف كما حددها الأستاذ البنا في رسالة التعاليم وغيرها ، وكل ذلك كان بين يدى عرض رسالة التعاليم التي حددت مقومات الشخصية الاسلامية التي تستطيع أن تحقق الأهداف كما حددت واجبات هذه الشخصية . وها نحن الآن وصلنا إلى المقصود الرئيسي في هذا الكتاب وهو تفهيم رسالة التعاليم . وهذا أوان الشروع في المقصود . والله المستعان .", "(( فصل )) ان مقومات الشخصية الاسلامية التي تحققت بالاسلام ، والقادرة على تحقيق أهدافه ضمن مراحل الدعوة هي عشرة مقومات : « الفهم والاخلاص والعمل والجهاد والتضحية والطاعة والثبات، والتجرد والأخوة والثقة » وأعطيت البيعة على ذلك . والتزمت بأربعين واجبا حددتها رسالة التعاليم . وقد حددت رسالة التعاليم مضامين المقومات وفصلت في الواجبات ، ونحن في هذا الباب سنقدم رسالة التعاليم كما هي ، مع تعليقات وهوامش وشروح وحواشي يخرج منها", "٧١ - في آفاق التعاليم »"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0094.png"}, {"n": 95, "paras": ["دارس هذا الباب بما يحتاجه من استيعاب لفكر الأستاذ البنا في هذه الرسالة .", "(( فصل ))", "قال الأستاذ البنا في تقديمه لرسالة التعاليم :", "بسم الله الرحمن الرحيم", "والحمد لله والصلاة والسلام على إمام المتقين وقائد المجاهدين سيدنا محمد النبي الأمين وعلى آله وصحبه ومن تبع هداهم إلى يوم الدين .", "أما بعد ...", "فهذه رسالتي إلى الإخوان المجاهدين من الإخوان المسلمين ، الذين آمنوا بسمو دعوتهم ، وقدسية فكرتهم ، وعزموا صادقين على أن يعيشوا بها أو يموتوا في سبيلها ، إلى هؤلاء الإخوان فقط أوجه هذه الكلمات الموجزة ، وهي ليست دروسا تحفظ لكنها تعليمات تنفذ ، فالى العمل أيها الإخوة الصادقون (( وسيرى الله عملكم ورسوله والمؤمنون ، وستردون إلى عالم الغيب والشهادة فينبئكم بما كنتم تعملون ))(١) (( وأن هذا صراطى مستقيما فاتبعوه ، ولا تتبعوا السبل فتفرق بكم عن سبيله ، ذلكم وصاكم به لعلكم تتقون ))(٢) أما غير هؤلاء فلهم دروس ومحاضرات ، وكتب ومقالات ، ومظاهر وأداريات ، (( ولكل وجهة هو موليها ، فاستبقوا الخيرات ))(٣) (( وكلا وعد الله الحسنى ))(٤) .", "والسلام عليكم ورحمة الله وبركاته .", "حسن البنا", "(١) من سورة التوبة : ١٠٥ ونص الآية : (( وقل اعملوا فسيرى ... )) .", "(٢) الأنعام : ١٥٣", "(٣) البقرة : ١٤٨", "(٤) النساء : ٩٥"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0095.png"}, {"n": 96, "paras": ["تعليق : من هذا التقديم ندرك أن رسالة التعاليم رسالة عملية ، كتبت من أجل أن ينصق الأخ الصادق على ضوئها ، والأخ الصادق هو الذي آمن بالدعوة ، وقرر أن يعطيها كل ما تحتاجه ، وأن يلتزم بكل ما تتطلبه منه .", "« فصل »", "قال الأستاذ رحمه الله : « أيها الإخوان الصادقون : أركان بيعتنا عشرة فاحفظوها : الفهم ، والإخلاص ، والعمل ، والجهاد ، والتضحية ، والطاعة ، والثبات ، والتجرد ، والأخوة ، والثقة » .", "شرح : كان رسول الله صلى الله عليه وسلم يأخذ أنواعا من البيعات من أصحابه رضي الله عنهم ؛ فهناك بيعة الدخول في الإسلام وكانت تتضمن أحكاما بعينها ، وهناك بيعات أخرى كان يأخذها على بعض أصحابه . ويوم العقبة بايع الأنصار رسول الله صلى الله عليه وسلم على أن يمنعوه مما يمنعون منه نساءهم . ويوم بيعة الرضوان بايع الأصحاب على ألا يفروا .", "ثم بعد رسول الله صلى الله عليه وسلم وجدت البيعة لأمير المؤمنين على السمع والطاعة في كتاب الله والسنة . ووجدت بجانب البيعة لأمير المؤمنين بيعات تعاقدية على عمل ما كتعاقد بعض المجاهدين يوم اليرموك .", "واستقر فيما بعد في المجتمع الإسلامي نوعان من البيعات . بيعة للسلطان المسلم على السمع والطاعة وبيعة على الفتوى للشيوخ . واستقل بهذه البيعة في النهاية الصوفية حتى أصبحت علما عليهم . وهكذا وجد في المجتمع الإسلامي بيعة يراد بها عين الشخص وهي البيعة التي تعطى في الأصل للخليفة الراشد ويترتب عليها أحكام"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0096.png"}, {"n": 97, "paras": ["شخصية يلاحظ بها عين الشخص المعطاة له البيعة ، وبيعة على العمل ويراد به العمل الذي حددته البيعة . والأصل أن البيعة من النوع الأول لا يصح أن تعطى إلا لشخص واحد هو أمير المؤمنين . وقد ورد في الحديث الصحيح : « اذا بويع لخليفتين فاقتلوا الآخر منهما » أما البيعة على عمل صالح فهذه يستطيع كل فرد أن يأخذها من كل فرد ولا يترتب عليها عقد شخصي بين الطرفين ، ولذلك قال فقهاء الحنفية كما في الفتاوى الحامدية : « رجل أعطى العهد لشيخ ثم أعطاه لآخر ، أي العهدين يلزمه ؟ قالوا : لا هذا ولا ذاك ولا أصل لذلك » . وعلى هذا فكل البيعات التي يأخذها شيوخ على تلاميذهم أو زعماء على أتباعهم أو متصدرون على تابعين لا تعتبر ملزمة . فهي إن كانت على عمل فاللازم هذا العمل ، فان كان في الأصل مفروضاً فالبيعة تزيده توثيقا ، وان كان مندوبا في الأصل فالبيعة تأخذ حكم اليمين ، أما إذا كانت بيعة لعين الشخص على الطاعة المطلقة أو الطاعة في المعروف فما لم يكن هذا الشخص هو أمير المؤمنين فان البيعة ليست ملزمة .", "في عصرنا فقد منصب الخلافة . وقد نص فقهاء الشافعية أنه في هذه الحالة تعطى الخلافة لأعلم أهل زمانه ، على أن فقهاء الحنفية لا يعتبرون أحدا خليفة حتى ينفذ أمره ، أي حتى يمتلك السلطة التنفيذية فما قبل ذلك تعتبر البيعة عندهم بيعة على عمل .", "جاء حسن البنا رحمه الله والمتصدرون لأخذ بيعات العمل على الناس كثيرون ، فكل شيخ طريق يأخذ البيعة على أصحابه ، وفي الغالب فان هذه البيعة تكون بيعة على ورد ذكر وكثيرا ما حدث لبس عند المريدين وعند الشيوخ اذ أخذ هؤلاء يعطون البيعة للشيخ معنى البيعة لأمير المؤمنين فصار في هذه الأمة آلاف الأمراء للمؤمنين . جاء حسن البنا والأمر كذلك ، فكان لابد من إرجاع أمر إلى نصابه في أكثر من شيء .", "١ - ما هي مجموع المعاني التي يحتاجها المسلمون لحركتهم في"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0097.png"}, {"n": 98, "paras": ["عصر ذي خصائص معينة وفي أوضاع استثنائية وفي فوضى ليست لها حدود .", "٢ - كيف يسير المسلمون في الطريق الذي تنبثق عنه القيادة الراشدة الواحدة التي تأخذ البيعة من المسلمين بحق . وللجواب على هذين السؤالين أوجد الأستاذ البنا جماعة الاخوان المسلمين وجعل أركان البيعة عشرة . فمهمة الاخوان المسلمين الأولى اذن أن يحققوا كل فرد بأركان البيعة العشرة كطريق وحيد لسير اسلامي متكامل ، كما أن مهمتهم أن يعملوا في محيط هذه الأرض لينبثق عن الصف الراشد القيادة الراشدة المؤهلة لأن تأخذ البيعة الحق من كل مسلم . لكن العالم تواطأ على ضرب هذه الجماعة والحيلولة دون وصولها الى المسلمين فضلا عن الوصول الى الهدف فتأخر الوصول الى تعميم أركان البيعة على كل مسلم وتأخر الوصول الى الحركة الاسلامية الواحدة الراشدة التي تنبثق عنها القيادة العالمية الواحدة الراشدة ، مع مصاحبتنا لفكرة أن هذه الضربات والابتلاءات هي سنة الله في الدعوات وأنها سنة لازمة للتمحيص والصقل . وبقيت صور من البيعات المريضة وصور عن الأغلاط في هذه البيعات . فلا البيعات المأخوذة تستوعب احتياجات الحركة الاسلامية ، ولا الأشخاص الذين يأخذونها من حقهم أن يأخذوها لأشخاصهم ، ولا المسلمون ملزمون بهذه البيعات ولا بهؤلاء الأشخاص .", "ان أركان البيعة العشرة هي التي استوعبت احتياجات الحركة الاسلامية المعاصرة ، وان الصف الذي يضم هؤلاء هو الصف الراشد ، وان القيادة التي تنبثق عن هذا الصف هي القيادة الراشدة ، وان الالتزام بهذه القيادة هو الرشد ، وأنا لنطمع أن يستطيع هذا الصف الموجود في كل مكان وهذه القيادة الموجودة في كل قطر أن توحد صفها ، ومع هذا فقبل أن تصبح السلطة التنفيذية بيد هذه القيادة فان البيعة لها بيعة على العمل ولا تعتبر البيعة لها بيعة لأمير المؤمنين ولكنها تشبه أن تكون كذلك كما قال فقهاء الشافعية : تعطى أحكام الخلافة لأعلم أهل زمانه ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0098.png"}, {"n": 99, "paras": ["انه بأركان البيعة العشرة وبالصف الذي يضم أهل ذلك وهو صف الاخوان المسلمين ، وضعنا الأستاذ البنا على الطريق وعندما نقول الاخوان المسلمين لا نقصد من تسمى بهذا الاسم فكثير من الأقطار فيها اخوان مسلمون ، ولكن بلا اسمهم ، فليست العبرة بالاسم بل العبرة في وجود صف اسلامى متحقق بأركان البيعة العشرة تنبثق منه قيادة وتقوم به جماعة .", "هذه الأركان العشرة للبيعة لابد منها لتقوم جماعة اسلامية راشدة في عصرنا . وسنرى عند الحديث عن كل ركن ضرورته وأدلة فرضيته ونكتفى هنا بتوضيح بعض الأمور :", "١ - أن تكون أركان البيعة عشرة فذلك شيء اقتضاه التفصيل الذى يحتاجه عصرنا فالاجمالي في عصرنا مع الجهل لا يؤدى غرضا ولذلك كان لابد من تفصيل لكل مستلزمات البيعة المعاصرة وأصل ذلك من السنة أن رسول الله صلى الله عليه وسلم كان يأخذ بعض البيعات التفصيلية على أصحابه مما تقتضيه قضية ما .", "٢ - ان كل بيعة في عصرنا تعطى لأمير محلى من اتصف الراشد يراعى فيها أنها بيعة لمن فوقه فاذا أخذها على أنها له ، حاجبا بين من معه وبين بقية الصف الراشد في العالم ، فانه يكون آثما وبيعته لاغية .", "٣ - هذا الصف الراشد ، وقيادته الواحدة الراشدة يجمعه أنه يعمل لتحقيق فرائض ومن ثم فوجوده فريضة ، والطاعة التي تستلزمها الحركة لتحقيق الأهداف فريضة ، ولكن البيعة فيه تبقى بيعة عمل ، حتى تقوم دولة الخلافة الراشدة فعندئذ تصبح البيعة شخصية ، يلاحظ بها شخص الخليفة ، ولذلك أيضا أحكامه .", "وبعد هذا التوضيح فنبدأ عرض أركان البيعة واحدا فواحدا آملين أن نعطى كل ركن حقه في التفصيل . فقد غلب على الكثير من اخواننا أنهم يلاحظون ركنا ويهملون ركنا ، كما أن الكثيرين لا يدركون أهمية بعض الأركان أو يغفلون المضامين المحددة التي عطاها الأستاذ البنا لهذه الأركان . وكثيرا ما يحدث أن أخا يسقط في ركن أفهم أو في ركن التضحية أو في ركن العمل الى غير ذلك مما يترتب عليه خلل في السير . فكان لابد من الايضاح والتفصيل ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0099.png"}, {"n": 100, "paras": ["ولنا أن نسأل .. لماذا جعل الأستاذ البنا أركان البيعة عشرا ولم يجعلها سبعا أو ثمانية أو تسعا . ولو تحرينا الاجابة لوجدنا أن كل ركن من هذه الأركان العشرة لازم ولابد من توفره في الأخ العامل كى يؤدى واجبه في داخل الجماعة . وأن عدم توفر أى ركن من هذه الأركان عند أحد الاخوة يمكن أن يؤتى الأخ من قبل هذا الركن الغير متوفر وبالتالى تؤتى الجماعة من قبل هذا الأخ . ولعل المحن التي مرت بالاخوان أوضحت هذا المعنى فقد تعرض كل ركن من أركان البيعة الى الامتحان عند كل تعرض للمحن . وقد جعل الأستاذ البنا الفهم الركن الأول لأهميته ولتوقف باقى الأركان عليه وأن أى خلل في الفهم أو خطأ ينعكس على باقى الأركان . وجعل له أصولا عشرين كإطار يحمى هذا الفهم من أى انحراف أو خطأ أو دخن .", "« فصل في أركان الفهم »", "قال الأستاذ البنا : « أيها الأخ الصادق : انما أريد بالفهم : أن توقن بأن فكرتنا : اسلامية صحيحة .. وأن تفهم الاسلام كما تفهمه في حدود هذه الأصول العشرين الموجزة كل الايجاز :", "١ - الاسلام نظام شامل يتناول مظاهر الحياة جميعا فهو دولة ووطن أو حكومة وأمة ، وهو خلق وقوة ، أو رحمة وعدالة وهو ثقافة وقانون أو علم وقضاء ، وهو مادة وثروة أو كسب وغنى ، وهو جهاد ودعوة أو هو جيش وفكرة كما هو عقيدة صادقة وعبادة .", "٢ - وأن القرآن الكريم والسنة المطهرة مرجع كل مسلم في تعرف أحكام الاسلام . ويفهم القرآن طبقا لقواعد اللغة العربية من غير تكلف ولا تعسف ، ويرجع في فهم السنة المطهرة الى رجال الحديث الثقات .", "٣ - وللايمان الصادق والعبادة الصحيحة . والمجاهدة نور وحلاوة يقذفها الله في قلب من يشاء من عباده ولكن الالهام والخواطر والكشف والرؤى ليست من أدلة الأحكام الشرعية . ولا تعتبر الا بشرط عدم اصطدامها بأحكام الدين ونصوصه ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0100.png"}, {"n": 101, "paras": ["٤ - والتمائم والرقى والودع والعرافة والكهانة ومعرفة الغيب وكل ما كان من هذا الباب منكر تجب محاربته الا ما كان من القرآن أو رقية مأثورة .", "٥ - ورأى الامام ونائبه فيما لا نص فيه ، وفيما يحتمل وجوها عدة ، وفى المصالح المرسلة معمول به ما لم يصطدم بقاعدة شرعية وقد يتغير بحسب الظروف والعرف والعادة - والأصل في العبادات التعبد دون الالتفات الى المعاني ، وفى العاديات الالتفات الى الأسرار والحكم والمقاصد .", "٦ - وكل أحد يؤخذ من كلامه ويترك الا المعصوم صلى الله عليه وسلم ، وكل ما جاء عن السلف رضوان الله عليهم موافقا للكتاب والسنة قبلناه والا فكتاب الله وسنة رسوله أولى بالاتباع ، ولكنا لا نعرض للأشخاص - فيما اختلف فيه - بطعن أو تجريح ونكلهم الى نياتهم وقد أفضوا الى ما قدموا .", "٧ - ولكل مسلم لم يبلغ درجة النظر في أدلة الأحكام الفرعية أن يتبع اماما من أئمة الدين - الفقه - ويحسن به مع هذا الاتباع أن يجتهد ما استطاع في تعرف أدلته ، وأن يتقبل كل ارشاد مصحوب بالدليل متى صح عنده من أرشده وكفايته وأن يستكمل نقصه العلمي أن كان من أهل العلم حتى يبلغ درجة النظر .", "٨ - والخلاف الفقهي في الفروع لا يكون سببا للتفرق في الدين ولا يؤدى الى خصومة ولا بغضاء ولكل مجتهد أجره ، ولا مانع من التحقيق العلمي النزيه في مسائل الخلاف في ظل الحب في الله والتعاون على الوصول الى الحقيقة من غير أن يجر ذلك الى المراء المذموم والتعصب .", "٩ - وكل مسألة لا ينبنى عليها عمل فالخوض فيها من التكلف الذي نهينا عنه شرعا ، ومن ذلك كثرة التفريعات للأحكام التي لم تقع ، والخوض في معاني الآيات القرآنية الكريمة التي لم يصل اليها العلم بعد ، والكلام في المفاضلة بين الأصحاب رضوان الله عليهم وما شجر بينهم من خلاف . ولكل منهم فضل صحبته وجزاء نيته ، وفى التأول مندوحة ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0101.png"}, {"n": 102, "paras": ["١٠ - معرفة الله تبارك وتعالى وتوحيده وتنزيهه أسمى عقائد الاسلام وآيات الصفات وأحاديثها الصحيحة وما يليق بذلك من التشابه نؤمن بها كما جاءت من غير تأويل ولا تعطيل ولا نتعرض لما جاء فيها من خلاف بين العلماء ويسعنا ما وسع رسول الله صلى الله عليه وسلم وأصحابه « والراسخون في العلم يقولون آمنا به كل من عند ربنا » ( آل عمران : ٧ )", "١١ - وكل بدعة في دين الله لا أصل لها : استحسنها الناس بأهوائهم - سواء بالزيادة فيه أو بالنقص منه - ضلالة تجب محاربتها والقضاء عليها بأفضل الوسائل التي لا تؤدى الى ما هو شر منها .", "١٢ - والبدعة الاضافية والتركية والالتزام في العبادات المطلقة خلاف فقهي . لكل فيه رأيه ولا بأس بتمحيص الحقيقة بالدليل والبرهان .", "١٣ - ومحبة الصالحين واحترامهم والثناء عليهم بما عرف من طيب أعمالهم قربة الى الله تبارك وتعالى . والأولياء هم المذكورون في قوله تعالى « الذين آمنوا وكانوا يتقون » ( فصلت : ١٨ ) . والكرامة ثابتة لهم بشرائطها الشرعية مع اعتقاد أنهم رضوان الله عليهم لا يملكون لأنفسهم نفعا ولا ضرا في حياتهم أو بعد مماتهم فضلا عن أن يهبوا شيئا من ذلك لغيرهم .", "١٤ - وزيارة القبور أيا كانت سنة مشروعة بالكيفية المأثورة ولكن الاستعانة بالمقبورين أيا كانوا ونداءهم ، وطلب قضاء الحاجات منهم عن قرب أو بعد ، والنذر لهم وتشييد القبور وسترها واضاءتها ، والتمسح بها والحلف بغير الله ، وما يلحق بذلك من المبتدعات كبائر تجب محاربتها ولا نتأول لهذه الأعمال سدا الذريعة .", "١٥ - والدعاء اذا قرن بالتوسل الى الله بأحد من خلقه : خلاف فرعى في كيفية الدعاء ، وليس من مسائل العقيدة .", "١٦ - والعرف الخاطىء لا يغير حقائق الألفاظ الشرعية بل يجب التأكد من حدود المعاني المقصود بها والوقوف عندها ، كما يجب الاحتراز عن الخداع اللفظي في كل نواحي الدنيا والدين بالمسميات لا بالأسماء .", "١٧ - والعقيدة أساس العمل ، وعمل القلب أهم من عمل الجارحة ، وتحصيل الكمال في كليهما مطلوب شرعا وان اختلفت مرتبتا الطلب ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0102.png"}, {"n": 103, "paras": ["١٨ - والإسلام يحرر العقل ويحث على النظر في الكون ويرفع قدر العلم والعلماء، ويرحب بالصالح النافع من كل شيء، والحكمة ضالة المؤمن أنى وجدها فهو أحق الناس بها .", "١٩ - وقد يتناول كل من النظر الشرعي والنظر العقلي ما لا يدخل في دائرة الآخرة، ولكنهما لن يختلفا في القطعي، فإن تصطدم حقيقة علمية صحيحة بقاعدة شرعية ثابتة، ويؤول الظني منهما ليتفق مع القطعي، فإن كانا ظنيين فالنظر الشرعي أولى بالاتباع حتى يثبت العقلي أو ينهار .", "٢٠ - لا نكفر مسلما أقر بالشهادتين وعمل بمقتضاهما وأدى الفرائض - برأي أو معصية - إلا أن أقر بكلمة الكفر، أو أنكر معلوما من الدين بالضرورة، أو كذب صريح القرآن، أو فسره على وجه لا تحتمله أساليب اللغة العربية بحال، أو عمل عملا لا يحتمل تأويلا غير الكفر .", "وإذا علم الأخ المسلم « دينه » في هذه الأصول فقد عرف معنى هتافه دائما : « القرآن دستورنا، والرسول قدوتنا » .", "وهذه الأصول التي ذكرها الأستاذ رحمه الله هي حصيلة نظرات دقيقة في كتاب الله وسنة رسوله، وحصيلة تأملات واسعة في كتب العقائد وأصول الفقه، وحصيلة فهم ثاقب لشريعة الله وإدراك عميق لواقع المسلمين ومعرفة راقية بتمييز الخير من الدخن في كل ما ورثته الأمة الإسلامية، ولكي يدرك الإنسان آفاق هذه المعاني ومستنداتها، فإن عليه أن يقرأ عشرات الصفحات في فنون كثيرة، ولقد كتبنا كتابنا « جولات في الفقهين الكبير والأكبر » لمعرفة أسرار بعض هذه الأصول، وكتبنا كتابنا « تربيتنا الروحية » لمعرفة دقائق بعض هذه الأصول، ثم أن المعاني الإجمالية لهذه الأصول من الوضوح لكل من عنده حس إسلامي بحيث لا تحتاج معه إلى كلام يقنع بها، ولذلك فسنكتفي بذكر حواش أو شروح قصيرة أو تعليقات خاطفة على بعضها ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0103.png"}, {"n": 104, "paras": ["« حاشية حول الأصل الأول من أصول الفهم » « الاسلام نظام شامل يتناول مظاهر الحياة جميعاً فهو دولة ووطن وحكومة وأمة ، وهو خلق وقوة أو رحمة وعدالة وهو ثقافة وقانون أو علم وقضاء ، وهو مادة وثروة أو كسب وغنى ، وهو جهاد ودعوة أو جيش وفكرة ، كما هو عقيدة صادقة وعبادة » . هذا هو الأصل الأول في الركن الأول من أركان البيعة : ركن الفهم ، وهو من أهم ما أحيته دعوة الأستاذ البنا من مفاهيم اسلامية غابت عن أكثر الناس أو جهلها أكثر الناس . لقد قال الله عز وجل : « ونزلنا عليك الكتاب تبيانا لكل شيء » ( النحل : ٨٩ ) . وقال تعالى واصفا كتابه : « ما كان حديثا يفترى ، ولكن تصديق الذي بين يديه وتفصيل كل شيء » ( يوسف : ١١١ ) . وقال عليه وآله الصلاة والسلام : « تركتكم على الواضحة ليلها كنهارها » ، وقال على بن أبي طالب رضى الله عنه : « تركتكم على الجادة منهج عليه أم الكتاب » . ان من تأمل هذه النصوص أدرك أنه ما من قضية من قضايا المكلفين الا وله فيها حكم ، سواء أكانت من العقائد أو من العبادات ، أو من مناهج الحياة في قضايا الدولة أو الوطن أو الأخلاق أو القضاء أو القانون أو الاقتصاد أو السياسة الى غير ذلك . وانما كان القرآن تفصيلا لكل شيء ، اما بما تحدث عنه بشكل مباشر ، أو بما أحال عليه من نصوص السنة ، أو بما أحالت عليه نصوص الكتاب والسنة من اعتماد القياس أو الاجماع أو الاستصلاح أو العرف الصالح ، أو بما يستخرج من ذلك كله من قواعد ضابطة ، أو بما يستنبط من ذلك كله من أحكام قابلة للتنامى .", "ومنذ سيطر الكافرون على الأرض الاسلامية ومنذ بدأ الكثيرون من أبناء المسلمين يستغربون ، بدأت المعاني الاسلامية تنحسر في كل الأبواب ، وكانت لحظة رهيبة محكمة ؛ فبدأ الناس يقبلون أن يحل محل أجزاء من الاسلام غيرها ، ناسين الأصل الكبير أنه لا يوجد عند المسلمين فراغ يملؤه غير الاسلام لأن الاسلام نظام شامل كامل ،"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0104.png"}, {"n": 105, "paras": ["وهو كذلك .", "إن فقهاء المسلمين يعتبرون أن الايمان بالاسلام كله شرط الدخول في الاسلام ، وهو مقتضى قبول الشهادتين ، واذا وجد تفريط في العمل فيما لا يعتبر ناقضا للشهادتين فانه يعتبر فسوقا . وعلى هذا فمن لم يؤمن بالاسلام كله وأنه عقيدة وعبادة ومناهج حياة ، وأنه تغطية لكل قضايا المكلفين وأنه تغطية للدنيا والآخرة فانه كافر ، أما اذا فرط بأن ترك أو فعل ما لا يعتبر ناقضا للشهادتين فانه يبقى مسلما ولكنه مسلم فاسق .", "لقد نص فقهاء الحنفية على أن بنت المسلم اذا تزوجت قبل البلوغ من مسلم ، فان الزواج صحيح ، ويحكم باسلامها تبعا لاسلام أبويها ، فاذا بلغت وسئلت عن الاسلام ، فلم تعرف أن تصفه فان العقد يعتبر لاغيا بسبب تبين عدم اسلامها ! لأنها لم تحسن وصف الاسلام ، وعلى هذا فان فقهاء الحنفية يعتبرون عدم معرفة الاسلام كفرا ، وليس المراد بذلك المعرفة التفصيلية ولكنها المعرفة الاجمالية .", "ولنا أن نتساءل ما هو السر في أن الكثيرين من أبناء المسلمين يرفضون أن يسموا كفارا مع أنهم يتبنون من الأفكار والمبادىء والاتجاهات ما هو كفر ؟ والجواب أن السر يعود الى جهلهم بحقيقة الاسلام وأنه نظام شامل وأنه معيار لا يسع غيره ، ولذلك فابتداء الأستاذ البنا بذكر شمول الاسلام كأول أصل من الأصول العشرين مهم جدا في عصرنا ، مهم في معرفة الاسلام ومهم في الدخول في الاسلام ومهم في عصمة الانسان من الانحراف عن الاسلام .", "ولم نشأ أن نشرح الأصل الأول شرحا حرفيا لوضوحه من ناحية ، ولأن ما ذكره الأستاذ فيه يدخل فيه الاسلام كله وهذا ، حده يقتضي مجلدا كبيرا ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0105.png"}, {"n": 106, "paras": ["« حاشية حول الأصل الثاني »", "« والقرآن الكريم والسنة المطهرة مرجع كل مسلم في تعريف أحكام الإسلام ، ويفهم القرآن طبقا لقواعد اللغة العربية من غير تكلف ولا تعسف ويرجع في فهم السنة المطهرة إلى رجال الحديث الثقات » .", "قال تعالى : « فإن تنازعتم في شيء فردوه إلى الله والرسول إن كنتم تؤمنون بالله واليوم الآخر » ( النساء : ٥٩ ) والرد إلى الله رد لكتابه ، والرد إلى رسول الله صلى الله عليه وسلم رد إلى سنته صلى الله عليه وآله وسلم ، والمسلمون مجمعون على أن الكتاب والسنة هما المصدران الأساسيان للتشريع الإسلامي ، وأن كل قضية اختلف فيها فالمرجع في حسم الخلاف فيها هو نصوص الكتاب والسنة ، ونصوص الكتاب والسنة نصوص عربية فلابد من فهمها على ضوء قواعد هذه اللغة وعلى ضوء أساليب العرب في الخطاب ، والقرآن كله متواتر ، ولكن السنة ليست كلها متواترة ، ويترتب على ذلك مباحث كثيرة تعاون على إيضاحها علماء الحديث للوصول إلى ما يعتمد ، وعلماء الأصول للوصول إلى وضع كل نص في موضعه في قضية بناء الأحكام واستخراجها واستنباطها ، ولادراك هذا الأصل والذي قبله فأننا نرى أنفسنا مضطرين لأن نقول :", "انه ما لم نعرف علم أصول الفقه سنبقى جاهلين لكثير من الأمور المرتبطة بكون الإسلام نظاما كاملا ، ولكثير من الأمور بكيفية انبثاق الأحكام عن الكتاب والسنة ، وسنبقى معرضين لكثير من مواطن الزلل في الفهم أو في التصور أو في العمل ، ولذلك فأننا نعتبر أن فهم الأصلين الأول والثاني يقتضيان منا الماما بعلم أصول الفقه من خلال كتاب معتمد فيه ، وهذا الالمام يخدم الفهم لهذين الأصلين ويكون مقدمة لفهم بعض الأصول العشرين .", "لقد كان الأصل الأول في الأصول العشرين تصحيحا لفهم الكثيرين من الدستوريين والقانونيين والسياسيين وعلماء الاجتماع والاقتصاد ، كما هو تصحيح لفهم العامة والخاصة على السواء ، ولذلك كان ضروريا ولابد منه ، والأصل الثاني يعتبر تصحيحا لمسار الفهم الباطني الذي"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0106.png"}, {"n": 107, "paras": ["جعل النصوص بمثابة رموز لا تفهم ؛ كما هو تصحيح لكثير من الاتجاهات الفقهية التي تكلفت في تأويل النصوص ، كما هو تصحيح لكثير من الاتجاهات القاصرة عن الرسوخ في العلم .", "(( هامش )) تحدثنا عن الأصل الثالث والأصل الثالث عشر والأصل الرابع عشر والأصل الخامس عشر في كتابنا « تربيتنا الروحية » . وتحدثنا عن الأصل السابع والأصل الثامن في كتابنا « جولات في الفقهين الكبير والأكبر » كما تحدثنا عنهما في كتابنا « جند الله ثقافة وأخلاقاً » ، ولا نرى أن التحديث المختصر في ذلك يغني ، فليراجع القارىء ما كتب عن هذه الأصول هناك .", "(( شرح الأصل الرابع )) « والتمائم والرقَى والودع والرمل والمعرفة والكهانة وادعاء معرفة الغيب ؛ وكل ما كان من هذا الباب منكر تجب محاربته ، الا ما كان من قرآن أو رقية مأثورة » .", "١ - قوله : « الا ما كان من قرآن أو رقية مأثورة » هذا الاستثناء يعود الى التمائم والرقَى ؛ فالتمائم جمع تميمة وهي ما يعلق ويحمله الانسان ، والرقَى جمع رقية ، وهي التلاوة أو الدعاء لمن به مرض ؛ فالتميمة اذا كانت قرآنا أو دعاء مأثوراً ، فذلك جائز وكذلك الرقية اذا كانت قرآنا أو دعاء ، أو كانت مأثورة ، فذلك جائز طيب ، أما اذا كانت في التميمة شركيات أو كان فيها شيء مجهول ، فذلك منكر تجب محاربته ، وكذلك الرقية اذا كانت بمجهول أو بمنكر .", "٢ - ورمي الودع وأمثاله ، كرمي علب الكبريت لاستكشاف الحظ ، منكر وجهل .", "٣ - وضرب الرمل لاستكشاف الغيب كما يفعله بعض الناس منكر تجب محاربته .", "٤ - والعرافة التي هي ادعاء معرفة الغيب ؛ وكذلك الكهانة ، وهي الاتصال بالجن بدعوى التعرف على الغيب ؛ وكل ما كان كذلك منكر نقف منه موقفاً حازماً .", "٥ - والجن بنص القرآن لا يعرفون الغيب أي المستقبل ، ولكن"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0107.png"}, {"n": 108, "paras": ["قد يعرف الجني شيئا قد وقع فلا ينبغي أن نخلط بين الحالين ، فقد فرق العلماء بين المقامين .", "« شرح الأصل الخامس »", "« ورأى الإمام ونائبه فيما لا نص فيه ، وفيما يحتمل وجوها عدة ، وفي المصالح المرسلة معمول به ما لم يصطدم بقاعدة شرعية ، وقد يتغير بحسب الظروف والعرف والعادة ، والأصل في العبادات التعبد دون الالتفات إلى المعاني ، وفي العاديات الالتفات إلى الأسرار والحكم والمقاصد » .", "١ - قوله : « ورأى الإمام ونائبه فيما لا نص فيه » يفهم منه أنه حيث وجد نص فلا يصح لأحد تعطيله أو الخروج عليه أو المخالفة له .", "٢ - حيث لا يوجد نص وحيث يوجد نص له وجوه عدة وحيث المصالح المرسلة التي أطلقها الشارع ، فمهنا يكون للإمام أو نائبه دور في توجيه القانون ؛ فقد قال الفقهاء : إن للإمام أن يختار من بين آراء الفقهاء الرأى الذي يرى أنه مصلحة ، وبذلك تتم وحدة التشريع في الأمة بسبب هذا الحق المعطى للإمام .", "٣ - إذا رجح الإمام رأيا اجتهاديا في مرحلة ثم تغيرت الظروف والعادات والأعراف ، فله أن ينتقل إلى غيره من الآراء الاجتهادية .", "٤ - هذه القضايا تحكمها الضوابط الاجتهادية الدقيقة كما تحكمها شورى أهل الشورى في الدولة المسلمة على ضوء المصلحة الإسلامية العليا .", "٥ - قوله : « والأصل في العبادات التعبد دون الالتفات إلى المعاني ، وفي العاديات الالتفات إلى الأسرار والحكم والمقاصد » : يفيد أن الأصل في التشريعات الحياتية أن نبحث عن العلل والحكم فيها ، ونقيس على النصوص وعلى روحها لنستخرج القواعد المستقراة التي تصلح كأساس للفهم العام ، أما القضايا التعبدية فالأصل فيها التسليم والالتزام ولا ينفى هذا البحث عن الحكمة ولكن لا يترتب على ذاك شيء كثير من الناحية العملية ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0108.png"}, {"n": 109, "paras": ["« شرح الأصل السادس »", "« وكل أحد يؤخذ من كلامه ويترك إلا المعصوم صلى الله عليه وسلم وكل ما جاء عن السلف رضوان الله عليهم موافقاً للكتاب والسنة قبلناه ؛ وإلا فكتاب الله وسنة رسوله أولى بالاتباع ، ولكنا لا نعرض للأشخاص فيما اختلف فيه - بطعن أو تجريح - ونكلهم إلى نياتهم وقد أفضوا إلى ما قدموا » .", "١ - لا عصمة عند أهل الحق إلا للكتاب والسنة ولذلك فان الخطأ فيما سوى ذلك ممكن وبالتالى فكل أحد بعد الله ورسوله يؤخذ من كلامه ويرد ومن ذلك كلام السلف وكلام الأئمة ؛ فحيثما تبين لنا أن هناك كلاماً يخالف الكتاب والسنة رددناه كائنا من كان قائله .", "٢ - وخلال التاريخ الاسلامى اختلفت وجهات النظر كثيرا ورد بعض العلماء على بعض وجرح بعضهم بعضا ، وحيثما كان الكلام وجه وللنية دخل فنحسن الظن بالأشخاص ولا نحمل عليهم ولا نجرحهم بل نترحم عليهم ؛ وذلك أدبنا الذي أدبنا الله عز وجل به : « والذين جاءوا من بعدهم يقولون ربنا اغفر لنا ولاخواننا الذين سبقونا بالايمان » ( الحشر : ١٠ ) أما إذا كان الكلام لا يحتمل وجها آخر وليس للنية فيه دخل فعندئذ يكون لنا موقف هو موقف الشرع ومع ذلك فاننا نحتمل أن يكون هناك خطأ في النقل أو توبة ، ولذلك فقد يكون من المستحسن أن نبقى على فكرة : هذا الكلام كذا والله أعلم بصاحبه ؛ فان كان الكلام لا يحتمل إلا الكفر حكمنا عليه بالكفر وان كان يحتمل الضلال حكمنا عليه بالضلال ؛ أما صاحبه فالله أعلم به فقد يكون مظلوما فيما نسب إليه وقد يكون أحدث توبة .", "« شرح الأصل التاسع »", "قال الأستاذ رحمه الله في الأصل التاسع : « وكل مسألة لا ينبنى عليها عمل ، فالخوض فيها من التكلف الذي نهينا عنه شرعا ومن ذلك كثرة التفريعات للأحكام التي لم تقع » . كان أدب الصحابة أنهم لا يسألون عن شيء لم يقع ؛ فاذا وقعت واقعة بحثوا عن حكم الله فيها حتى أن عمر كان يلعن من سأل عن شيء"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0109.png"}, {"n": 110, "paras": ["لم يقع كما ذكره الدارمي ؛ وهناك مسائل ليست من باب العقائد التي كلفنا بها وليست من باب الفقهيات التي نحتاجها أو يحتاجها المسلمون ، وليست من باب السلوكيات ولا يتوقف عليها فهم نصوص الكتاب والسنة ، وليست لازمة في أمر دنيا ولا دين ، مثل هذه المسائل لا ينبغي أن نشغل فيها وقتا لأنها لا تخرج عن كونها اتعابا للأنفس والعقول واضاعة للوقت في غير طائل ، بل لعلها داخلة في أخلاقيات المتفاصحين والمتفعرين والمتفيهقين ، وكل ذلك من التكلف المنهي عنه شرعا ، قال تعالى : « قل ما أسألكم عليه من أجر وما أنا من المتكلفين » ( سورة ص : ٨٦ ) ، وقال عليه الصلاة والسلام : « أنا وصالح أمتي براء من التكلف » . ولا يدخل فيما نحن فيه التفريعات الفقهية التي وقعت مسائلها خلال العصور واضطر العلماء للاجابة عليها فسجلوها في كتبهم ، ولا يدخل في ذلك التفريعات الفقهية التي يحتاجها واحد في الجيل الواحد ، لأن ذلك واجب شرعي ويعتبر الكلام فيه ووجود المختصين فيه من فروض الكفايات ، راجع كتابنا « جولات » مع ملاحظة قوله عليه السلام : « سيكون من أمتي أقوام يتعاطى فقهاؤهم عضل المسائل أولئك شر أمتي » ، أخرجه الطبراني ورمز السيوطي إلى حسنه .", "وقال الأستاذ في الأصل التاسع : « والخوض في معاني الآيات الكريمة التي لم يصل اليها العلم بعد » هذا نموذج على المسائل التي لا يترتب عليها عمل ولا يدخل في ذلك الآيات القرآنية التي جاء العلم القطعي يفسرها ، كما لا يدخل في ذلك أن يسجل الانسان فهمه لمثل هذه الآيات ، فذلك أدب العلماء في كل العصور . والشيء الذي نهى عنه الأستاذ البنا هو الخوض في مثل هذا ، ومظهر ذلك الجزم حيث لا ينبغي الجزم ، والجدال في مثل هذه الشئون حيث لا ينبغي الجدال وكنموذج على هذه الآيات قوله تعالى : « الله الذي خلق سبع سموات ومن الأرض مثلهن » ( الطلاق : ١٢ ) فهل المراد بالأرضين السبع طبقات الأرض أو السيارات السبع من الأرض فما بعد ، اذ الكواكب السيارة تسع ، أولها : عطارد والزهرة ثم تأتي بعد ذلك الأرض وهي مع الكواكب التي تأتي بعدهما سبع ، ( ٨١ - في آفاق التعاليم ) ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0110.png"}, {"n": 111, "paras": ["أو مراد بذلك أرضون مثل أرضنا في هذا الفضاء الواسع ؟ لا يستطيع أحد أن يقدم لنا شيئا والنصوص لم تعطنا تفسيرا قطعي الدلالة وبعض النصوص في هذا الشأن ليست قطعية الثبوت ، فالجزم والخوض الزائد على تسجيل احتمالات النص من التكلف . وقال الأستاذ في هذا الأصل : « والكلام في المفاضلة بين الأصحاب رضوان الله عليهم وما شجر بينهم من خلاف ولكل منهم فضل صحبته وجزاء نيته وفي التأول مندوحة » . هذا نموذج آخر على المسائل التي لا ينبنى عليها عمل وبالتالى فالخوض فيها من التكلف ولابد من وقفة حول هذا الموضوع :", "١ - هناك نصوص قطعية الثبوت قطعية الدلالة في فضل بعض الأصحاب على غيرهم فهذه جزء من العقيدة التي ينبغى على كل مسلم أن يعرفها .", "٢ - هناك نصوص صحيحة أو حسنة في تفضيل بعض الأصحاب على بعض فهذه يعتبر انكارها ورفضها فسوقا ، وليس مراد الأستاذ البنا مثل هذا حتما لأن هذا جزء من دراسات السنة ، واذن فأن يتكلم المتكلم في المفاضلة بين الأصحاب من دون نص فذلك تكلف في مسألة لم يذكرها رسول الله صلى الله عليه وسلم ولا ينبنى عليها عمل ، ونحن نجزم أن مراد الأستاذ هو هذا لأنه يأمر ، كما سنرى في قسم الواجبات بدراسة رسالة في أصول العقائد ، وفى العادة فان كتب العقائد تتحدث عن مثل ما ذكرناه .", "٣ - شجر بين الصحابة خلاف وصل في بعض الأحوال إلى درجة الاقتتال ومثل هذا الخلاف لا ينبغى أن يؤثر على وحدة المسلمين في عصرنا ولكن من الواضح أن بعض أنواع الخلافات قد حكمت فيها النصوص فهذه ليست داخلة فيما نهى الأستاذ عنه لأنها جزء من العقيدة فالنصوص واضحة وثابتة في أن الذين خرجوا على على من الخوارج ضلال ، والنصوص واضحة وثابتة في أن فئة معاوية رضى الله عنه كانت باغية على على رضى الله عنه فحيثما كان الكلام مبنيا على نص ثابت وواضح فلا يعتبر تكلفا بل يعتبر فهما للنص .", "٤ - أن الخلاف الذي حدث بين الأصحاب لا ينفى فضلهم ولا يصح أن يدعونا الى اتهام النيات في غير ما دليل ظاهر ، بل أن"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0111.png"}, {"n": 112, "paras": ["نتأول لما حدث بينهم من أنه أثر عن اجتهادات ، بعضهم أصاب بها وبعضهم أخطأ فذلك هو الأسلم لقلوبنا .", "يبقى أن نقول شيئا : واقع المسلمين الحالي أنه يوجد أهل سنة ويوجد شيعة ويوجد بعض فرق الخوارج ، وباب النقاش في الأصحاب باب يدخل فيه كل من هؤلاء ولا يستطيعون الخروج منه بنتيجة موحدة في الغالب وقد فتح الأستاذ البنا في كلامه المجمل في هذا الأصل ، الباب لأن يلتقي هؤلاء على الصمت في هذا الموضوع لأنه لا يترتب عليه عمل مباشر في عصرنا ويستطيع كل من هؤلاء أن يدرس عقيدته في كتبها ، وعلى الجميع أن يعملوا للوصول إلى الحقيقة وذلك طالب في أصل آخر بالالتزام بالكتاب والسنة الثابتة وأن يكون ذلك على ضوء الفهم الصحيح الذي تقتضيه قواعد اللغة .", "« شرح الأصل العاشر »", "« معرفة الله تبارك وتعالى وتوحيده وتنزيهه أسمى عقائد الإسلام وآيات الصفات وأحاديثها وما يتعلق بذلك من المتشابه نؤمن بها كما جاءت من غير تأويل ولا تعطيل ولا نتعرض لما جاء فيها من خلاف بين العلماء، ويسعنا ما وسع رسول الله صلى الله عليه وسلم وأصحابه « والراسخون في العلم يقولون آمنا به كل من عند ربنا » . ( آل عمران : ٧)", "١ - هناك قضايا فتح فيها باب الاختلاف ويستحيل أن يجتمع المختلفون فيها على رأى واحد . وقد كان للصحابة قبل فتح باب الاختلاف فيها موقف ، وقد حاول الأستاذ البنا أن يرجع بالناس في هذه القضايا إلى ما كان عليه الأصحاب رضى الله عنهم ومن ذلك هذه المسألة .", "٢ - ان هناك آيات وأحاديث صحيحة تصف الله عز وجل بما ظاهره تشبيه الله عز وجل بخلقه : هذه النصوص كان الصحابة يؤمنون بها ولا يؤولونها مع استقرار معنى التنزيه ونفى التشبيه في أنفسهم"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0112.png"}, {"n": 113, "paras": ["ولكنه فيما بعد وجد نفاة للصفات ووجد مشبهة ، فانقسم أهل السنة والجماعة بسبب ذلك قسمين : قسم التزم الموقف الأول واعتبرهما سواء بدعة ، وقسم بدأ يتكلم رادا على النفاة ورادا على المشبهة فاقتضى ذلك منه تفصيلات ترتب عليها معارك كثيرة ، هذه المعارك لا يصح أن تدخل صفوف الجماعة ولذلك فقد حسم الأستاذ البنا هذا الجدل العريض بأن ألزم الإخوان بالموقف الأول الذي كان عليه الصحابة : لا تأويل ولا تعطيل مع التوحيد والتنزيه ، والكتب التي تحدثت عن موضوع المتشابه والاختلاف فيه كثيرة جدا ، وما ذكره الأستاذ البنا في هذا الشأن هو الموقف الأسلم والأحكم والأعلم يدرك ذلك كل من عانى متاعب النقاش في هذا الموضوع .", "٣ - حرص الأستاذ البنا أن يوضح أن دعوة الإخوان دعوة سلفية وفى رسالة العقائد نجده يرجح رأى السلف في آيات الصفات والمتشابه ويحث الإخوان ألا يرضوا بغير ذلك بديلا .", "« شرح الأصل الحادي عشر »", "« وكل بدعة في دين الله لا أصل لها : استحسنها الناس بأهوائهم - سواء بالزيادة فيه أو بالنقص منه - ضلالة تجب محاربتها والقضاء عليها بأفضل الوسائل التي لا تؤدى إلى ما هو شر منها » .", "١ - قد تطلق البدعة على كل ما هو جديد ولا تكون بدعة مذمومة كأن يكون هذا الجديد مما يدخل في أصل ندب إليه الشارع أو أنه يحقق مصلحة شرعية ككتابة المصاحف وجمع الحديث الشريف وبناء المستشفيات .", "٢ - وهناك نوع من البدع يظن أصحابها أن لها أصلا في شريعة الله وأنهم يحققون فيما يفعلونه مصلحة شرعية أو أمرا مطلقا من أوامر الشارع كما سيحدثنا عن ذلك الأستاذ البنا نفسه في الأصل الثاني عشر فهذا له حكمه .", "٣ - وهناك بدعة في دين الله لا أصل لها وإنما هي متابعة الأهواء المحض فهذه هي التي ينصب عليها الكلام هنا والفارق عندى بين هذا النوع والذي بعده أن هذا الأصل تحدث عما ليس فيه خلاف بين"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0113.png"}, {"n": 114, "paras": ["الفقهاء على أنه بدعة محرمة وأن الأصل اللاحق تحدث عما فيه خلاف بين الفقهاء ؛ فما أجمع الفقهاء على أنه بدعة محرمة فهذا الذي يتحدث عنه الأستاذ هنا وما اختلفوا فيه فهذا الذي يتحدث عنه في الأصل الثاني عشر .", "٤ - البدعة التي أجمع الفقهاء على تحريمها ضلالة تجب محاربتها والقضاء عليها ولكن عندنا في شريعتنا أصل عام يجب أن يراعى وهو : إن تغيير المنكر اذا أدى الى منكر أكبر منه فعلينا أن نفتش عن طريقة أخرى للتغيير أو نسكت ولذلك فان ابن تيمية رحمه الله كان ينهى تلاميذه عن نهى التتار عن الخمر لأن التتار اذا سكروا ناموا فخف شرهم عن المسلمين في سكرهم ونومهم ولكن اذا استيقظوا ولم يكن لهم شغل هتكو أعراض المسلمين أو سلبوا أموالهم أو قتلوهم .", "هذه النقطة التي فطن اليها الأستاذ البنا من أهم ميزات التجديد في دعوته كما شرحنا ذلك في كتابنا « المدخل » هناك حق العلم وهناك حق الدعوة وهناك حق التربية وهناك حق المعركة ودعوة الأستاذ البنا راعت هذا كله .", "« شرح الأصل الثاني عشر »", "« والبدعة الاضافية والتركية والالتزام في العبادات المطلقة خلاف فقهي ؛ لكل فيه رأيه ولا بأس بتمحيص الحقيقة بالدليل والبرهان » .", "١ - هناك مثال ينطبق على البدعة الاضافية والبدعة التركية بأن واحد وهو الذكر الجهرى فى الجنائز فالسنة فى الجنائز الصمت للاعتبار ، ثم درج الناس فى العصور المتأخرة على الاعلان بالذكر أثناء السير فى الجنازة وترتب على الذكر فى هذه الحالة أن تركت سنة فكان ذلك بدعة تركية ، والذكر فى هذا المقام بدعة اضافية ، هذا النوع من البدع فيه خلاف بين الفقهاء بسبب أن الذكر مطلوب فى كل حال ووضع الناس تغير فأصبح ما هو الحكمة فى زمنه عليه الصلاة والسلام متغيرا ؛ ومع أن الأستاذ البنا يميل دائما الى جانب العودة الى الأصل وتربية الناس على ذلك لكنه ترك هذا النوع من القضايا لنقاش الفقهاء ، ولم يعتبر"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0114.png"}, {"n": 115, "paras": ["تبنى إحدى وجهتي النظر في هذه الأمور مبررا لعدم قبول الإنسان في دعوة الإخوان المسلمين .", "٢ - هناك عبادات ندبنا إليها بشكل مطلق كالذكر الكثير دون تحديد ، فقد ندبنا إلى الاستغفار الدائم وإلى التهليل الدائم وإلى الصلاة على رسول الله صلى الله عليه وسلم ، وقد لحظ بعض المربين خلال العصور أن الإطلاق مع وجود الإقبال ووجود العلم يعطى ثماره ولكن العامة وفتور الإقبال على الله في العصور المتأخرة يقتضى أن يدرج السالك إلى الله ، فيطلب منه أن يذكر عددا معينا ثم يدرج لغير ذلك على حسب استعداده وبما يحتاجه شفاء قلبه وبما يحتاجه النقل إلى اليقظة القلبية ، هذه المعاني أوجدت فكرة الالتزام بعدد معين في العبادات المطلقة ؛ وهذا الموضوع كذلك تدور حوله معارك فقهية ، ودعوة الأستاذ البنا تستوعب كلا الاتجاهين لأن الأمر لا يدور بين كفر وإيمان وإنما يدور بين الفاضل والأفضل .", "٣ - ومع أن الأستاذ البنا لم يعتبر هذه المسألة من الأصول لكنه رغب إلى الأطراف المختلفة بتمحيص الحقيقة ؛ والشيء الذي سار عليه الأستاذ البنا عمليا أنه جمع في رسالة المأثورات كل ما ورد فيه نص من الأذكار طالب فيه إخوانه وأبقى الإطلاق على حاله .", "« شرح الأصل السادس عشر » « والعرف الخاطىء لا يغير حقائق الألفاظ الشرعية بل يجب التأكد من حدود المعاني المقصودة بها والوقوف عندها كما يجب الاحتراز عن الخداع اللفظي في كل نواحي الدنيا والدين فالعبرة بالمسميات لا بالأسماء » .", "١ - افرض أن الناس سموا الخمرة بغير اسمها أو سموا الربا بغير اسمه ، فهل يؤثر ذاك على حقيقة التحريم ؟ أن علينا أن ننظر إلى حقائق ما يراد بالألفاظ الشرعية ثم نفتش عما يوافق ذلك أو يخالفه ونبنى على ذلك مواقفنا وهذا معنى قول الأستاذ : « والعرف الخاطىء لا يغير الألفاظ الشرعية ، بل يجب التأكد من حدود المعاني المقصود بها والوقوف عندها » ذكر صاحب الجامع"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0115.png"}, {"n": 116, "paras": ["الصغير فصا عزاه إلى ابن عساكر عن كيسان : « ستشرب أمتي من بعدي الخمر يسمونها بغير اسمها يكون عونهم على شربها أمراؤهم » ، فهل تغيير اسم الخمر يخرجها عن كونها حراما ؟ قال عليه وآله الصلاة والسلام : « لتستحلن طائفة من أمتي الخمر باسم يسمونها إياه » ، خرجه الإمام أحمد بإسناد حسن . وقد أخرج أبو داوود بإسناد رمز السيوطي إلى حسنه ، قوله عليه وآله الصلاة والسلام : « إذا تبايعتم بالعينة وأخذتم أذناب البقر ورضيتم بالزرع وتركتم الجهاد سلط الله عليكم ذلا لا ينزعه حتى ترجعوا إلى دينكم » .", "العينة : هي أن يشترى إنسان من آخر سلعة بالدين ثم يبيعها منه نقدا بأقل مما اشتراها منه فهذا ظاهره بيع وباطنه ربا ، فهل تؤثر التسمية على الحقيقة ؟ والذي أراه أنه يدخل فيما ذكره الأستاذ البنا موضوع المسح على الجوربين ، فالمسح على الجوربين بديل عن المسح على الخف ، وقد كانت الجوارب سميكة في زمن رسول الله صلى الله عليه عليه وسلم فاستحلال المسح على الجورب الرقيق لمجرد اشتراكه باسم الجورب فيه ما فيه .", "٢ - ويقول الأستاذ : « كما يجب الاحتراز عن الخداع اللفظي في كل نواحي الدنيا والدين فالعبرة بالمسميات لا بالأسماء » .", "أقول : وقد أخذ هذا الخداع اللفظي في عصرنا مداه حتى أثر على كثير من مواقف المسلمين ومن جملة ذلك خداع الشعارات التي تحدثنا عنه في كتاب « من أجل خطوة إلى الأمام على طريق الجهاد المبارك » فبحجة أن الإسلام مساواة أراد قوم أن يساووا بين الكافر والمسلم والله عز وجل يقول : « أفنجعل المسلمين كالمجرمين » ( القلم : ٣٥ ) ، وبحجة أن في الإسلام إخاء ، أرادوا أن يجعلوا الكافرين إخوة للمؤمنين ، والله عز وجل يقول : « إنما المؤمنون إخوة » ( الحجرات : ١٠ ) وبحجة أن الإسلام ينصف الفقير أرادوا أن يجعلوا الإسلام هو الماركسية التي تنفى وجود الله أصلا .", "ولقد ركب الكثيرون متن الخداع اللفظي ليحرفوا المسلمين ولذلك حذرنا الأستاذ البنا رحمه الله ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0116.png"}, {"n": 117, "paras": ["ومن مظاهر الخداع اللفظي ما يمكن أن يحدث أثناء الحوار الكلامي أو المفتوح مما يقتضي منا أن نحدد المصطلحات ، وأن نحدد نقاط الاختلاف والاتفاق .", "« شرح الأصل السابع عشر » « والعقيدة أساس العمل ، وعمل القلب أهم من عمل الجارحة ، وتحصيل الكمال في كليهما مطلوب شرعا وإن اختلفت مرتبتا الطلب » .", "١ - لا يقبل الله عملا اذا لم يكن هناك عقيدة ، قال الله تعالى : « وقدمنا إلى ما عملوا من عمل فجعلناه هباء منثورا » ( الفرقان : ٢٣ ) وقال تعالى : « إنما يتقبل الله من المتقين » ( المائدة : ٢٧ ) وهذا معنى كلام الأستاذ : « والعقيدة أساس العمل » .", "٢ - أيهما أثقل في ميزان الله : الشهادتان بصدق أو الصلاة ؟ لا شك أنه الشهادتان وهذا معنى كلام الأستاذ : « وعمل القلب أهم من عمل الجارحة » وفي الحديث : « إنما الأعمال بالنيات » .", "٣ - نحن مطالبون بأعمال هي من أعمال القلوب ، وبأعمال هي من أعمال الجوارح ، ومع أن أعمال القلوب أعظم وزنا في ميزان الله فنحن مطالبون بتحصيل الكمال في الاثنين ، وهذا معنى كلام الأستاذ : « وتحصيل الكمال في كليهما مطلوب شرعا وإن اختلفت مرتبتا الطلب » .", "٤ - يدخل في أعمال القلوب المطلوبة : الايمان والاخلاص والتوكل والاحسان والشكر والندم على المعصية ، ويدخل في أعمال الجوارح المطلوبة : الصلاة والزكاة والصوم والحج ، والذكر والتلاوة ، ويدخل في أعمال القلوب المحرمة : النفاق والرياء والحسد والعجب والكبر والغرور ، ويدخل في أعمال الجوارح المحرمة : الزنا وأكل الربا وإيذاء المسلمين واستعمال اللسان في غيبة أو نميمة الى غير ذلك من محرمات الجوارح في كتابنا « تربيتنا الروحية » تفصيلات كثيرة في هذا الشأن .", "« شرح الأصلين : الثامن عشر والتاسع عشر » « والإسلام يحرر العقل ويحث على النظر في الكون ويرفع قدر العلم والعلماء ويرحب بالصالح النافع من كل شيء ، والحكمة ضالة المؤمن أنى وجدها فهو أحق الناس بها » ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0117.png"}, {"n": 118, "paras": ["وقد يتناول كل من النظر الشرعي والنظر العقلي ما لا يدخل في دائرة الآخر ولكنهما لن يختلفا في القطعي ، فان كانا ظنيين فالنظر الشرعي أولى بالاتباع حتى يثبت العقلي أو ينهار » .", "١ - تحدثنا في كتابنا « جولات .. » عن الحكم العقلي والحكم الشرعي والحكم العادي ، وبينا أن الحكم العقلي هو الذي يتوصل اليه بمحض العقل ، وأن الحكم العادي هو الذي يتوصل اليه باستقراء صحيح أو باستنتاج صحيح ، وأن ذلك مما علمنا الاسلام أن نعتمدة كمسلمات .", "٢ - وذكرنا هناك أنه يستحيل أن يصطدم ما هو حقيقة شرعية بما هو حكم عقلي أو بما هو حقيقة علمية ، ومن ثم فان الاسلام حرر عقل الانسان من الخرافة ومن الوهم .", "٣ - النظر في الكون فريضة شرعية والتفكير للوصول الى بعض الحقائق فريضة شرعية ، فدين هذا شأنه لا يمكن أن يكون الا مع العلم والعقل .", "٤ - جعل الله هذا الكون مسخرا لمصالح الانسان فكل علم يساعد على هذا التسخير فهو مطلوب شرعا .", "٥ - من استقراء شامل لشريعة الله وصل ابن القيم الى أنه : « حيثما وجدت المصلحة فثم شرع الله » ولكنها المصلحة الحقيقية للانسان وليست المتوهمة ، والحكمة ضالة المؤمن أنى وجدها فهو أحق بها ، ولذلك فالمسلم منفتح على العالم في كل ما هو نافع وصالح وحكمة .", "٦ - أطلق الاسلام للعقل أن يفكر فيما ينبغي ، وأطلق الاسلام للمسلم آفاق البحث العلمي ، فاذا وصل العقل أو العلم الى شيء فذلك مسلم شرعا مع ملاحظة أنه لم يتكلم الشرع في كثير من تفصيلات ما يصل اليه العقل أو ما يستكشفه البحث العلمي ، ولكن حيث تكلم فان التناقض مستحيل بين النص الشرعي القطعي الثبوت والدلالة وبين الحكم والدلالة وبين الحكم العقلي الخالص أو الحقيقة العلمية .", "٧ - هناك حالات يكون النص فيها محتملا ، فاذا جاءت الحقيقة العلمية ترجح أحد الاحتمالات تعين في هذه الحالة قبول ما وفق الحقيقة العلمية .", "٨ - أما الحالات التي لا يجزم فيها العلم ، والنص الشرعي فيها"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0118.png"}, {"n": 119, "paras": ["داروين بالنسبة للانسان مرفوضة قطعاً .", "٩ - وقد يحتمل النص عدة وجوه والعلم لم يجزم فيها فهينا مجال البحث واسع وحتى يثبت العكس هناك حالات يكون النص فيها ظني الثبوت والعلم لم يجزم فنحن نبقى مع النص الشرعي وان كان ظني الثبوت .", "« شرح الأصل العشرين »", "« لا نكفر مسلما أقر بالشهادتين وعمل بمقتضاهما وأدى الفرائض ، برأى أو معصية ، الا ان أقر بكلمة الكفر ، أو أنكر معلوما من الدين بالضرورة ، أو كذب صريح القرآن ، أو فسره على وجه لا تحتمله أساليب اللغة العربية بحال ، أو عمل عملا لا يحتمل تأويلا غير الكفر » .", "١ - ان قضية التكفير من أخطر القضايا التي أثرت على وحدة المسلمين قديما وحديثا ففرقتهم وجعلت بعضهم يسفك دماء بعض وبسببها وجدت فرق انشقت عن جسم الأمة الاسلامية ، وهذا الموضوع غلا به الخوارج والمعتزلة وتوسط به أهل السنة والجماعة .", "٢ - في عهد رسول الله صلى الله عليه وسلم كان النطق بالشهادتين هو علامة الدخول في الاسلام ، فمن شهد الشهادتين وآمن بمقتضى ذلك ، أى آمن بالاسلام كله ، ولم يأت بناقض من نواقض الشهادتين ولم ينكر معلوما من الدين بالضرورة ، فهو مسلم ، وان قصر في العمل بأن ترك أمرا أو عصى في نهى ، ما لم يكن عصيانه في ناقض من نواقض الشهادتين .", "٣ - لم يتعرض الأستاذ البنا لموضوع الدخول في الاسلام لأنه معروف وهو ما ذكرناه آنفا ، ولكن تعرض للاخراج من الاسلام ، فمتى نخرج انسانا من الاسلام ؟ يقول الأستاذ :", "(١) « الا ان أقر بكلمة الكفر » بأن نفى وجود الله مثلا أو قال انه يكفر بالاسلام .", "(٢) « أو أنكر معلوما من الدين بالضرورة » كأن أنكر فرضية الصلاة أو أنكر تحريم الخمر ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0119.png"}, {"n": 120, "paras": ["(٣) « أو كذب صريح القرآن » بأن نفى شيئا قرره القرآن بما لا يحتمل تأويلا .", "(٤) « أو عمل عملا لا يحتمل تأويلا غير الكفر » كأن حمل الصليب لغير خدعة حرب أو سجد لصنم . هذه الأشياء الأربعة هي التي نخرج بها الإنسان من الإسلام بلا تردد ، ولكن من هو الذي نخرجه من الإسلام إذا فعل واحدا من هذه الأربعة : نخرج من أقر بالشهادتين وعمل بمقتضاهما وأدى الفرائض ! فمن باب أولى إذا كان لا يقر بالشهادتين ولا يعمل بمقتضاهما ولا يؤدى الفرائض .", "٤ - هل يفهم من كلام الأستاذ البنا أن الإنسان الذي لا يؤدى الفرائض أو لا يعمل بمقتضى الشهادتين كافر ، ولو نطق بالشهادتين ، ولو آمن بالاسلام كله ؟ قد يفهم فاهم هذا الفهم ، ولكنه فهم خاطىء ، فالأستاذ البنا بنى أصوله على فهوم أهل الحق خلال العصور ، وأهل الحق متفقون على أن من أقر بالشهادتين ، وآمن بالاسلام كله ، ولم يأت ناقضا من نواقض الشهادتين ، ولم ينكر معلوما من الدين بالضرورة ، بأنه مسلم على تقصير في العمل أو ركوب للمعصية إلا ما ذكر عن الحنابلة في تكفيرهم تارك الصلاة .", "٥ - هناك كفر بمعنى ترك الشكر ويستحق صاحبه في بعض الحالات القتل حدا ، وهناك كفر هو ردة يستحق به صاحبه القتل ردة ، ولابد ونحن نقرأ كلام العلماء ، أو ونحن نقرأ بعض الآثار من أن ننتبه إلى هذه الدقائق .", "« تعليقات وشروح وهوامش »", "عندما بدأ الأستاذ دعوته كانت الأمة الإسلامية قد وصلت إلى حالة بعيدة من الفوضى الفكرية ، فهؤلاء ناس كفروا بالاسلام ، وآخرون قسروه على بعض الشئون ، وآخرون اعتقدوا أن للقرآن باطنا يخالف ظاهره ، وآخرون انطلقوا من خلال مفهوم خاطىء للولاية كادوا به أن يستغنوا عن هدى النبوة ، وهؤلاء ظنوا أن الدين يخالف العلم أو العقل ، وآخرون فهموا أن الاسلام هو كل ما هو شديد ، وآخرون"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0120.png"}, {"n": 121, "paras": ["تسرعوا في الكفر والتكفير ، وآخرون تساهلوا في كل شيء ، وأكثر المسلمين استسلموا لإبعاد الإسلام عن مجالات الحكم والتقنين ؛ وكان هذا كله يحتاج إلى علاج وكان هذا العلاج في هذه الأصول العشرين التي تقضى على الفهم الخاطئ .", "ولقد كان من مظاهر الفوضى الفكرية في الأمة الإسلامية أن اختلط ما هو أصل بما هو فرع وتصلب الكثيرون لفروع حاربوا من أجلها إخوانهم المسلمين ، وضيع آخرون أصولا وحاربوا من دعاهم إليها مع أنها حق خالص ، وبمثل هذا لا يمكن أن ينطلق المسلمون في صف واحد ، فكانت هذه الأصول العشرين علاجا لواقع مريض يتحدد فيه ما هو أصل لا يصح التساهل فيه وما هو فرع يمكن الالتقاء مع الاختلاف فيه .", "ونتيجة لمسيرة طويلة تكثفت فيها عوامل الفرقة والخلاف بين المسلمين ونتيجة لاستحالة الانطلاق مع وجود خلل في أصل الفهم كان لابد من أرضية مشتركة لفهم يمكن أن تشكل قاسما مشتركا أعظم بين المسلمين دون أن يكون ذلك على حساب حق ، وكانت الأصول العشرين بتوفيق الله عز وجل تحقق ذلك كله ؛ لقد ذكرت الناسين وخففت من الغلو ووحدت من الفرقة وضبطت المسار ولا نعرف أحدا في عصرنا استطاع أن يجمع كل المنصفين على معان ينطلقون من خلالها في صف موحد كحسن البنا رحمه الله بهذه الأصول العشرين التي الهمه الله اياها وألهمه جمعها .", "معرفة الإسلام فريضة ، ومعرفة بعض الأحكام فيه فريضة ؛ وما يفترض على كل مسلم أن يعرفه من أحكام يختلف باختلاف الشخص وعمله ومسئوليته ؛ وركن الفهم جمع فيه الأستاذ البنا كل ما لا يصح"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0121.png"}, {"n": 122, "paras": ["لكل مسلم أن يجهله لما لما يترتب على الجهل به من إنكار لمعلوم من الدين بالضرورة فذلك كفر ، وأما لما يترتب على الجهل به وعدم الالتزام من قصور ، وإما لما يترتب على الجهل من خطر على وحدة الحركة الإسلامية أو خطر على وحدة الصف أو خطر على المفاهيم الكلية للمسلم أو خطر على المسلمين أنفسهم .", "لقد أدخل الأستاذ البنا في ركن الفهم أصلا لابد أن يفهمها المسلم وأن يفهم على ضوئها الاسلام ، كل أصل من هذه الأصول لا يسع المسلم أن يجهله .", "كما أدخل الأستاذ البنا في ركن الفهم كل ما هو ضرورى لفهم الاسلام ولانطلاق حركة المسلمين ؛ أنه بعد مسيرة نيف وثلاثة عشر قرنا وجدت عوامل مفتتة لوحدة المسلمين ووجدت اتجاهات خاطئة وفهوم قاصرة وتيارات عاتية فكان لابد من فهم صحيح على ضوئه يكون انطلاق صحيح ، هذا الفهم يجمع عليه المسلمون ويستطيعون بالتزامهم فيه أن يتحركوا نحو تحقيق الأهداف فكانت هذه الأصول العشرين على صغر حجمها هي هذا كله ، وقد ختم الأستاذ كلامه في هذه الأصول العشرين بقوله : « وإذا علم الأخ المسلم دينه في هذه الأصول فقد عرف معنى هتافه دائما : القرآن دستورنا والرسول قدوتنا » ا ه . أقول : وإذا عرف الانسان هذه الأصول والتزم بها فانه يكون قد أقام الركن الأول من أركان البيعة ووفى به ، وكما رأينا فأركان البيعة عشرة هذا أولها ، فلنر تتمة أركان بيعتنا :", "« فصل في الركن الثانى من أركان البيعة وهو الاخلاص »", "يقول الأستاذ البنا : « وأريد بالاخلاص : أن يقصد الأخ المسلم بقوله وعمله وجهاده كله وجه الله ، وابتغاء مرضاته وحسن مثوبته من غير نظر الى مغنم أو مظهر أو جاه أو لقب أو تقدم أو تأخر ، وبذلك يكون جندى فكرة وعقيدة لا جندى غرض ومنفعة « قل ان صلاتى ونسكى ومحياى ومماتى لله رب العالمين »"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0122.png"}, {"n": 123, "paras": ["لا شريك له وبذلك أمرت » ( الأنعام : ١٦٢ ، ١٦٣ ) وبذلك يفهم الأخ المسلم معنى هتافه الدائم :", "- الله أكبر ولله الحمد .", "- الله غايتنا .", "« تعليق »", "١ - في الحديث المتفق عليه عن أبي موسى الأشعري رضى الله عنه قال : سئل رسول الله صلى الله عليه وسلم عن الرجل يقاتل شجاعة ويقاتل حمية ويقاتل رياء ، أى ذلك في سبيل الله ؟ فقال رسول الله صلى الله عليه وسلم : « من قاتل لتكون كلمة الله هي العليا فهو في سبيل الله » . وأخرج الإمام مسلم عن أبي هريرة رضى الله عنه قال : قال رسول الله صلى الله عليه وسلم : « إن الله لا ينظر إلى أجسامكم ولا إلى صوركم ولكن ينظر إلى قلوبكم » . وفي الحديث المتفق عليه عن رسول الله صلى الله عليه وسلم : « انما الأعمال بالنيات وانما لكل امرىء ما نوى ، فمن كانت هجرته الى الله ورسوله ، فهجرته الى الله ورسوله ، ومن كانت هجرته لدنيا يصيبها أو مرأة ينكحها فهجرته الى ما هاجر اليه » .", "٢ - يقول أهل السلوك الى الله : « الأعمال أشباح وروحها سر الاخلاص فيها » فكل عمل لا اخلاص فيه ميت عديم القبول ولا بركة فيه .", "٣ - على الانسان من أجل أن يحقق الاخلاص أن يصحح نيته دائما ويفتش عن دوافعه الحقيقية في كل عمل ثم يقدم بعد أن يصحح نيته .", "٤ - المسلم مكلف بعدة أمور في آن واحد : أن يعمل لفرض سلطان شريعة الله ، وأن يسعى في نفسه لكل كمال ، وأن يصحح نيته بحيث يكون ذلك كله لا من أجل الاستعلاء الشخصي « تلك الدار الآخرة نجعلها للذين لا يريدون علوا في الأرض ولا فسادا » ( القصص : ٨٣ )", "٥ - من استقراء واسع لدوافع النفس البشرية التي تحرفها عن الاخلاص يصل الأستاذ الى ذكره عدة دوافع : المغنم ، والمظهر ، والجاه ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0123.png"}, {"n": 124, "paras": ["واللقب والتقدم والتأخر والغرض والمصلحة ، وعلى الأخ أن يبحث في ثنايا نفسه عما إذا كان واحدا من هذه هو الذي يدفعه نحو العمل ، فإذا اكتشف ذلك فلا يترك العمل بل يحاول أن يصحح النية ويستمر بالعمل فقد قالوا : « ترك العمل من أجل الناس رياء ، والعمل من أجل الناس شرك » .", "٦ - عندما يكون الإخلاص موجودا ، فالاخوان يكفرون عند الفزع ويقلون عند الطمع ، يتزاحمون عند الأعمال ، ويفرون عند المغانم ، يتدافعون الدنيا ويتنافسون على الآخرة ، العمل مبارك والصف ملتئم ، فإذا ذهب الإخلاص فقد أصبحت الحركة دورانا في الفراغ ، فلا قبول عند الله ولا بركة بالعمل ولا تحقيق للهدف ولذلك كان الإخلاص هو الركن الثاني من أركان بيعتنا .", "« فصل في الركن الثالث من أركان البيعة وهو العمل » قال الأستاذ البنا رحمه الله : « والمراد من العمل : ثمرة العلم والإخلاص : « وقل اعملوا فسيرى الله عملكم ورسوله والمؤمنون ، وستردون إلى عالم الغيب والشهادة فينبئكم بما كنتم تعملون » ( التوبة : ١٠٥ ) . ومراتب العمل المطلوبة من الأخ الصادق سبعة :", "١ - إصلاح نفسه حتى يكون : قوى الجسم ، متين الخلق ، مثقف الفكر ، قادرا على الكسب ، سليم العقيدة ، صحيح العبادة ، مجاهدا لنفسه ، حريصا على وقته ، منظما في شئونه ، نافعا لغيره ، وذاك واجب كل أخ مسلم على حدة .", "٢ - وتكوين بيت مسلم : بأن يحمل أهله على احترام فكرته والمحافظة على آداب الإسلام في كل مظاهر الحياة المنزلية ، وحسن اختيار الزوجة ، وتوقيفها على حقها وواجباتها ، وحسن تربية الأولاد ، والخدم ، وتنشئتهم على مبادىء الإسلام وذلك واجب كل أخ مسلم على حدة كذلك ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0124.png"}, {"n": 125, "paras": ["٣ - وارشاد المجتمع : بنشر دعوة الخير فيه ومحاربة الرذائل والمنكرات وتشجيع الفضائل والأمر بالمعروف والمبادرة الى فعل الخير ، وكسب الرأى العام الى جانب الفكرة الاسلامية وصبغ مظاهر الحياة العامة بها دائما ، وذلك واجب كل أخ على حدة ، وواجب الجماعة كهيئة عاملة .", "٤ - وتحرير الوطن : بتخليصه من كل سلطان أجنبى - غير اسلامى - سياسى أو اقتصادى أو روحى .", "٥ - واصلاح الحكومة : حتى تكون اسلامية بحق ، وبذلك تؤدى مهمتها كخادم للأمة وأجير عندها وعامل على مصلحتها ، والحكومة اسلامية ما كان أعضاؤها مسلمين ، مؤدين لفرائض الاسلام ، غير متجاهرين بعصيان ، وكانت منفذة لأحكام الاسلام وتعاليمه . ولا بأس بأن تستعين بغير المسلمين عند الضرورة فى غير مناصب الولاية العامة ، ولا عبرة بالشكل الذى تتخذه ولا بالنوع ما دام موافقا للقواعد العامة فى نظام الحكم الاسلامى . ومن صفاتها الشعور بالتبعة والشفقة على الرعية ، والعدالة بين الناس والعفة عن المال العام والاقتصاد فيه .", "ومن واجباتها صيانة الأمن وانفاذ القانون ، ونشر التعليم ، وأعداد القوة ، وحفظ الصحة ، ورعاية المنافع العامة ، وتنمية الثروة ، وحراسة المال ، وتقوية الأخلاق ، ونشر الدعوة ، ومن حقها - متى أدت واجبها - الولاء والطاعة والمساعدة بالنفس والأموال . فاذا قصرت ، فالنصح والارشاد ، ثم الخلع والابعاد ، ولا طاعة لمخلوق فى معصية الخالق .", "٦ - واعادة الكيان الدولى للأمة الاسلامية : بتحرير أوطانها ، واحياء مجدها ، وتقريب ثقافاتها ، وجمع كلمتها ، حتى يؤدى ذلك كله الى اعادة الخلافة المفقودة والوحدة المنشودة ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0125.png"}, {"n": 126, "paras": ["٧ - وأستاذية العالم : ينشر دعوة الاسلام في ربوعه « حتى لا تكون فتنة ، ويكون الدين كله لله » ( الأنفال : ٣٩ ) « ويأبى الله الا ان يتم نوره » ( التوبة : ٣٢ ) وهذه المراتب الأربعة تجب على الجماعة متحدة ، وعلى كل أخ باعتباره عضوا في الجماعة . وما أثقلها تبعات ، وما أعظمها مهمات يراها الناس خيالا ، ويراها المسلم حقيقة ، ولن نيأس أبدا ، ولنا في الله أعظم الأمل « والله غالب على أمره ، ولكن أكثر الناس لا يعلمون » ( يوسف : ٢١ )", "« تعليقات »", "١ - من أكثر أبواب العلم غموضا باب التكليف الالهي ، وقليلون هم الذين يفطنون لمجموع ما هم مكلفون به كأفراد ، وما هم مكلفون به مع غيرهم كأبناء لأمة واحدة ؛ فاقتضى ذلك بيانا : الانس والجن مكلفون بالايمان والاسلام ، ولكن ما يطالب به كل فرد من الاسلام ليس واحدا بل يزيد وينقص : فبقدر ما تتوسع دائرة المسئولية يزداد التكليف ، فتكليف المتزوج أوسع في جانب من تكليف الأعزب ، وتكليف الوزير أوسع من جانب من تكليف الاذن في الوزارة . ثم ان التكليف يختلف باختلاف الطاقات ؛ فمن تعين لفرض من فروض الكفاية أصبح فرض الكفاية في حقه فرض عين ، ثم ان التكليف يختلف باختلاف الظروف التي يواجهها الفرد أو تواجهها أمته فاذا رأيت منكرا تستطيع أن تزيله فواجبك أن تزيله واذا هوجمت أمتك من الخارج فانه يفترض عليك أن تقاتل . ثم ان كل مسلم مكلف تكليفا فرديا ، والمسلمون بمجموعهم مكلفون تكليفا جماعيا بتحقيق أهداف ودرء مفاسد ، فهم مكلفون تكليفاً تكافليا بكثير من الأمور : « واتقوا فتنة لا تصيبن الذين ظلموا منكم خاصة » . ( الأنفال : ٢٥ ) هذا التكليف الذي كلف الله به المسلمين يقتضي عملا ولقد استطاع الأستاذ البنا في ركن البيعة على العمل أن يحصى بعبارته الدقيقة كل", "( ٩ - في آفاق التعاليم )"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0126.png"}, {"n": 127, "paras": ["ما يكلف به المسلم والمسلمون في عصرنا ، وهذا الجانب من أهم ما غفل عنه المسلمون وأحيته دعوة الأستاذ البنا ، فقد غفل كثير من المسلمين عن واجباتهم الفردية وواجباتهم الجماعية ، ومن فطن لشيء من ذلك فانما يفطن لجانب وتغيب عنه جوانب فجاء الأستاذ البنا وذكر بالجميع ، وجعل ذلك ركنا من أركان البيعة ، وأوجد الصف الذي يحقق هذا في نفسه ، ويحاول تحقيقه من خلال العمل الجماعي ، وينبغي أن يكون واضحا أن دائرة العمل هي دائرة التكيف ولذلك فهي أوسع من دائرة الجهاد الذي هو جزء من التكيف ولكن ليس كل تكليف جهادا ولذلك جعل الأستاذ البنا ركن العمل شيئا وركن الجهاد شيئا ثانيا يتمم الأول ويكمله .", "٢ - في باب الأهداف شرحنا ما قاله الأستاذ البنا عن كل بند من بنود العمل وما يدخل فيه ولذلك فإننا نكتفي بما ذكرناه هناك في هذا الشأن .", "٣ - ان الوعي لهذه الأهداف والقيام بحق الله عز وجل فيها هو الطريق الوحيد لاحياء الاسلام على مستوى شخصي ومحلي وعالمي ، ولذلك كان ركنا من أركان بيعتنا ، والذين يغفلون عن هذا الركن وآفاقه يعيشون في أنفسهم في المتاهات ويجعلون غيرهم يعيش كذلك .", "٤ - لاحظ قول الأستاذ رحمه الله ههنا : « والمراد من العمل ثمرة العلم والاخلاص » انه بدون علم لا يقوم ركن العمل وبدون اخلاص لا يقوم العمل ولا يقبله الله ولا يبارك فيه فعليك يا أخي بالعلم النافع والاخلاص لله في كل شيء .", "٥ - لاحظ كلمة الأستاذ في خاتمة ركن العمل : « وما أثقلها تبعات ، وما أعظمها مهمات يراها الناس خيالا ويراها الأخ المسلم حقيقة ، ولن نيأس أبدا ، ولنا في الله أعظم الأمل » لقد كلفنا الله وعلينا أن نعمل ، ولم يكلفنا الله عز وجل الا بقدر وسعنا والا بما هو ممكن التحقيق ، وما دام كل ما ذكره الأستاذ البنا هو من باب التكليف الالهي فنحن واثقون من أنه كائن باذن الله مهما خذل المخذلون وثبط المثبطون ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0127.png"}, {"n": 128, "paras": ["« فصل في الركن الرابع من اركان البيعة وهو ركن الجهاد » قال الأستاذ البنا رحمه الله : « والمراد من الجهاد : الفريضة الماضية الى يوم القيامة ، والمقصود بقول رسول الله صلى الله عليه وسلم : « من مات ولم يغز ولم ينو الغزو مات ميتة جاهلية » .", "وأول مراتبه : انكار القلب ، وأعلاها : القتال في سبيل الله ، وبين ذلك جهاد باللسان ، والقلم ، واليد ، وكلمة الحق عند السلطان الجائر ، ولا تحيا الدعوة الا بالجهاد ، وبقدر سمو الدعوة وسعة أفقها تكون عظمة الجهاد في سبيل الله ، وضخامة الثمن الذي يطلب لتأييدها ، وجزالة الثواب للعاملين « وجاهدوا في الله حق جهاده » ( الحج : ٧٨ ) وبذلك تعرف معنى هتافك الدائم : « والجهاد سبيلنا » .", "« تعليقات »", "١ - أنواع الجهاد خمسة ذكرناها في كتاب « جند الله ثقافة وأخلاقاً » : الجهاد باليد وباللسان وبالمال والجهاد التعليمي والجهاد السياسي المتمثل بكلمة حق عند سلطان جائر .", "٢ - والجهاد بأنواعه كلها هو الطريق لبقاء الاسلام واستمراريته ولاقامته وأعلاء كلمته .", "٣ - واذا أطلقت كلمة الجهاد فانها تطلق على الجهاد باليد ، والجهاد باليد يكون فرض عين ويكون فرض كفاية ، وهذه الفريضة تحوى في طياتها فرائض فالتدريب فريضة ، ونية الجهاد فريضة ، والاعداد فريضة ، وهذه الفرائض يطالب بها الجميع رجالا ونساء وأفرادا وجماعة وتتأكد الفريضة في حق بعض الناس .", "٤ - من آيات الردة في سورة المائدة وهي التي بنينا عليها كتاب « جند الله ثقافة وأخلاقاً » ومن آيات الجهاد في القرآن نعلم أنه لا تنتهى الردة المعاصرة بدون جهاد . ولا يمكن أن ينتهى استعلاء الكفر على الأرض الاسلامية بلا جهاد ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0128.png"}, {"n": 129, "paras": ["ولا يمكن أن ينكف بأس الذين كفروا عن المسلمين بلا جهاد . ولا ينقطع تحكم الكافرين بنا وتكالبهم علينا بلا جهاد ولذلك كانت البيعة على الجهاد ركنا من أركان البيعة .", "« فصل في الركن الخامس من أركان البيعة وهو ركن التضحية » قال الأستاذ البنا رحمه الله : « وأريد بالتضحية : بذل النفس والمال والوقت والحياة وكل شيء في سبيل الغاية وليس في الدنيا جهاد ولا تضحية معه ، ولا تضيع في سبيل فكرتنا تضحية وانما هو الأجر الجزيل والثواب الجميل ، ومن قعد عن التضحية معنا فهو آثم « ان الله اشترى من المؤمنين أنفسهم وأموالهم » ( التوبة : ١١١ ) « قل ان كان آباؤكم وأبناؤكم ... » الآية ( التوبة : ٢٤ ) « ذلك بأنهم لا يصيبهم ظمأ ولا نصب » الآية ( التوبة : ١٢٠ ) « فان تطيعوا يؤتكم الله أجرا حسنا » ( الفتح : ١٦ ) وبذلك تعرف معنى هتافك الدائم : « والموت في سبيل الله أسمى أمانينا » .", "« تعليقات »", "١ - هناك فارق الى حد ما بين الجهاد والتضحية فأحيانا يتطابقان وأحيانا يتكاملان ولذلك اعتبرهما الأستاذ ركنين ، فقد يجاهد المجاهد حتى اذا جاء دور بذل الروح تردد ، وقد يجاهد المجاهد بالوقت ويضحى بالمال ولكنه لا يضحى بالحياة ، ومن ثم أدخل الأستاذ الينا التضحية بالنفس والمال والوقت والحياة وكل شيء في هذا الركن ؛ أنه حيث وجد جهاد وجد نوع من التضحية غير أن الجهاد الكامل لا يكون الا اذا وجدت تضحية كاملة .", "٢ - ان ميزان هذا الركن هو أن يبذل الانسان نفسه وماله ووقته وحياته من أجل تحقيق الأهداف في سبيل الله .", "٣ - أنه اذا لم يوجد مثل هذا النوع من الفناء في الدعوة فان"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0129.png"}, {"n": 130, "paras": ["دعوة الله عز وجل لا تقوم ، وبالتالى فان المقصرين آثمون ولذلك كانت التضحية ركنا من أركان بيعتنا وهي ركن متمم لركن الجهاد .", "« فصل في الركن السادس من أركان البيعة وهو ركن الطاعة » قال الأستاذ البنا رحمه الله : « وأريد بالطاعة : امتثال الأمر وانفاذه توا في العسر واليسر والمنشط والمكره » وذلك أن مراحل هذه الدعوة ثلاث : التعريف : بنشر الفكرة العامة بين الناس ، ونظام الدعوة في هذا الطور نظام الجمعيات الايرادية ومهمتها العمل للخير العام ووسيلتها الوعظ والارشاد تارة واقامة المنشآت النافعة تارة أخرى الى غير ذلك من الوسائل العملية ، وكل شعب الاخوان القائمة الآن تمثل هذا الطور من حياة الدعوة وينظمها « القانون الأساسي » ، وتشرحها رسائل الاخوان وجريدتهم ، والدعوة في هذا الطور « عامة » . ويتصل بالجماعة فيه كل من أراد من الناس متى رغب المساهمة في أعمالها ووعد بالمحافظة على مبادئها ، وليست الطاعة التامة لازمة في هذا الطور بقدر ما يلزم فيه احترام النظم والمبادىء العامة للجماعة . التكوين : باستخلاص العناصر الصالحة لحمل أعباء الجهاد وضم بعضها الى بعض . ونظام الدعوة في هذا الطور صوفى بحت من الناحية الروحية ، وعسكرى بحت من الناحية العملية ، وشعار هاتين الناحيتين دائما « أمر وطاعة » من غير تردد ولا مراجعة ولا شك ، ولا حرج ، وتمثل الكتائب الاخوانية هذا الطور من حياة الدعوة وتنظمها رسالة « المنهج » سابقا وهذه الرسالة الآن « رسالة التعاليم » . والدعوة فيه خاصة لا يتصل بها الا من استعد استعدادا حقيقيا لتحمل أعباء جهاد طويل المدى كثير التبعات ، وأول بوادر هذا الاستعداد « كمال الطاعة » . التنفيذ : والدعوة في هذا الطور جهاد لا هوادة معه ، وعمل متواصل في سبيل الوصول الى الغاية وامتحان وابتلاء ، لا يصبر عليهما"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0130.png"}, {"n": 131, "paras": ["الا الصادقون ، ولا يكفل النجاح في هذا الطور الا كمال انطاعة كذلك .. وعلى هذا بايع انصف الأول من الاخوان المسلمين في يوم ٥ ربيع الأول سنة ١٣٥٩ ه . وأنت بانضمامك الى هذه الكتيبة ، وتقبلك لهذه الرسالة ، وتعهدك بهذه البيعة تكون في الدور الثانى وبالقرب من الدور الثالث ، فقدر التبعة التي التزمتها وأعد نفسك للوفاء بها » .", "(( تعليقات ))", "١ - ما من رسول من الرسل الا وقد طالب قومه بأمرين : بالتقوى والطاعة (( فاتقوا الله وأطيعون )) ( آل عمران : ٥٠ ، والشعراء ، والزخرف ) فبدون طاعة لا تكون جماعة ولا حركة ولا نظام ولا تنظيم ولا زكاة للنفس ولا مسارعة نحو مرضاة الله ولا جهاد ولا هدفا يتحقق .", "٢ - لكن الطاعة الكاملة لا تكون الا بعد العلم والثقة ولذلك فلم يطالب الأستاذ البنا بكمال الطاعة عندما يكون الأخ في مرحلة التعريف لأن الطلب في مثل هذه الحالة غير عملى ؛ نفهم من ذلك أن مرحلة التعريف تقتضى منا أن نعرف الأخ على الاسلام وعلى الجماعة بحيث يعلم ويثق فاذا علم ووثق فقد أن يدخل في مرحلة التكوين ليأخذ دوره في مرحلة التنفيذ ، والطاعة في هذه الحالة لابد منها .", "٣ - ميزان هذا الركن أن ينفذ الأخ الأمر دون تردد ولا مراجعة ولا شك ولا حرج .", "٤ - غير أنه ينبغى أن يكون واضحا أن هذا الركن منوط بكون الجماعة في موضع صحى على رأسها قيادة متوافرة فيها شروط الشرعية الاسلامية والتنظيمية وأن تكون قراراتها متخذة على ضوء الشورى والأحكام الشرعية وبما يتفق مع القواعد التنظيمية المعتمدة لدى الجماعة .", "٥ - ولعله من البديهيات أنه لا يمكن لجماعة أن تحقق هدفا أو تنجز عملا الا اذا كان لقيادتها حق الطاعة على الأفراد الملتزمين في الصف المرتبطين بها عضويا ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0131.png"}, {"n": 132, "paras": ["« فصل في الركن السابع من أركان البيعة وهو ركن الثبات » قال الأستاذ البنا رحمه الله : « وأريد بالثبات : أن يظل الأخ عاملا مجاهدا في سبيل غايته مهما بعدت المدة وتطاولت السنوات والأعوام حتى يلقى الله على ذلك وقد فاز بإحدى الحسنيين فاما الغاية واما الشهادة في النهاية « من المؤمنين رجال صدقوا ما عاهدوا الله عليه ، فمنهم من قضى نحبه ، ومنهم من ينتظر وما بدلوا تبديلا » ( الأحزاب : ٢٣ ) والوقت عندنا جزء من العلاج والطريق طويلة المدى بعيدة المراحل كثيرة العقبات ولكنها وحدها التي تؤدى إلى المقصود مع عظيم الأجر وجميل المثوبة . وذلك أن كل وسيلة من وسائلنا « الستة » إلى حسن الاعداد ، وتحين الفرص ، ودقة الانفاذ ، وكل ذلك مرهون بوقته « ويقولون متى هو قل عسى أن يكون قريبا » ( الاسراء : ٥١ ) .", "« تعليقات »", "١ - لا شيء يدل على صدق الانسان مع الله مثل استمراره على محل الدعوة في كل الظروف ، ولقد سألت مرة أحد الشيوخ عن الطريقة التي أتعرف بها على صدق الانسان مع الله ، فقال لي : استمراره على الدعوة وحملها في كل الظروف والأحوال ، وهذا هو المراد بالثبات هنا .", "٢ - لم يصل المسلمون في يوم من الأيام إلى حالة من الضعف كما وصلوا اليها في عصرنا هذا ، مع تنامى قوة الخصوم بشكل هائل ، والانتقال من هذه المرحلة الى مرحلة أحسن منها يحتاج الى زمن طويل ، وتحقيق الأهداف يحتاج الى زمن أطول ، فالاستمرار في كل الظروف هو الطريق لتحقيق الأهداف وتكاثر الصف .", "٣ - لنفترض أن كل من حمل الدعوة سار بها زمنا وترك ، ففي هذه الحالة تكون المحصلة دائما صفرا ، ويكون الصف في هذه الحالة في حكم المعدوم ، فلا مراحل تقطع ولا أهدافا تحقق ، وبالتالى فان تفريطا خطيرا في فرائض كثيرة يكون قد وقع ، ولذلك كان الثبات ركنا من أركان البيعة في دعوتنا ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0132.png"}, {"n": 133, "paras": ["٤ - مما يساعد على الثبات الزهد في الدنيا وجاهها ومناصبها ، ويساعد على الثبات طلب الأجر من الله ، وتوقع جميل المثوبة منه ، ويساعد على الثبات خوف عقوبة الله في الدنيا والآخرة .", "٥ - ولعله يكون واضحا أن الثبات على طريق الدعوة وعدم التخلى عن الصف رغم المحن والشدائد يحقق استمرارية المسيرة وامكانية توريث الدعوة بأماناتها من جيل إلى جيل حتى يتحقق النصر باذن الله . وقد أعان الله الاخوان في مصر وغيرها على الوفاء بهذا الركن وثبتهم الله وظلوا رافعي الراية رغم قسوة الضغوط وطول زمنها .", "(( فصل في الركن الثامن من أركان البيعة وهو ركن التجرد ))", "قال الأستاذ البنا رحمه الله :", "(( وأريد بالتجرد : أن تتخلص لفكرتك من ما سواها من المبادىء والأشخاص لأنها أسمى الفكر وأجمعها وأعلاها (( صبغة الله ، ومن أحسن من الله صبغة )) ( البقرة : ١٣٨ ) (( قد كانت لكم أسوة حسنة في ابراهيم والذين معه ، اذ قالوا لقومهم انا برآء منكم ومما تعبدون من دون الله ، كفرنا بكم وبدا بيننا وبينكم العداوة والبغضاء أبدا حتى تؤمنوا بالله وحده )) ( الممتحنة : ٤ ) والناس عند الأخ الصادق واحد من ستة أصناف :", "مسلم مجاهد ، أو مسلم قاعد ، أو مسلم آثم ، أو ذمي ، أو معاهد ، أو محايد ، أو محارب ، ولكل حكمه في ميزان الاسلام ، وفي حدود هذه الأقسام توزن الأشخاص والهيئات ويكون الولاء أو العداء )) .", "(( تعليقات ))", "١ - ان الذي يعرف دعوة الاخوان المسلمين يدرك أنها أصفى فهم للاسلام وأنها أجود طريق للعمل له ، وهذا يقتضى أن يخلص الانسان لها اخلاصا كاملا بحيث يزن الناس من خلالها ويتعامل على ضوء ذلك ، وهذا معنى التجرد .", "٢ - وأن علامة التجرد هو وزن الأشخاص والهيئات بميزان"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0133.png"}, {"n": 134, "paras": ["الدعوة واتخاذ موقف بناء على ذلك ، فهناك المسلمون المجاهدون وموقفنا منهم الولاء اذا أعطونا الولاء ولو اختلفت اجتهاداتنا ، وهناك مسلمون قاعدون بعذر ، موقفنا منهم الولاء مع الاعذار ، وهناك مسلمون آثمون ومنهم القاعدون لغير عذر فهؤلاء موقفنا منهم الدعوة والنصيحة ، وهناك ذميون لم ينقضوا عهدا فهؤلاء لهم ما لنا وعليهم ما علينا ، وهناك ذميون نقضوا العهود فهؤلاء أصبحوا محاربين ، وهناك محايدون دخلوا بلادنا بأماننا الحر فهؤلاء لا يعتدى عليهم ، وهناك محايدون بين الكفر والاسلام فهؤلاء ان كانوا يتظاهرون بالاسلام فهم منافقون وان كانوا كافرين فلنا حق قبول حيادهم أو رفضه ، وهناك محاربون فالأصل في علاقاتنا معهم الحرب الا لمناورة أو لخدعة أو لغير ذلك مما أجازه الاسلام . ان موقفك الاسلامي والدعوى من الناس هو الذي يحدد تجردك لدعوتك أولا .", "٣ - انه اذا لم يوجد التجرد لم يوجد الصف الاسلامي الواحد ، ولذلك كان التجرد ركنا من أركان البيعة في عصرنا ليكون ولاؤك لصفك ولجماعتك فقط .", "(( فصل في الركن التاسع من أركان البيعة وهو ركن الأخوة )) قال الأستاذ البنا رحمه الله : (( والمراد من الأخوة : أن ترتبط القلوب والأرواح برباط العقيدة ، والعقيدة أوثق الروابط وأعلاها ، والأخوة : أخوة الايمان ، والتفرق : أخو الكفر . وأول القوة قوة الوحدة ، ولا وحدة بغير حب ، وأقل الحب سلامة الصدر ، وأعلاه مرتبة الايثار : (( ومن يوق شح نفسه فأولئك هم المفلحون )) ( الحشر : ٩ ، التغابن : ١٦ ) الأخ الصادق يرى أخوانه أولى بنفسه من نفسه لأنه ان لم يكن بهم فلن يكون بغيرهم ، وهم ان لم يكونوا به كانوا بغيره (( وانما يأكل الذئب من الغنم القاصية )) و (( المؤمن للمؤمن كالبنيان يشد بعضه بعضا )) (١) .", "(١) رواه البخاري ومسلم والترمذي والنسائي من طريق أبي موسى بأسناد صحيح ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0134.png"}, {"n": 135, "paras": ["والمؤمنات بعضهم أولياء بعض » ( التوبة : ٧١ ) وهكذا يجب أن تكون » ...", "« تعليقات »", "١ - من كلمات أحمد شوقى : « أصدقاء السياسة أعداء بعد الرئاسة » . أن كل الدعوات السياسية لا تستقيم أخوة أبنائها بعضهم لبعض بسبب الماحكات الحزبية والتنافس على الرئاسة والمناصب والمادة ، وما دخلت الدنيا فى شيء إلا أفسدته ؛ وقد وصف جيل من الأجيال بأنهم أعداء السر أصدقاء العلانية ، ومثل ذلك لا يقوم عليه اسلام ولا تتحقق به أهداف ، ولذلك كان الاخاء الحقيقى ركنا من أركان البيعة .", "٢ - لقد أعطانا الأستاذ البنا علامة نعرف بها الاخاء وهى : الحب الذى أقله سلامة الصدر على الاخوان ، وأعلاه ايثارهم فى كل شيء من أمور الدنيا من المناصب الى المنفعة الى الجاه ، ولا يحقق المحبة فى الصف شيء مثل أن يزهد كل أخ بما فى يد الآخر : « ازهد فى الدنيا يحبك الله وازهد فيما فى أيدى الناس يحبك الناس » .", "٣ - لا شيء يديم الاخاء مثل طاعة الله والبعد عن معصيته ، والاخاء القائم على التقوى يستمر فى الدنيا والآخرة قال تعالى : « الأخلاء يومئذ بعضهم لبعض عدو الا المتقين » ( الزخرف : ٦٧ ) .", "٤ - لا شيء يقطع تصدع الاخاء مثل الايمان والعمل الصالح قال تعالى : « وأن كثيراً من الخلطاء ليبغى بعضهم على بعض الا الذين آمنوا وعملوا الصالحات وقليل ما هم » ( سورة ص : ٢٤ ) .", "٥ - عدو الله ابليس يغيظه الحب والأخوة بين الداعين الى الله ويحاول أن ينزغ بينهم ، فعلى الاخوان أن يقولوا التي هي أحسن وألا يفسد الخلاف فى الرأى بينهم للمود قضية .", "« فصل فى الركن العاشر من أركان البيعة وهو ركن الثقة » قال الأستاذ البنا رحمه الله : « والمراد من الثقة : اطمئنان الجندى الى القائد فى كفاءته"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0135.png"}, {"n": 136, "paras": ["وإخلاصه ؛ اطمئنانا عميقا ينتج الحب والاحترام والطاعة « فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجا مما قضيت ويسلموا تسليما » ( النساء : ٦٥ ) .", "والقائد جزء من الدعوة ولا دعوة بغير قيادة ؛ وعلى قدر الثقة المتبادلة بين القائد والجنود تكون قوة النظام للجماعة ، وأحكام خططها ، ونجاحها في الوصول إلى غاياتها ، وتغلبها على ما يعترضها من عقبات وصعاب « فأولى لهم . طاعة وقول معروف » ( محمد : ٢٠ ، ٢١ ) .", "وللقيادة في دعوة الإخوان حق الوالد بالرابطة القلبية ، والأستاذ بالإفادة العلمية ، والشيخ بالتربية الروحية ، والقائد بحكم السياسة العامة للدعوة ؛ ودعوتنا تجمع هذه المعاني جميعا ، والثقة بالقيادة هي كل شيء في نجاح الدعوات ، ولهذا يجب أن يسأل الأخ الصادق نفسه هذه الأسئلة ليتعرف مدى ثقته بقيادته :", "١ - هل تعرف إلى قائده من قبل ودرس ظروف حياته ؟", "٢ - هل اطمأن إلى كفايته وإخلاصه ؟", "٣ - هل هو مستعد لاعتبار الأوامر التي تصدر إليه من القيادة - في غير معصية طبعا - قاطعة لا مجال فيها للجدل ولا للتردد ولا للانتقاص ولا للتحوير ؟ مع إبداء النصيحة والتنبيه إلى الصواب ؟", "٤ - هل هو مستعد لأن يفترض في نفسه الخطأ وفي القيادة الصواب إذا تعارض ما أمر به مع ما تعلم في المسائل الاجتهادية التي لم يرد فيها نص شرعي ؟", "٥ - هل هو مستعد لوضع ظروفه الحيوية تحت تصرف الدعوة ؟ وهل تملك القيادة في نظره حق الترجيح بين مصلحته الخاصة ومصلحة الدعوة العامة .", "وبالإجابة على هذه الأسئلة وأشباهها يستطيع الأخ أن يطمئن على مدى صلته بالقائد ، وثقته به ، والقلوب بيد الله يصرفها كيف يشاء « لو أنفقت ما في الأرض جميعا ما ألفت بين قلوبهم ولكن الله ألف بينهم ، أنه عزيز حكيم » ( الأنفال : ٦٣ ) ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0136.png"}, {"n": 137, "paras": ["(( تعليق ))", "لقد حقق الأستاذ بهذه الفقرة مجموعة أغراض :", "١ - أعطانا مواصفات القائد في الإخوان المسلمين وأنه من اجتمعت فيه خصائص الأبوة ، وصفات العالم ، ومواصفات الرباني ، وكمالات القائد العسكري والسياسي ، فمن لم تجتمع فيه هذه الأمور كلها فليس هو القائد الكامل ؛ وبالتالى فان الثقة في القيادة لا تكون كاملة ، ومن هذه المواصفات التي تحققت كلها في حسن البنا رحمه الله نستنتج أن الجماعة أن تقدم لقيادتها من اجتمعت له هذه المواصفات .", "٢ - دلنا الأستاذ البنا في هذه الفقرة على الطريق التي تتعمق بها الثقة في القيادة وهي توافر المؤهلات عند القائد ، والتعرف على القائد من قرب ، ومعرفة تاريخ حياته ، ونظافة هذا التاريخ واطمئنان الجندى الى كفايته وأخلاصه .", "٣ - أعطانا الأستاذ البنا في هذه الفقرة الموازين التي تستكشف بها الثقة وهي : التسليم للأمر مع تبيان وجهة النظر في حال عدم الاقتناع وافتراض الجندى أن القيادة أقرب للصواب واستعداده لقبول رأى الجماعة في ترجيح المصالح العامة على المصالح الخاصة .", "٤ - دلنا في هذه الفقرة على علامات الثقة بالقائد : وهي الحب والتقدير والاحترام والطاعة .", "(( هوامش على موضوع الثقة ))", "١ - من أخطاء بعض القيادات أنها تطالب بالثقة دون أن تؤدى مهرها ؛ أن الثقة بالقيادة لا تأتى من خلال المطالبة بقدر ما تأتى من خلال شعور الجندى بكفاءة قيادته وجدارته وحكمته من خلال الاحتكاك والممارسة والمواقف اليومية .", "٢ - من أخطاء بعض القيادات أنها لا تستطيع تنمية الثقة ، ومن ثم فكلما زاد الاحتكاك بها تقلصت الثقة ؛ وذلك يعود إما لجهلها بالتعامل مع النفس البشرية أو لقصورها في نفسها أو لعجزها عن تربية الذين يحيطون بها ويحتكون بها .", "٣ - من أعظم ما ينمى الثقة داخل الجماعة ألا تعطى صفة لأحد"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0137.png"}, {"n": 138, "paras": ["داخل الجماعة دون أن يستحقها ، وأن يؤدى كل ذي صفة في الجماعة حقوق صفته ، بذلك تنمو الثقة .", "٤ - ومما ينمى الثقة داخل الجماعة شعور كل فرد فيها بصحة القرارات وسلامة السير ودقته ، وهذا يقتضى أن تكون القرارات دائما معللة الا لضرورة أمنية .", "٥ - لماذا كانت البيعة على الثقة ركنا من أركان بيعتنا ؟", "- اننا حركة دينية أخروية مسيرتها ممتدة عبر الزمان وعلى امتداد المكان فبدون ثقة بالقيادة لا يمكن الاستمرار في السير .", "- ونحن حركة نريد أن نحقق أهدافا محلية وأهدافا عالمية واذا لم تكن هناك ثقة بالقيادة فان أى هدف من الأهداف لا يمكن أن يتحقق .", "- ولأن أكثر الخطط كفاءة لا تساوى شيئا اذا لم يوجد منفذون ولا تنفيذ راقيا لا بثقة مطلقة في القيادة .", "٦ - ماذا تعنى بيعتى على ركن الثقة ؟ لقد أعطانا الأستاذ البنا المضمون وأنه : اعتبار الأوامر الصادرة من القيادة في غير معصية قاطعة لا مجال فيها للجدل ولا للتردد ولا للانتقاص ولا للتحوير مع ابداء النصيحة والتنبيه الى الصواب مع الاستعداد لافتراض الخطأ في نفسه وفى القيادة الصواب في المسائل الاجتهادية مع الاستعداد لوضع ظروفه الحيوية تحت تصرف الدعوة واعطاء الجماعة حق الترجيح بين مصلحته الخاصة ومصلحة الدعوة العامة .", "٧ - هل يمكن للمسلمين أن يسيروا بدون ركن الثقة ؟", "- يستحيل أن يكون هناك سير بدون هذا الركن ، ولذلك فان أول واجبات الجماعة أن توجد الهيكل التنظيمى الذى يوحى بالثقة ، وأن تملأه بالرجال الذين يوحون بالثقة ، وأن توجد القواعد التي تضبط السير التنظيمى بما يوحى بالثقة ، وأن تعتمد الطرق المناسبة لصحة القرارات بما يفيض ثقة على قلوب الاخوان .", "٨ - كيف نعالج الخلل اذا حدث في هذا الركن ؟", "- كثيرا ما تعالج القيادات فقد الثقة بالوعود بازالة الأسباب الموجبة لتخلخل الثقة في الوقت الذى قد تكون عاجزة فيه عن ذلك وأحسن شيء في مواجهة ضعف الثقة - هو تبيان الحقيقة والتعاون على ازالة القصور ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0138.png"}, {"n": 139, "paras": ["٩ - من أخطر ما يواجه العمل وجود المشككين والمحطمين للثقة وذلك فان على القيادة أن تتحرك بسرعة اذا وجد أمثال هؤلاء ، اما مراجعة الأوضاع ومعالجة القصور أو بمحاسبة هؤلاء .", "١٠ - كثيرا ما يلجأ أعداء الله إلى محاولة النيل من الأخوة والثقة بين أفراد الجماعة وبينهم وبين القيادة ويبثون الاشاعات والافتراءات ، والاسلام يدعونا الى التبين وعدم الأخذ بالظن .", "(( تعليقات على كون أركان البيعة عشر ))", "١ - هل رأيت أن استقراء الأستاذ البنا كان في غاية الدقة بحيث فطّن الى كل ما يلزم لسير الحركة سيرا سليما فجعله ركنا في البيعة ؟ وهل ترى أنه يمكن أن يستغنى عن ركن من هذه الأركان ويبقى بعد ذلك المسير صحيحا أو سليما أو محققا للهدف ؟", "٢ - قد يحدث أن تفتن الجماعة ككل في ركن من الأركان أو في مجموع الأركان وكثيرا ما يفتن الأخ عن ركن أو عن مجموعة الأركان ، فقد يمتحن الأخ مثلا في ركن الفهم بحيث يطغى عليه فهم خاطىء ، أو يمتحن في ركن الاخاء فيمتلىء قلبه بالحقد أو بالضغينة أو بالكيد ، أو يمتحن بركن الثبات فيتخلى أو يعتزل ، أو يمتحن في ركن الثقة فلا يسير وينشر دوائر من التشكيك الى غير ذلك ، وكل ذلك يعود الى ضعف التربية أو الى الخلل في بناء الجماعة ، فعلى الجماعة ألا تفرط في التربية وعليها أن تحكم البناء . وقد تتعرض الجماعة كلها لامتحان قد يزعزع أركان البيعة العشرة كما حدث في بعض المحن وعندئذ فالخلاصة التي تنجح في الامتحان هي الجماعة .", "٣ - انه يستحيل عادة سير سليم للبدايات موصل الى الغايات الا بوجود صف تحلى كل فرد من أفراده بأركان البيعة العشرة والتزم بها وانصهر فيها ، وان كثيرين ينقضهم الصف بسبب اخلالهم بأحد أركان البيعة ، وهؤلاء في كثير من الأحيان يكونون فتنة لغيرهم ولذلك فان على الصف أن يكون كله مرآة لهذه الأركان ، وعليه أن يكون درءا للخلل فيفصل أهله أو يقومهم ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0139.png"}, {"n": 140, "paras": ["(( فصل في واجبات الأخ المجاهد ))", "قال الأستاذ البنا رحمه الله : (( إن إيمانك أيها الأخ المسلم بهذه البيعة يوجب عليك أداء هذه الواجبات حتى تكون لبنة قوية في الجماعة الإسلامية وهذه الواجبات وسنذكرها فيما بعد مع شرحها )) .", "(( تعليقات ))", "١ - ليس المراد بكلمة الواجب هنا الواجب الشرعي بل المراد أوسع من ذلك فمن بين هذه الواجبات ما هو فريضة شرعية ومنه ما هو مندوب شرعي ، فالمراد اذن بكلمة الواجب هنا الالتزامات الدعوية التي تقتضيها طبيعة الحركة الإسلامية في هذا العصر ، وقد راعى الأستاذ البنا في هذه الواجبات أمورا كثيرة كما سنرى ؛ راعى طبيعة العصر ، وراعى الاحتمالات التي يمكن أن تواجه الدعوة أو الداعية ، وراعى كسب ثقة الأمة ، وراعى مستلزمات البيعة الى غير ذلك مما سنراه .", "٢ - ان البيعة على الأركان العشرة التي مرت معنا تجعل الأخ لبنة في الجماعة ولكن هذه الواجبات هي التي تجعله لبنة قوية في بنائها فقد غطت كل جوانب شخصية الأخ العامل تقريبا .", "٣ - والبيعة على الأركان العشرة تقتضى عملا يناسبها ، وهذه الواجبات الأربعون هي مقتضيات البيعة على الأركان العشر .", "(( فصل في الواجب الأول ))", "قال الأستاذ رحمه الله : (( ١ - أن يكون لك ورد يومى من كتاب الله لا يقل عن جزء ، واجتهد ألا تختم القرآن في أكثر من شهر ولا في أقل من ثلاثة أيام )) .", "(( شروح وتعليقات ووصايا ))", "١ - عن عبد الله بن عمرو رضى الله عنهما قال : كنت أصوم الدهر وأقرأ القرآن كل ليلة فاما ذكرت لنبى صلى الله عليه وسلم واما أرسل الى ، فأتيته فقال لي : (( ألم أخبر أنك تصوم الدهر وتقرأ القرآن )) ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0140.png"}, {"n": 141, "paras": ["كل ليلة » ؟ فقلت : بلى يا نبي الله ، ولم أرد بذلك إلا الخير . قال : « فإن بحسبك أن تصوم من كل شهر ثلاثة أيام » ، قلت : يا نبي الله إني أطيق أفضل من ذلك ، قال : « فإن لزوجك عليك حقا ، ولجسدك عليك حقا ، فصم صوم داوود نبي الله فانه كان أعبد الناس » قلت : يا نبي الله وما صوم داوود ؟ قال : « كان يصوم يوما ويفطر يوما واقرأ القرآن في كل شهر » ، قلت : يا نبي الله إني أطيق أفضل من ذلك ، قال : « فاقرأه في كل عشرين » قلت : يا نبي الله إني أطيق أفضل من ذلك ، قال : « فاقرأه في كل عشر » قلت : يا نبي الله إني أطيق أفضل من ذلك ، قال : « فاقرأه في كل سبع ولا تزد على ذلك ، فإن لزوجك عليك حقا ، ولزورك عليك حقا ، ولجسدك عليك حقا » فشددت فشدد علي ، وقال لي النبي صلى الله عليه وسلم : « انك لا تدري لعلك يطول بك عمر » فصرت اني الذي قال لي النبي صلى الله عليه وسلم ، فلما كبرت وددت أني كنت قبلت رخصة نبي الله صلى الله عليه وسلم . رواه البخاري ومسلم .", "وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال : قال رسول الله صلى الله عليه وسلم : « لم يفقه من قرأ القرآن في أقل من ثلاث » رواه أبو داوود والترمذي وابن ماجه ، وقال الترمذي : حديث حسن صحيح ، والمراد بعدم الفقه ، عدم فهم المعاني ، والمراد نفى الفهم لا نفى الثواب فمن قرأ القرآن كله في يوم واحد لم يفته أجر التلاوة وإنما يفوته أجر التدبر .", "٢ - يحتاج القلب البشري الى غذاء ودواء وفي القرآن غذاء ودواء : « قد جاءتكم موعظة من ربكم وشفاء لما في الصدور وهدى ورحمة للمؤمنين » (يونس : ٥٧) . أخرج الحاكم عن ابن مسعود رضي الله عنه : « ان هذا القرآن مأدبة الله فاقبلوا مأدبته ما استطعتم » . ان الذي ليس له ورد يومي من كتاب الله يقع في المرض ولا يشعر ويذوى الايمان في قلبه ولا يشعر ، ولذلك فلابد لتجديد المعاني الايمانية في القلب من ورد يومي من القرآن « واذا تليت عليهم آياته زادتهم ايمانا » (الأنفال : ٢) .", "٣ - قد لا تواتيك الفرصة أن تقرأ وردك القرآني كل يوم أو قد"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0141.png"}, {"n": 142, "paras": ["لا تستطيع أن تقرأ جزأك كل يوم فحاول في هذه الحالة أن تفرغ بعض أيامك في الشهر لتكمل ختمتك .", "(( فصل في الواجب الثاني )) قال الأستاذ البنا رحمه الله :", "٢ - (( أن تحسن تلاوة القرآن الكريم والاستماع إليه والتدبر في معانيه )) .", "(( شروح وتطبيقات )) من حقوق القرآن احسان تلاوته بتحسين الصوت أثناء التلاوة وبترتيله ، قال تعالى : (( ورتل القرآن ترتيلا )) ( المزمل : ٤ ) . وعن سعد بن أبي وقاص رضى الله عنه ، عن رسول الله صلى الله عليه عليه وسلم : (( ان هذا القرآن نزل بحزن فاذا قرأتموه فابكوا ، فان لم تبكوا فتباكوا ، وتغنوا به ، فمن لم يتغن بالقرآن فليس منا )) ، رواه ابن ماجه . والمراد بالتغني هنا التحزن واظهار الخشوع مع تجويد القراءة ، فقد جاء في حديث جابر رضى الله عنه قال : قال رسول الله صلى الله عليه عليه وسلم : (( ان من أحسن الناس صوتا بالقرآن الذي اذا سمعتموه يقرأ حسبتموه يخشى الله )) ، رواه ابن ماجه . قال ابن كثير : (( والغرض أن المطلوب شرعا انما هو التحسين بالصوت ، الباعث على تدبر القرآن وتفهمه ، والخشوع والخضوع والانقياد للطاعة ، فأما الأصوات المحدثة المركبة على الأوزان والأوضاع الملهية والقانون الموسيقى ، فالقرآن ينزه عن هذا ويجل ويعظم أن يسلك في أدائه هذا المذهب ، وقد جاءت السنة بالزجر عن ذلك )) . وللقيام بحق القرآن في ترتيله وحسن تلاوته فان على المسلم أن يتقن علم التجويد الذي سجله علماء هذه الأمة مستقرئين به كيفية تلاوته عليه الصلاة والسلام لهذا القرآن ، وقد كتبت في هذا رسائل كثيرة منها القديم ومنها الحديث ومما كتب قريبا : (( فن التجويد )) للدعاسي ، ومنها : (( فن الترتيل )) للشيرازى الصباغ ، ومنها (( حق التلاوة )) لحسنى الشيخ عثمان .", "( ٦٠ - في آفاق التعاليم )"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0142.png"}, {"n": 143, "paras": ["ومن حقوق القرآن تدبر معانيه : قال تعالى : « أفلا يتدبرون القرآن ، ولو كان من عند غير الله لوجدوا فيه اختلافا كثيرا » ( النساء : ٨٢ ) وقال تعالى : « كتاب أنزلناه إليك مبارك ليدبروا آياته وليتذكر أولوا الألباب » ( سورة ص : ٢٩ ) ومن حقوق القرآن ، حسن الاستماع وحسن الإنصات أثناء تلاوته ؛ قال تعالى : « وإذا قرىء القرآن فاستمعوا له وأنصتوا لعلكم ترحمون » ( الأعراف : ٢٠٤ ) . وقد سجل الأستاذ البنا هذه الحقوق في هذه الوصية .", "(( مسألة فقهية )) لا يستحسن أن يفتح الإنسان الراديو أو المسجل على قراءة القرآن في الأسواق وأمثالها ؛ لأن الحال ليس حال إنصات وفي ذلك إحراج للناس ، وذلك لم يعتبر الفقهاء أن الاستماع والإنصات في هذه الحالة واجبان على كل سامع بل اعتبر بعض فقهاء الحنفية الاستماع والإنصات في هذه الحالات وأمثالها من باب فروض الكفايات ، ولكن الأدب في مجالس التلاوة المخصصة لذلك هو الإنصات والاستماع والتدبر للجميع .", "(( فصل في الواجب الثالث )) قال الأستاذ البنا رحمه الله :", "٣ - « وأن تدرس السيرة المطهرة ، وتاريخ السلف الصالح بقدر ما يتسع له وقتك ، وأقل ما يكفى في ذلك كتاب « حماة الإسلام » وأن تكثر من القراءة في حديث رسول الله صلى الله عليه وسلم وأن تحفظ أربعين حديثا على الأقل ، كمتن الأربعين النووية ، وأن تدرس رسالة في أصول العقائد ، ورسالة في فروع الفقه » .", "(( تعليقات وشروح ووصايا ))", "١ - أن هذه الأمة لاتحيا بدون دراسة للكتاب وللسنة وللسيرة ؛ ففى الكتاب وأنسنة الهدى ، وفى السيرة القدوة ، وبقدر ما يلتصق المسلمون بهذه الأمور الثلاثة يرتقون ويكونون مرشحين للقيام بأعلى"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0143.png"}, {"n": 144, "paras": ["الواجبات فدراسة السيرة وحياة الصحابة هي التي تجعل الأجيال ترتقى الى مقامات القدوة العليا وبدون ذلك فلا ارتقاء ، وثمة نماذج في التاريخ الاسلامى تصلح للاقتداء في بعض الجوانب ولكن القدوة العليا في كل شيء هو رسول الله صلى الله عليه وسلم والجيل الذي رباه .", "٢ - ولقد انقسم المسلمون خلال العصور الى فرق شتى نتيجة لمفهوم خاطئة ، ولذلك كان لابد من دراسة علم أصول العقائد في كتب أهل السنة والجماعة المعتمدة لتكون المسلم مناعة .", "٣ - وان سهولة التفقه تقتضى أن يدرس الأخ كتابا في الفقه على مذهب امام ، وكتابنا « جولات في الفقهين الكبير والأكبر » يبين أهمية وصية الأستاذ البنا هذه .", "« فصل في الواجب الرابع »", "قال الأستاذ البنا رحمه الله :", "٤ - « أن تبادر بالكشف الصحى العام ، وأن تأخذ في علاج ما يكون فيك من أمراض ، وتهتم بأسباب القوة والوقاية الجسمانية ، وتبتعد عن أسباب الضعف الصحى » .", "« تعليقات »", "قال عليه الصلاة والسلام : « والمؤمن القوى خير وأحب الى الله من المؤمن الضعيف وفى كل خير » ، أخرجه مسلم .", "١ - فالمسلم عليه أن يبحث عن أسباب القوة ويأخذ بها ان كان يستطيع ذلك ، ومن أوائل أسباب القوة أن يعالج أسباب الضعف الجسمى من مرض وغيره ، وبداية ذلك الكشف الصحى العام .", "٢ - والقوة الجسمية تحتاج الى وقاية وتدريب ومن أهم مظاهر الوقاية التحكم في قضايا الطعام والشراب ومن أهم أسباب القوة التدريب الرياضى اليومى ولو كان خفيفاً .", "٣ - من أهم أسباب الضعف الصحى شرب الدخان والمخدرات والمسكرات والسكنى في بيوت غير صحية مع عدم مراعاة ذلك ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0144.png"}, {"n": 145, "paras": ["٤ - ان جسمك ليس منك انما هو ملك لله عز وجل فعليك أن تعتنى به لتستطيع أن تستعمله في خير .", "(( فصل في الواجب الخامس ))", "قال الأستاذ رحمه الله :", "٥ - (( أن تبتعد عن الاسراف في قهوة البن والشاي أو نحوها من المشروبات المنبهة ، فلا تشربها الا لضرورة وأن تمتنع بتاتا عن التدخين )) .", "(( تعليقات ))", "١ - قوة البن قليلها مفيد صحيا ومتوسطها لا يضر وكثيرها يضر وقل مثل ذلك في الشاي وأمثاله من المنبهات ولذلك نهانا الأستاذ عن الاسراف فيها لما يترتب على ذلك من ضرر ولما يترتب على ذلك من اعتياد يلهى أو يقطع عن خير أو يحول دون تحقيق واجب .", "٢ - الاعتياد على المنبهات قد يجعل الانسان أسير عادة ، لا يستطيع فراقها بالتالي ضعيفا أمامها ، واذا طرأت ظروف كظروف القتال أو السفر أو السجن . فان الانسان يصبح في آلام نتيجة انفقدان وقد يدفعه ذلك الى موقف ذليل أو موقف غير مشروع ، ولذلك قال الأستاذ البنا : (( فلا تشربها الا لضرورة )) فالأصل عدم الاسراف والأجود عدم الاعتياد بل أن يعود الانسان نفسه على تركها فذلك أجود .", "٣ - اما الدخان فبعد أن ثبت ضرره فقد مال أكثر الفقهاء الى تحريمه ، ولذلك قال الأستاذ البنا : (( وأن تمتنع بتاتا عن التدخين )) ومعالجة أمر التدخين عند من اعتاده من أصعب الأمور ، ولذلك فان علينا أن نكون حكماء في هذه المعالجة ، خاصة وقد وجد من أجازه من الفقهاء ، فأبن عابدين مثلا يقول عن الدخان : (( انه مكروه طبعا ، مباح شرعا )) ولا شك أن ابن عابدين قال مثل هذه الأقوال قبل اكتشاف الأضرار الكثيرة للدخان ولكن ومع وجود الأضرار فانه بقى من الفقهاء من يناقش في الحرمة بحجة أن ليس كل ضرر يقتضى تحريما فهذه التوابل مثلا ، فلوجود مثل هذه الأقوال نجد بعض المدخنين المدمنين يتساهلون في هذا الشأن والمربى الحكيم لا يعجز أن يقتلع العادة الضارة ، فكيف اذا كانت هذه العادة محققة الضرر مظنة التحريم ؟ فكيف اذا كان شرب"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0145.png"}, {"n": 146, "paras": ["الدخان يعتبره بعضهم من المحرمات القطعية التي استحلالها كفر ثم كم يذهب من أموال المسلمين هدرا بسبب الدخان .", "(( فصل في الواجب السادس )) قال الأستاذ البنا رحمه الله :", "٦ - (( أن تعنى بالنظافة في كل شيء : في المسكن والملبس والمطعم واليدن ومحل العمل ، فقد بنى الدين على النظافة )) . (( تعليقات ))", "١ - من أهم مظاهر الاسلام ومن أهم آداب المسلم النظافة ، قال عليه الصلاة والسلام : (( انكم قادمون على اخوانكم فأصلحوا رحالكم وأصلحوا لباسكم حتى تكونوا كأنكم شامة في الناس فان الله لا يحب الفحش ولا التفحش )) ، أخرجه أحمد وأبو داوود والحاكم والبيهقي ورمز السيوطي لصحته ، وأخرج الامام مسلم والترمذي وغيرهما عن رسول الله صلى الله عليه وسلم قوله : (( ان الله جميل يحب الجمال )) ، وأخرج ابن عدى باسناد رمز السيوطي لضعفه عن رسول الله صلى الله عليه وسلم قوله : (( ان الله تعالى جميل يحب الجمال ، سخي يحب السخاء ، نظيف يحب النظافة )) .", "٢ - ذكر الأستاذ البنا مجموعة من الأمور ينبغي أن تراعى فيها النظافة وهي نماذج ، والأمر أوسع من ذلك ، والنظافة لا تحتاج الا الى همة قوية والى جهد بسيط يجعلك نظيفا في بيتك ولباسك ومحل عملك ، وكم يترك ذلك من آثار طيبة على نفس الانسان وعلى من حوله ، وكم يترك الاهمال من انطباعات سيئة في الأنفس .", "(( فصل في الواجب السابع )) قال رحمه الله :", "٧ - (( أن تكون صادق الكلمة فلا تكذب أبدا )) . (( تعليقات ))", "١ - الأصل في المسلم أن يكون صادقا ، قال عليه الصلاة والسلام : (( ان الصدق يهدى الى البر ، وان البر يهدى الى الجنة ، وان الرجل ليصدق حتى يكتب عند الله صديقا ، وان الكذب يهدى الى"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0146.png"}, {"n": 147, "paras": ["الفجور ، وأن الفجور يهدي إلى النار ، وإن الرجل ليكذب حتى يكتب عند الله كذابا » متفق عليه .", "٢ - هناك حالات يترتب على الصدق فيها أضرار غير مشروعة ، فهذه مستثناة من هذا الأصل ، قال النووي في رياض الصالحين : « باب بيان ما يجوز من الكذب » : « إن الكذب وإن كان أصله محرما فيجوز في بعض الأحوال بشروط قد أوضحتها في كتاب الأذكار ، ومختصر ذلك : أن الكلام وسيلة إلى المقاصد ؛ فكل مقصود محمود يمكن تحصيله بغير الكذب ؛ يحرم الكذب فيه ، وأن لم يمكن تحصيله إلا بالكذب جاز الكذب ، ثم إن كان تحصيل ذلك المقصود مباحا كان الكذب مباحا ، وإن كان واجبا كان الكذب واجبا ، فإذا اختفى مسلم من ظالم يريد قتله أو أخذ ماله ، أو أخفى ماله ، وسئل إنسان عنه وجب الكذب بإخفائه ؛ وكذا لو كان عنده وديعة وأراد ظالم أخذها وجب الكذب بإخفائها والأحوط في هذا كله أن يورى - ومعنى التورية : أن يقصد بعبارته مقصودا صحيحا هو صادق بالنسبة إليه ، وإن كان كاذبا في ظاهر اللفظ وبالنسبة إلى ما يفهمه المخاطب ، ولو ترك التورية وأطلق عبارة الكذب فليس بحرام في هذا الحال » . واستدل العلماء بجواز الكذب في هذا الحال بحديث أم كلثوم رضي الله عنها أنها سمعت رسول الله صلى الله عليه وسلم يقول : « ليس الكذاب الذي يصلح بين الناس فينمي خيرا أو يقول خيرا » متفق عليه . زاد مسلم في رواية : قالت أم كلثوم : « ولم أسمعه يرخص في شيء مما يقول الناس إلا في ثلاث : يعنى الحرب ، والاصلاح بين الناس ، وحديث الرجل امرأته ، وحديث المرأة زوجها » .", "« فصل في الواجب الثامن » قال رحمه الله :", "٨ - « أن تكون وفيا بالعهد ، والكلمة والوعد فلا تخلف مهما كانت الظروف » . « تطبيقات »", "١ - لا شيء يعطل الأوقات ويفقد الثقة ويعطل البناء مثل نقض العهد ، وعدم حفظ شرف الكلمة ، والاخلاف بالوعد على مستوى العمل ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0147.png"}, {"n": 148, "paras": ["الجماعي أو على مستوى العمل الدنيوي ، أو على مستوى العلاقات الشخصية ، أو على مستوى العالم ، ونحن جماعة حريصة على الوقت وعلى البناء وعلى الثقة ولذلك فالفرد فينا ينبغي أن يكون دقيق الكلمة وفيا بها إذا قالها .", "٢ - فكر كثيرا قبل أن تعاهد أو تقول أو تعد ، فإذا فعلت فابذل كل جهد مستطاع لإنفاذ كلامك فقد وصف الله إسماعيل بقوله : « إنه كان صادق الوعد » ( مريم : ٥٤ ) . وقال عليه وآله الصلاة والسلام : « لا تمار أخاك ولا تمازحه ولا تعده موعدا فتخلفه » أخرجه الترمذي عن ابن عباس وقد رمز السيوطي إلى ضعفه .", "٣ - احرص على حضور لقاءاتك مع إخوانك في الموعد دون تأخر ، ولا تكن سببا في ضياع الوقت والإنتاج للدعوة بسبب تأخرك .", "« فصل في الواجب التاسع » قال الأستاذ رحمه الله :", "٩ - « أن تكون شجاعا عظيم الاحتمال ، وأفضل الشجاعة الصراحة في الحق ، وكتمان السر والاعتراف بالخطأ ، والإنصاف من النفس وتملكها عند الغضب » . « تعليقات » الشجاعة خلق من الأخلاق التي أكدها الإسلام عند العرب وعند غيرهم وربى عليها الإنسان ، ومن مظاهر الشجاعة قوة الاحتمال « إنما أشكو بثي وحزني إلى الله » ( يوسف : ٨٦ ) ومن مظاهر الشجاعة الصراحة في الحق وخاصة داخل الجماعة ؛ فالمساكت عن الحق شيطان أخرس ، ومن مظاهر الشجاعة كتمان السر لأن كثيرين يجبنون أو يخجلون فيفشون الأسرار ، ومن مظاهر الشجاعة الاعتراف بالخطأ لأن ذلك يدل على قوة الشخصية ، وعلى عمق تقواها ، وعلى قوة صلتها بالله ، ومن مظاهر الشجاعة الإنصاف من النفس بأن تعترف بالظلم إذا وقع منك ، وأن تجعل الآخرين يقتصون منك ، ومن أعظم مظاهر الشجاعة ضبط النفس عند الغضب ، « ليس الشديد بالصرعة ؛ إنما الشديد الذي يملك نفسه عند الغضب » متفق عليه ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0148.png"}, {"n": 149, "paras": ["وهذا من الأخلاق التي ينبغي أن يدرب الإنسان نفسه عليها فالحلم بالتحلم . ولو نظرنا إلى عكس هذه الصفات وهي عدم الاحتمال والسكوت عن الحق وإفشاء السر والإصرار على الخطأ وعدم الاعتراف به وعدم الإنصاف من النفس وإنفاذ الغضب لوجدنا أن هذه الصفات كفيلة بتدمير أي عمل وإحلال الفرقة والتنازع والفشل وتفرقة الصف .", "« فصل في الواجب العاشر » قال رحمه الله :", "١٠ - « أن تكون وقورا تؤثر الجد دائما ، ولا يمنعك الوقار من المزاح الصادق والضحك في تبسم » . « تعليقات »", "١ - الأصل في حياة المسلم الجد ، وللمداعبة والمزاح في حياة المسلم دور ولكنهما كالملح بالنسبة للطعام ، ولو أنك عددت مداعبات رسول الله صلى الله عليه وسلم ومزاحه لوجدت ذلك قليلا في حياته عليه وآله الصلاة والسلام ، فأن تجد مسلما دأبه المزاح فذلك خروج عن الأصل .", "٢ - وكان رسول الله صلى الله عليه وسلم يمزح ولكن لا يقول إلا حقا ، وكان جل ضحكه التبسم ، وكان الغالب في شأنه أنه إذا ضحك عليه الصلاة والسلام لا ترى لهواته ، فالذين يضحكون حتى ينقلبوا على ظهورهم عليهم أن يراجعوا أنفسهم ، وقد يغلب الإنسان مرات ولكن لا ينبغي أن يكون الضحك قهقهة ديدنا له ، فأمتنا في آلام ، والمسلم طالب كمال ، والكمال لا يصلح معه ذلك ، وأوضاع أمتنا لا تسمح بذلك أيضا .", "« فصل في الواجب الحادي عشر » قال رحمه الله :", "١١ - « أن تكون شديد الحياء ، دقيق الشعور ، عظيم التأثر بالحسن والقبح : تسر للأول ، وتتألم للثاني ، وأن تكون متواضعا في غير ذلة ولا خنوع ولا ملق ، وأن تطلب أقل من مرتبتك لتصل إليها » ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0149.png"}, {"n": 150, "paras": ["« تعليقات »", "١ - قال عليه الصلاة والسلام : « والحياء شعبة من الايمان » متفق عليه ، وقال : « أن مما أدرك الناس من كلام النبوة الأولى : إذا لم تستح فاصنع ما شئت » ، أخرجه البخاري . وهذا يفيد على بعض أوجه الفهم : أن الانسان متى فقد الحياء فقد أصبح لا يحجزه شيء عن شيء ، وكان رسول الله صلى الله عليه وآله وسلم أشد حياء من العذراء في خدرها ولكنه الحياء الذي لا يمنع عن واجب ولا عن قول حق ، ولا عن نصح المسلم ، ولا عن دعوة إلى الله ؛ انه الحياء الذي يحجز عن محارم الله ، ويحجز عن المخلات بالمروءة ، ويحجز عما ينفر عنه الذوق العام الصالح .", "٢ - ومن مظاهر الحياء دقة الشعور ، وعظيم التأثر بالحسن والقبح ، فمن كان ذا حياء كان دقيق الشعور بما يجرح الآخرين ، دقيق الاحساس فيما يحسن وما يقبح ، يتأثر بأنفعل الحسن ويحبه ، وينزعج من الفعل القبيح ويكرهه .", "٣ - ومن آداب المسلم التواضع قال تعالى : « أذلة على المؤمنين » ( المائدة : ٥٤ ) وقال تعالى : « واخفض جناحك للمؤمنين » ( الحجر : ٨٨ ) ولكن التواضع المطلوب هو الذي لا يرافقه ذلة لأهل الدنيا ، ولا يرافقه خنوع واستسلام لأهل الباطل ، ولا يرافقه ملق على غير حق ، فذلك كله ممجوج ، ومن مظاهر التواضع ألا يطلب الأخ فوق مرتبته ، فمن عادة الناس أنه من طلب فوق رتبته أنزلوه إلى ما دونها ، ومن طلب مرتبته قد يعطونه اياها وقد لا يعطونه ، ومن تواضع دون مرتبته رفعه الناس اليها .", "« فصل في الواجب الثاني عشر » قال الأستاذ البنا رحمه الله :", "١٢ - « أن تكون عادلا صحيح الحكم في جميع الأحوال ، ولا ينسينك الغضب الحسنات ، ولا تغضى عين الرضا عن السيئات ، ولا تحملك الخصومة على نسيان الجميل ، وتقول الحق ، ولو كان على نفسك أو على أقرب الناس اليك وان كان مرا » ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0150.png"}, {"n": 151, "paras": ["(( تعليقات ))", "١ - قال تعالى : (( يا أيها الذين آمنوا كونوا قوامين بالقسط شهداء لله ولو على أنفسكم أو الوالدين والأقربين ، إن يكن غنيا أو فقيرا فالله أولى بهما ، فلا تتبعوا الهوى أن تعدلوا )) ( النساء : ١٣٥ ) .", "٢ - من الأخلاق الرديئة أن ينسى الانسان حسنات الآخرين إذا غضب وأن يغضى عن سيئاتهم إذا رضى ؛ تلك طبيعة النفس البشرية وعلى الانسان أن يعدلها : (( وعين الرضا عن كل عيب كليلة ... ولكن عين السخط تبدى المساويا ))", "٣ - في غمرة الخصومة قد ينسى الانسان الجميل ويتجنب الانصاف ويقول الباطل ولن يستطيع مخاصم أن يحافظ على التقوى إلا بصعوبة .", "٤ - من الأشياء التي ينبغي أن يمرن الانسان نفسه عليها الاعتراف بالخطأ وقول الحق ولو على نفسه وتلك مرارة يتجرع الانسان مذاقها ، وشأن الأنفس التقية المزكاة أن تفعل ذلك وتعتاده .", "(( فصل في الواجب الثالث عشر )) قال رحمه الله :", "١٣ - (( أن تكون عظيم النشاط ، مدربا على الخدمات العامة تشعر بالسعادة والسرور إذا استطعت أن تقدم لغيرك من الناس ، فتعود المريض ، وتساعد المحتاج ، وتحمل الضعيف ، وتواسى المنكوب ولو بالكلمة الطيبة، وتبادر دائما إلى الخيرات )) .", "(( تعليقات ))", "١ - الخدمة العامة أدب عظيم من آداب الاسلام (( من كان في حاجة أخيه كان الله في حاجته )) متفق عليه ؛ فالأخ المسلم عليه ألا يكل ولا يمل في الخدمة العامة وأن يعتاد أن يفعل ذلك بروح السعادة والسرور فذلك من تمام الخدمة .", "٢ - ومن مظاهر الخدمة : عيادة المريض ، ومساعدة المحتاج ، والقيام بحق الضعيف ، ومواساة المنكوب بالكلمة الطيبة إذا فات غيرها ، والمسارعة إلى كل خير ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0151.png"}, {"n": 152, "paras": ["٣ - وقد كان مما وقر في صدور الناس حتى في الجاهلية أن أصحاب الخدمات العامة يرعاهم الله ولذلك قالت خديجة لرسول الله صلى الله عليه وآله وسلم عندما قال لها : « لقد خشيت على نفسي » : « والله لا يخزيك الله أبدا ، إنك لتصل الرحم ، وتصدق الحديث ، وتحمل الكل(١) ، وتكسب المعدوم(٢) ، وتقرى(٣) الضيف ، وتعين على نوائب الحق »(٤) .", "« فصل في الواجب الرابع عشر »", "قال رحمه الله :", "١٤ - « أن تكون رحيم القلب ، كريما سمحا ، تعفو وتصفح ، وتلين وتحلم ، وتترفق بالانسان والحيوان ، جميل المعاملة ، حسن السلوك مع الناس جميعا ، محافظا على الآداب الاجتماعية ، فترحهم الصغير ، وتوقر الكبير ، وتفسح في المجالس ، ولا تتجسس ولا تغتب ولا تصخب وتستأذن في الدخول والانصراف .. الخ » .", "« تعليقات »", "١ - قال الله لرسوله صلى الله عليه وآله وسلم : « ولو كنت فظا غليظ القلب لانفضوا من حولك ، فاعف عنهم واستغفر لهم وشاورهم في الأمر ، فإذا عزمت فتوكل على الله » ( آل عمران : ١٥٩ ) . فقوله : « فاعف عنهم » يفيد أنهم يخطئون وقوله « واستغفر لهم » يفيد أنهم يذنبون ، فمع أنهم يذنبون ويخطئون فقد أمره الله عز وجل باللين معهم وبالعفو عنهم وبالاستغفار لهم وبمشاورتهم فهذا أدب المسلم .", "٢ - وقال الله عن رسوله : « لقد جاءكم رسول من أنفسكم عزيز عليه ما عنتم حريص عليكم بالمؤمنين رؤوف رحيم » ( التوبة : ١٢٨ ) : فالحرص على المؤمنين ، والرأفة فيهم ، والحرص على عدم عناتهم ، كل ذلك من أدب النبوة التي ينبغي أن نقتدي بها .", "٣ - قال عليه الصلاة والسلام : « إن الرفق لا يكون في شيء", "(١) الكل : رب الأسرة المحتاج .", "(٢) المعدوم : الفقير .", "(٣) تقرى : تطعم .", "(٤) نوائب : مصائب الدهر ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0152.png"}, {"n": 153, "paras": ["إلا زانه ، ولا ينزع من شيء إلا شانه » رواه مسلم ، وقال عليه السلام : « من يحرم الرفق يحرم الخير كله » رواه مسلم ، وقال عليه الصلاة والسلام : « إن الله رفيق يحب الرفق في الأمر كله » متفق عليه ، وقال عليه الصلاة والسلام : « إن الله رفيق يحب الرفق ، ويعطى على الرفق ما لا يعطى على العنف ، وما لا يعطى على سواه » رواه مسلم ، وقال عليه الصلاة والسلام لأشجع عبد القيس : « إن فيك خصلتين يحبهما الله ورسوله : الحلم والأناة » رواه مسلم . فالمسلم رفيق بالإنسان رفيق بالحيوان وفي الحديث : « إن شر الرعاء الحطمة » أخرجه الامام مسلم والامام أحمد .", "٤ قال عليه الصلاة والسلام : « ليس منا من لم يرحم صغيرنا ويوقر كبيرنا » أخرجه الترمذي ورمز السيوطي لصحته ، فنحن جماعة يرحم الكبير فيها الصغير ، ويوفر الصغير فيها الكبير ، ويجمع بعضها مع بعض الصراحة على الحق .", "٥ من آداب المسلم ما ذكره تعالى بقوله : « إذا قيل لكم تفسحوا في المجالس فافسحوا يفسح الله لكم ، وإذا قيل انشزوا فانشزوا »(١) (المجادلة : ١١) .", "٦ قال تعالى : « ولا تجسسوا ولا يغتب بعضكم بعضا » . ( الحجرات : ١٢ )", "٧ قال عليه الصلاة والسلام : « ليس المؤمن بالطعان ولا اللعان ولا الفاحش ولا البذيء » ، أخرجه الامام أحمد والبخاري في الأدب والحاكم وابن حبان ، ورمز السيوطي لصحته .", "٨ ومن آداب المسلم الاستئذان عند الدخول وعند الانصراف قال تعالى : « يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها » ( النور : ٢٧ ) . وقال عليه الصلاة والسلام : « الاستئذان ثلاث فان أذن لك وإلا فارجع » متفق عليه ، وقال عليه الصلاة والسلام : « إذا انتهى", "(١) التفسح في المجلس : التوسع فيه ، والمراد أن يوسع بعضنا لبعض ، ومعنى انشزوا : انهضوا ، والمراد به النهوض للتوسعة ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0153.png"}, {"n": 154, "paras": ["أحدكم إلى المجلس فليسلم فإذا أراد أن يقوم فليسلم ؛ فليست الأولى بأحق من الآخرة » رواه أبو داوود والترمذي وقال : حديث حسن .", "« فصل في الواجب الخامس عشر » قال رحمه الله :", "١٥ - « أن تجيد القراءة والكتابة ، وأن تكثر من المطالعة في رسائل الإخوان وجرائدهم ومجلاتهم ونحوها ، وأن تكون لنفسك مكتبة خاصة مهما كانت صغيرة ، وأن تتبحر في علمك وفنك أن كنت من أهل الاختصاص وأن تلم بالشئون الإسلامية العامة إلماما يمكنك من تصورها والحكم عليها حكما يتفق مع مقتضيات الفكرة » . « تطبيقات »", "١ - أن الصلة بكتب الإخوان وجرائدهم ومجلاتهم هي التي تبقى حيوية الصلة بين المسلم وبين دعوته ، وبينه وبين قضايا المسلمين في العالم ، كما تجعل بينه وبين إخوانه وحدة في الفكر ووحدة في المواقف ؛ فمطالعة مجلات الدعوة وصحفها وكتبها تبقى الأخ على حيوية وصلة فيما يستجد .", "٢ - المكتبة في البيت أداة الثقافة لصاحب البيت وأسرته فلابد أن تكون موجودة ولعل من أهم ما يحرص الأخ على اقتنائه الكتب التي سجلناها في كتاب « جند الله ثقافة وأخلاقا » وكتب رواد الفكر الإسلامي الحديث وأمهات المراجع .", "٣ - هناك من العلوم الإسلامية ما هو فرض عين وهناك ما هو فرض كفاية وكل علم يحتاجه المسلمون فهو من قبيل فروض الكفايات ، فالطب بفروعه والهندسة بفروعها والزراعات والصناعات ، وإذا كان صاحب أي اختصاص مرغوب يسقط عن الأمة فرض كفاية ، فان تبحر المختص في اختصاصه شيء ندب اليه الإسلام واقرأ هذا النص الفقهي : « واعلم أن تعلم العلم يكون فرض عين ، وفرض كفاية ، ومندوبا ؛ وهو التبحر في الفقه وعلم القلب ، وحراما ومكروها ومباحا » فأصل الفقه فرض عين في الحدود التي يحتاجها الانسان وأن يوجد"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0154.png"}, {"n": 155, "paras": ["الفقيه المختص فذلك فرض كفاية والتبحر في الفقه مندوب ، وكذلك التبحر في كل فرض من فروض الكفاية . من مثل هذا الكلام الفقهي ندرك معنى قول الأستاذ : « وأن تتبحر في علمك وفنك إن كنت من أصحاب الاختصاص » ان الاختصاص شرط أساسي لوجود التقدم المدني ، ووجود القمة فيه هو شرط الوصول لحضارة القمة التي نريدها لأمتنا ، « راجع بحث السياسة التعليمية والاعلامية في كتابنا : الاسلام » .", "٤ - ان كثيرا من الشعوب تقف من الحادث الواحد وقفة تلقائية واحدة بسبب من ثقافتها الموحدة وتربيتها الموحدة وقد فات مسلمي عصرنا مثل هذا المعنى بسبب من ضآلة ثقافتهم الاسلامية ، حتى أصبحت الحكومات وأجهزة الاعلام العالمية تتحكم في ايجاد الحس العام الذي تريده فتفرق مواقف المسلمين بسبب من ذلك ، وما ذلك الا لفقدان الحس الاسلامي العام الذي هو أثر الثقافة الاسلامية الراقية والمعاصرة ، والمعرفة الدقيقة لأحوال المسلمين والتيارات المواجهة .", "ولذلك قال الأستاذ : « وأن تلم بالشئون الاسلامية العامة الماماً يمكنك من تصورها ، والحكم عليها حكما يتفق مع مقتضيات الفكرة » ان علينا أن نصل الى حالة يقف فيها مسلمو العالم موقفا عفويا واحدا من كل قضية ، ولا يعنى هذا اهمال التوجيه ولا يعفى هذا الجماعة من أن تؤدى دورها ، ولكنا هنا نتكلم في حدود واجبات الأفراد .", "« فصل في الواجب السادس عشر » قال رحمه الله :", "١٦ - « أن تزاول عملا اقتصاديا مهما كنت غنيا وأن تقدم على العمل الحر مهما كان ضئيلا ، وأن تزج بنفسك فيه مهما كانت مواهبك العلمية » .", "« تعليقات »", "١ - أى عمل حر يجعلك على صلة بدوائر من الناس تمكنك من أن تستفيد تجربة ومن خلال هذه الصلة يمكن أن تكسب دعوتك ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0155.png"}, {"n": 156, "paras": ["٢ - عندما تشغل مالك تفيد وتستفيد ، تفيد أفراد وتفيد الأمة بمجموعها .", "٣ - قد لا يدوم الغنى فالعمل الاقتصادي يعطيك جرأة وخبرة تستطيع بهما أن تنطلق في أي لحظة لكسب لقمة العيش .", "٤ - لا ينبغي أن تحول مواهبك العلمية دون الاقدام على شيء من الأعمال الحرة لما في ذلك من اطلاق الطاقات ، ولكن عليك أن تلاحظ في هذا كله النية الصالحة والوفاء بالوعود والحذر الزائد في العلاقات الدنيوية ، فالمعاملة غير المنضبطة تفسد ما بين القلوب ، كما أن عليك أن تكون صريحا وعادلا في تعاملك مع أي انسان واجعل الفضل ديدنا لك .", "٥ - لا يصح أن تستغرقك الأعمال الدنيوية عن الأعمال الدعوية .", "٦ - ينبغي أن يكون من أهدافك في الأعمال الحرة أو الأعمال الاقتصادية أن تنقل الفعاليات السياسية والاقتصادية الى يد المسلمين .", "« فصل في الواجب السابع عشر » قال رحمه الله :", "١٧ - ألا تحرص على الوظيفة الحكومية ، وأن تعتبرها أضيق أبواب الرزق ولا ترفضها اذا أتيحت لك ، ولا تتخل عنها الا ان تعارضت تعارضا تاما مع واجبات الدعوة » . « تعليقات »", "١ - الوظيفة في الغالب أبشع أنواع العمل لأنها تقيد حرية الانسان في وقته ، ولأنها تجعله أسير رؤسائه ووظيفته ، ولأنها تحول بين الانسان وبين الحركة ، ولأنها تجعله في قبضة الحكم أيا كان الحكم ، ثم هي في الغالب ذات مردود قليل وضيق ، ولذلك فعلى المسلم ألا يحرص عليها .", "٢ - ولكن العمل في كثير من دوائر الدولة قد يكون من باب فرض الكفايات ، ثم ان الدولة الاسلامية تحتاج الى خبرات عملية كما أن الكثير من الخدمات اللازمة للجماعة والمسلمين لا تؤدى الا من خلال الموظفين ، وفوق هذا هناك وظائف تعتبر منطلقات للدعوة كالتدريس ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0156.png"}, {"n": 157, "paras": ["ثم ان موظفى الجماعة هم الرقباء على ما يجرى لصالح الأمة ، كل ذلك يجعلنا بحاجة الى أن نقبل الوظيفة .", "٣ - كثيرون من الأخوة يتطلعون الى ترك الوظيفة لصالح العمل الدعوى ، وقد لا يستغرق العمل الدعوى كل أوقاتهم ، وقد يكون الدافع الى ذلك الكسل ، أو العزوف عن العمل ، أو الرغبة الخفية غير المخلصة فى التفرغ ؛ لقد راعت وصية الأستاذ البنا هذه الأمور كلها فكانت فى منتهى الدقة .", "(( فصل فى الواجب الثامن عشر ))", "قال رحمه الله :", "١٨ - « أن تحرص كل الحرص على أداء مهنتك من حيث الإجادة ، والإتقان ، وعدم الغش ، وضبط المواعيد » . (( تعليقات ))", "١ - نقد أصبح من الأمور البديهية عند شعوبنا أن صناعة بلادنا سيئة وصناعة الأمم الأخرى أكثر اتقاناً .", "٢ - وأصبح من أمراضنا الشائعة الاهمال والغش والخلف فى المواعيد ، ونحن جماعة مسلمة والاسلام أمرنا بالاتقان : « ان الله يحب اذا عمل أحدكم عملا أن يتقنه » ، « من غشنا فليس منا » . ومن علامات المنافق : « اذا وعد أخلف » فكوننا مسلمين يقتضى منا أن نتقن وألا نغش وأن نفى بالوعد ، ثم نحن جماعة نريد أن تكسب ثقة المسلمين وأن تعيد ثقة المسلمين بأنفسهم وأن تكسب ثقة العالم بالاسلام وهذا لن يكون الا اذا كان اخواننا هم القدوة فى هذا وغيره ، بحيث تتغير ملامح المجتمع شيئا فشيئا .", "(( فصل فى الواجب التاسع عشر ))", "قال رحمه الله :", "١٩ - « أن تكون حسن التقاضى لحقك ، وأن تؤدى حقوق الناس كاملة غير منقوصة بدون طلب ولا تماطل أبدا » . (( تعليقات ))", "١ - قال عليه الصلاة والسلام : « اتقوا الظلم فان الظلم"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0157.png"}, {"n": 158, "paras": ["ظلمات يوم القيامة ، واتقوا الشح فان الشح أهلك من كان قبلكم حملهم على أن سفكوا دماءهم واستحلوا محارمهم » أخرجه مسلم ، وقال عليه السلام : « فان خيركم أحسنكم قضاء » متفق عليه ، وقال عليه السلام : « رحم الله رجلا سمحا إذا باع وإذا اشترى وإذا اقتضى » أخرجه البخاري .", "٢ - وقال عليه السلام : « مطل الغنى ظلم » متفق عليه .", "٣ - وقال تعالى : « ان الله يأمركم أن تؤدوا الأمانات إلى أهلها وإذا حكمتم بين الناس أن تحكموا بالعدل » ( النساء : ٥٨ ) .", "« فصل في الواجب العشرين » قال رحمه الله :", "٢٠ - أن تبتعد عن الميسر بكل أنواعه مهما كان المقصد من ورائها ، وتتجنب وسائل الكسب الحرام مهما كان وراءها من ربح عاجل » . « تعليقات »", "١ - قال تعالى : « انما الخمر والميسر والأنصاب والأزلام رجس من عمل الشيطان » ( المائدة : ٩٠ ) ومن مظاهر الميسر اليانصيب بأنواعه ، وأخبثه ذلك الذي يسمونه اليانصيب الخيري فهو أشبه شيء بميسر الجاهلية مهما كانت النية في الميسر فان الله حرمه تحريما قطعيا فاستحلاله كفر .", "٢ - قال تعالى : « يا أيها الناس كلوا مما في الأرض حلالا طيبا » ( البقرة : ١٦٨ ) وقد تساهل الناس في عصرنا بالحرام وذلك مصداق قوله عليه السلام : « ليأتين على الناس زمان لا يبالى المرء بما أخذ المال أمن حلال أم من حرام » أخرجه البخاري وأحمد ، فلنحذر من الحرام وشبهة الحرام ، قال عليه السلام : « لا يبلغ العبد أن يكون من المتقين حتى يدع ما لا بأس به حذرا مما به بأس » أخرجه الترمذي وقال : حديث حسن ، وقال عليه السلام : « اجتنبوا السبع الموبقات » ، قالوا : يا رسول الله وما هن ؟ قال : « الشرك بالله والسحر وقتل النفس", "( ١١ - في آفاق التعاليم )"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0158.png"}, {"n": 159, "paras": ["التي حرم الله الا بالحق وأكل الربا وأكل مال اليتيم والتولي يوم الزحف وقذف المحصنات المؤمنات الغافلات » متفق عليه .", "« فصل في الواجب الحادي والعشرين » قال رحمه الله :", "٢١ - « أن تبتعد عن الربا في جميع المعاملات وأن تتطهر منه تماما » . « تعليقات »", "١ - قال عليه الصلاة والسلام : « الربا ثلاثة وسبعون بابا أدناها مثل أن ينكح الرجل أمه في الاسلام » . وقال عليه الصلاة والسلام : « درهم ربا يأكله الرجل وهو يعلم أشد عند الله من ست وثلاثين زنية » أخرجه أحمد والطبراني ورمز السيوطي لصحته ، وقال ابن مسعود : « لعن رسول الله صلى الله عليه وسلم آكل الربا وموكله وشاهديه وكاتبه ، وقال : هم سواء » أخرجه الترمذي وغيره .", "٢ - وقد خالط الربا في عصرنا كل شيء وذلك مصداق قوله عليه الصلاة والسلام : « ليأتين على الناس زمان لا يبقى منهم أحد الا أكل الربا فان لم يأكله أصابه من غباره » أخرجه أبو داوود وابن ماجه والحاكم ورمز السيوطي لصحته . ولذلك فان على المسلم في عصرنا أن يكون دقيقا في معاملاته .", "« فصل في الواجب الثاني والعشرين » قال رحمه الله :", "٢٢ - « أن تخدم الثروة الاسلامية بتشجيع المصنوعات والمنشآت الاقتصادية الاسلامية ، وأن تحرص على القرش فلا يقع في يد غير اسلامية مهما كانت الأحوال ، ولا تلبس ، ولا تأكل الا من صنع وطنك الاسلامي » . « تعليقات »", "١ - ان من الأشياء التي أخذت طابع البدهيات في عصرنا ، أن هناك تلازما بين الغزو السياسي والاقتصادي والفكري والثقافي"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0159.png"}, {"n": 160, "paras": ["والعسكرى ، ولذلك فان علينا أن نقف ضد هذا كله ، ومن جملة ما ينبغى علينا فعله في مواجهة الغزو الاقتصادي مقاطعة المصنوعات والمنتوجات الكافرة ما استطعنا الى ذلك سبيلا ، وهذا يقتضى أن نقيم المنشآت الاسلامية ونشجع المصنوعات الاسلامية وأن نلبس وأن نأكل من صناعتنا الاسلامية .", "٢ - يجوز للمسلم أن يشترى المباح من كافر أو مسلم ، لكن تجربة عصرنا أثبتت أن تنمية ثروة الكافر ستنعكس آثارها على استعباد المسلم ولذلك فان المسلم أن لا يشترى الا من مسلم ما استطاع الى ذلك سبيلا ، والضرورات تقدر بقدرها .", "« فصل في الواجب الثالث والعشرين »", "قال رحمه الله :", "٢٣ - « أن تشترك في الدعوة بجزء من مالك ، وأن تؤدى الزكاة الواجبة فيه ، وأن تجعل فيه حقا معلوما للسائل والمحروم مهما كان دخلك ضئيلا » .", "« تعليقات »", "١ - قال تعالى : « الذى يؤتى ماله يتزكى » ( النيل : ١٨ ) فلا شيء يزكى النفس بعد التوحيد والصلاة مثل الانفاق ، ولذلك كان الانفاق علامة على صدق الايمان ، قال عليه الصلاة والسلام : « والصدقة برهان » ولذلك كان من فرائض الله اخراج الزكاة ، ومن فرائض الله الجهاد بالمال ان احتيج اليه .", "٢ - أن دفعك الزكاة الى الجماعة ودفعك اشتراكا شهريا لها من أهم ما ينبغى أن تحرص عليه لما يترتب على ذلك من آثار طيبة على العمل الاسلامى .", "٣ - في الحديث الصحيح الذي أخرجه النسائي والحاكم وابن حيان : « سبق درهم مائة ألف درهم ، رجل له درهمان أخذ أحدهما فتصدق به ، ورجل له مال كثير فأخذ من عرضه فتصدق به » فتصدق أيها الأخ ولو بالقليل اذا كنت لا تملك الكثير فالبركة في هذا القليل ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0160.png"}, {"n": 161, "paras": ["« فصل في الواجب الرابع والعشرين » قال رحمه الله :", "٢٤ - « أن تدخر للطوارىء جزءا من دخلك مهما قل وألا تتورط في الكماليات أبدا » .", "« شرح »", "١ - استقرت سنة رسول الله صلى الله عليه وآله وسلم على أنه كان يدخر لعياله قوت سنة .", "٢ - فطن كبار المربين الاسلاميين في العصور المتأخرة إلى أن الزهد عما في أيدى الناس يقتضى أن لا يحتاج الانسان إلى الناس ، وهذا يستدعى أن يكون الانسان غنيا عن أموالهم ، كما فطنوا إلى أن الناس لا يحترمون ذا الحاجة إليهم ، ولذا ينبغى أن يكون العالم غنيا عن الناس حتى يستفيدوا منه ، ومما يساعد على الاستغناء عن الناس الادخار وحسن الاقتصاد وتجنب الكماليات .", "٣ - شراء الكماليات ليس عمليا من ناحية ، ومن ناحية أخرى فإنه يقصى رأس المال عن الانتاج والفاعلية .", "٤ - نحن أمة محاربة وهذا يجعلنا في وضع متقلب ، فلحفظ ماء الوجه ولحفظ حق العيال فان على الانسان المسلم أن يوفر بعض المال .", "٥ - ونحن جماعة قد يضيق على أفرادها وقد يجد الانسان نفسه فجأة محاربا بقوت يومه ، فعليه أن يستعد لمثل ذلك .", "٦ - أن أى مال يتملكه الفرد في الجماعة هو بمثابة احتياطي ورصيد للجماعة .", "٧ - ان الانسان معرض للبلاء والأحداث وعليه أن يعد العدة لذلك .", "٨ - غلب على العقلية الاسلامية في العصور الأخيرة الافراط والتفريط في الأخذ بالأسباب والأخذ بالكماليات والرفاه . وفيما ذكره الأستاذ البنا في هذا الواجب علاج وتحقيق لكل ما ذكر ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0161.png"}, {"n": 162, "paras": ["(( فصل في الواجب الخامس والعشرين )) قال رحمه الله :", "٣٥ - « أن تعمل ما استطعت على إحياء العادات الإسلامية وأماتة العادات الأعجمية « غير الإسلامية » في كل مظاهر الحياة ، ومن ذلك : التحية ، واللغة ، والتاريخ ، والزي ، والأثاث ، ومواعيد العمل والراحة ، والطعام والشراب ، والقدوم والانصراف ، والحزن والسرور .. الخ ، وأن تتحرى السنة المطهرة في كل ذلك » .", "(( تعليقات ))", "١ - هناك طريقان ؛ طريق الكفر وطريق الايمان ، وقد أمرنا الله سبحانه بأن نسير في طريق الايمان وأن نترك طريق أهل الكفر : « اهدنا الصراط المستقيم . صراط الذين أنعمت عليهم غير المغضوب عليهم ولا الضالين » ( الفاتحة : ٦ ، ٧ ) والذين أنعم الله عليهم هم النبيون والصديقون والشهداء والصالحون ، فابحث عن هدى الأنبياء والصالحين والشهداء والصديقين واترك ما خالف ذلك في أي شيء ، ومن ذلك كل ما ذكره الأستاذ البنا هنا ، ولنتذكر أن عمر رضي الله عنه كان يحرص على احياء زي المسلمين واماتة زي الكافرين .", "٢ - بقدر التزام الأخ المسلم بسنة نبيه صلى الله عليه وسلم بقدر ما تميزت شخصيته المستقلة متحررا من العادات الغربية على المجتمع الاسلامي في مثل الأشياء التي ذكرها الأستاذ .", "(( فصل في الواجب السادس والعشرين )) قال رحمه الله :", "٣٦ - « أن تقاطع المحاكم الأهلية وكل قضاء غير اسلامي ، والأندية والصحف والجماعات والمدارس والهيئات التي تناهض فكرتك الاسلامية مقاطعة تامة » .", "(( تعليقات ))", "١ - قال تعالى : « ألم تر الى الذين يزعمون أنهم آمنوا بما أنزل اليك وما أنزل من قبلك يريدون أن يتحاكموا الى الطاغوت وقد أمروا أن يكفروا به » ( النساء : ٦٠ ) . هذه الآية أصل في أنه لا يجوز الاحتكام الا الى شريعة الله والى"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0162.png"}, {"n": 163, "paras": ["الحاكمين بها وهذا معنى قول الأستاذ : « أن تقاضع المحاكم الأهلية وكل قضاء غير إسلامي » وههنا استثناء وهو ما إذا وقع على إنسان ظلم بالمقياس الإسلامي فاضطر لرفع هذا الظلم أي يلجأ إلى مثل هذه المحاكم فلا بأس . وإذا كن له حق بالميزان الإسلامي ولا يستطيع الوصول إليه إلا من خلال هذه المحاكم فلا بأس والله أعلم .", "٢ - هناك أندية أسست لتخدم أعداء الإسلام ، لا يصح الانتساب إليها إلا بتكليف ، ولا يصح حضور اجتماعاتها ، وتكثير سوادها ، ويدخل في ذلك أندية الروتاري وأمثالها ، والنوادي التابعة لأحزاب أخرى ، ففي الحديث : « من كثر سواد قوم فهو منهم » .", "٣ - وهناك صحف تحارب الدعوة الإسلامية وصحف تنشر الفساد أو تدعو إلى الإفساد ، فهذه لا يجوز شراؤها ألا لمن كلف بمتابعة شئونها لمعرفة الشر الذي فيها ومكافحته .", "٤ - وهناك مدارس تبشيرية أو مدارس أهلية أسسها الأعداء ، فهذه تجب مقاطعتها إلا لضرورة ، وأما المدارس الحكومية التي تنشر الفساد والإفساد ، فاذا أمكن الاستغناء عنها بما لا يعطل السير العلمي للحركة كان ذلك ، وإلا فتدخل فيها مع تحصيل المناعة مع نية نشر الدعوة .", "٥ - أما الهيئات التي أسست على فكرة غير إسلامية أو لمناهضة الفكرة الإسلامية فتجب مقاطعتها أيضا مقاطعة تامة ، ألا لمكلف ، ويدخل في ذلك الأحزاب السياسية والمحافل الماسونية وأمثال ذلك .", "« فصل في الواجب السابع والعشرين » قال رحمه الله :", "٢٧ - « أن تديم مراقبة الله تبارك وتعالى ، وتذكر الآخرة ، وتستعد لها ، وتقطع مراحل السلوك إلى رضوان الله بهمة وعزيمة ، وتتقرب إليه سبحانه بنوافل العبادة ، ومن ذلك صلاة الليل ، وصيام ثلاثة أيام من كل شهر على الأقل ، والإكثار من الذكر القلبي واللساني ، وتحرى الدعاء المأثور على كل الأحوال » . « تعليقات »", "١ - قال عليه الصلاة والسلام عندما سأله جبريل بقوله :"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0163.png"}, {"n": 164, "paras": ["فأخبرني عن الإحسان ؟ قال : « أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك » وإذا كان المسلم في عبادة دائمة فان أدبه أن يكون في مراقبة دائمة .", "٢ - قال الحسن البصري : « الناس هلكى إلا العالمون والعالمون هلكى إلا العاملون والعاملون هلكى إلا المخلصون والمخلصون على خطر عظيم » . فالمخلصون على خطر ، فهل هناك مقام أرقى من مقام المخلص ؟ نعم مقام المخلص : « إلا عبادك منهم المخلصين » ( الحجر : ٤٠ ، سورة ص : ٨٣ ) وما هو الطريق لمقام المخلص ؟ قال تعالى : « إنا أخلصناهم بخالصة ذكرى الدار » ( سورة ص : ٤٦ ) أن تذكر الآخرة هو الطريق لمقام المخلص ولذلك أوصانا الإمام به .", "٣ - قال تعالى : « ولتنظر نفس ما قدمت لغد » ( الحشر : ١٨ ) وقال عليه الصلاة والسلام : « الكيس من دان نفسه وعمل لما بعد الموت والعاجز من اتبع نفسه هواها وتمنى على الله الأماني » أخرجه الحاكم والترمذي وابن ماجه وأحمد ، ورمز السيوطي لصحته ، ولذلك كان من أدب المسلم أن يستعد للآخرة .", "٤ - وللسلوك إلى الله مراحل ذكرناها في كتابنا « تربيتنا الروحية » : المرحلة الأولى : العلم مع التوبة ، والمرحلة الثانية : المجاهدة بأركانها ، والمرحلة الثالثة : تهذيب النفس ، والمرحلة الرابعة : الفناء في مرضاة الله . ه - قال عليه وآله الصلاة والسلام في الحديث القدسي : « من عادى لي وليا آذنته بالحرب ؛ وما تقرب إلي عبدي بشيء أحب إلي مما افترضته عليه ، وما يزال عبدي يتقرب إلي بالنوافل حتى أحبه ، فإذا أحببته كنت سمعه الذي يسمع به ، وبصره الذي يبصر به ، ويده التي يبطش بها ، ورجله التي يمشي بها ، وإن سألني أعطيته ولئن استعاذني لأعيذنه » أخرجه البخاري . فالمسلم مقبل على الفرائض والنوافل ، ومن أمهات النوافل : السنن الرواتب والإنفاق غير الواجب والحج غير المفروض والصوم المندوب والذكر بأنواعه وقراءة القرآن والصلاة على رسول الله صلى الله عليه وسلم ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0164.png"}, {"n": 165, "paras": ["٦ - من أنواع الذكر ، الذكر القلبي ، وقد ورد في ذلك حديث : « خير الذكر الخفى » أخرجه أحمد وابن ماجه والبيهقى ، ورمز السيوطى لصحته ، ومن ثم فالمسلم بين ذكرين ، ذكر اللسان وذكر القلب .", "٧ - ذكر الأستاذ البنا في رسالة « المأثورات » الدعوات المأثورات في المناسبات أو في أحوال النهار والليل ، فعلى الأخ أن يتتبع ذلك ، وأن يحافظ على أوراده القرآنية وأوراد الذكر ، ومن ذلك الوظيفة الكبرى أو الصغرى ، وورد الدعاء ، وكل ذلك مذكور في رسالة المأثورات .", "« فصل في الواجب الثامن والعشرين » قال رحمه الله :", "٢٨ - « أن تحسن الطهارة وأن تظل على وضوء غالب الأحيان » .", "« شرح وتعليقات »", "١ - قال رسول الله صلى الله عليه وآله وسلم : « الطهور شطر الايمان » . وقال : « ولا يحافظ على الوضوء إلا مؤمن » .", "٢ - في الاسلام طهارة ونظافة ، فقد يكون الانسان طاهرا وليس نظيفا كأن كان ظاهرا من الحدث الأكبر والأصغر وثيابه قذرة بسبب العمل ، وقد يكون نظيفا وليس طاهرا كأن يغسل نفسه وثيابه في الكحول وهو جنب ، والاسلام حضنا على الطهارة والنظافة ما استطعنا إلى ذلك سبيلا .", "٣ - في الاستنجاء والاستبراء : يكفى الماء وحده وتكفى الحجارة وحدها ، والأحسن أن تجمع بين الاثنين « أن تحسن الطهارة » ومن إحسان الطهارة التفقه في شئون الطهارة ، والعمل على ضوء ذلك ، ويدخل في التفقه معرفة قضايا الحيض والنفاس والنجاسات والمطهرات وكيفية الغسل وكيفية الوضوء .", "٤ - كثرت تعقيدات عصرنا ، وكثرت الصوارف فيه ، فعندما يكون الانسان على وضوء دائم فما أسهل عليه أن يصلى الصلوات في وقتها ، وإذا فاته الوضوء فكثيرا ما يجد نفسه في وضع حرج .", "٥ - يشكو الموجودون في بلاد الغرب من صعوبة أداء الصلوات"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0165.png"}, {"n": 166, "paras": ["في وقتها كما يشكو الطلبة في بعض الجامعات من ذلك ، ومع أن هناك من يتطوع بالافتاء في الجمع بين الصلاتين لأدنى حرج ، فاننا نرى أن الحل هو الوضوء الدائم ، والأرض كلها للمسلم مسجد وطهور فما أسهل أن يصلى ان كان متوضئا خلال دقائق معدودة .", "(( فصل في الواجب التاسع والعشرين ))", "قال رحمه الله :", "٢٩ - (( أن تحسن الصلاة وتواظب على أدائها في أوقاتها ، وتحرص على الجماعة والمسجد ما أمكن ذلك )) .", "(( تعليقات ))", "١ - سمى الله الصلاة ايمانا بقوله : (( وما كان الله ليضيع ايمانكم )) ( البقرة : ١٤٣ ) لأنها هي التي تجدد الايمان وتبقيه حيا ولأنها تذكر بأركان الايمان .", "٢ - الصلاة هي أعظم مظهر من مظاهر الشكر وما أكثر النعم ولذلك جاء قوله عليه الصلاة والسلام : (( .. أفلا أكون عبدا شكورا )) ، بمناسبة قيامه في الليل ، وجاء في الأحاديث أن صلاة الضحى تكفى في شكر نعمة الأعضاء المتجددة : أخرج الامام مسلم عن أبي ذر رضى الله عنه عن النبي صلى الله عليه عليه وسلم قال : (( يصبح على كل سلامى(١) من أحدكم صدقة ، فكل تسبيحة صدقة ، وكل تحميدة صدقة ، وكل تهليلة صدقة ، وكل تكبيرة صدقة ، وأمر بالمعروف ونهى عن المنكر صدقة ، ويجزىء من ذلك ركعتان يركعهما من الضحى )) .", "٣ - جعل الله عز وجل الصلوات المفروضة مؤقتة بأوقات فقال تعالى : (( ان الصلاة كانت على المؤمنين كتابا موقوتا )) ( النساء : ١٠٣ ) أى فريضة مؤقتة بوقت ولذلك فان على المسلم أن يحافظ على الصلاة في وقتها ، وهناك حالات أجاز فيها بعض الفقهاء الجمع بين صلاتين وتقديم بعض الصلوات أو تأخيرها ، كالسفر مثلا وهو موضوع يدرس .", "(١) السلامى : عظام الأصابع في اليد والقدم ، والجمع سلاميات ، والسلاميات : عروق ظلامر الكف والقدم ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0166.png"}, {"n": 167, "paras": ["في كتب الفقه وما دام الانسان على رأى امام مجتهد في قضايا الفروع الفقهية فلا حرج عليه .", "٤ - ولزوم الجمعة والجماعة والمسجد من أهم شعائر الاسلام ومن أوكد ما يحرص عليه المسلم . ( أ ) أخرج الامام مسلم عن رسول الله صلى الله عليه وآله وسلم قال : « لينتهين أقوام عن ودعهم الجمعات أو ليختمن الله على قلوبهم ثم ليكونن من الغافلين » . وأخرج الامام مسلم عن رسول الله صلى الله عليه وآله وسلم قوله : « من توضأ فأحسن الوضوء ثم أتى الجمعة فاستمع وأنصت غفر له ما بينه وبين الجمعة وزيادة ثلاثة أيام » . ( ب ) أخرج الامام مسلم عن رسول الله صلى الله عليه وآله وسلم قال : « ألا أدلكم على ما يمحو الله به الخطايا ويرفع به الدرجات ؟ قالوا : بلى يا رسول الله ؛ قال : اسباغ الوضوء وكثرة الخطا إلى المساجد وانتظار الصلاة بعد الصلاة ، فذلكم الرباط .. فذلكم الرباط » . وأخرج مسلم عن ابن مسعود قال : « ان رسول الله صلى الله عليه وآله وسلم علمنا سنن الهدى وأن من سنن الهدى الصلاة في المسجد الذي يؤذن فيه » . ( ج ) في الحديث المتفق عليه أن رسول الله صلى الله عليه وآله وسلم قال : « صلاة الجماعة أفضل من صلاة الفذ بسبع وعشرين درجة » .", "« فصل في الواجب الثلاثين »", "٣٠ - « أن تصوم رمضان وتحج البيت ان استطعت اليه سبيلا وتعمل على ذلك ان تكن مستطيعا الآن ذلك » . « تعليقات »", "١ - صيام رمضان فريضة ، وحج البيت فريضة ، والتذكير بهاتين الفريضتين هنا للتأكيد على ضرورتهما .", "٢ - هل يجب الحج للمستطيع على الفور أو على التراخي ؟ قولان للفقهاء ، والأستاذ البنا يطالبك بالعزيمة فتحج بمجرد أن قدرت ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0167.png"}, {"n": 168, "paras": ["٣ - عن أبي هريرة رضي الله عنه قال : « سئل النبي صلى الله عليه وآله وسلم : أي العمل أفضل ؟ قال : إيمان بالله ورسوله ، قيل : ثم ماذا ؟ قال : الجهاد في سبيل الله ، قيل : ثم ماذا ؟ قال : حج مبرور » متفق عليه ، قال النووي : المبرور هو الذي لا يرتكب صاحبه فيه معصية .", "« فصل في الواجب الحادي والثلاثين »", "قال رحمه الله :", "٣١ - « أن تستصحب دائما نية الجهاد وحب الشهادة ، وأن تستعد لذلك ما وسعك الاستعداد » .", "« تعليقات »", "١ - حب الجهاد فريضة قال تعالى : « قل إن كان آباؤكم وأبناؤكم وإخوانكم وأزواجكم وعشيرتكم وأموال اقترفتموها وتجارة تخشون كسادها ومساكن ترضونها أحب إليكم من الله ورسوله وجهاد في سبيله فتربصوا حتى يأتي الله بأمره ، والله لا يهدي القوم الفاسقين » ( التوبة : ٢٤ ) لقد قرن الله حب الجهاد بحبه وحب رسوله صلى الله عليه وآله وسلم وهدد من لم يتحقق بذلك ، فدل ذلك على فرضية حب الجهاد .", "٢ - ونية الجهاد فريضة بدليل قوله عليه وآله الصلاة والسلام : « من لم يغز ولم يحدث نفسه بالغزو مات على شعبة من النفاق » .", "٣ - وهاتان الفريضتان تستتبعان حب الشهادة في سبيل الله ، ومن عرف مقام الشهيد ثم لم يحب الشهادة فايمانه ضعيف وعليه أن يسأل الله أن يحبب اليه الشهادة .", "٤ - ومن أحب الجهاد ونواه ، وعزم على نيل الاستشهاد ، فعليه أن يستعد لذلك بالتجافي عن الدنيا ، وبترك المعاصي ، وبالوصول الى مقام ولاية الله ، فأولياء الله وحدهم هم الجاهزون للموت في كل لحظة ، قال تعالى مؤنبا اليهود : « قل يا أيها الذين هادوا ان زعمتم أنكم أولياء لله من دون الناس فتمنوا الموت ان كنتم صادقين . ولا يتمنونه أبدا بما قدمت أيديهم » ( الجمعة : ٦ ، ٧ ) ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0168.png"}, {"n": 169, "paras": ["ه - أخرج الإمام مسلم ، أن النبي صلى الله عليه وآله وسلم قال : « من سأل الله تعالى الشهادة بصدق بلغه الله منازل الشهداء وإن مات على فراشه » .", "٦ - وهذا كله يقتضي تدريبا ، فالتدريب فريضة عينية ويقتضي إعدادا فذلك علامة الصدق « ولو أرادوا الخروج لأعدوا له عدة » ( التوبة : ٤٦ )", "« فصل في الواجب الثاني والثلاثين » قال رحمه الله :", "٣٢ - « أن تجدد التوبة والاستغفار دائما وأن تتحرز من صغائر الآثام فضلا عن كبائرها ، وأن تجعل لنفسك ساعة قبل النوم تحاسبها فيها على ما عملت من خير أو شر ، وأن تحرص على الوقت فهو الحياة فلا تصرف جزءا منه في غير فائدة وأن تتورع عن الشبهات حتى لا تقع في الحرام » .", "« تعليقات »", "١ - قال عليه الصلاة والسلام : « انه ليغان على قلبي وإني لأستغفر الله في اليوم مائة مرة » رواه مسلم ، وأخرج أبو داوود بسند حسن صحيح عن ابن عمر قال : « كنا نعد لرسول الله صلى الله عليه وآله وسلم في المجلس الواحد مائة مرة : « رب أغفر لي وتب علي إنك أنت التواب الرحيم » وقال عليه الصلاة والسلام : « من لزم الاستغفار جعل الله له من كل ضيق مخرجاً ومن كل هم فرجاً ورزقه من حيث لا يحتسب » رواه أبو داوود .", "٢ - قال عليه الصلاة والسلام : « إن الشيطان قد أيس أن يعبد في بلدكم هذا ولكن ستكون له طاعة فيما تحتقرون من أعمالكم وسيرضى به » أخرجه الترمذي ، وأخرج البخاري عن أنس قال : « إنكم لتعملون أعمالا هي أدق في أعينكم من الشعر كنا نعدها على عهد رسول الله صلى الله عليه وسلم من الموبقات » (١) أخرجه البخاري .", "٣ - قال عمر بن الخطاب : « حاسبوا أنفسكم قبل أن تحاسبوا ، وزنوا أعمالكم قبل أن توزن عليكم » .", "(١) الموبقات : المهلكات ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0169.png"}, {"n": 170, "paras": ["٤ - قال عليه الصلاة والسلام : « لا تزول قدما عبد حتى يسأل عن عمره فيم أفناه ، وعن علمه فيم فعل فيه ، وعن ماله من أين اكتسبه وفيم أنفقه ، وعن جسمه فيم أبلاه » رواه الترمذي ، وقال : حديث حسن صحيح .", "٥ - قال عليه الصلاة والسلام : « ان الحلال بين والحرام بين ، وبينهما أمور مشتبهات لا يعلمهن كثير من الناس فمن اتقى الشبهات استبرأ لدينه وعرضه ، ومن وقع في الشبهات وقع في الحرام كالراعي يرعى حول الحمى ، يوشك أن يرتع فيه ، ألا وان لكل ملك حمى ألا وان حمى الله محارمه ألا وان في الجسد مضغة أذا صلحت صلح الجسد كله واذا فسدت فسد الجسد كله ألا وهي القلب » متفق عليه . وكان أصحاب رسول الله صلى الله عليه وآله وسلم يتركون تسعة أعشار الحلال مخافة الوقوع في الحرام .", "« فصل في الواجب الثالث والثلاثين »", "قال رحمه الله :", "٣٣ - « أن تجاهد نفسك جهادا عنيفا حتى يسلس قيادها لك ، وأن تغض طرفك وتضبط عاطفتك وتقاوم نوازع الغريزة في نفسك وتسمو بها دائما الى الحلال الطيب وتحول بينها وبين الحرام من ذلك أيا كان » .", "« تعليقات »", "١ - قال عليه الصلاة والسلام : « والمجاهد من جاهد نفسه في ذات الله » ولقد أوردنا في كتابنا « تربيتنا الروحية » بابا حول مجاهدة النفس ومحلها في السلوك الى الله عز وجل .", "٢ - قال الله عز وجل : « قل للمؤمنين يغضوا من أبصارهم ويحفظوا فروجهم » ( النور : ٣٠ ) . « وقل للمؤمنات يغضضن من أبصارهن ويحفظن فروجهن » ( النور : ٣١ ) فالمسلم مأمور بغض البصر وحفظ الفرج وكذلك المسلمة وعليهما أن يبذلا جهدا لغض البصر وحفظ الفرج ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0170.png"}, {"n": 171, "paras": ["٣ اذا رأى الانسان أن نفسه تنازعه نحو الشهوة فعليه أن يتزوج ؛ فاذا عجز عن ذلك فعليه أن يستعف بالصيام وبالصحبة الصالحة .", "« فصل في الواجب الرابع والثلاثين » قال رحمه الله :", "٣٤ « أن تتجنب الخمر والمسكر ، والمفتر .. وكل ما هو من هذا القبيل كل الاجتناب » . « تعليق » قال تعالى : « انما الخمر والميسر والأنصاب والأزلام رجس من عمل الشيطان » ( المائدة : ٩٠ ) . وفي الحديث : « نهى رسول الله صلى الله عليه وسلم عن كل مسكر ومفتر » . فدخل في ذلك المخدرات كلها ولذلك قال الأستاذ : « وكل ما هو من هذا القبيل » .", "« فصل في الواجب الخامس والثلاثين » قال رحمه الله :", "٣٥ « أن تبتعد عن أقران السوء ، وأصدقاء الفساد ، وأماكن المعصية والاثم » . « تعليقات »", "١ فقد نص الفقهاء على كراهة مخالطة أهل الفساد لما يترتب على ذلك من ظن سوء بالمسلم ولما يترتب على ذلك من انتقال الأخلاق المرذولة ثم لما في ذلك من جعل الظن السيء محل ظن حسن عند من يعرف الأخ اذا كان يثق فيه عندما يراه مع الانسان السيء .", "٢ وقد نص الفقهاء على حرمة أنظر الى المحرمات فأن يجلس الأخ في مكان فيه معصية واثم فذلك يعرضه للوقوع في الحرام ولذلك فان أدبه ألا يجلس في مكان فيه معصية أو اثم ؛ وتستثنى من ذلك حالات الضرورة وحالات النزول في الفنادق ؛ فأنه في هذه الحالات تقدر ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0171.png"}, {"n": 172, "paras": ["الضرورة بقدرها ، فالعبرة في الفنادق ، في بعض البلدان ألا يكون في غرفة الأخ منكر .", "(( فصل في الواجب السادس والثلاثين ))", "قال رحمه الله :", "٣٦ - « أن تحارب أماكن اللهو فضلا عن أن تقربها ، وأن تبتعد عن مظاهر الترف والرخاوة جميعا » .", "(( تطبيقات ))", "١ - من أماكن اللهو : المراقص والسينما والمسارح ، والأصل أن نحارب مثل هذه فضلا عن أن نقربها ، وعلينا أن نبتعد عن الشر كله وإن كان بعضه أهون من بعض فإذا كانت بعض الأفلام أو بعض المسرحيات أهون شرا فذلك لا يعفينا من الابتعاد .", "٢ - ما ابتليت أمة بالترف الا انهارت ، ولذلك فان أدب المسلم أن يترك كل ما يجعله يستغرق بالدنيا ، والترف هو أكثر المحببات في الدنيا .", "٣ - ان التعامل الرخو يفسد العلاقات ويؤدي إلى المفاسد ، ولذلك فان على أخواتنا واخواننا أن يتجنبوا كل مظهر من مظاهر الرخاوة ، من العناق الى تشبيك الأيدى الى وضع اليد على العنق الى غير ذلك من مظاهر لا تدل على صلابة التعامل الاسلامي ، وهذا كله شيء ، والرحمة واللين مع الاخوان والحياء أشياء أخرى .", "(( فصل في الواجب السابع والثلاثين ))", "قال رحمه الله :", "٣٧ - « أن تعرف أعضاء كتيبتك فردا فردا معرفة تامة ، وتعرفهم نفسك معرفة تامة وتؤدى حقوق أخوتهم كاملة من الحب والتقدير ، والمساعدة والايثار وأن تحضر اجتماعاتهم فلا تتخلف عنها الا بعذر قاهر ، وتؤثرهم بمعاملتك دائما » .", "(( شرح وتطبيق ))", "١ - قال الحسن البصري : « مجالستك الرجل دون أن تعرف اسمه أو اسم أبيه مجالسة النوكى » أى الحمقى ، هذا هو أصل الأدب"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0172.png"}, {"n": 173, "paras": ["الاسلامي ، غير أن هناك أوضاعا استثنائية ، كظروف الحرب أو ظروف العمل السري فهذه لها آدابها وقوانينها .", "٢ - قال عليه الصلاة والسلام : « حق المسلم على المسلم ست : إذا لقيته فسلم عليه ، وإذا دعاك فأجبه ، وإذا استنصحك فانصح له ، وإذا عطس فحمد الله فشمته ، وإذا مرض فعده ، وإذا مات فاتبعه » ومن استقراء واسع للنصوص خرج الأستاذ البنا بأن من حقوق الأخوة الحب والتقدير ، والمساعدة والايثار ، وحضور الاجتماعات والتقديم للاخوان ، والنصوص التي استند اليها الأستاذ البنا في هذا الاستقراء كثيرة : « أوثق عرى الايمان الحب والبغض » . « بحسب امرىء من الشر أن يحقر أخاه المسلم » . « ومن كان في حاجة أخيه كان الله في حاجته » . « ويؤثرون على أنفسهم ولو كان بهم خصاصة » ( الحشر : ٩ ) . « عن يمين الرحمن تعالى - وكلتا يديه يمين - رجال ليسوا أنبياء ولا شهداء ، يغشى بياض وجوههم نظر الناظرين ، يغبطهم النبيون والشهداء بمقعدهم وقربهم من الله تعالى ، هم جماع من نوازع القبائل ، يجتمعون على ذكر الله فينتقون أطايب الكلام كما ينتقى آكل التمر أطايبه » أخرجه الطبراني ورمز السيوطي لحسنه ، وقال تعالى : « واخفض جناحك للمؤمنين » ( الحجر : ٨٨ ) .", "« فصل في الواجب الثامن والثلاثين » قال رحمه الله :", "٣٨ - « أن تتخلى عن صلتك بأي هيئة أو جماعة لا يكون الاتصال بها في مصلحة فكرتك وبخاصة إذا أمرت بذلك » . « تعليقات وشرح »", "١ - حيثما وجدت فائدة دينية فخذها فالحكمة ضالة المؤمن ، وحيثما وجدت خيرا فحاول أن تكون شريكا ، ولكن عليك أن تكون كالنحلة تعرف كيف ترجع الى خليتها .", "٢ - هناك علماء وربانيون لهم اجتهادات تختلف عن اجتهاداتنا فاذا وثقت أن اجتهاداتنا حق فاستفد منهم بما لا يؤثر على اجتهادك ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0173.png"}, {"n": 174, "paras": ["٣ - وهناك اتجاهات إسلامية تريد المشاركة معها على خير جزىء أن تحول بينك وبين الصف الذي تحقق بوجودك فيه فرائض فلا تقطع الصلة بهذه الاتجاهات ولكن ينبغي أن يكون ولاؤك وطاعتك للجماعة وعليك أن تؤلف قلوب هؤلاء على الجماعة ما داموا إسلاميين .", "٤ - هناك هيئات وجماعات وجودك فيها وجلوسك مع أهلها وتعاونك معهم اثم فهؤلاء اياك واياهم « فلا تقعد بعد الذكرى مع القوم الظالمين » (الأنعام : ٦٨) .", "٥ - قد تكون قبل انتسابك للجماعة مع أمثال هؤلاء ، فعليك أن تترك الا اذا أمرتك الجماعة بذلك لمصلحة إسلامية كما أمر رسول الله صلى الله عليه وسلم نعيم بن مسعود أن يؤدى دورا في موقعة الأحزاب .", "« فصل في الواجب التاسع والثلاثين » قال رحمه الله :", "٣٩ - « أن تعمل على نشر دعوتك في كل مكان ، وأن تحيط القيادة علما بكل ظروفك ، ولا تقدم على عمل يؤثر فيها تأثيرا جوهريا الا باذن » . « شرح وتعليقات »", "١ - تستطيع أن تدعو الى الله في كل الظروف وفي كل الأحوال وفي كل البيئات .", "٢ - لا تحتقر كلمة من الخير تستطيع أن تقولها فرب كلمة بسيطة أوصلت الى خير كبير .", "٣ - لابد أن يترك التركيز آثاره في القلوب التي لم تمت فطرتها ، ذكر الطفل والطفلة والفتى والفتاة والشيخ والشيخة ولو بأدنى معنى من المعاني فلن يضيع باذن الله .", "٤ - عندما تعرف قيادتك كل ظروفك تستطيع أن تستفيد من هذه الظروف ولا تكلفك أكثر من طاقتك ولا بما يتعارض مع ظروفك أو تهيىء لك ظروفا أفضل .", "٥ - كل ما يفترض عليك الاسلام عمله كفرد لا تحتاج فيه الى رأى أحد ، وكل عمل يفترض عليك الاسلام عمله كفرد من جماعة المسلمين ويمكن أن يؤثر على الجماعة نفسها فان عليك أن تستشير به ، ولقد نص الغزالي على الأمر بالمعروف والناهي عن المنكر اذا ترتب (١٢ - في آفاق التعاليم)"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0174.png"}, {"n": 175, "paras": ["على أمره الضرر بآخرين فعليه أن يستشيرهم وذلك في حالة كون هذا الشخص لا يتعين عليه شخصيا أن يفعل ، والاستشارة في كل الأحوال ضيبة ، والأستاذ كان دقيقا عندما قال : « ولا تقدم على عمل يؤثر فيها تأثيرا جوهريا إلا بإذن » .", "« فصل في الواجب الأربعين »", "قال رحمه الله :", "٤٠ - « أن تكون دائم الاتصال الروحي والعملي بها « أي بالجماعة » وأن تعتبر نفسك جنديا في الثكنة تنتظر الأمر » .", "« تعليقات »", "١ - متى انقطعت الصلة الروحية والعملية للأخ في الجماعة انقطع عنها شيئا فشيئا حتى يؤول أمره إلى الانفصال ، وفي ذلك موت لحيويته وتخل عن فرائض كلفه الله عز وجل بها ، كما أن في ذلك خسارة للصف الذي ينبغي أن يكون في تمام دائم ، فلابد من الاتصال العملي والروحي في الجماعة ، والاتصال العملي يتمثل بالمداومة على حضور الاجتماعات والاحتفالات ، ومتابعة قراءة النشرات والبيانات والاتصال الروحي يكون بالمراسلة ومشاعر الولاء والصفاء نحو الصف والجماعة والقيادة .", "٢ - أن على الأخ أن يكون دائم الجاهزية لتنفيذ الأمر ، بل أكثر من ذلك أن يبحث بشكل دائم عن احتياجات الجماعة واحتياجات العمل ويتطوع بالتذكير والمتابعة والخدمة .", "« فصل : تلخيص وتوجيه أخير »", "قال رحمه الله في خاتمة رسالة التعاليم : أيها الأخ الصادق : هذا مجمل لدعوتك وبيان موجز لفكرتك وتستطيع أن تجمع هذه المبادىء في خمس كلمات : الله غايتنا ، والرسول قدوتنا ، والقرآن شرعتنا ، والجهاد سبيلنا ، والشهادة أمنيتنا ، وأن تجمع مظاهرها في خمس كلمات أخرى : البساطة ، والتلاوة ، والصلاة ، والجندية ، والخلق ، فخذ نفسك"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0175.png"}, {"n": 176, "paras": ["بشدة بهذه التعاليم ، وإلا ففى صفوف القاعدين متسع للكسالى والعابثين . واعتقد أنك ان عملت بها وجعلتها أمل حياتك وغاية غايتك كان جزاؤك العزة فى الدنيا والخير والرضوان فى الآخرة وأنت منا ونحن منك ، وان انصرفت عنها وقعدت عن العمل لها فلا صلة بيننا وبينك ، وان تصدرت فينا المجالس وحملت أفخم الألقاب وظهرت بيننا بأكبر المظاهر وسيحاسبك الله على قعودك أشد الحساب ، فاختر لنفسك ونسأل الله لنا ولك الهداية والتوفيق .", "« يا أيها الذين آمنوا هل أدلكم على تجارة تنجيكم من عذاب أليم :", "١ - تؤمنون بالله ورسوله .", "٢ - وتجاهدون فى سبيل الله بأموالكم وأنفسكم ، ذلكم خير لكم ان كنتم تعلمون .", "٣ - يغفر لكم ذنوبكم ويدخلكم جنات تجرى من تحتها الأنهار ، ومساكن طيبة فى جنات عدن ، ذلك الفوز العظيم .", "٤ - وأخرى تحبونها ، نصر من الله وفتح قريب » وبشر المؤمنين . يا أيها الذين آمنوا كونوا أنصار الله كما قال عيسى ابن مريم للحواريين من أنصارى الى الله ، قال الحواريون نحن أنصار الله ، فآمنت طائفة من بنى اسرائيل وكفرت طائفة ، فأيدنا الذين آمنوا على عدوهم فأصبحوا ظاهرين » ( الصف : ١٠ - ١٤ ) . والسلام عليكم ورحمة الله وبركاته .", "(( تعليقات )) حاول الأستاذ البنا فى هذه الخاتمة أن يلخص كل مقومات الشخصية وواجباتها بأنها تحقق بشعارات خمس والتزام بكلمات خمس وأن ذلك كله مرجعه الى آيات الله فى كتاب الله ، وبين أن ما سوى ذلك فى عصرنا فانه قعود أو نوع قعود ، فهل استطعنا بعد ذلك يا أخى أن نزيدك شيئا عما تستطيع أن تفهمه مباشرة من قراءة رسالة التعاليم أو هل ساعدناك على أن تفهم هذه الرسالة حق الفهم ؟ نرجو ذلك وعندئذ يكون عنوان هذا الكتاب فى محله ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0176.png"}, {"n": 177, "paras": ["الباب الثامن", "فصول متممة", "ان رسالة التعاليم لها محلها بالنسبة لمناهج الاخوان المسلمين ولها محلها بالنسبة لموضوع العضوية في دعوة الاخوان المسلمين ، ولكى لا يفهم فاهم من اخوتنا أن رسالة التعاليم هي كل شيء في المناهج أو أنها كل شيء في موضوع العضوية فقد كتبنا هذا الباب وذكرنا فيه عدة فصول :", "الفصل الأول : وفيه ارشادات الى قواعد لابد من مراعاتها في أى منهاج ثقافى تربوى تكوينى داخل الاخوان المسلمين . الفصل الثاني : في مراحل العضوية وبعض الأساسيات فيها . الفصل الثالث : في ذكر بعض الموازين والتوضيحات والأساليب . وانما ذكرنا هذه الفصول هنا ليتم التعرف على ملامح الشخصية الاسلامية التي يريدها الاخوان المسلمون وبعض وسائلهم في ذلك ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0177.png"}, {"n": 178, "paras": ["الفصل الأول", "إرشادات إلى بعض القواعد التي تناسب طبيعة دعوتنا في المناهج الثقافية والتعليمية والتربوية", "(( القاعدة الأولى )) أول ما يجب أن نلاحظه في مناهجنا أن نكون منسجمين مع طبيعة دعوتنا وحركتنا ، فنحن حركة إسلامية تريد أن تجدد الاسلام في عصر ذي خصائص معينة ، كما أننا حركة تريد أن تحقق أهدافا على مستوى محلى ومستوى عالمى ، فالاسلامية تقتضى منا أن نستوعب كل أصول الثقافة الاسلامية وفروعها ، والمعاصرة تقتضى منا أن نستوعب ثقافة العصر وطبيعته وخصائصه ، لأن الفتوى تقدر زمانا ومكانا وشخصا . والأهداف المحلية والعالمية تقتضى منا ثقافة تؤهلنا لتحقيق هذه الأهداف ، فاذا كان جزء من أهدافنا اقامة الحكم الاسلامى فتأهيل اخواننا ليكونوا رجال دولة هو جزء من المناهج الثقافية التي ينبغى أن نعتمدها ، فالاسلامية المعاصرة والتأهيل المكافىء لتحقيق الأهداف أركان أساسية في قضية المنهاج ، اذ بدون ثقافة اسلامية متكاملة يستحيل أن تنضج الشخصية المسلمة ، وبدون ثقافة معاصرة تبقى الشخصية تعمل في الفراغ وبدون ثقافة تؤهلنا لتحقيق الأهداف نبقى دائما وبيننا وبين الأهداف هوة واسعة لا يمكن تجاوزها .", "(( القاعدة الثانية )) مما ينبغى أن يلاحظ في مناهجنا أن نعطى المسلم مناعة تحول بينه وبين أن يضل أو يزل ، أو تمر عليه فكرة غريبة عن الاسلام أو عن فكر الجماعة ، يقول الأستاذ البنا في معرض كلامه عن القوة النفسية التي يجب أن تتوافر في الأمة أو الجماعة التي تحاول تحقيق الآمال"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0178.png"}, {"n": 179, "paras": ["ومناصرة المبادىء : « ان تكوين لامم وتربية الشعوب وتحقيق الآمال ومناصرة المبادىء تحتاج من لأمة التي تحاول هذا أو من الفئة التي تدعو اليه على الأقل الى قوة نفسية عظيمة تتمثل في عدة أمور : ارادة قوية لا يتطرق اليها ضعف ، ووفاء ثابت لا يعدو عليه تلون ولا غدر ، وتضحية عزيزة لا يحول دونها طمع ولا بخل ، ومعرفة بالمبدأ وايمان به وتقدير له يعصم من الخطأ فيه والانحراف عنه ، والمساومة عليه والخديعة بغيره » هذه المعاني التي ذكرها الأستاذ قسم منها يجب أن يراعى في التعليم ، وقسم منها يحتاج الى أن يراعى في التربية ، وايجاد المناعة عند الأخ يبقى هدفا يجب أن يراعى في المناهج التربوية التعليمية ، ويدخل في قضية المناعة أن يكون الأخ على حالة لا يقبل فيها فكرا غريبا ، أو هجينا .", "(( القاعدة الثالثة ))", "مما ينبغي أن نلاحظه في مناهجنا أن نضع بيد المسلم الميزان الذي يزن به كل شيء حوله بميزان الاسلام فلا يبقى جانب من الجوانب الا وهو قادر أن يزنه بميزان الاسلام ليحكم عليه ، وان شئت قلت : أن نعطى المسلم المنظار الاسلامي الكامل الذي به يرى الأشياء على ما هي عليه ، قال تعالى واصفا كتابه : « هذا بصائر للناس » ( الجاثية : ٢٠ ) فالقرآن هو بصيرة الانسان التي ينبغي أن يكون بها ابصار قلبه للأشياء ، فما لم نصل بالمسلم الى أن يكون وزنه كل شيء دقيقا ، وابصاره للأشياء كلها على نور كتاب الله فاننا نكون مقصرين تعليما وتربية ومن ثم فلابد أن نلاحظ في مناهجنا هذا .", "(( القاعدة الرابعة ))", "مما ينبغي أن نلاحظه في مناهجنا أنصور انعام للعلوم في الاسلام ، فهناك العلوم المفروضة فرض عين ، وهناك التوسع في العلوم المفروضة فرض عين ، وذلك مندوب في حق عامة الناس ومفروض فرض كفاية في حق بعضهم ، وهناك العلوم المندوبة ، وهناك العلوم المباحة ، وهناك العلوم المحرمة والعلوم المكروهة ، والتوسع في فروض الكفايات مندوب بل قد يكون وجود رجل القمة في كل اختصاص من باب فروض الكفاية ،"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0179.png"}, {"n": 180, "paras": ["وفي مناهجنا وفي سيرنا العام والخاص لابد أن يلاحظ هذا كله فيلاحظ في حق كل مسلم على حدة ماذا يفترض عليه من علوم لأن هذا يختلف من إنسان إلى إنسان ، ثم يسعى من أجل التوسع في ذلك ، ويلاحظ كذلك أن يدفع كل أخ نحو إتقان اختصاص ما ينفع الأمة ، فينبغي أن يراعى في مجموع المناهج أن تخرج أخا متقنا لفروض العين متوسعا في علومها ، متمكنا منها ، وإذا أمكن أن تدفع المناهج التربوية والتعليمية والقواعد التنظيمية كل أخ نحو إتقان اختصاص يسقط به فرضا من فروض الكفاية عن هذه الأمة بحيث يكون رجل قمة فيه فإن ذلك نجاح لحركتنا وجماعتنا وهو سير لها في الطريق الصحيح .", "« القاعدة الخامسة »", "ذكر الأستاذ البنا في مذكراته أنواع العضوية في دعوة الإخوان المسلمين فذكر الانضمام العام والانضمام الأخوي والانضمام العملي والانضمام الجهادي ، فالانضمام العام يسمى به الأخ : أخا مساعدا ، والانضمام الأخوي يسمى به الأخ أخا منتسبا ، والانضمام العملي يسمى به الأخ أخا عاملا ، والانضمام الجهادي يسمى به الأخ أخا مجاهدا ، ثم يقول الأستاذ : « مكتب الإرشاد الحق في منح ألقاب شرفية منها : نقيب ونائب في كل من درجتي الانضمام العملي والانضمام الجهادي » ، وعلى هذا الأصل فدرجات العضوية عندنا : مساعد ، منتسب ، عامل ، مجاهد ، نقيب ، نائب ، وهذا يقتضي أن يكون لكل مرحلة أو لكل نوع من أنواع العضوية في حال اختصارها مناهجها الخاصة التي تحقق أهدافها ، وقد ذكر الأستاذ أننا أشياء رئيسية منها نستطيع أن نستنتج بعض ما يلزم لكل نوع من أنواع العضوية .", "« القاعدة السادسة »", "بعد أن ذكر الأستاذ البنا في رسائله مجموعة التصورات القاصرة عند الناس للإسلام قال : « هذه الصور المتعددة للإسلام الواحد في نفوس الناس جعلتهم يختلفون اختلافا بينا في دعوة الإخوان المسلمين ، وتصور فكرهم » ومن كلام الأستاذ البنا هذا ندرك أن فهم قضية الإخوان المسلمين ، مرتبط بفهم الإسلام بل قد يكون من المتعذر أن تفهم قضية الإخوان المسلمين دون فهم الإسلام ، ولذلك ألف إخواننا"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0180.png"}, {"n": 181, "paras": ["خاصة في المراحل الصعبة أن يجعلوا الدعوة إلى الاسلام سابقة على الدعوة إلى الاخوان، وأصبحوا يرون أن تفهيم الاسلام مقدم على تفهيم قضية الاخوان، وأن تعميم المناهج الاسلامية العلمية والعملية هي الطريق العملي في دعوة الاخوان؛ ولا شك أن نقل الانسان من اللااسلامية إلى الاسلامية غير الملتزمة، إلى الاسلامية الملتزمة كل ذلك عمل شاق وضروري وهذا يستلزم مناهج تكافىء وتحقق مثل هذه المعاني ومن ثم فلابد أن نراعي هذه المعاني كلها في المناهج، ونقطة البداية في ذلك كله الفهم الشامل المقنع للاسلام والتدليل على أنه حق، وأن وجود الله حق، وأن محمدا صلى الله عليه وسلم هو رسول الله حقا، وهذا كله يجب أن تكون الحجة فيه قائمة وواضحة.", "(( القاعدة السابعة ))", "ان هناك ناسا يبقون عند الفهم الكلى للاسلام وتغيب عنهم الجزئيات بل هم أحيانا ينطلقون في الجزئيات من الأهواء فمثلا هم يؤمنون بأن الاسلام فيه عدل ومساواة ولكنهم يفهمون العدل والمساواة على حسب أهوائهم لا على حسب شريعة الله، وهناك ناس يفهمون كلية ما ويطبقونها في كل الأحوال غير مراعين الحالات الاستثنائية أو حالات الضرورة أو حالات الرخصة والعزيمة وكل ذلك يؤدى إلى خلل إما في الاعتقاد أو في الالتزام وذلك يؤدى إلى خلل في السير ومن ثم فلابد أن يراعى في المناهج ألا تبقى ثغرة من الثغرات ليكون فهم المسلم للكليات والجزئيات كاملا، ويمر الانسان في حياته على مرحلتين: مرحلة ما قبل البلوغ وهي مرحلة لا يكون الانسان فيها مكلفا ولكن على أوليائه خاصة وعلى المسلمين عامة أن يؤهلوه لمرحلة ما بعد البلوغ وهي المرحلة التي يصبح بها الانسان مكلفا، ويجب أن تلاحظ المناهج هاتين المرحلتين، فمرحلة ما قبل البلوغ لها خصائصها ومناهجها، ومرحلة ما بعد البلوغ لها خصائصها ومناهجها.", "(( القاعدة الثامنة ))", "يجب أن نلاحظ في المناهج أن لا تبقى ثغرة يمكن أن يلج منها الكفر أو الضلال إلى عقل المسلم أو قلبه أو نفسه وهناك قضايا دقيقة"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0181.png"}, {"n": 182, "paras": ["إذا لم تلاحظ فان في ذلك الهلاك الدنيوى والأخروى أو أحدهما ، فاذا تركنا فجوة في ثقافة الانسان فانه من خلال هذه الفجوة يمكن أن تهب عليه رياح قاتلة ، فلو أننا مثلا لم نعرف المسلم على طرق التآمر على الاسلام ، فان المسلم يمكن أن يسير بما يهدم الاسلام ولا يشعر ، ولو أننا تركنا في ثقافته ثغرة في مواضيع اللغة العربية والتاريخ فانه يمكن أن يقبل أفكارا توصله الى الضلال ، ولو أننا تركنا ثغرة في شخصيته الاسلامية فان مرضا واحدا قد يدمره ويدمر الجماعة كلها ، كما لو أصيب بمرض الحسد أو الكبر أو حب الزعامة والرئاسة ومن ثم فلابد أن يلاحظ في المناهج ألا تبقى ثغرة ثقافية أو روحية أو تربوية عند المسلم .", "(( القاعدة التاسعة ))", "يترتب على الالتزام بالاسلام تحقق بمعان ينبغى أن يأخذ بها الانسان المسلم والجماعة الاسلامية ، هذه المعانى نسميها الخصائص وهذه الخصائص ينفرد بها المسلم وتتفرد بها الجماعة المسلمة ، فالبحث عن الخصائص والتحقق بها والقدرة على التحقيق بها شيء مهم في سير المسلم وسير الجماعة الاسلامية ، ومن ثم فلابد أن يلاحظ في المناهج ذلك ، وهناك خصائص معينة تقتضيها مرحلة معينة فعلينا أن نلاحظ ذلك ، فمرحلة ما قبل الاستخلاف تختلف عن مرحلة الاستخلاف ، ومرحلة الردة تختلف عن مرحلة التمكين ، وخصائص العاملين في كل مرحلة تختلف شيئا ما عن بعضها فبعض الخصائص في مرحلة يجب أن تكون أكمل منها في مرحلة أخرى وهكذا .", "(( القاعدة العاشرة ))", "في جماعة الاخوان المسلمين يوجد شعارات عليا ، كما يوجد ألف باء أخلاقى وسلوكى معين ، فالشعارات العليا هي : « الله غايتنا - والرسول قدوتنا - والقرآن دستورنا - والجهاد سبيلنا - والموت في سبيل الله أسمى أمانينا » ووصايا الأستاذ البنا العشر هي التي تمثل الألف باء الذوقى والأخلاقى للاخوان المسلمين ، وجعل الأستاذ من شعاراتنا : الحق والقوة والحرية ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0182.png"}, {"n": 183, "paras": ["فنحن جماعة تحمل الحق وتعشقه وتربى عليه وتلتزم به ، ونحن جماعة تؤمن بقدرة الفرد وقوة الأمة ، ونحن جماعة تؤمن بوجوب تحرير الانسان نفسه وغيره من عبودية العباد لعبودية الله الواحد القهار ، وهذا كله يجب أن يراعى في المناهج التعليمية والتربوية والا فان تناقضا كبيرا يقوم بين ما ندعو اليه وبين سلوكنا وأشخاصنا ، وبالتالى فاننا سنكون عاجزين عن تحقيق أمتنا بما ندعو اليه لأن فاقد الشيء لا يعطيه .", "(( القاعدة الحادية عشرة )) ان المسلم لا يكمل الا من اجتماع عدة أمور : مشاركته العلمية في الحلقات العلمية العامة اذ أن لها بركتها الخاصة ، ومشاركته في الحلقات العلمية الخاصة لأنها توصل الى ثقافة مركزة ، ولابد له من المطالعة الشخصية لأنه يستحيل أن يثقف الانسان ثقافة عالية معاصرة الا من خلال جهد شخصى طويل ومركز ، ولابد مع هذا كله من مذاكرة شخصية للانسان المسلم مع من هو أكمل منه علما أو حالا أو تجربة ويجب أن يلاحظ في المناهج العلمية والتربوية والسير التطبيقى لها وفيها ما يحقق ذلك كله بأن توجد مجموعة الظروف مع مجموعة ما يعتمد من دراسة لذلك .", "(( القاعدة الثانية عشرة )) لابد أن يكون للجماعة الاسلامية نظامها ، وأن يستند هذا النظام على أسس ، ولابد أن يكون للجماعة الاسلامية خطتها ومخططاتها ، ولابد أن يكون للجماعة الاسلامية نظريتها التربوية والتعليمية التي تتلاءم مع هذا كله ، كما يجب أن يكون للجماعة الاسلامية قواعدها التي تأخذ طابع البديهيات عند كل فرد من أفرادها ، وهذا كله يجب أن يراعى في مجموع ما يعتمد من مناهج تربوية وتعليمية .", "(( القاعدة الثالثة عشرة )) ان هناك صيغة مستمرة في هذه الأمة للحق لا يجوز أن تنقطع ولا أن تفقد في لحظة من اللحظات ، يقول عليه الصلاة والسلام :"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0183.png"}, {"n": 184, "paras": ["« لا تزال طائفة من أمتى ظاهرين على الحق لا يضرهم من خذلهم الى قيام الساعة » ، هذه الصيغة المستمرة والتي لا تنقطع تستند الى هدى وتحمل هدى وعلينا أن تكون جماعتنا استمرارا لصيغة أحق هذه . ومن ثم فيجب أن نلاحظ في كل ما نعتمده من مناهج ودراسات وطرائق تربية ألا نخرج عن هذه الصيغة ، والاخوان المسلمون هم أحرص الناس على أن يكونوا كما كان عليه رسول الله صلى الله عليه وسلم وأصحابه ، واستمرارية ما كان عليه الرسول صلى الله عليه وسلم وأصحابه هي في حملة الحق خلال العصور في مجموع مذاهبهم التوحيدية والفقهية والسلوكية ، وهذا أصل لا يجوز الفرار منه ولا الخروج عليه . ومن ثم يجب اعتماده في المناهج ، وقد رغب الأستاذ أن يلتقى المسلمون على صيغة من الحق تجمعهم جميعا ، ولكن بعودة الخاطىء الى الصف لا بتخلى الصف عن الحق أو عن بعض الحق ، ولذلك وحتى نعطى العالم الاسلامى كله مداه في التعامل معنا فاننا نعطى من يمكن أن يلتقى معنا على صيغة الحق التي طرحها الأستاذ البنا في بداية رسالة التعاليم فرصة أن يكونوا جماعة اخوان مسلمين على ضوء اجتهادات مذاهبهم بشرط قبولهم الأسس العشرين للفهم التي طرحها الأستاذ رحمه الله ، مع ملاحظة أن هذا كله فيمن يمكن أن نلتقى معه أما الفرق المنشقة عن جسم الأمة الاسلامية كالقاديانية والبهائية وأمثالهما فهؤلاء أعلن عليهم الأستاذ رحمه الله الحرب فلا لقاء بيننا وبينهم .", "« القاعدة الرابعة عشرة »", "نحن حركة تجديدية ومن مظاهر التجديد أن نحيى الاسلام كه وان نجدده علما وعملا وحالا على كل مستوى ، والأشياء التي وهت في هذه الأمة كثيرة والأشياء التي انعدمت كذلك كثيرة ، والرسول عليه وآله الصلاة والسلام يحدثنا أن أول عم يرفع من الأرض الخشوع ويحدثنا أن عرى الاسلام تنقض عروة عروة فأولها نقضا الحكم وآخرها الصلاة ، ونحن اذ نعمل لتجديد الاسلام لابد أن نلاحظ تجديد كل شيء وهي واحياء كل شيء ، يدخل في ذلك احياء الأمر بالمعروف والنهي عن المنكر كما يدخل في ذلك قضايا الجهاد ويدخل في ذلك تزكية"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0184.png"}, {"n": 185, "paras": ["النفس كما يدخل احياء الحكم الاسلامي باعلان الحاكمية لله ووجوب أن تكون كلمة الله هي العليا وبين ذلك ترابط قال تعالى : « قال الذين يظنون أنهم ملاقوا الله كم من فئة قليلة غلبت فئة كثيرة باذن الله ، والله مع الصابرين » ( البقرة : ٢٤٩ ) . فلا يستخف بكثرة العدد والعدد(١) الا من كان صابرا وكان في قلبه يقين . فاحياء هذه المعاني كلها مما ينبغي أن تراعيه مناهجنا .", "« القاعدة الخامسة عشرة » انه لا ينبغي أن يغيب عن بالنا دائما أننا نصارع على جبهتين فكريتين : جبهة الديمقراطية الرأسمالية ، وجبهة الاشتراكية والشيوعية ، وعلينا ألا ننسى احدى الجبهتين في غمرة الصراع المباشر مع احداهما فنهمل تثقيف أنفسنا وأمتنا وتعميق المناعة عندنا ضد الفكرين بآن واحد ، لأنه في أشد الحالات التي نرى فيها أحد الفكرين متغلبا في بلد ما يمكن أن يقفز هذا البلد الى الجانب الآخر ، وفي كتاب « حوار مع الشيوعيين في أقبية السجون » وكتاب « فلسفتنا » وكتاب « اقتصادنا » ما يكمل ثقافتنا في هذه الشئون على أنه قد يكون من المناسب أن توجد الكتب المبسطة التي يلاحظ فيها من الأخ ليقدم لكل طبقة من الاخوان ما يناسبها من هذه الدراسات هذا مع ملاحظة أنه لابد من دراسة خاصة للفكرين توضح موقفنا كأخوان مسلمين بالذات من السلبيات والايجابيات في الفكرين وكيفية تحقيق الايجابيات في النظام الاسلامي مع كون هذه الايجابيات في النظام الاسلامي تشكل جزءا من كل ، والكل كله ايجابيات بلا سلبيات « من بين فرث ودم لبنا خالصا سائغا للشاربين » ( النحل : ٦٦ ) .", "(١) العدد والعدد : الأولى بفتح العين والثانية بضمها ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0185.png"}, {"n": 186, "paras": ["الفصل الثاني", "في مراحل العضوية وبعض الأساسيات فيها", "ان أكثر المسلمين اليوم سائب الولاء وذلك بسبب من الجهل بالاسلام ، والجهل بما يطالب به الاسلام ، ومن ثم فانه لابد من أن ندخل كل مسلم في مرحلة الفهم للاسلام والالتزام به ومعرفة أهله واعطائه الولاء لهم ، ومجموع ما يلزم لذلك هو الذي ينبغي أن يعطاه المسلم في المرحلة الأولى ، فاذا ما نضج المسلم في المرحلة الأولى أصبح مؤهلا للمرحلة الثانية التي ينبغي أن يغلب عليها الجانب العلمي بحيث يربى المسلم على كل ما تستلزمه مقتضيات الجهاد من أجل الاسلام . فاذا نضج في ذلك فانه يؤهله لأن يدخل في مرحلة التأهيل على القيادة في العمل الاسلامي وهذا يستلزم منه أشياء كثيرة لابد من اعطائه اياها وتدريبه عليها . فاذا ما نضج في ذلك فانه يكون قد أصبح مؤهلا لمرحلة الوراثة الكاملة لرسول الله صلى الله عليه وسلم ليقوم بما تستلزمه مهمات الوراثة في هذا العصر ، وهذه كلمات مختصرة في درجات العضوية ومراحلها ولوازم كل مرحلة ، فنقول :", "بشكل عام ان علة المسلمين تكمن في الخلل بواحدة من دوائر ثلاث : اما دائرة العلم والثقافة ، وأما دائرة النقص في الخصائص ، واما في دائرة الالتزام فاما أن تجد مسلما لا ثقافة ولا علم اسلاميين عنده ثم لا خصائص ولا التزام ، وأما أن تجد بعض علم دون خصائص أو التزام أو التزاما بدون خصائص أو علم ، أو شيئا من الخصائص والعلم دون الالتزام ، وهكذا تبقى قضايا المسلمين سائبة أو ضائعة بسبب ذلك ، وبشكل عادى تبقى قضية الاسلام نفسه ضعيفة ولاشك أن علاج هذا الوضع انما يكون بالانتساب الى جماعة المسلمين فذلك"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0186.png"}, {"n": 187, "paras": ["الذي يحقق الالتزام وأن تحاول الجماعة على ضوء نظرية متكاملة أن تعطى كل ما يلزم في باب الثقافة والعلم وأن تنمى ما استطاعت قضية الخصائص ، وشيء عادى أنه في هذه الدوائر الثلاث لابد من تدرج ولابد من الانتقال بالعضو من حد أدنى إلى حد أرقى منه إلى ما فوق ذلك .", "والأستاذ البنا ذكر تفصيلا ست درجات في مراتب العضوية يمكن أن تختصر إلى أربعة ، هي : درجة الأنصار ثم درجة المجاهدين أو العاملين ثم درجة النقباء ثم درجة النواب ، والمفروض أن يكون لكل درجة منهاجها العلمي والثقافي وأن يكون لها خصائصها وأن يكون لها التزاماتها وعلى ضوء التحصيل العلمي والتحقق بالخصائص ومقدار الالتزام يكون التقدم في درجات العضوية أو البقاء في درجات دنيا أو حتى البقاء على هامش الصف .", "ويمكن أن نقول أن الأبواب التي ذكرت في كتاب « جند الله » هي مجموعة الأبواب التي يعتبر أخذها دليل الكمال في الثقافة الاسلامية وعلومها أصولا وفروعا ، ولكن الثقافة الكاملة المرادة من الأخ شيء يزيد على ذلك اذ الثقافة المعاصرة ينبغي أن تكون جزءا من تكوين الأخ الثقافي وكذلك الثقافة التأهيلية التي تؤهله للنبوغ في اختصاص حياتي أو تؤهله لنجاح في جانب من العمل الاسلامي ، فذلك كله هو مظهر الكمال في الدائرة الأولى ، أما الخصائص فلا شك أن مجموع خصائص الأخ النصير أقل من خصائص الأخ النقيب فضلا عن النائب في الخصائص التي تناسب كلا من درجات العضوية ، ثم أن مقدار ما يطالب به العضو من التزامات يختلف حتما باختلاف درجات عضويته .", "واذن لابد أن تكون نظرياتنا في هذا الموضوع واضحة ولابد أن نعطيها وجودها العملي ، وينبغي أن تكون النظريات من القوة والوضوح بحيث يستشعر كل مسلم يطالب بها ضرورتها وبداهتها ، ولاشك أنه ما من مسلم يمارى أن عليه كحد أدنى من الثقافة أو يعرف أهم ما يلزمه في حياته لواقعه اليومي ولتأدية الواجبات والسنن اليومية والأسبوعية والشهرية والسنوية والعمرية وبالتالى فأن نطالب المسلم مثلا بأن يدرس كتابا مختصرا في العقائد ، وكتابا مختصرا في الأخلاقيات ، وأن"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0187.png"}, {"n": 188, "paras": ["يعرف كيف يقرأ كتاب الله من خلال تلاوة يومية وتعرف على علم التجويد ، وأن يحفظ بعض ما ورد في شأنه ندب خاص من سور قرآنية ، وأن يعرف شبهات أعداء الله عن الاسلام من خلال دراسته لكتاب في ذلك ، وأن يعرف معركة الاسلام مع خصومه ، وأن يكون عنده شيء من الفقه الأساسي للدعوة إلى الاسلام .", "ان هذه المعاني كلها يمكن أن يستشعر المسلم ضرورتها وأن يعرف بالبداهة أنها تلزمه كحد أدنى في دائرة الثقافة ، وأن يطالب المسلم بأن يقيم الصلاة ، ويؤتى الزكاة ، وأن يحرر ولاءه لجماعة المسلمين ، وأن يكون له ورده اليومي من قراءة قرآن ، واستغفار وصلاة على رسول الله صلى عليه وسلم وتكرار لا اله الا الله ، وقيام الليل ، كل ذلك يقبله المسلم بداهة كحد أدنى من الخصائص ، وأن يطالب المسلم بأن يلتزم بحضور الاجتماعات العلمية اذا دعى اليها ، وأن يدفع زكاته لأهل الاسلام وبالتحديد لجماعة المسلمين اذا لم يكن أحق شرعا فذلك أيضا يقبله المسلم بداهة كحد أدنى من الالتزام .", "وهذا الذي نتصور أنه لابد منه لاعطاء صفة العضوية الأولى فاذا ما أريد نقل الأخ الى درجة المجاهد فانه لابد من أن يقنع بضرورة التحقق بخصائص الجندية الربانية ، ولابد من أن يقنع بضرورة الدراسات القرآنية الخاصة في قضايا الجهاد وبضرورة الدورة الروحية للتحقق بخصائص المقاتل الروحية وبضرورة الدورة الأمنية وخاصة في بعض الأفكار ليعرف ما يحذره مما يصادفه ، وبضرورة ممارسة الأمر بالمعروف والنهي عن المنكر كصفتين أساسيتين للجماعة التي تستأهل نصر الله وبضرورة أنواع من الأعمال تؤهله للقيام بلوازم الجندية الربانية ، وذلك كله ينبغي أن يكون الأساس المعتمد لاعطاء صفة العضوية من الدرجة الثانية ، عضوية العامل ، وأن يطالب الأخ أن يأخذ حظا لا بأس به من كل أبواب الثقافة الاسلامية ، وحظا مما يلزم كتقانة معاصرة ، وأن يطالب الأخ ويمرن على الكرم وتحمل المسئوليات وتنفيذها بشجاعة ، وأن يطالب بالحلم والأناة والرحمة باخوانه وخدمتهم ورعايتهم كخصائص وردت في شأنها نصوص مرتبطة بقضية الامرة ، وأن يطالب الأخ ببيعة على الالتزام بقواعد الجماعة المنبثقة عن شوراها ، وأن يطالب بالالتزام بطاعة القيادة المنبثقة عن القواعد التنظيمية"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0188.png"}, {"n": 189, "paras": ["للجماعة ، كل ذلك واضح المعنى ويسهل فهمه بالبداهة ، وكل ذلك لابد منه ليعطى الأخ درجة النقيب .", "وأن نطالب الأخ بالتوسع في كل أبواب الثقافة الإسلامية المعاصرة وأن نطالبه بأخذ الخصائص التي تقتضيها الوراثة النبوية وأن نطالبه بالنزول على رأى الأكثرية صاحبة الحق في الشورى على ضوء نظريات الجماعة كل ذلك معقول المعنى بالنسبة لاعطاء الأخ درجة النائب ولا يصح أن يعطى أخ رتبة درجة ما دام متخلفا في دائرة من دوائرها الثلاث لأن أى تساهل في هذا سيكون على حساب الثقة التي بدونها لا يتم عمل وسيكون على حساب سلامة الصف التي بدونها لا يستطيع الصف أن يحتفظ بقدرته على الحركة السليمة المستمرة ، ولا يقدر على تحقيق الأهداف ، أن أى تفريط في سلامة الصف يجعل الصف غير مرشح لنمو الذي يؤهله للتوسع المستمر ، قال الأستاذ البنا رحمه الله شارحا طريق الدعوات : « وخلاصة ذلك جملتان : إيمان وعمل ، ومحبة وأخاء ، وماذا فعل رسول الله صلى الله عليه وسلم في تركيز دعوته في نفوس الرعيل الأول من أصحابه أكثر من أن دعاهم إلى الايمان والعمل ، ثم جمع قلوبهم على الحب والاخاء فاجتمعت قوة العقيدة إلى قوة الوحدة وصارت جماعتهم هي الجماعة النموذجية التي لابد أن تظهر كلمتها وتنتصر دعوتها وان ناوأها أهل الأرض جميعا ، وماذا فعل الدعاة جميعا من قبل ومن بعد أكثر من هذا ، ينادون بالفكرة ويوضحونها ويدعون الناس اليها فيؤمنون بها ويعملون لتحقيقها ويجتمعون عليها ويزدادون عددا فتزداد الفكرة ظهورا حتى تبلغ مداها وتبتلع ما سواها ، وتلك سنة الله « ولن تجد لسنة الله تبديلا » ( الأحزاب : ٦٢ ، الفتح : ٢٣ ) انها قدرة الصف على النمو المضطرد مع احتفاظه بسلامته بحيث لا يتعرض للانقسام ، هي وحدها السبيل لنبتلع ما سوانا ، وأى اهمال في قضية العضوية أو تساهل في اعطاء أحد صفة لا يستحقها تفريط في الصف وبالتالى هو تفريط في حق العمل الاسلامى أصلا ومن ثم هو", "تفريط بالتنفيذ كله لأن التنفيذ يستحيل اذا لم يوجد الصف السليم الذي تملؤه الثقة ببعضه والقادر على اتخاذ كل قرار سليم » ووسائلنا للوصول إلى التربية على مراحل العضوية كلها هي الحلقات العلمية العامة والخاصة والأسر ونظام الدورات ، وعلى الجماعة أن"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0189.png"}, {"n": 190, "paras": ["تؤمن هذه الأمور كلها ولوازمها والترتيبات والأجهزة اللازمة لذلك ، وبشكل عام استطعنا من خلال الشعب ومن خلال شخصيات علمية فيها ولو شخصية واحدة في دائرة المركز أن نرتب أمر الحلقات العلمية المتدرجة للقضايا الرئيسية في الثقافة الإسلامية وإذا استطاع المركز ايجاد مختصين في كل نوع من أنواع الدورات الخاصة مع تأمين الأمن فان ذلك يعتبر الأساس الصالح للنجاح ، وشيء عادي أنه لا نستطيع أن ننجح في أي شيء من هذا الا اذا وجدت المناهج المعدة أو الكتب المعتمدة أو الدراسات اللازمة لذلك كله ؛ فأي تكليف لأحد بشيء لا تعطى له مادته مع تعريفه على كل خطوطها اللازمة انما هو دفع بالأخ نحو الفشل الا اذا كان الأخ ذا كفاءة عالية ، وحبذا لو استطعنا أن نجعل كل شيء من لوازم دراساتنا من كتابة اخواننا ولكن ريثما يتأمن ذلك فان أشياء كثيرة موجودة يمكن أن تخدم في هذا السبيل .", "بمناسبة تفسير قوله تعالى : « ألم يأن للذين آمنوا أن تخشع قلوبهم لذكر الله وما نزل من الحق » ( الحديد : ١٦ ) نقل ابن كثير ما يلي :", "١ - عن ابن مسعود رضي الله عنه قال : ما كان بين اسلامنا وبين أن عاتبنا الله بهذه الآية : « ألم يأن للذين آمنوا أن تخشع قلوبهم لذكر الله .. » الآية ، الا أربع سنين ، كذا رواه مسلم وأخرجه النسائي عند تفسير هذه الآية ، وقد رواه ابن ماجه .. من هذا النص ندرك أن أربع سنين كافية لينضج المسلم نضجا كاملا اذ عتاب الله عز وجل لمن لم ينضج قلبه بعد أربع سنين يدل على أن الأربع سنين كافية للنضج ومن ثم يقترح أن تكون الأربع سنين حدا أدنى ليصل الانسان الى العضوية العاملة في الجماعة وهي عضوية العامل ، وعلى هذا فعلينا أن نضع في حسابنا أن نسارع في انضاج الاخوة الثقات خلال أربع سنين من خلال السير العادي ومن خلال الدورات .", "( ١٣ - في آفاق التعليم )"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0190.png"}, {"n": 191, "paras": ["الفصل الثالث", "في بعض الموازين والتوضيحات والأساليب", "نذكر في هذا الفصل بعض الموازين وبعض التوضيحات كما نتحدث عن موضوع الدورات كأسلوب من أساليب السير التربوي والتعليمي وكل ذلك لاستكمال صورة السير التربوي والتعليمي في دعوة الإخوان المسلمين .", "« موازين » إن ميزان النجاح في المرحلة الأولى في منهاجنا وفي سيرنا بالعضو في بدايته هو التحقق الكامل بالإيمان والصلاة والإنفاق والولاء الكامل لجماعة المسلمين ، نأخذ هذا من قوله تعالى : « إنما وليكم الله ورسوله والذين آمنوا الذين يقيمون الصلاة ويؤتون الزكاة وهم راكعون . ومن يتول الله ورسوله والذين آمنوا فإن حزب الله هم الغالبون » ( المائدة : ٥٥ ، ٥٦ ) وميزان النجاح في المرحلة الثانية التحقق الكامل بمحبة الله وبالذلة على المؤمنين والعزة على الكافرين وبالجهاد في سبيل الله دون خوف من لومة لائم ، نأخذ ذلك من قوله تعالى : « من يرتد منكم عن دينه فسوف يأتي الله بقوم يحبهم ويحبونه أذلة على المؤمنين أعزة على الكافرين يجاهدون في سبيل الله ولا يخافون لومة لائم ، ذلك فضل الله يؤتيه من يشاء ، والله واسع عليم » ( المائدة : ٥٤ ) . أما ميزات النجاح لإعطاء صفة النقيب ، فهو العلم زائداً عن هذه المعاني مع مجموعة من الخصائص التي لابد منها لنقيب مسلم ، من حلم وكرم وحزم ورحمة على المؤمنين وكثرة شورى وصدق مع الالتزام وورع وأمثل هذه المعاني من خصائص النفس الإسلامية الكامنة ، ولا شك أن من جملة ذلك نجاحه في المهمات التنفيذية التي يكلف بها واستفادته من أخطائه ، فنحن لا نتوقع أن لا يخطىء المسلم ولكن نطلب منه ألا يكرر الخطأ مرتين ، وكل مرحلة ينبغي أن تهتم بنجاح"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0191.png"}, {"n": 192, "paras": ["المرحلة السابقة ، فنكمل القصور ، ونبنى على النجاح حتى يبقى الصف دائما صف علم وخصائص ، ومن هذا العرض ندرك أن المسلم بحاجة الى أن يمر على كل المراحل ليأخذ كمالاته العلمية والعملية ، فاذا استطعنا أن لا نبقى مسلما الا وقد سرنا به في هذا الطريق كله فذلك جيد وطيب ، ولكن لا يبدو أن الأمور ستكون سهلة الا أنه يبقى هدفا من الأهداف أن نصل الى كل مسلم .", "« توضيحات »", "قال الأستاذ البنا رحمه الله : « ان الدعوة في مرحلة التكوين صوفية بحتة عسكرية بحتة » فما الحكمة من هذا الجمع ؟ الأصل أن الانسان لا يبيع نفسه لله الا اذا اجتمعت فيه مجموعة خصائص هي المذكورة في الآيتين : « أن الله اشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة ، يقاتلون في سبيل الله فيقتلون ويقتلون ، وعدا عليه حقا في التوراة والانجيل والقرآن ، ومن أوفى بعهده من الله فاستبشروا ببيعكم الذي بايعتم به ، وذلك هو الفوز العظيم . التائبون العابدون الحامدون السائحون الراكعون الساجدون الآمرون بالمعروف والناهون عن المنكر والحافظون لحدود الله ، وبشر المؤمنين » ( التوبة : ١١١ ، ١١٢ ) .", "فهذه النوعية وحدها هي التي تستطيع الجهاد في سبيل الله وهي التي تستعذب البيع في سبيل الله ، واعادة روح الجهاد للأمة الاسلامية حتى تستأنف الجهاد ، وحتى يصبح الموت أعذب أمانيها ، يحتاج الى تحقق بمجموع هذه الصفات التي ذكرناها ، وهي تحتاج الى سير صوفى سلفى رفيع ننأى به عن الشر ونتحقق فيه بالخير ، ومن لم يتحرر من كسبه السيء لا يستطيع أن يتلذذ بالشهادة ، قال تعالى عن اليهود في كراهيتهم للموت : « ولا يتمنونه أبدا بما قدمت أيديهم » ( الجمعة : ٧ ) ان كسبهم السيء يجعلهم لا يتمنون الموت ، وفى شريعتنا منعنا من تمنى الموت وطولبنا بتمنى الشهادة ولن نستطيع تمنى الشهادة الا بمجموعة من الخصائص التي ذكرتها الآيتان .", "وبهذا يتبين أن السير الصوفى الاخوانى ، شيء ضرورى في عصر غلبت عليه المادة والشهوة فما لم يكن للأخ سيره الى الله بالذكر وقراءة القرآن والعبادة وكثرة الصلاة والصوم فان نفسه ستغلبه ، أما اذا كان له مثل هذا فلن تغلبه لو غلبته فان فيئه الى الله متوقع ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0192.png"}, {"n": 193, "paras": ["ومن ثم فعلى الأخوة المربين أن يلاحظوا ذلك ، وجهاز التكوين هو محور البناء في الجماعة منه يكون الخلل وبه يتم البناء الصحيح ، ومن ثم فعلى هذا الجهاز أن يعرف كيف يختار عناصره وكيف يؤدون مهماتهم ، وأن أجود الإخوان علما وتقى وتربية وحسن تصرف ينبغي أن يفرزوا لجهاز التكوين .", "ان تحقيق الأخ بالتوبة والتوحيد الخالص والسياحة سواء فسرت بأنها الصوم أو فسرت بأنها السياحة في الأرض لمعرفتها ، وتحقيقه بالحمد لله على كل حال ، وتحقيقه بكثرة الركوع والسجود وبالأمر بالمعروف والنهي عن المنكر وبحفظ حدود الله فلا يتجاوزها كل ذلك لابد منه لاتقان عملية الجهاد ، وبهذا نفسر الصوفية البحتة في مرحلة التكوين ، أما العسكرية البحتة فمظهرها ما قاله الله عز وجل : « لا يستأذنك الذين يؤمنون بالله واليوم الآخر أن يجاهدوا بأموالهم وأنفسهم ، والله عليم بالمتقين . انما يستأذنك الذين لا يؤمنون بالله واليوم الآخر وارتابت قلوبهم فهم في ريبهم يترددون . ولو أرادوا الخروج لأعدوا له عدة ولكن كره الله انبعاثهم فثبطهم وقيل اقعدوا مع القاعدين » ( التوبة : ٤٤ - ٤٦ ) فذلك الميزان انفارق بين صدق الراغب في الجهاد والراغب عنه « من مات ولم يغز ولم يحدث نفسه بالغزو مات على شعبة من النفاق » رواه مسلم .", "« الدورات »", "ذكر الأستاذ البنا رحمه الله فكرة الدورات الصيفية في مذكراته ، وذكر بمناسبة كلامه عن الانضمام الجهادي وشروطه هذه العبارة : « والاستعداد لقضاء مدة التربية الخاصة بمكتب الارشاد » من هذا نحس اعتماد مبدأ الدورات كأصل في الاخوان المسلمين وخاصة في مرحلة التكوين ، وهو مبدأ ان لم يكن موجودا في الأصل فعلينا أن نوجده لضرورته وأهميته في عصرنا ، اذ يحتاج الانضاج في شيء ما مع الاسراع فيه الى اعتماد مبدأ الدورات كأصل ، والملاحظ أن العالم كله يعتمد مبدأ الدورات ، كما يلاحظ في كثير من الأحيان أن الانسان يخرج من دورة ثم يكلف بمهام تكون بمثابة اتمام للدورة وبمثابة استمرار على التدريب فيها ، وفي الغالب فان الانسان من خلال هذا وهذا ينضج . والدورات أنواع : منها دورات علمية ، ومنها دورات روحية ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0193.png"}, {"n": 194, "paras": ["وهناك دورات يمكن أن تكون في مرحلة التعريف ، ودورات يمكن أن تكون في مرحلة التكوين ، ودورات يمكن أن تكون في مرحلة التنفيذ ، وهذه قضايا تستتبع قضايا أخرى متصلة بالمنهج وشروط العضوية واحتياجات المرحلة وتوعية الأخ ونوع التأهيل الذي ترغب الجماعة أن تؤهله فيه ، وهكذا ، ونحن هنا نرغب أن نذكر نماذج على دورات لا نقيد بها ونكن نلفت النظر إليها للقياس عليها أو لاعتمادها مع ملاحظة أن هذا الأمر ينبغي أن يكون محل عناية القيادات باستمرار ، فقد ترى القيادة في لحظة من اللحظات أن من المصلحة أن تقيم دورة على موضوع ما لمجموعة الاخوان ، فتهييء مادته ومدرسيه وتعد العدة لذلك فيدخل في الدورة جميع الاخوان ، كل في وحدته أو جهازه أو في أسرته أو بشكل منفرد .", "« ١ - نماذج على دورات في مرحلة التعريف » يمكن أن تنشأ دورات مدتها اربعون يوما أو ثلاثون استئناسا بقوله تعالى : « وواعدنا موسى ثلاثين ليلة وأتممناها بعشر » ( الأعراف : ١٤٢ ) وليس في الآية نص على ما نحن فيه الا أن فيها ما يشير إلى الثلاثين أو الأربعين ففيها معنى يمكن أن يعتمد في قضية تعليمية أو تربوية تطيقه النفس البشرية ، والدورات هذه اما أن تخصص لنوع من العلوم أو لمجموعة من العلوم الاسلامية كأن تخصص للتوحيد أو للفقه أو للأصول الثلاثة أو لدراسة شيء من القرآن كسورة البقرة كما يمكن أن تخصص لحد أدنى من العلوم أو مجموعة علوم يتحقق بها فرض عين ، كدورة على علم التجويد وفقه العبادات والتوحيد وبعض الآداب الضرورية وأمثال ذلك وعلينا أن نلاحظ أن الدورات تكون مساعدة للبرنامج اليومي أو الأسبوعي الذي على الأخ أن يسير فيه ، وواضح أن الهدف من مثل هذه الدورات هو النضج العلمي والعبادي ، وبالامكان في هذه المرحلة ايجاد دورة ثلاثة أيام أو أسبوع في قراءة من كتاب أو قراءة مختصر أو الاسراع في استكمال نواقص المرحلة .", "« ٢ - نماذج على دورات في مرحلة التكوين » قد يحتاج الانسان في مرحلة التكوين الى مجموعة دورات لانضاجه زيادة على البرنامج اليومي أو الأسبوعي ؟ وقد تقدم له كل ما يحتاج"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0194.png"}, {"n": 195, "paras": ["اليه في الدورات بشكل يومي أو أسبوعي . وكل ما ذكرناه حول دورات مرحلة التعريف يمكن أن يوجد في مرحلة التكوين مع تركيز خاص على دورات فقه الدعوة التي ينبغي أن يدرس الانسان فيها مجموعة من الرسائل الخاصة مع تركيز خاص على دورات الثقافة والأخلاق، مع تركيز خاص على دورات في دراسات قرآنية حول سورتي الأنفال وبراءة الا أن من الأشياء الضرورية اقامة دورات على بعض المعاني التي لابد منها : دورة تخص الجانب الروحي والعبادي والعمل التطبيقي ، دورة تدريبية على أنواع الرياضة الخاصة والتدريب الجسمي ، وكل دورة من هذه الدورات يجب أن تهيأ لها كتبها وبرامجها وأدواتها ، والأحسن أن يقدمها كلها شخص واحد ، ولكن هذا يقتضي أن يكون هذا الشخص مؤهلا تأهيلا عاليا وفي حالة التعذر يمكن أن يقدمها مجموعة أشخاص واذا كان هناك أفضلية ما في الدورات في مرحلة التكوين فان الأحسن أن يكون الترتيب على الشكل التالي : الدورة الروحية ، الدورة الفكرية على فقه الدعوة ، ثم الدورة الأمنية ، ثم الدورة التدريبية ولنذكر نمطا لكل هذه الدورات :", "١ - الدورة الروحية العملية : الغرض منها المران على كل ما يلزم الأخ من أوراد يومية أو أسبوعية أو شهرية أو سنوية ، كما أن الغرض منها التحقق العملي بانكمال الروحي ، ويمكن أن تكون هذه الدورة أربعين أو ثلاثين أو عشرة أيام ، يكلف الأخ فيها أن يجدد ايمانه بقول : لا اله الا الله ، وهي البداية التي لابد منها في المرحلة الأولى . أخرج الطبراني في الكبير باسناد حسن عن رسول الله صلى الله عليه وسلم قال : « ان الايمان ليخلق في جوف أحدكم فاسألوا الله أن يجدد الايمان في قلوبكم » . وأخرج الامام أحمد باسناد جيد عن رسول الله صلى الله عليه وسلم قال : « جددوا ايمانكم ، قيل : يا رسول الله كيف نجدد ايماننا ؟ قال : أكثروا من قول : لا اله الا الله » من هذين الحديثين ندرك أن تجديد الايمان في القلب يكون في الدعاء والافتقار الى الله ، ويكون بالاكثار من قول لا اله الا الله . ثم يكتف بالاستغفار الدائم أخذا من قوله صلى الله عليه وسلم : « من لازم الاستغفار جعل الله له من كل هم فرجا ومن كل ضيق مخرجا »"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0195.png"}, {"n": 196, "paras": ["ورزقه من حيث لا يحتسب » ثم يكلف بالصلاة على رسول الله صلى الله عليه وسلم والمداومة عليها ، وبعد ذلك كله يرجى أن يكون قلبه قد تنور بورد الدعاء في رسالة المأثورات أن يلازمه كحد أدنى في كل يوم وهو : مائة مرة استغفار ومائة مرة صلاة على رسول الله ومائة مرة لا اله الا الله ، ويختم ذلك بقراءة « قل هو الله أحد » ثلاث مرات ، ثم يؤمر بختم القرآن في ثلاثة أيام ، ثم يكلف بالمداومة على جزء واحد في اليوم أخذا من قوله عليه الصلاة والسلام لابن عمرو عن القرآن : « اقرأ القرآن في شهر » ثم يكلف بأوراد الصلاة وأذكارها من سنن رواتب وسنة الضحى وقيام الليل والوتر ويؤمر بإطالة ذلك ثم يطالب بالدوام على حد أدنى من ذلك كركعتي الضحى مع السنن الرواتب مع ثمان ركعات قيام الليل مع الوتر ، ولو بحد أدنى من السور القصار ، ثم يكلف أن يمارس الأمر بالمعروف والنهي عن المنكر مع السياحة في قطره ، والهدف من هذه الدورة التحقق بصفات البائع نفسه لله التي مرت معنا ، ويوصى في نهاية الدورة بملازمة ورد الذكر وقراءة القرآن وقيام الليل وورد العلم والصيام ، ومن ذكر الأخيرة تعرف أنه من المناسب أن يصوم خلال هذه المرحلة أو يصوم بعض أيامها ، وقد يكون من المناسب أثناء هذه المرحلة قراءة بعض الرسائل الوعظية أو بعض الأحاديث المختارة المذكرة في أمر الآخرة ، أو كتاب كتاب الترغيب والترهيب أو مواضيع من كتاب احياء علوم الدين ككتاب الأمر بالمعروف والنهي عن المنكر . ويوصى خلال ذلك بكثرة الصمت حتى يعتاد على ضبط لسانه وعلى العزلة حتى لا يضيع وقته ، وعلى المدارسة مع موجبه في الصغيرة والكبيرة وعلامة النجاح في هذه الدورة التمسك بالأوراد اليومية الدائمة ، وظهور آثار ذلك وبركته على الأخ ، انه لا خير في بداية لا تنطلق من قلب سليم .", "٢ - الدورة الفكرية : يمكن أن تكون هذه الدورة دراسة لرسالة في فقه الدعوة وهي اما دورة لبحث منفرد أو استكمال لدراسة يومية أو أسبوعية من قبل ، واذا كانت الدورة السابقة المراد بها الاحتراق في العمل فهذه المراد بها الاحتراق في فكر الجماعة والصهر به ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0196.png"}, {"n": 197, "paras": ["الباب التاسع خاتمة الكتاب", "وبعد ... يا تلاميذ الأستاذ البنا : انه بعد مرحلة صعبة طويلة ومجهدة لابد من عمل ضخم تعبأ له كل الجهود بناء الجماعة دون الالتفات كثيرا الى ما يجرى حولنا ، وان أى تطلع الى غير ذلك قبل استكماله يبقى نوعا من ترك الواجبات الأولى الى غير ذلك مما يأتى فى الدرجة الرابعة أو الخامسة فى تسلسل الأفضليات ، نحن بحاجة بعد عمليات التشويه القذرة الكاذبة الخائنة أن نعيد الى أنفسنا حيويتها وأنى أمتنا الثقة بنا ، وذلك لن يكون الا من خلال البناء السليم لأفراد الجماعة وللجماعة على أسس صحيحة ، وبدون ذلك نبقى بمنأى عن تحقيق الأهداف المحلية والعالمية ، انه لابد بواسطة البناء السليم أن نصل الى أن يطمئن كل من فيه شيء من الخير فى هذه الأمة الى أشخاصنا ، والى جماعتنا والى الحق الذي نحمله وذلك من خلال الرؤية العملية لنضجنا فى كل ميدان .. فالسياسي لابد أن يرى أننا أنضج فى السياسة من المحسوبين عليها ، والعالم المسلم لابد أن يرى أننا أنضج فى فهم الاسلام وأكثر التزاما من الكثيرين ، وقل مثل ذلك فى كل دائرة ، وكل ذلك ينبغى أن يكون فى الله ولله ، وكل انطلاقة تبعد عن تحقيق مثل هذه المعانى ستنعكس سلبياتها علينا فى المستقبل ، وان اعادة الثقة الى المسلمين بالاسلام واعادة الثقة للمسلمين بعضهم ببعض على أساس الاسلام الخالص لن تتم الا من خلال الثقة بشخصية مبنية بناء سليما وبجماعة مبنية بناء سليما ، وهذا ما يجعل التركيز على بناء الشخصية وبناء الجماعة يشكل المنطلق السليم الوحيد ومن ثم كانت هذه السلسلة .", "هناك ناس يجهلوننا ، وهناك ناس عواطفهم متضاربة تجاهنا ؛ فهم مشفقون علينا وغير واثقين بقدراتنا ، مشفقون ان فعلنا ويائسون من أن نفعل ؛ خائفون ومشفقون أن نتعثر ثم نتحسر ، ومن ثم يأخذون"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0197.png"}, {"n": 198, "paras": ["دورهم كمثبطين ومعوقين بحجة الاشفاق ، الى هؤلاء ، نقول : اننا نؤمن ان الوضع السليم للمسلم لا ينبغي ان يكون كذلك بل ينبغي ان يمضى على أمر الله أو تتفرد سالفته ... هكذا كان شأن رسول الله صلى الله عليه وسلم ومع أن الأمر كذلك فان علينا أن نطمئن هؤلاء ونعلم أولئك أن جماعتنا جديرة بالثقة ، وأن اسلامنا جدير بالثقة ، وأنه مع توفيق الله عز وجل فلا خوف ولا وجل وذلك كله لن يتم الا من خلال البناء السليم .", "ولا شك أن عوامل كثيرة كرست ضعف الثقة بالامكانيات السياسية للعاملين للاسلام اذ أنه بسبب الضربات الظالمة والنظرات الخاطئة والقيادات الدينية القاصرة تعمق لدى الكثيرين انطباع أن المسلم لا شغل له بالسياسة وأن الاسلام لا محل له في القيادة السياسية ، فهو ككل الأديان ينبغي أن يعزل عن السياسة ، وهذا كله أدى الى ضمور التربية السياسية ، والعقلية السياسية عند كثير من المسلمين في وقت أصبحت فيه السياسة تشكل ثمانين بالمائة من المؤثرات في هذا العالم سواء على شخصية الانسان أو على مجتمعاته ومن ثم فلابد من ارجاع الأمر الى نصابه في هذا الشأن عن طريق البناء السليم لشخصية الأخ وبناء الجماعة ليعود للمسلم تفكيره السليم فيضع الأمور في مواضعها لتستأنف هذه الأمة رسالتها العالمية في هداية الانسان الى الاسلام ... ان هناك تناقضا رهيبا بين الاسلام والواقع وبين المسلم وما حوله ففي الوقت الذي يغطى فيه الاسلام الحياة يحاول الكثيرون أن يجردوه من كل شيء، ومن ثم لم يعد أمام المسلم خيار في دخوله كفاحا متواصلا على أسس واضحة المعالم ولعل هذه الرسالة توضح الكثير من احتياجات هذا الكفاح على ضوء فكر الأستاذ البنا رحمه الله ، الرجل الوحيد الذي فطن لكل احتياجات هذا الكفاح وأعطاه مداه من نقطة الصفر الى نهاياته ، وعلى امتداد ذلك من مسار فهو الذي فطن الى ضرورة نقل المسلم من كونه سائرا في تيارات جاهلية الى أن يصبح جزءا من تيار اسلامي خالص وهو الذي فطن الى ضرورة الوسائل المتكافئة ، وهو الذي فطن الى ضرورة العمل لتحقيق الأهداف الاسلامية والى كيفية اعادة ما وهى من عرى الاسلام الى حيويته والى"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0198.png"}, {"n": 199, "paras": ["الصلة بين ضرورة الجمع بين تطلعات الشعوب وبين التبني الكامل للإسلام الشامل وأعطى ذلك كل مستلزماته من التطبيق العملي والبناء المناسب ولكن تصورا ما قد حدث ؛ قسم منه سببه نحن ، وقسم منه سببه خارجي ، ومن مظاهر هذا القصور عدم وضوح نظرياتنا في أنفس الكثير مما أدى إلى ضمور امكانية الكثير منا في التعامل مع النفس البشرية وإلى ضمور القدرات على استيعاب الاخوان أصحاب الطاقات ، فبدلا من أن نفسح المجال للطاقات أن تنفجر كانت تحمل على انفرك ، مما أدى إلى ابقائنا كثيرا من قطاعات الحياة بلا عمل ؛ ولقد أشرنا إلى هذا الموضوع للاشعار بأهمية المعرفة للقواعد المتكاملة في البناء على ضوء فكر الأستاذ البنا وللاشعار بأن القصور لا يتحمل مسئوليته فكر الأستاذ البنا ، وانما التقصير فيه هو السبب ..", "لقد حدث في التاريخ الاسلامي أن اغتيل النظام الاسلامي في الاسلام بانتقال نظام الخلافة الراشدة إلى ملكية عضوض فأغتييت بذلك أمور متعددة كان من المفروض أن تزيدها العصور توسعة وتعضيدا ، ومن ثم اختفى الكلام عن كثير من الجوانب أو قل ، فأنت ترى كتبه الفقه الاسلامي ذكرت آلاف المسائل الجديدة في الموضوع الواحد لكنك تجد كلامها قليلا عن كثير من معاني الشورى وجوانب الاقتصاد المرتبطة بالحكم وأمثال ذلك .. حتى كتب الأحكام السلطانية لم تمس كثيرا من الأمور إلا مسا رقيقا ، واقتصرت كثير من الكتب خلال العصور على التبرير لوضع أنه الوضع الأمثل ؛ ولكن بحكم أنه أهون الشرين وأخف الضررين وهكذا ... ونحن جماعة نريد أن يستأنف الاسلام سيره العالمي الجديد ، وهو سير بدايته ما نحن فيه ونهايته الزمانية والمكانية هي العالم كله ومن ثم فلابد من ترسيخ قواعد الشورى وتعميقها في نفس كل العاملين ، ليكون السير على بصيرة ويكون السير الحالي مقدمة لسير بعيد ويحال دون ظهور الظواهر المرضية ، وليقطع الطريق على أي نزوة شخصية تريد أن تنقل الحركة أو الجماعة من وضع أصيل إلى وضع دخيل أو تنحرف بالاسلام عن أن تأخذ كل نصوصه تطبيقاتها العملية ، وعلينا بعد وضوح الطريق أن نتحرك الحركة الجادة التي يحتاجها عصرنا ، وتقتضيها واجبات دعوتنا ، وتحقق طموحات اخواننا وتفجر طاقاتهم ، لقد استطاعت قيادات كافرة أن تفعل الكثير في"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0199.png"}, {"n": 200, "paras": ["الزمن القليل ؛ فهذا هتلر وهو ظاهرة غريبة في تاريخ البشرية ، استطاع بزمن قليل أن ينهى أوضاعا في غاية القسوة ليجعل بلاده في منتهى القوة ، فالملايين العاطلة عن العمل أوجد لها عملا ، والعملة المتدهورة جعل لها قيمة ، والتمزق في الشعب جعله يندمل ، والصناعة العسكرية الممنوعة على ألمانيا بموجب معاهدة فرساي الا ضمن حدود استطاع أن يوجدها ، والجيش المحدود العدد استطاع نقله إلى قوة جبارة ، وهكذا خلال سنين محدودة نقل ألمانيا من دولة مهزومة إلى دولة كادت تتغلب على أكثر دول العالم وقتذاك ؛ فإذا كان هذا شأن القيادات الجادة تستطيع أن تفعل الكثير في الزمن القليل ؛ فإذا ما توافرت للقيادات الإسلامية نظرة بعيدة شاملة وقدرة صحيحة على استيعاب حاجات الأمة ومران على التعامل مع الطبيعة البشرية وتمكن في سياستها ، وإذا ما استطاعت هذه القيادات أن تصل إلى قطاعات الأمة وكان ذلك كله ضمن نظرية مبصرة في التنظيم والتخطيط والتنفيذ ... أن قيادة من هذا النوع تستطيع أن تفعل الكثير ، علينا أن ننقل أمتنا من طور إلى طور ، وبجدية كاملة ، وبعزيمة لا تعرف الكلل ، وبعقلية محترفة تحترف العمل الاسلامي ، وهذا كله هو واجب الوقت الذي لا ينبغي أن تنصب جهود المجاهدين في سواه ، وليعلم العاملون أن هناك قضايا لا تحتمل الخطأ : الدين ، والحرب ، والسياسة ، فالخطأ في الدين يؤدي إلى خراب الدنيا والآخرة ، والخطأ في الحرب قد ينهي أمة ، والخطأ في السياسة مدمر قاتل أو متعب مؤلم ، ونحن جماعة تحمل الدين الحق ولا يجوز أن تخطئ ، فيه ، لا في فهمه ، ولا في عرضه ، ولا في تطبيقه ، وهي جماعة جزء من أهدافها وأعبائها العمل السياسي فلا يجوز في قراراتها السياسية ولا في حساباتها أن تخطىء التقدير ؛", "والحرب هي فننا المفضل ومهمتنا العالية فيجب أن نجعل المسلمين أكثر خلق الله لها اتقانا ، وعلينا دائما أن نحسن التفكير للمستقبل وللحاضر ، وأن نحسن اختيار القرار الملائم الخطة الحاضرة وللمستقبل ، وذلك كله لن يتم الا بتوفيق من الله عز وجل وبارتماء على أبواب العبودية له جل جلاله ..", "انه تفريط أن نقصر في الأخذ بعالم الأسباب ، وانحراف كبير أن لا نتوكل على الله خالق الأسباب في كل شيء ، ومن الأخذ بعالم الأسباب أن نتقن العمل في أمورنا كلها وأن لا نهمل في شأن من شئوننا ، ومن"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0200.png"}, {"n": 201, "paras": ["ثم فقد آن الأوان لأن ننهى من أنفسنا العقلية الجامدة المتحجرة وأن ننهى العقلية التي تقول الكثير وهي عاجزة عن فعل القليل ، وأن ننمى العقلية التي تريد تحقيق الأهداف من خلال الأحلام فقط ، وقد آن الأوان لانهاء العقلية التي تسوف في كل أمر كأن ارجاء الأمور يحل كل قضية ليحل محل ذلك كله عقلية مرنة تمتلك القدرة الكاملة على التنفيذ العبقرى مخلفة الدنيا كلها وراءها ، مقبلة على تحقيق الأهداف بعقلية المحترفين الراغبين في الدار الآخرة فقط ، ان هذه العقلية هي التي يحتاجها مستقبل الاسلام فلا عليها أن تسير ولو خالفها الكثير .. وقد يظن بعض الناس أن الانقسامات التي تصيب الحركات الاسلامية علامة على نهايتها والأمر ليس كذلك ، فالانقسامات لابد منها أمام توسع الحركة على غير أساس مركزى كامل النضج والسيطرة ، ويظن بعض الناس أن الحركة تحتاج الى فكر جديد كل الجدة لتنطلق انطلاقة جديدة وهذا وهم فالأستاذ البنا أطلق السير في الطريق الصحيح ، أن الذي نحتاجه بعد التوسع الكبير للقاعدة الاسلامية هو العقلية الاسلامية المنفذة العبقرية ... هذه العقلية هي التي تجمع الصف على أساس من القديم مجتمعا معه عبقرية التنفيذ ، ومهما كانت بداية الانطلاقة صغيرة فان هذا الانطلاق هو الذي سيؤدى الى الوصول باذن الله .", "غير أن هذه العقلية ستسلط عليها سهام النقد من الداخل والخارج وعليها أن تصمد ما دامت منطلقة على أساس من الشورى والالتزام المبصر بشرع الله فسيفىء الى ظلها في النهاية - باذن الله - كل المتطلعين وكل أصحاب الورع الجاهل وكل أصحاب المفاهيم الخاطئة والأحلام الخيالية ولكن بعد أن يجتهدوا ، وعلينا دائما أن نتحمل اجتهادهم ونتعامل معهم بسعة صدر .. فهم اخواننا وأحباؤنا ونحن معهم في كل خطوة خيرة لا تتعارض مع مخططاتنا ، ونحن على استعداد لأن نبذل لهم الأموال والجهود ليحققوا بعض الانتصارات لأشخاصهم ولاتجاههم الاسلامى اذا وجدنا أن المصلحة الاسلامية تقتضى ذلك ، واذا شتمونا فلن نشتمهم ، واذا أرادوا تحطيمنا فلن نحطمهم ، غير أننا لن نعطيهم - هم أو غيرهم - فرصة التأثير على الصف ، سنكون واضحين مع صفنا صريحين معه ، نحدثه بصراحة كاملة عن نقاط الخلاف بيننا وبين كل أحد ولن نخشى مغبة ذلك لأنه ليست لنا مواقف شخصية وليست لنا"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0201.png"}, {"n": 202, "paras": ["أمزجة خاصة ، بل المصلحة الاسلامية وحدها هي التي تجمعنا تتحرك حركتنا ونحن على استعداد في كل وقت وبقلب مفتوح لكل اقتراح ولكل تصحيح ولن يصعب علينا الاعتراف بالخطأ ، نسأل الله أن يجعلنا من الأوابين .", "يحتاج الاسلام اليوم الى عمل بداياته سليمة وأن طال الطريق ، أما البدايات الخاطئة فانها لا تؤهل الى شيء ، والبداية السليمة هي التأسيس على التقوى : « أفمن أسس بنيانه على تقوى من الله ورضوان خير أم من أسس بنيانه على شفا جرف هار فانهار به في نار جهنم » ( التوبة : ١٠٩ ) والبداية السليمة تكمن في وجود أنورات الكامنين والأولياء المرشدين ، قال تعالى : « ومن يضلل فلن تجد له وليا مرشدا » ( الكهف : ١٧ ) دل ذلك على أن الولى المرشد هو الغاية في الهداية فاذا لم يهتد الانسان على يد الولى المرشد « فما له من هاد » ( الزمر : ٢٣ ) لأن الله عز وجل أراد أضلاله ومن ثم كانت البداية الصحيحة هي وجود أمثال هؤلاء ، فبقدر ما ننجح في ايجاد هؤلاء المستكملين لمعاني الربانية - أى الأولياء المرشدين - الربيين الربانيين تكون بدايتنا صحيحة ، وقد جرت عادة المرشدين أنهم اذا وجدوا انسانا عنده استعداد خاص وجهوه وأعطوه وأجازوه في دعوة الخلق ، ونحن علينا أن نبحث في هذه الأمة عمن يصلح للنيابة عن رسول الله صلى الله عليه وآله وسلم في دعوة الخلق وارشادهم ثم تفقهه في دين الله وفي دعوته ، ونطلق يده في العمل على هدى قواعدنا التنظيمية ، علينا أن نربط كل المسلمين اليوم برباط محكم يقيهم التفلت ، وعلينا أن نتخلص من الكلمة غير المسئولة ، فقد مضى الزمن الذي يقول فيه قائلنا وتكون كل كلمة من كلماته تخسرنا جزءا من أمتنا ، يجب أن نكون دقيقين ونحن نتكلم بأسم الاخوان المسلمين فلا نقول كلمة الا بميزان دقيق نلاحظ فيه حقوق العلم وحقوق الدعوة وحقوق المعركة وحقوق التربية .", "أن دعوة الاخوان المسلمين دواء ، لمفرداته نسب معينة ، فاذا ما حدث خلل في النسب حدث خلل في الدواء نفسه حتى أنه قد يصبح سما فليحاول كل أخ أن يحتفظ بخصائص هذه الدعوة كاملة دون أن"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0202.png"}, {"n": 203, "paras": ["يغير نسب تركيبات الأشياء فيها لأن ذلك سيترتب عليه فساد وزيف .. السلفية والصوفية والآمال والمادة والروح والفكر والقلب والتخطيط والتوكل والأخذ بالأسباب ، كل ذلك له نسب داخل هذه الجماعة ، وبهذه النسب كانت هذه الجماعة هي العلاج الحاسم لكل أمراض المسلمين فإذا اختلفت النسب اختلف العلاج . فلنحافظ على النسب لتكون روحا لهذه الأمة ، وحياة لها ...", "ان علينا أن نتقن أمر الدعوة إلى الله وأن تكون دعوتنا خالصة لله لا لأنفسنا ، فكثيرون من الدعاة يبدأون دعاة إلى الله ثم ينقلبون دعاة لأنفسهم ، وعلينا أن نحسن طرق أبواب النفس البشرية وأن نحسن تربيتها وتزكيتها وترقيتها ، وهذا لا يتأتى لنا الا بأن نملك مفتاح المغاليق للقلب البشرى ، وهذا لا يتأتى بدون علم وعمل وقبل ذلك كله حكمة مهداة من الله رب العالمين .", "لابد أن نعرف كيف نبدأ مع كل إنسان ، ثم كيف ننتقل به ، ولابد أن نعرف حدود التعامل مع كل إنسان فهذا يمكن أن يكون عضوا وهذا يمكن أن يكون صديقا في حدود ، وهذا يمكن أن يكون صديقا بلا حدود ، وهذا يمكن أن يخدم مرة في العمر ولكنه يؤذى مرات ، وهكذا كل ذلك ينبغى أن يتقنه كل فرد منا ... أن نعرف سقف كل إنسان فلا نهول بينه وبين سقفه وألا نعطيه فوق استعداده وألا نقطع شعرة بيننا وبين أى فرد مسلم الا اذا قطعها ، أن نعرف حدود مواقفنا مع المسلمين ومع غيرهم ، وما هو الموقف المناسب لكل مقام ؟ وما هو المقال المناسب لكل موقف ؟ كل ذلك ينبغى أن يربى كل فرد منا عليه ، ولنعلم أن وزن الجماعة بوزن أفرادها ، وتجربة الجماعة بتجربة أفرادها ، وحكمة الجماعة بحكمة أفرادها ، وهذا كله يقتضى تركيزا هائلا على البناء ، بناء أفراد الجماعة ليتم بناء الجماعة .", "ولعل هذه الرسالة تؤدى دورا في ذلك ، ان شاء الله تعالى . والله المرجو والمستعان ، وهو حسبنا ونعم الوكيل ."], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0203.png"}, {"n": 204, "paras": ["محتويات الكتاب", "الموضوع الصفحة المقدمة ٥ - ١٠ الباب الأول : حسن البنا واضع نظريات العمل الإسلامي المعاصر ١١ الباب الثاني : في مفاتيح الفهم والدعوة لقضية الإخوان المسلمين ١٦ الباب الثالث : في المهمات الكبرى ٢٦ الباب الرابع : في الأهداف ٢٩ الباب الخامس : في الوسائل ٥٥ الباب السادس : في مراحل الدعوة ٧٧ الباب السابع : في مقومات الشخصية الإسلامية وواجباتها من خلال رسالة التعاليم ٩٧ الباب الثامن : فصول متممة ١٨٠ الفصل الأول : إرشادات إلى بعض القواعد التي تناسب طبيعة دعوتنا في المناهج الثمانية والتعليمية والتربوية ١٨١ الفصل الثاني : في مراحل العضوية وبعض الأساسيات فيها ١٨٩ الفصل الثالث : في بعض الموازين والتوضيحات والأساليب ١٩٤ الباب التاسع : خاتمة الكتاب ٢٠٠ محتويات الكتاب ٢٠٧"], "img": "../../../_ocr-work/libocr/sharh-fi-afaq/pages/0204.png"}]};
